/// Native real-time F1 audio bridge (communicates with Android AudioTrack synthesizer)
class F1SoundEngine {
  static const MethodChannel _channel = MethodChannel('f1_audio');
  static bool soundEnabled = true;
  static bool _sentSilent = false;
  // Reused zero-GC IPC payload maps (eliminates 25 Map allocations/sec!)
  static final Map<String, Object> _updatePayload = <String, Object>{
    'rpm': 4200.0,
    'speed': 0.0,
    'throttle': false,
    'brake': false,
    'ers': false,
    'offTrack': false,
    'onKerb': false,
    'slip': 0.0,
    'active': false,
    'muted': false,
  };
  static final Map<String, Object> _eventPayload = <String, Object>{
    'type': '',
    'intensity': 1.0,
  };

  static void update({
    required double rpm,
    required double speed,
    required bool throttle,
    required bool brake,
    required bool ers,
    required bool offTrack,
    required bool onKerb,
    required double slip,
    required bool active,
  }) {
    final bool effectiveActive = active && soundEnabled;
    if (!effectiveActive && _sentSilent) return;
    _sentSilent = !effectiveActive;
    _updatePayload['rpm'] = rpm;
    _updatePayload['speed'] = speed;
    _updatePayload['throttle'] = throttle;
    _updatePayload['brake'] = brake;
    _updatePayload['ers'] = ers;
    _updatePayload['offTrack'] = offTrack;
    _updatePayload['onKerb'] = onKerb;
    _updatePayload['slip'] = slip;
    _updatePayload['active'] = effectiveActive;
    _updatePayload['muted'] = !soundEnabled;
    try {
      _channel.invokeMethod<void>('update', _updatePayload);
    } catch (_) {}
  }

  static void playEvent(String type, {double intensity = 1.0}) {
    if (!soundEnabled) return;
    _sentSilent = false;
    _eventPayload['type'] = type;
    _eventPayload['intensity'] = intensity;
    try {
      _channel.invokeMethod<void>('event', _eventPayload);
    } catch (_) {}
  }

  static void stop() {
    _sentSilent = true;
    try {
      _channel.invokeMethod<void>('stop');
    } catch (_) {}
  }
}

/// Native Android SharedPreferences persistence store (saves ALL settings, livery, camera & GP progress immediately!)
class GamePrefsStore {
  static const MethodChannel _channel = MethodChannel('f1_prefs');
  static bool loaded = false;
  static int selectedLiveryIndex = 0;
  static bool defaultCockpitCamera = true;
  static final Map<int, int> bestPositionByRound = {};
  static final Map<int, int> pointsByRound = {};

  static String _encodeIntMap(Map<int, int> map) {
    if (map.isEmpty) return '';
    return map.entries.map((e) => '${e.key}:${e.value}').join(',');
  }

  static void _decodeIntMap(String raw, Map<int, int> target) {
    target.clear();
    if (raw.isEmpty) return;
    for (final String pair in raw.split(',')) {
      final List<String> kv = pair.split(':');
      if (kv.length == 2) {
        final int? k = int.tryParse(kv[0]);
        final int? v = int.tryParse(kv[1]);
        if (k != null && v != null) {
          target[k] = v;
        }
      }
    }
  }

  static Future<void> loadAll() async {
    try {
      final Map<Object?, Object?>? data =
          await _channel.invokeMethod<Map<Object?, Object?>>('load');
      if (data == null) return;

      final Object? sens = data['steerSensitivity'];
      if (sens is num) {
        RaceEngineState.steerSensitivity = sens.toDouble().clamp(0.50, 2.50).toDouble();
      }
      final Object? analog = data['analogSteeringMode'];
      if (analog is bool) {
        RaceEngineState.analogSteeringMode = analog;
      }
      final Object? rLine = data['showRacingLine'];
      if (rLine is bool) {
        RaceEngineState.showRacingLine = rLine;
      }
      final Object? snd = data['soundEnabled'];
      if (snd is bool) {
        F1SoundEngine.soundEnabled = snd;
      }
      final Object? eco = data['eco60FpsMode'];
      if (eco is bool) {
        RaceEngineState.eco60FpsMode = eco;
      }
      final Object? diff = data['aiDifficultyLevel'];
      if (diff is num) {
        RaceEngineState.aiDifficultyLevel = diff.toInt().clamp(0, 4).toInt();
      }
      final Object? cam = data['cockpitCamera'];
      if (cam is bool) {
        defaultCockpitCamera = cam;
      }
      final Object? liv = data['selectedLiveryIndex'];
      if (liv is num) {
        selectedLiveryIndex = liv.toInt().clamp(0, kLiveries.length - 1).toInt();
      }
      final Object? bestRaw = data['bestPositions'];
      if (bestRaw is String) {
        _decodeIntMap(bestRaw, bestPositionByRound);
      }
      final Object? ptsRaw = data['pointsByRound'];
      if (ptsRaw is String) {
        _decodeIntMap(ptsRaw, pointsByRound);
      }
      loaded = true;
    } catch (_) {}
  }

  static Future<void> saveAll({bool syncFlush = true}) async {
    try {
      await _channel.invokeMethod<void>('save', <String, Object>{
        'steerSensitivity': RaceEngineState.steerSensitivity.clamp(0.50, 2.50).toDouble(),
        'analogSteeringMode': RaceEngineState.analogSteeringMode,
        'showRacingLine': RaceEngineState.showRacingLine,
        'soundEnabled': F1SoundEngine.soundEnabled,
        'eco60FpsMode': RaceEngineState.eco60FpsMode,
        'aiDifficultyLevel': RaceEngineState.aiDifficultyLevel.clamp(0, 4).toInt(),
        'cockpitCamera': defaultCockpitCamera,
        'selectedLiveryIndex': selectedLiveryIndex.clamp(0, kLiveries.length - 1).toInt(),
        'bestPositions': _encodeIntMap(bestPositionByRound),
        'pointsByRound': _encodeIntMap(pointsByRound),
        'sync': syncFlush,
      });
    } catch (_) {}
  }
}

