class TrackGeometry {
  final List<Offset> smoothPoints;
  final List<double> cumulativeLen;
  final double totalArcLen;
  final List<double> kappaSamples;      // EXACT physical Euclidean curvature in radians/meter (integral = +-360 deg!)
  final List<double> curvatureSamples;  // Normalized curvature index (kappa / 0.015) for HUD/UI cues
  final List<double> idealLineSamples;
  final List<double> targetSpeedSamples;
  final List<double> runoffLeftSamples;   // Real meters from left track edge to left barrier (flares smoothly at corners!)
  final List<double> runoffRightSamples;  // Real meters from right track edge to right barrier (pit wall on main straight!)
  static const int sampleCount = 1200;

  TrackGeometry._({
    required this.smoothPoints,
    required this.cumulativeLen,
    required this.totalArcLen,
    required this.kappaSamples,
    required this.curvatureSamples,
    required this.idealLineSamples,
    required this.targetSpeedSamples,
    required this.runoffLeftSamples,
    required this.runoffRightSamples,
  });

  factory TrackGeometry.fromWaypoints(
    List<Offset> raw, {
    double lapLengthMeters = 5000.0,
    double straightRunoffMeters = 8.0,
    double cornerRunoffMeters = 22.0,
    bool isStreetCircuit = false,
  }) {
    // Sample directly along the exact FIA waypoint polyline (exact tangent circular arcs + laser-straightaways!)
    final List<Offset> pts = List<Offset>.from(raw);
    final List<double> cumLen = [0.0];
    double total = 0.0;
    for (int i = 0; i < pts.length; i++) {
      final Offset a = pts[i];
      final Offset b = pts[(i + 1) % pts.length];
      total += (b - a).distance;
      cumLen.add(total);
    }

    final double ds = lapLengthMeters / sampleCount;
    final List<Offset> uniform = [];
    for (int s = 0; s < sampleCount; s++) {
      final double target = (s / sampleCount) * total;
      uniform.add(_pointAtArc(pts, cumLen, target));
    }

    // 1. Exact discrete Euclidean turning angle dTheta[i] / ds -> TRUE physical curvature kappa(s) in rad/m!
    // Integral sum(rawKappa[i] * ds) == +-2*pi (+-360.0 deg for closed loops, 0.0 deg for Suzuka figure-8!)
    final List<double> rawKappa = List<double>.filled(sampleCount, 0.0);
    for (int i = 0; i < sampleCount; i++) {
      final Offset p0 = uniform[(i - 1 + sampleCount) % sampleCount];
      final Offset p1 = uniform[i];
      final Offset p2 = uniform[(i + 1) % sampleCount];
      final Offset v1 = p1 - p0;
      final Offset v2 = p2 - p1;
      final double cross = v1.dx * v2.dy - v1.dy * v2.dx;
      final double dot = v1.dx * v2.dx + v1.dy * v2.dy;
      final double dTheta = atan2(cross, dot);
      rawKappa[i] = dTheta / ds;
    }

    // Conservative 5-tap smoothing (weights sum to 1.0 -> preserves 100% of every corner's exact angle & 0.000 straights!)
    List<double> smoothKappa = List<double>.filled(sampleCount, 0.0);
    for (int i = 0; i < sampleCount; i++) {
      smoothKappa[i] = (rawKappa[(i - 2 + sampleCount) % sampleCount] * 0.12) +
          (rawKappa[(i - 1 + sampleCount) % sampleCount] * 0.22) +
          (rawKappa[i] * 0.32) +
          (rawKappa[(i + 1) % sampleCount] * 0.22) +
          (rawKappa[(i + 2) % sampleCount] * 0.12);
    }

    // Angle-preserving radius floor (k_cap = 0.072 rad/m => R_min = 13.9m, exact real F1 hairpin centerline radius!).
    // Any polyline spike tighter than 13.9m redistributes ONLY the excess angle to immediate arc neighbors ->
    // 100.00% of every corner's exact real angle (90 deg, 180 deg, etc.) is mathematically preserved!
    const double kCap = 0.072;
    for (int pass = 0; pass < 96; pass++) {
      bool changed = false;
      final List<double> nxt = List<double>.from(smoothKappa);
      for (int i = 0; i < sampleCount; i++) {
        final double kv = smoothKappa[i];
        if (kv.abs() > kCap) {
          final double excess = kv - (kv.sign * kCap);
          nxt[i] -= excess;
          nxt[(i - 1 + sampleCount) % sampleCount] += excess * 0.5;
          nxt[(i + 1) % sampleCount] += excess * 0.5;
          changed = true;
        }
      }
      smoothKappa = nxt;
      if (!changed) break;
    }

    // Clean micro floating-point noise on straightaways (R > 5500m -> strictly 0.0000 rad/m laser-straight!)
    for (int i = 0; i < sampleCount; i++) {
      if (smoothKappa[i].abs() < 0.00018) {
        smoothKappa[i] = 0.0;
      }
    }

    final List<double> normCurv = List<double>.generate(
      sampleCount,
      (i) => (smoothKappa[i] / 0.015).clamp(-5.0, 5.0).toDouble(),
    );

    // 2. Solve exact max F1 cornering speed per sample matching TRUE 1:1 Euclidean curvature kappa(s)!
    final List<double> vLimitMs = List<double>.filled(sampleCount, 360.0 / 3.6);
    for (int i = 0; i < sampleCount; i++) {
      final double ak = smoothKappa[i].abs();
      if (ak >= 0.0012) {
        double lo = 45.0;
        double hi = 360.0;
        for (int iter = 0; iter < 14; iter++) {
          final double mid = 0.5 * (lo + hi);
          final double v = mid / 3.6;
          final double roadYaw = v * ak;
          final double aLat = 54.0 + 24.0 * (mid / 280.0).clamp(0.0, 1.0).toDouble();
          final double maxYaw = min(v * 0.125, aLat / max(v, 4.0));
          if (maxYaw * 0.88 >= roadYaw) {
            lo = mid;
          } else {
            hi = mid;
          }
        }
        vLimitMs[i] = lo / 3.6;
      }
    }

    // 3. Circular backward-braking envelope matched to progressive gradual F1 braking (~105-115m from 320->80 km/h)
    const double brakeDecelMs2 = 34.0;
    for (int pass = 0; pass < 2; pass++) {
      for (int i = sampleCount - 1; i >= 0; i--) {
        final double vNext = vLimitMs[(i + 1) % sampleCount];
        final double vAllow = sqrt(vNext * vNext + 2.0 * brakeDecelMs2 * ds);
        if (vAllow < vLimitMs[i]) {
          vLimitMs[i] = vAllow;
        }
      }
    }
    final List<double> targetSpeedKmh = List<double>.generate(
      sampleCount,
      (i) => (vLimitMs[i] * 3.6).clamp(48.0, 360.0).toDouble(),
    );

    // 4. Smooth FIA Out-In-Out Racing Line (outside on entry -> inside apex -> outside exit)
    final List<double> rawLine = List<double>.filled(sampleCount, 0.0);
    final int lookEntry = max(1, (85.0 / ds).round());
    final int lookExit = max(1, (65.0 / ds).round());
    for (int i = 0; i < sampleCount; i++) {
      final double kNow = smoothKappa[i];
      final double kIn = smoothKappa[(i + lookEntry) % sampleCount];
      final double kOut = smoothKappa[(i - lookExit + sampleCount) % sampleCount];
      if (kNow.abs() > 0.0055) {
        rawLine[i] = kNow.sign * min(0.76, 0.44 + (kNow.abs() / 0.055) * 0.32);
      } else if (kIn.abs() > 0.0070) {
        rawLine[i] = -kIn.sign * min(0.70, 0.36 + (kIn.abs() / 0.055) * 0.32);
      } else if (kOut.abs() > 0.0070) {
        rawLine[i] = -kOut.sign * min(0.64, 0.32 + (kOut.abs() / 0.055) * 0.28);
      } else {
        rawLine[i] = 0.0;
      }
    }
    List<double> smoothLine = List<double>.from(rawLine);
    for (int pass = 0; pass < 4; pass++) {
      final List<double> nxt = List<double>.filled(sampleCount, 0.0);
      for (int i = 0; i < sampleCount; i++) {
        double sum = 0.0;
        for (int k = -5; k <= 5; k++) {
          sum += smoothLine[(i + k + sampleCount) % sampleCount];
        }
        nxt[i] = sum / 11.0;
      }
      smoothLine = nxt;
    }

    // 5. Real Asymmetric Left & Right FIA Barrier Distances (Run-off / Gravel Trap Envelopes!)
    // Outside of right-hand corners (kappa > 0) widens LEFT barrier; outside of left-hand corners (kappa < 0) widens RIGHT barrier!
    // Braking zones flare out ~95m ahead of apexes and smoothly taper back after corner exit; Pit Wall tightens right edge on main straight.
    final List<double> rawRunL = List<double>.filled(sampleCount, straightRunoffMeters);
    final List<double> rawRunR = List<double>.filled(sampleCount, straightRunoffMeters);
    final int lookAheadBrake = max(1, (95.0 / ds).round());
    final int lookBehindExit = max(1, (45.0 / ds).round());
    final double pitWallMeters = isStreetCircuit
        ? max(straightRunoffMeters, 2.2)
        : min(straightRunoffMeters, 6.2);

    for (int i = 0; i < sampleCount; i++) {
      double peakRightTurn = 0.0; // kappa > 0 -> outside is LEFT
      double peakLeftTurn = 0.0;  // kappa < 0 -> outside is RIGHT
      for (int off = -lookBehindExit; off <= lookAheadBrake; off += 3) {
        final double kv = smoothKappa[(i + off + sampleCount) % sampleCount];
        final double wgt = off >= 0
            ? (1.0 - (off / (lookAheadBrake + 1.0)) * 0.35)
            : (1.0 - ((-off) / (lookBehindExit + 1.0)) * 0.45);
        if (kv > 0.0) {
          peakRightTurn = max(peakRightTurn, kv * wgt);
        } else if (kv < 0.0) {
          peakLeftTurn = max(peakLeftTurn, (-kv) * wgt);
        }
      }
      final double flareL = ((peakRightTurn - 0.0045) / 0.038).clamp(0.0, 1.0).toDouble();
      final double flareR = ((peakLeftTurn - 0.0045) / 0.038).clamp(0.0, 1.0).toDouble();
      // Inside of corner also widens slightly on permanent tracks for visibility
      final double insideL = isStreetCircuit ? 0.0 : (flareR * 0.16);
      final double insideR = isStreetCircuit ? 0.0 : (flareL * 0.16);

      double distL = straightRunoffMeters + (cornerRunoffMeters - straightRunoffMeters) * max(flareL, insideL);
      double distR = straightRunoffMeters + (cornerRunoffMeters - straightRunoffMeters) * max(flareR, insideR);

      // Authentic Pit Wall on the right side of the Start/Finish straight
      final double sMeters = i * ds;
      if (sMeters < 185.0 || sMeters > lapLengthMeters - 85.0) {
        distR = min(distR, pitWallMeters);
      }

      rawRunL[i] = distL;
      rawRunR[i] = distR;
    }

    // Smooth barrier transitions over ~35m so walls curve naturally without sudden kinks
    List<double> smoothRunL = List<double>.from(rawRunL);
    List<double> smoothRunR = List<double>.from(rawRunR);
    final int smoothRad = max(2, (16.0 / ds).round());
    for (int pass = 0; pass < 3; pass++) {
      final List<double> nxtL = List<double>.filled(sampleCount, straightRunoffMeters);
      final List<double> nxtR = List<double>.filled(sampleCount, straightRunoffMeters);
      final double denom = (smoothRad * 2 + 1).toDouble();
      for (int i = 0; i < sampleCount; i++) {
        double sumL = 0.0;
        double sumR = 0.0;
        for (int k = -smoothRad; k <= smoothRad; k++) {
          final int idx = (i + k + sampleCount) % sampleCount;
          sumL += smoothRunL[idx];
          sumR += smoothRunR[idx];
        }
        nxtL[i] = sumL / denom;
        nxtR[i] = sumR / denom;
      }
      smoothRunL = nxtL;
      smoothRunR = nxtR;
    }

    return TrackGeometry._(
      smoothPoints: pts,
      cumulativeLen: cumLen,
      totalArcLen: total,
      kappaSamples: smoothKappa,
      curvatureSamples: normCurv,
      idealLineSamples: smoothLine,
      targetSpeedSamples: targetSpeedKmh,
      runoffLeftSamples: smoothRunL,
      runoffRightSamples: smoothRunR,
    );
  }

  static Offset _pointAtArc(List<Offset> pts, List<double> cumLen, double target) {
    final int n = pts.length;
    for (int i = 0; i < n; i++) {
      if (target <= cumLen[i + 1] || i == n - 1) {
        final double segLen = max(1e-6, cumLen[i + 1] - cumLen[i]);
        final double t = ((target - cumLen[i]) / segLen).clamp(0.0, 1.0).toDouble();
        final Offset a = pts[i];
        final Offset b = pts[(i + 1) % n];
        return Offset(a.dx + (b.dx - a.dx) * t, a.dy + (b.dy - a.dy) * t);
      }
    }
    return pts.first;
  }

  Offset pointAtProgress(double normProgress) {
    final double wrapped = ((normProgress % 1.0) + 1.0) % 1.0;
    return _pointAtArc(smoothPoints, cumulativeLen, wrapped * totalArcLen);
  }

  double _sampleLinear(List<double> arr, double normProgress) {
    final double wrapped = ((normProgress % 1.0) + 1.0) % 1.0;
    final double exactIdx = wrapped * sampleCount;
    final int i0 = exactIdx.floor() % sampleCount;
    final int i1 = (i0 + 1) % sampleCount;
    final double frac = exactIdx - exactIdx.floor();
    return arr[i0] * (1.0 - frac) + arr[i1] * frac;
  }

  double kappaAtProgress(double normProgress) => _sampleLinear(kappaSamples, normProgress);
  double curvatureAtProgress(double normProgress) => _sampleLinear(curvatureSamples, normProgress);
  double idealLineAtProgress(double normProgress) => _sampleLinear(idealLineSamples, normProgress);
  double targetSpeedAtProgress(double normProgress) => _sampleLinear(targetSpeedSamples, normProgress);
  double runoffLeftAtProgress(double normProgress) => _sampleLinear(runoffLeftSamples, normProgress);
  double runoffRightAtProgress(double normProgress) => _sampleLinear(runoffRightSamples, normProgress);
}

/// Pre-baked 40-meter Track Sector Chunk (GTA 3 World-Streaming Model)
/// Loaded on-demand ahead of the player and unloaded/recycled immediately once passed!
class TrackStreamChunk {
  static const double chunkMeters = 40.0;
  static const int samples = 40; // 1.0 meter exact pre-baked resolution per sector!
  static const double samplesD = 40.0;

  int chunkId = -1;
  final Float64List kappa = Float64List(samples + 1);
  final Float64List hillElev = Float64List(samples + 1);
  final Float64List runoffLeftW = Float64List(samples + 1);
  final Float64List runoffRightW = Float64List(samples + 1);
  final Float64List idealLineW = Float64List(samples + 1);
  final Float64List targetSpeed = Float64List(samples + 1);
  final Uint8List heavyBraking = Uint8List(samples + 1);

  void bake(
    int id,
    CircuitInfo circuit,
    TrackGeometry geometry,
    double roadHalfWorldX,
    double laneToWorldX,
  ) {
    chunkId = id;
    final double lapLen = circuit.lapLengthMeters;
    final double baseDist = id * chunkMeters;
    final double hillScale = circuit.hillAmp * 2.15;
    final double roundOff = circuit.round.toDouble();

    for (int s = 0; s <= samples; s++) {
      final double d = baseDist + s;
      double r = d % lapLen;
      if (r < 0.0) r += lapLen;
      final double prog = r / lapLen;

      double rAhead = (d + 32.0) % lapLen;
      if (rAhead < 0.0) rAhead += lapLen;
      final double progAhead = rAhead / lapLen;

      kappa[s] = geometry.kappaAtProgress(prog);
      hillElev[s] = (sin(prog * pi * 4.0 + roundOff) * 0.68 +
              cos(prog * pi * 6.0 - roundOff * 0.6) * 0.32) *
          hillScale;
      runoffLeftW[s] = roadHalfWorldX + geometry.runoffLeftAtProgress(prog) * RaceEngineState.kMetersToWorldX;
      runoffRightW[s] = roadHalfWorldX + geometry.runoffRightAtProgress(prog) * RaceEngineState.kMetersToWorldX;
      idealLineW[s] = geometry.idealLineAtProgress(prog) * laneToWorldX;
      final double spdHere = geometry.targetSpeedAtProgress(prog);
      final double spdAhead = geometry.targetSpeedAtProgress(progAhead);
      targetSpeed[s] = spdHere;
      heavyBraking[s] = (spdHere - spdAhead) > 22.0 ? 1 : 0;
    }
  }
}

/// GTA 3-Style Dynamic World Streamer:
/// Keeps ONLY [-1 sector behind .. +6 sectors ahead] loaded in RAM (~320m sliding window),
/// automatically streaming new sectors in front and unloading passed sectors behind with zero GC stutter!
class TrackStreamManager {
  static const int sectorsBehind = 1;
  static const int sectorsAhead = 6;

  final CircuitInfo circuit;
  final TrackGeometry geometry;
  final double roadHalfWorldX;
  final double laneToWorldX;

  final Map<int, TrackStreamChunk> _active = {};
  final List<TrackStreamChunk> _pool = [];
  final List<int> _toUnloadScratch = [];
  int _centerChunkId = -999999;

  TrackStreamManager({
    required this.circuit,
    required this.geometry,
    required this.roadHalfWorldX,
    required this.laneToWorldX,
  });

  int get loadedSectorCount => _active.length;

  /// Advances the streaming window around `originDist`:
  /// unloads passed sectors behind (recycling their buffers) and streams in upcoming sectors ahead!
  void streamAround(double originDist) {
    final int curId = (originDist / TrackStreamChunk.chunkMeters).floor();
    if (curId == _centerChunkId && _active.isNotEmpty) return;
    _centerChunkId = curId;

    final int minId = curId - sectorsBehind;
    final int maxId = curId + sectorsAhead;

    // 1. UNLOAD sectors behind/outside the active streaming window & recycle buffers to pool (ZERO GC!)
    _toUnloadScratch.clear();
    for (final int id in _active.keys) {
      if (id < minId || id > maxId) {
        _toUnloadScratch.add(id);
      }
    }
    for (final int id in _toUnloadScratch) {
      final TrackStreamChunk? evicted = _active.remove(id);
      if (evicted != null) {
        _pool.add(evicted);
      }
    }

    // 2. LOAD & pre-bake new sectors entering the front of the streaming window!
    for (int id = minId; id <= maxId; id++) {
      if (!_active.containsKey(id)) {
        final TrackStreamChunk chunk = _pool.isNotEmpty ? _pool.removeLast() : TrackStreamChunk();
        chunk.bake(id, circuit, geometry, roadHalfWorldX, laneToWorldX);
        _active[id] = chunk;
      }
    }
  }

  TrackStreamChunk _chunkForDist(double worldDist) {
    final int id = (worldDist / TrackStreamChunk.chunkMeters).floor();
    final TrackStreamChunk? cached = _active[id];
    if (cached != null) return cached;
    final TrackStreamChunk chunk = _pool.isNotEmpty ? _pool.removeLast() : TrackStreamChunk();
    chunk.bake(id, circuit, geometry, roadHalfWorldX, laneToWorldX);
    _active[id] = chunk;
    return chunk;
  }

  double _sampleList(Float64List arr, double localMeters) {
    final double clamped = localMeters.clamp(0.0, TrackStreamChunk.samplesD).toDouble();
    final int i0 = clamped.floor();
    if (i0 >= TrackStreamChunk.samples) return arr[TrackStreamChunk.samples];
    final double frac = clamped - i0;
    return arr[i0] * (1.0 - frac) + arr[i0 + 1] * frac;
  }

  double kappaAt(double worldDist) {
    final TrackStreamChunk c = _chunkForDist(worldDist);
    return _sampleList(c.kappa, worldDist - c.chunkId * TrackStreamChunk.chunkMeters);
  }

  double hillAt(double worldDist) {
    final TrackStreamChunk c = _chunkForDist(worldDist);
    return _sampleList(c.hillElev, worldDist - c.chunkId * TrackStreamChunk.chunkMeters);
  }

  double runoffLeftAt(double worldDist) {
    final TrackStreamChunk c = _chunkForDist(worldDist);
    return _sampleList(c.runoffLeftW, worldDist - c.chunkId * TrackStreamChunk.chunkMeters);
  }

  double runoffRightAt(double worldDist) {
    final TrackStreamChunk c = _chunkForDist(worldDist);
    return _sampleList(c.runoffRightW, worldDist - c.chunkId * TrackStreamChunk.chunkMeters);
  }

  double idealLineAt(double worldDist) {
    final TrackStreamChunk c = _chunkForDist(worldDist);
    return _sampleList(c.idealLineW, worldDist - c.chunkId * TrackStreamChunk.chunkMeters);
  }

  double targetSpeedAt(double worldDist) {
    final TrackStreamChunk c = _chunkForDist(worldDist);
    return _sampleList(c.targetSpeed, worldDist - c.chunkId * TrackStreamChunk.chunkMeters);
  }

  bool isHeavyBrakingAt(double worldDist) {
    final TrackStreamChunk c = _chunkForDist(worldDist);
    final int rawIdx = (worldDist - c.chunkId * TrackStreamChunk.chunkMeters).round();
    final int idx = rawIdx.clamp(0, TrackStreamChunk.samples).toInt();
    return c.heavyBraking[idx] == 1;
  }

  void reset() {
    _pool.addAll(_active.values);
    _active.clear();
    _centerChunkId = -999999;
  }
}

/// Photorealistic 4K-Grade Procedural Pre-Baked GPU Material Suite
