        for (int row = 0; row < 32; row++) {
          for (int col = 0; col < 32; col++) {
            final double x = col * 8.0;
            final double y = row * 8.0;
            final int phase = (row + col) & 3;
            final bool warp = phase < 2;
            final Rect cell = Rect.fromLTWH(x + 0.30, y + 0.30, 7.4, 7.4);
