                ..shader = LinearGradient(
                  begin: warp ? Alignment.topLeft : Alignment.bottomLeft,
                  end: warp ? Alignment.bottomRight : Alignment.topRight,
                  stops: const [0.0, 0.34, 0.70, 1.0],
                  colors: warp
                      ? const [Color(0xFF667894), Color(0xFF2D3748), Color(0xFF121720), Color(0xFF07090E)]
                      : const [Color(0xFF394558), Color(0xFF1C2330), Color(0xFF0D1118), Color(0xFF06080C)],
                ).createShader(cell),
            );
            // Crisp specular resin micro-filament sheen lines inside each carbon tow
            c.drawLine(
              Offset(x + 1.0, y + (warp ? 1.4 : 6.2)),
              Offset(x + 6.8, y + (warp ? 6.2 : 1.4)),
              Paint()..color = Color.fromARGB(warp ? 78 : 34, 228, 240, 255)..strokeWidth = 0.85,
