            c.drawLine(
              Offset(x + 1.0, y + (warp ? 3.2 : 4.4)),
              Offset(x + 6.8, y + (warp ? 4.4 : 3.2)),
              Paint()..color = const Color(0x2E000000)..strokeWidth = 0.75,
            );
