  double get trackHalfWidthMeters => circuit.trackWidthMeters * 0.5;
  double get roadHalfWorldX => trackHalfWidthMeters * kMetersToWorldX;
  double get laneToWorldX => roadHalfWorldX;
  double get carCollisionDxLane => (2.04 / trackHalfWidthMeters).clamp(0.25, 0.50).toDouble();

