  RaceEngineState({
    required this.circuit,
    required this.livery,
  }) : geometry = TrackGeometry.fromWaypoints(
          circuit.waypoints,
          lapLengthMeters: circuit.lapLengthMeters,
          straightRunoffMeters: circuit.straightRunoffMeters,
