  /// Auto-calibrates AI pace on THIS exact circuit by comparing a 1-lap Reference Player Physics run
  /// (exact player accel, progressive carbon brakes, corner scrub, track width & street wall margin)
  /// against a 1-lap Reference AI run -> eliminates easy/impossible disparities (Australia vs Monaco/Jeddah)!
  double _calibrateCircuitAiPaceScale() {
    final double refPlayerSec = _simulateReferencePlayerLap();
    double lo = 0.62;
    double hi = 1.12;
    for (int iter = 0; iter < 8; iter++) {
      final double mid = 0.5 * (lo + hi);
      final double refAiSec = _simulateUnifiedAiLap(
        skill: 0.96,
        paceScale: mid,
        diffLevel: 2,
        standingStart: false,
      );
      if (refAiSec < refPlayerSec) {
        hi = mid;
      } else {
        lo = mid;
      }
    }
    return (0.5 * (lo + hi)).clamp(0.62, 1.08).toDouble();
  }

  double _simulateReferencePlayerLap() {
    double dist = 0.0;
    double spd = 240.0;
    double t = 0.0;
    const double dt = 0.025;
    double ers = 100.0;
    double bp = 0.0;

    int tightSamples = 0;
    for (int i = 0; i < TrackGeometry.sampleCount; i++) {
      if (geometry.kappaSamples[i].abs() > 0.016) tightSamples++;
    }
    final double tightFrac = tightSamples / TrackGeometry.sampleCount;
    final double widthFactor = (0.84 + ((circuit.trackWidthMeters - 9.0) / 6.0) * 0.18).clamp(0.84, 1.02).toDouble();
    final double streetPen = circuit.isStreetCircuit ? 0.945 : 1.0;
    final double twistPen = (1.0 - max(0.0, tightFrac - 0.14) * 0.30).clamp(0.91, 1.0).toDouble();
    final double humanCornerMult = widthFactor * streetPen * twistPen * 0.97;

    final double lapLen = circuit.lapLengthMeters;
    while (dist < lapLen && t < 240.0) {
      final double prog = (dist % lapLen) / lapLen;
      final double progAhead18 = ((dist + 18.0) % lapLen) / lapLen;
      final double progAhead45 = ((dist + 45.0) % lapLen) / lapLen;
      final double k0 = geometry.kappaAtProgress(prog).abs();
      final double k45 = geometry.kappaAtProgress(progAhead45).abs();
      final double vtHere = geometry.targetSpeedAtProgress(prog) * humanCornerMult;
      final double vtAhead = geometry.targetSpeedAtProgress(progAhead18) * humanCornerMult;
      final double des = min(vtHere, vtAhead);

      bool ersOn = (k0 < 0.0055 && k45 < 0.0075 && ers > 15.0 && spd < 358.0 && des > 265.0);
      if (spd > des + 4.0) {
        ersOn = false;
        bp = min(1.0, bp + 2.15 * dt);
        final double sb = pow(bp, 1.25).toDouble();
        final double decel = 52.0 + 132.0 * sb + 48.0 * sb * (spd / 320.0).clamp(0.0, 1.0).toDouble();
        spd = max(0.0, spd - decel * dt);
        ers = min(100.0, ers + (11.0 + 17.0 * bp) * dt);
      } else {
        bp = 0.0;
        final double maxSpd = ersOn ? 360.0 : 322.0;
        final double acc = ersOn ? 182.0 : 128.0;
        if (ersOn) {
          ers = max(0.0, ers - 21.0 * dt);
        } else {
          ers = min(100.0, ers + 6.8 * dt);
        }
        if (spd < min(maxSpd, des)) {
          spd = min(min(maxSpd, des), spd + acc * dt);
        } else {
          spd = max(0.0, spd - (38.0 + spd * 0.08) * dt);
        }
        if (k0 > 0.009 && spd > 125.0) {
          final double estSteer = ((k0 / 0.032) * (spd / 220.0)).clamp(0.0, 1.0).toDouble();
          if (estSteer > 0.52) {
            spd = max(0.0, spd - (estSteer - 0.52) * (spd / 320.0) * 24.0 * dt);
          }
        }
      }
      dist += (spd / 3.6) * dt;
      t += dt;
    }
    return max(15.0, t);
  }

  double _simulateUnifiedAiLap({
    required double skill,
    required double paceScale,
    required int diffLevel,
    required bool standingStart,
  }) {
    final int lvl = diffLevel.clamp(0, 4).toInt();
    double dist = 0.0;
    double spd = standingStart ? 0.0 : 240.0;
    double t = 0.0;
    const double dt = 0.025;
    double ers = standingStart ? 100.0 : 80.0;

    final bool eliteTier = lvl >= 3;
    final bool legendTier = lvl == 4;
    final double sNorm = ((skill - 0.78) / 0.21).clamp(0.0, 1.0).toDouble();
    final double lvlFrac = lvl / 4.0;
    final double baseTop = _aiTopMin[lvl] + (_aiTopMax[lvl] - _aiTopMin[lvl]) * sNorm;
    final double cornerCap = eliteTier ? 1.42 : 1.22;
    final double cornerMult = ((_aiCornerMin[lvl] + (_aiCornerMax[lvl] - _aiCornerMin[lvl]) * sNorm) * paceScale).clamp(0.55, cornerCap).toDouble();
    final double aiAccel = _aiAccelMin[lvl] + (_aiAccelMax[lvl] - _aiAccelMin[lvl]) * sNorm;
    final double aiErsAdd = _aiErsAccelAdd[lvl];
    final double aiBrake = _aiBrakeMin[lvl] + (_aiBrakeMax[lvl] - _aiBrakeMin[lvl]) * sNorm;
    final double ersCap = min(_aiErsCap[lvl], baseTop + (eliteTier ? 36.0 : (26.0 + 13.0 * lvlFrac)));
    final double ersMin = _aiErsMinCharge[lvl];
    final double lookMeters = legendTier ? 3.5 : (eliteTier ? 8.0 : 18.0);

    final double lapLen = circuit.lapLengthMeters;
    while (dist < lapLen && t < 240.0) {
      final double prog = (dist % lapLen) / lapLen;
      final double progAhead = ((dist + lookMeters) % lapLen) / lapLen;
      final double progAhead45 = ((dist + 45.0) % lapLen) / lapLen;
      final double k0 = geometry.kappaAtProgress(prog).abs();
      final double k45 = geometry.kappaAtProgress(progAhead45).abs();
      final double vtMin = min(
        geometry.targetSpeedAtProgress(prog) * cornerMult,
        geometry.targetSpeedAtProgress(progAhead) * cornerMult,
      );
      double des = min(baseTop, vtMin);

      final bool onStr = (k0 < (eliteTier ? 0.0080 : 0.0060) && k45 < (eliteTier ? 0.0095 : 0.0080));
      final bool exitLaunch = eliteTier && k0 < 0.0088 && spd < 280.0 && vtMin > spd + 14.0;
      bool drs = false;
      if ((onStr || exitLaunch) && ers > ersMin && vtMin > (eliteTier ? 125.0 : 235.0)) {
        drs = true;
        ers = max(0.0, ers - (legendTier ? 18.5 : 20.0) * dt);
        des = min(ersCap, vtMin);
      } else {
        final double regenRate = spd > des + 8.0
            ? (eliteTier ? 19.5 : 16.0)
            : (legendTier ? 8.4 : (eliteTier ? 7.8 : 7.2));
        ers = min(100.0, ers + regenRate * dt);
      }

      if (des > spd) {
        spd = min(des, spd + (aiAccel + (drs ? aiErsAdd : 0.0)) * dt);
      } else {
        spd = max(des, spd - aiBrake * dt);
      }
      dist += (spd / 3.6) * dt;
      t += dt;
    }
    return max(15.0, t);
  }

  void recalculateAiQualiTimes() {
    for (final ai in aiDrivers) {
      ai.qualiTimeSec = _simulateAiQualiLap(ai);
    }
    poleReferenceTime = aiDrivers.map((a) => a.qualiTimeSec).reduce((a, b) => min(a, b));
  }

  void _initDriversAndQualifyingTimes() {
    const List<Map<String, Object>> gridTemplates = [
      {'c': 'VER', 'b': Color(0xFF13245E), 'hl': Color(0xFF436BE6), 'w': Color(0xFFE10600), 'h': Color(0xFFFF6D00), 'sk': 0.99, 'ag': 0.96, 'df': 0.95},
