  /// Unified auto-calibrated 1-lap qualifying simulation (identical physics & fairness across all 24 circuits!)
  double _simulateAiQualiLap(AiDriver ai) {
    final double baseLap = _simulateUnifiedAiLap(
      skill: ai.skill,
      paceScale: circuitAiPaceScale,
      diffLevel: aiDifficultyLevel,
      standingStart: true,
    );
    final double variance = (rng.nextDouble() - 0.45) * 0.36;
    return max(15.0, baseLap + variance);
  }

