        ai.overtakeCommitTimer = 0.0;
        ai.evadeSide = 0.0;
        ai.evadeLockTimer = 0.0;
        ai.defenseCooldown = 0.0;
        ai.defenseHoldTimer = 0.0;
        ai.defenseTargetX = startLane;
        final int dLvl = aiDifficultyLevel.clamp(0, 4).toInt();
        if (dLvl == 4) {
          ai.launchDelay = ((1.0 - ai.skill) * 0.05) + rng.nextDouble() * 0.025;
        } else if (dLvl == 3) {
          ai.launchDelay = 0.02 + ((1.0 - ai.skill) * 0.09) + rng.nextDouble() * 0.045;
        } else {
          ai.launchDelay = _aiLaunchBaseDelay[dLvl] + ((1.0 - ai.skill) * (0.24 - dLvl * 0.04)) + rng.nextDouble() * (0.10 - dLvl * 0.015);
        }
