  int get currentLap {
    if (phase == SessionPhase.qualifying) return 1;
    // Exact visual Start/Finish line synchronization: Lap increments the exact millisecond you cross `N * lapLengthMeters`!
    return ((playerDist / circuit.lapLengthMeters).floor() + 1).clamp(1, totalLaps).toInt();
  }

  double get lapProgress => (playerDist % circuit.lapLengthMeters) / circuit.lapLengthMeters;
  static const List<double> _gearTops = [0.0, 96.0, 138.0, 178.0, 216.0, 252.0, 288.0, 322.0, 372.0];

  int get gear {
    if (speedKmh < 2.0) return 1;
    for (int g = 1; g <= 8; g++) {
      if (speedKmh <= _gearTops[g]) return g;
    }
    return 8;
  }

  int get rpm => _engineRpm.clamp(3800.0, 14200.0).toInt();

  void _updateEngineRpm(double dt, {required bool onGrid}) {
    _downshiftBlip *= exp(-9.5 * dt);
    final bool curThrottleOn = gasHeld && !brakeHeld;
    if (_prevThrottleOn && !curThrottleOn && _engineRpm > 9000.0) {
      F1SoundEngine.playEvent('wastegate');
    }
    _prevThrottleOn = curThrottleOn;
    if (onGrid || speedKmh < 2.0) {
      // Realistic free-revving on the starting grid with rev-limiter bounce!
      if (gasHeld && !brakeHeld) {
        _engineRpm = min(13200.0, _engineRpm + 14500.0 * dt);
        if (_engineRpm >= 12750.0) {
          _revLimiterPhase += dt * 19.0;
          _engineRpm = 12450.0 + sin(_revLimiterPhase * pi * 2.0) * 420.0;
        }
      } else {
        _engineRpm = max(4100.0, _engineRpm - 9200.0 * dt);
      }
      return;
    }

    final int g = gear;
    final double lo = _gearTops[g - 1];
    final double hi = _gearTops[g];
    final double frac = ((speedKmh - lo) / max(1.0, hi - lo)).clamp(0.0, 1.0).toDouble();
    // Wide, dramatic F1 V6 RPM sweep per gear: 7,800 -> 13,400 RPM (+600 on ERS)
    double wheelRpm = g == 1
        ? (4300.0 + frac * 9100.0)
        : (7800.0 + frac * 5600.0);
    if (ersActive) wheelRpm += 550.0;
    if (!gasHeld && !brakeHeld) wheelRpm -= 450.0;
    final double targetRpm = (wheelRpm + _downshiftBlip).clamp(3900.0, 14100.0).toDouble();
    final double followRate = targetRpm > _engineRpm ? 18.0 : 12.0;
    _engineRpm += (targetRpm - _engineRpm) * (1.0 - exp(-followRate * dt));
  }
  bool get ersActive => ersToggledOn && ersCharge > 0.5 && gasHeld && !brakeHeld;

  int get currentPosition {
    if (phase == SessionPhase.qualifying) {
      // Live projected grid position based on current pace vs Pole reference
      if (qualiElapsed <= 0.1) return 1;
      final double progress = (playerDist / circuit.lapLengthMeters).clamp(0.02, 1.0).toDouble();
      final double projectedTotal = qualiElapsed / progress;
      int faster = 0;
      for (final ai in aiDrivers) {
        if (ai.qualiTimeSec < projectedTotal) faster++;
      }
      return (faster + 1).clamp(1, totalCars).toInt();
    }
    int ahead = 0;
    for (final ai in aiDrivers) {
      if (ai.trackDist > playerDist) ahead++;
    }
    return (ahead + 1).clamp(1, totalCars).toInt();
  }

  void showRadio(String msg, {double secs = 2.4}) {
    radioMessage = msg;
    radioTimer = secs;
  }

  void spawnParticles(Color color, int count, {bool sparks = false}) {
    for (int i = 0; i < count; i++) {
      particles.add(
        TrackParticle(
          x: 0.25 + rng.nextDouble() * 0.5,
          y: 0.62 + rng.nextDouble() * 0.22,
          vx: (rng.nextDouble() - 0.5) * (sparks ? 1.65 : 0.72),
          vy: (sparks ? -0.58 : -0.22) - rng.nextDouble() * 0.45,
          life: 0.30 + rng.nextDouble() * 0.32,
          color: color,
          radius: sparks ? (2.1 + rng.nextDouble() * 2.4) : (3.0 + rng.nextDouble() * 4.2),
          isSpark: sparks,
        ),
      );
    }
  }

  double _kappaAtDist(double dist) {
    final double prog = (dist % circuit.lapLengthMeters) / circuit.lapLengthMeters;
    return geometry.kappaAtProgress(prog);
  }

  double _curvatureAtDist(double dist) {
    final double prog = (dist % circuit.lapLengthMeters) / circuit.lapLengthMeters;
    return geometry.curvatureAtProgress(prog);
  }

  /// Returns: 0 = running, 1 = qualifying finished, 2 = race finished
  int step(double dt) {
    if (raceFinished || isPaused || phase == SessionPhase.gridOverview) return 0;

    if (resumeCountdownTimer > 0.0) {
      final double prevResume = resumeCountdownTimer;
      resumeCountdownTimer = max(0.0, resumeCountdownTimer - dt);
      final int currentSec = resumeCountdownTimer.ceil();
      if (currentSec > 0 && currentSec < _lastResumeCount) {
        _lastResumeCount = currentSec;
        F1SoundEngine.playEvent('light');
      }
      if (prevResume > 0.0 && resumeCountdownTimer == 0.0) {
        _lastResumeCount = 0;
        F1SoundEngine.playEvent('go');
      }
      notifyListeners();
      return 0;
    }

    if (radioTimer > 0) {
      radioTimer = max(0.0, radioTimer - dt);
      if (radioTimer == 0) radioMessage = '';
    }

    if (startLightsTimer > 0) {
      final double prevTimer = startLightsTimer;
      startLightsTimer = max(0.0, startLightsTimer - dt);
      final double totalCountdown = phase == SessionPhase.qualifying ? 2.2 : 3.2;
      int litCount = 0;
      for (int idx = 0; idx < 5; idx++) {
        if (startLightsTimer < (totalCountdown - 0.15 - idx * (totalCountdown * 0.15))) {
          litCount++;
        }
      }
      if (litCount > _lastLitStartLights) {
        _lastLitStartLights = litCount;
        F1SoundEngine.playEvent('light');
      }
      if (prevTimer > 0.0 && startLightsTimer == 0.0) {
        F1SoundEngine.playEvent('go');
      }
      // Free-rev V6 engine on the grid while waiting for lights out!
      _updateEngineRpm(dt, onGrid: true);
      _audioUpdateAcc += dt;
      if (_audioUpdateAcc >= 0.040) {
        _audioUpdateAcc = 0.0;
        F1SoundEngine.update(
          rpm: _engineRpm,
          speed: 0.0,
          throttle: gasHeld && !brakeHeld,
          brake: brakeHeld,
          ers: false,
          offTrack: false,
          onKerb: false,
          slip: 0.0,
          active: true,
        );
      }
      notifyListeners();
      return 0;
    }

    if (phase == SessionPhase.qualifying) {
      qualiElapsed += dt;
    } else {
      totalRaceTime += dt;
    }

    for (int i = particles.length - 1; i >= 0; i--) {
      final TrackParticle p = particles[i];
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vy += 1.45 * dt;
      p.life -= dt;
      if (p.life <= 0) particles.removeAt(i);
    }

    prevPlayerDist = playerDist;
    final double prevSpeedKmh = speedKmh;

    // Crisp Carbon-Ceramic F1 Brakes: responsive initial bite & full stopping power in ~0.46s, instant lift release!
    if (brakeHeld) {
      brakePressure = (brakePressure + 2.15 * dt).clamp(0.0, 1.0).toDouble();
    } else {
      brakePressure = 0.0;
    }

    if (brakeHeld && ersToggledOn) {
      ersToggledOn = false;
    }

    final bool ersOn = ersActive;
    if (ersOn) {
      ersCharge = max(0.0, ersCharge - 21.0 * dt);
      if (ersCharge <= 0.5) {
        ersToggledOn = false;
        showRadio('BATERÍA ERS AGOTADA', secs: 1.8);
      }
    } else {
      final double rechargeRate = brakeHeld ? (11.0 + 17.0 * brakePressure) : 6.8;
      ersCharge = min(100.0, ersCharge + rechargeRate * dt);
    }

    // Player aerodynamic slipstream (only during Race when rivals are on track)
    playerInSlipstream = false;
    if (phase == SessionPhase.race && speedKmh > 150.0 && !brakeHeld) {
      for (final ai in aiDrivers) {
        final double dz = ai.trackDist - playerDist;
        if (dz > 6.0 && dz < 42.0 && (ai.laneX - carX).abs() < 0.36) {
          playerInSlipstream = true;
          break;
        }
      }
    }

    // 100% Manual Throttle & Progressive Gradual Braking (ZERO auto-gas, smooth modular deceleration!)
    final bool effectivelyAccelerating = gasHeld && !brakeHeld;
    final double slipBonus = playerInSlipstream ? 16.0 : 0.0;
    final double maxSpeed = (ersOn ? 360.0 : 322.0) + slipBonus;

    double targetPitch = 0.0;
    if (effectivelyAccelerating) {
      final double accel = (ersOn ? 182.0 : 128.0) + (playerInSlipstream ? 18.0 : 0.0);
      speedKmh = min(maxSpeed, speedKmh + accel * dt);
      targetPitch = ersOn ? -1.0 : -0.35;
    } else if (brakeHeld) {
      // Predictable Carbon-Ceramic F1 Braking: short taps smoothly trim speed, sustained holds nail heavy braking zones!
      final double shapedBrake = pow(brakePressure, 1.25).toDouble();
      final double aeroBrakeBonus = 48.0 * shapedBrake * (speedKmh / 320.0).clamp(0.0, 1.0).toDouble();
      final double brakeDecel = 52.0 + (132.0 * shapedBrake) + aeroBrakeBonus;
      speedKmh = max(0.0, speedKmh - brakeDecel * dt);
      targetPitch = speedKmh > 25 ? (0.20 + 0.80 * brakePressure) : 0.0;
    } else {
      // Natural engine braking & aerodynamic drag all the way down to 0 km/h
      speedKmh = max(0.0, speedKmh - (38.0 + speedKmh * 0.08) * dt);
    }

    smoothPitch += (targetPitch - smoothPitch) * (1.0 - exp(-9.0 * dt));
    final double targetFov = ((speedKmh - 140.0) / 220.0).clamp(0.0, 1.0).toDouble() + (ersOn ? 0.25 : 0.0);
    smoothFovBoost += (targetFov - smoothFovBoost) * (1.0 - exp(-5.0 * dt));

    // 100% MANUAL PRO-PRECISION F1 STEERING (Planted Rails Grip + Pneumatic Caster + Instant Counter-Steer!)
    final double sens = steerSensitivity.clamp(0.50, 2.50).toDouble();
    final double realKappa = geometry.kappaAtProgress(lapProgress); // EXACT real FIA curvature in rad/m!
    double targetSteer = 0.0;
    if (analogSteerTarget != null) {
      targetSteer = analogSteerTarget!.clamp(-1.0, 1.0).toDouble();
    } else {
      if (leftHeld) targetSteer -= 1.0;
      if (rightHeld) targetSteer += 1.0;
    }

    // Ultra-Responsive Dual-Stage Steering Rack:
    // - Analog slider: direct thumb-locked response (30/s) with surgical center control
    // - Digital < > buttons: smooth micro-tap precision near center, fast apex lock-in, & instant snap-back on release!
    if (analogSteerTarget != null) {
      steerAngle += (targetSteer - steerAngle) * (1.0 - exp(-30.0 * dt));
    } else {
      final bool inPrecisionZone = (steerAngle.abs() < 0.32) && (targetSteer * steerAngle >= 0.0) && (realKappa.abs() < 0.010);
      final double baseRamp = inPrecisionZone ? (6.8 + 7.6 * sens) : (12.8 + 12.2 * sens);
      final double rampInRate = baseRamp.clamp(7.0, 34.0).toDouble();
      final double counterSteerRate = (28.0 + 10.0 * sens).clamp(28.0, 44.0).toDouble();
      final double returnRate = (24.0 + 8.0 * sens).clamp(24.0, 38.0).toDouble();
      final double steerRate = targetSteer.abs() > 0.01
          ? (targetSteer * steerAngle >= 0.0 ? rampInRate : counterSteerRate)
          : returnRate;
      steerAngle += (targetSteer - steerAngle) * (1.0 - exp(-steerRate * dt));
    }

    if (controlRecoveryTimer > 0) {
      controlRecoveryTimer = max(0.0, controlRecoveryTimer - dt);
    }

    final bool offTrack = carX.abs() > 1.02;
    final bool inGravel = isInGravelAt(carX, lapProgress);
    final bool onGrass = isOnGrassAt(carX, lapProgress);
    final double vMs = speedKmh / 3.6;
    final double speedMoveScale = (speedKmh / 4.2).clamp(0.0, 1.0).toDouble();
    // Smart Rejoin Grip: steering back toward the asphalt from off-track retains reliable traction so you never get stuck!
    final bool steeringBackOnTrack = offTrack && (steerAngle * carX < -0.04);
    final double surfaceGrip = steeringBackOnTrack
        ? 0.94
        : (inGravel ? 0.80 : (onGrass ? 0.86 : (offTrack ? 0.95 : 1.0)));
    final double gripMult = surfaceGrip * (controlRecoveryTimer > 0 ? 0.90 : 1.0);

    // High-Downforce F1 Aero & Mechanical Front-End Bite + Trail-Braking Load Transfer (+24% sharper turn-in on brakes!)
    final double sensMult = 0.56 + 0.44 * sens;
    final double trailBrakeBite = 1.0 + 0.24 * brakePressure;
    final double speedFrac = (speedKmh / 280.0).clamp(0.0, 1.0).toDouble();
    final double aLatMax = (64.0 + 28.0 * speedFrac) * gripMult * sensMult * trailBrakeBite;
    final double omegaMech = max(vMs, 3.2) * (0.148 * sensMult * trailBrakeBite) * speedMoveScale;
    final double omegaGrip = (aLatMax / max(vMs, 4.0)) * speedMoveScale;
    final double maxManualYawRate = min(omegaMech, omegaGrip);

    final double absSteer = steerAngle.abs();
    // Smooth speed-adaptive linearity: calm micro-corrections at 300+ km/h, nimble immediate turn-in at hairpins!
    final double curveExp = (1.30 - 0.16 * sens + 0.12 * speedFrac).clamp(0.95, 1.42).toDouble();
    final double signedSteerCurve = steerAngle.sign * pow(absSteer, curveExp).toDouble();
    // +52% crisp counter-steer recovery bite when actively steering opposite to current heading!
    final double counterCatchMult = (steerAngle * carHeading < -0.003) ? 1.52 : 1.0;
    final double manualYawRate = signedSteerCurve * maxManualYawRate * counterCatchMult;

    // Gentle natural F1 tire cornering scrub when holding deep lock at high speed -> helps rotate cleanly onto the apex!
    if (absSteer > 0.52 && speedKmh > 125.0 && !brakeHeld) {
      final double cornerScrub = (absSteer - 0.52) * (speedKmh / 320.0) * 24.0;
      speedKmh = max(0.0, speedKmh - cornerScrub * dt);
    }

    // 100% EXACT EUCLIDEAN ROAD CURVATURE (ZERO auto-driving! Releasing steering on a curve still travels straight off!)
    final double roadYawRate = vMs * realKappa;
    carHeading = carHeading + (manualYawRate - roadYawRate) * dt;

    // Real F1 Pneumatic Caster & Anti-Fishtail Chassis Stability:
    // 1. On straights/gentle bends when you lift off steering: snaps straight cleanly (zero ping-pong wobble!)
    // 2. On corner exit when you lift while still angled inward: gently unwinds excess inward angle back to straight (never auto-turns!)
    // 3. During active cornering: caps excessive over-rotation so holding turn carves smooth apexes without diving into inside walls!
    if (targetSteer.abs() < 0.01 && speedKmh > 8.0) {
      if (realKappa.abs() < 0.0045) {
        carHeading *= exp(-8.5 * dt);
      } else if (carHeading * realKappa > 0.0) {
        carHeading *= exp(-5.5 * dt);
      }
    } else if (targetSteer.abs() > 0.01 && targetSteer * realKappa > 0.003) {
      final double steerDir = targetSteer >= 0.0 ? 1.0 : -1.0;
      if (carHeading * steerDir > 0.26) {
        carHeading -= (carHeading - steerDir * 0.26) * (1.0 - exp(-8.5 * dt));
      }
    }
    carHeading = carHeading.clamp(-0.44, 0.44).toDouble();

    // Exact 1:1 lateral kinematics matching THIS circuit's real FIA track width (e.g. 9.0m Monaco vs 15.0m COTA/Shanghai!)
    impactLatVel *= exp(-7.2 * dt);
    lateralVel = (vMs * sin(carHeading)) / trackHalfWidthMeters;
    final double totalLatVel = lateralVel + impactLatVel;
    carX += totalLatVel * dt;
    spinYaw *= exp(-6.5 * dt);

    // Live Off-Track Detection & Surface Classification for Instant HUD Warning!
    final bool nowOffTrack = carX.abs() > 1.02;
    offTrackStateChanged = (nowOffTrack != isOffTrack);
    isOffTrack = nowOffTrack;
    if (nowOffTrack) {
      offTrackTime += dt;
      offTrackSurface = isInGravelAt(carX, lapProgress)
          ? 'GRAVA'
          : (isOnGrassAt(carX, lapProgress) ? 'CÉSPED' : 'LÍMITES DE PISTA');
    } else {
      offTrackTime = 0.0;
      offTrackSurface = '';
    }

    // Sky/Horizon rotates strictly from YOUR manual steering rotation (continuous double -> ZERO wrap teleports!)
    horizonPan -= manualYawRate * dt * 420.0;

    // Real-Life F1 G-Force Head Inertia, Spring-Damped Suspension Heave & Thermal Brake/Tire Simulation!
    final double targetLook = steerAngle * (speedKmh / 240.0).clamp(0.15, 1.0).toDouble();
    smoothSteerLook += (targetLook - smoothSteerLook) * (1.0 - exp(-9.5 * dt));
    final double targetBank = steerAngle * 0.026;
    smoothCamBank += (targetBank - smoothCamBank) * (1.0 - exp(-9.0 * dt));

    // Real lateral & longitudinal G-forces smoothed with human neck/helmet compliance
    final double rawLatG = ((manualYawRate * vMs) / 48.0).clamp(-1.15, 1.15).toDouble();
    smoothLatG += (rawLatG - smoothLatG) * (1.0 - exp(-8.0 * dt));
    final double accelKmhS = (speedKmh - prevSpeedKmh) / max(dt, 0.004);
    final double rawLongG = (accelKmhS / 195.0).clamp(-1.25, 1.0).toDouble();
    smoothLongG += (rawLongG - smoothLongG) * (1.0 - exp(-7.5 * dt));

    // Silky filtered 3D hill slope & spring-damped cockpit suspension heave
    final double lapL = circuit.lapLengthMeters;
    final double pNow = (playerDist % lapL) / lapL;
    final double pAhead = ((playerDist + 10.0) % lapL) / lapL;
    final double hNow = (sin(pNow * pi * 4.0 + circuit.round) * 0.68 + cos(pNow * pi * 6.0 - circuit.round * 0.6) * 0.32) * (circuit.hillAmp * 2.15);
    final double hAhead = (sin(pAhead * pi * 4.0 + circuit.round) * 0.68 + cos(pAhead * pi * 6.0 - circuit.round * 0.6) * 0.32) * (circuit.hillAmp * 2.15);
    final double rawSlope = ((hAhead - hNow) / 10.0).clamp(-0.22, 0.22).toDouble();
    smoothHillSlope += (rawSlope - smoothHillSlope) * (1.0 - exp(-7.0 * dt));

    final bool onKerbSmooth = carX.abs() > 0.86 && carX.abs() <= 1.06 && speedKmh > 35.0;
    final double roughShake = (inGravel || onGrass) && speedKmh > 25.0
        ? (sin(playerDist * 3.1) * 3.8 * (speedKmh / 180.0).clamp(0.2, 1.0).toDouble())
        : (onKerbSmooth ? sin(playerDist * 4.6) * 2.2 : 0.0);
    final double roadMicro = sin(playerDist * 0.85) * (speedKmh / 320.0) * 1.15;
    if (shiftKickTimer > 0.0) {
      shiftKickTimer = max(0.0, shiftKickTimer - dt);
    }
    final double shiftKickPx = shiftKickTimer > 0.0 ? (sin((shiftKickTimer / 0.14) * pi) * (shiftWasUp ? 2.4 : -1.8)) : 0.0;
    final double targetHeave = roadMicro + roughShake + (smoothLongG * -3.6) + shiftKickPx;
    smoothCockpitHeave += (targetHeave - smoothCockpitHeave) * (1.0 - exp(-18.0 * dt));

    // Carbon brake thermal glow (heats quickly under heavy braking, cools realistically after lift!)
    final double brakeHeatTarget = (brakeHeld && speedKmh > 45.0)
        ? (brakePressure * (speedKmh / 240.0).clamp(0.35, 1.0).toDouble())
        : 0.0;
    final double brakeRate = brakeHeatTarget > smoothBrakeHeat ? 6.5 : 1.65;
    smoothBrakeHeat += (brakeHeatTarget - smoothBrakeHeat) * (1.0 - exp(-brakeRate * dt));

    // Live Pirelli slick tire heat (warms up under high lateral G & braking, settles to optimal green on straights)
    final double tireTarget = (0.36 + smoothLatG.abs() * 0.44 + smoothBrakeHeat * 0.24).clamp(0.25, 1.0).toDouble();
    smoothTireHeat += (tireTarget - smoothTireHeat) * (1.0 - exp(-0.95 * dt));

    // Smooth real-time Monaco Tunnel, Yas Hotel Canopy, overhead bridge shadow & night floodlight sweep!
    final double lapDNow = playerDist % lapL;
    final bool inMonacoTunnel = circuit.code == 'MON' && pNow >= 0.42 && pNow <= 0.52;
    final bool underYasHotel = circuit.code == 'ABU' && pNow >= 0.72 && pNow <= 0.77;
    final bool underSpan = inMonacoTunnel || underYasHotel || (lapDNow < 8.5 || lapDNow > lapL - 4.0) || ((lapDNow % 380.0) < 11.0);
    final double targetShade = inMonacoTunnel ? 1.35 : (underYasHotel ? 0.78 : (underSpan ? 1.0 : 0.0));
    smoothBridgeShade += (targetShade - smoothBridgeShade) * (1.0 - exp(-14.0 * dt));
    final bool inTunnelLight = inMonacoTunnel && ((playerDist / 11.0).floor() % 2 == 0);
    final bool inFlood = inTunnelLight || underYasHotel || (circuit.nightMode && !underSpan && ((playerDist / 1.75).floor() % 9 < 2));
    smoothFloodGlow += ((inFlood ? 1.0 : 0.0) - smoothFloodGlow) * (1.0 - exp(-12.0 * dt));

    final double wallLimL = wallLimitLaneLeftAtProgress(lapProgress);
    final double wallLimR = wallLimitLaneRightAtProgress(lapProgress);
    final double activeWallLim = carX < 0.0 ? wallLimL : wallLimR;
    if (offTrack) {
      // Gentle off-track rolling resistance so going wide costs pace without slamming the brakes or bogging you down!
      if (inGravel) {
        speedKmh = max(0.0, speedKmh - (38.0 + speedKmh * 0.16) * dt);
        if (speedKmh > 35.0 && rng.nextDouble() < 0.60) {
          spawnParticles(const Color(0xFFD2B88C), 3);
        }
      } else if (onGrass) {
        speedKmh = max(0.0, speedKmh - (22.0 + speedKmh * 0.10) * dt);
        if (speedKmh > 55.0 && rng.nextDouble() < 0.38) {
          spawnParticles(const Color(0xFF4F7A38), 2);
        }
      } else {
        // Painted FIA tarmac runoff: very light drag so you can rejoin cleanly
        speedKmh = max(0.0, speedKmh - (8.0 + speedKmh * 0.03) * dt);
      }
      if (carX.abs() >= activeWallLim) {
        final double wallSign = carX >= 0 ? 1.0 : -1.0;
        carX = wallSign * activeWallLim;
        final double intoWallAngle = carHeading * wallSign;
        final bool pushingIntoWall = (intoWallAngle > 0.02) || (targetSteer * wallSign >= 0.0);
        if (intoWallAngle > 0.14 && speedKmh > 40.0) {
          final double impactSeverity = (intoWallAngle * 1.8).clamp(0.32, 1.0).toDouble();
          speedKmh = max(0.0, speedKmh * (0.68 - impactSeverity * 0.34));
          carHeading = -wallSign * 0.04;
          impactLatVel = -wallSign * 0.12;
          spinYaw = -wallSign * (0.10 + impactSeverity * 0.10);
          hitFlash = (0.35 + impactSeverity * 0.65).clamp(0.35, 1.0).toDouble();
          ersToggledOn = false;
          spawnParticles(const Color(0xFFFFB300), 14, sparks: true);
          F1SoundEngine.playEvent('crash', intensity: (0.45 + impactSeverity * 0.55).clamp(0.45, 1.0).toDouble());
          showRadio('¡IMPACTO CONTRA EL MURO!', secs: 1.6);
        } else if (pushingIntoWall) {
          // ZERO WALL-RIDING: staying against the barrier kills speed rapidly; steering away rotates you cleanly back onto track!
          if (carHeading * wallSign > 0.0) carHeading = 0.0;
          if (impactLatVel * wallSign > 0.0) impactLatVel = 0.0;
          speedKmh = max(0.0, speedKmh - (240.0 + speedKmh * 2.10) * dt);
          if (speedKmh > 30.0 && rng.nextDouble() < 0.40) {
            spawnParticles(const Color(0xFFFFB300), 2, sparks: true);
          }
        }
      }
    }

    playerDist += max(0.0, vMs * cos(carHeading)) * dt;

    if (hitFlash > 0) hitFlash = max(0.0, hitFlash - dt * 2.8);

    // Check Qualifying completion (1 full lap — sub-frame exact millisecond interpolation right at the checkered line!)
    if (phase == SessionPhase.qualifying) {
      if (playerDist >= circuit.lapLengthMeters) {
        final double moveDist = max(1e-5, playerDist - prevPlayerDist);
        final double frac = ((circuit.lapLengthMeters - prevPlayerDist) / moveDist).clamp(0.0, 1.0).toDouble();
        final double exactQualiTime = max(0.001, (qualiElapsed - dt) + frac * dt);
        qualiElapsed = exactQualiTime;
        lapStateChanged = true;
        completeQualifying(forcedTime: exactQualiTime);
        return 1;
      }
      final int qGear = gear;
      if (qGear != _lastGear && speedKmh > 35.0) {
        shiftKickTimer = 0.14;
        shiftWasUp = qGear > _lastGear;
        if (qGear > _lastGear) {
          F1SoundEngine.playEvent('upshift');
        } else {
          _downshiftBlip = 1550.0;
          F1SoundEngine.playEvent('downshift');
        }
        _lastGear = qGear;
      }
      _updateEngineRpm(dt, onGrid: false);
      _audioUpdateAcc += dt;
      if (_audioUpdateAcc >= 0.040) {
        _audioUpdateAcc = 0.0;
        final bool onKerbNow = carX.abs() > 0.88 && carX.abs() <= 1.04;
        final double tireSlip = ((steerAngle.abs() * (speedKmh / 205.0)) + (carHeading.abs() * 0.85) + (lateralVel.abs() * 0.24)).clamp(0.0, 1.0).toDouble();
        F1SoundEngine.update(
          rpm: _engineRpm,
          speed: speedKmh,
          throttle: gasHeld && !brakeHeld,
          brake: brakeHeld,
          ers: ersActive,
          offTrack: inGravel || onGrass,
          onKerb: onKerbNow,
          slip: tireSlip,
          active: true,
        );
      }
      notifyListeners();
      return 0;
    }

    // Update Smart AI + Precision Swept Collisions (Race phase only)
    _updateSmartAiAndCollisions(dt);

    // Gear shift audio + physical shift kick & glove paddle animation!
    final int curGearNow = gear;
    if (curGearNow != _lastGear && speedKmh > 35.0) {
      shiftKickTimer = 0.14;
      shiftWasUp = curGearNow > _lastGear;
      if (curGearNow > _lastGear) {
        F1SoundEngine.playEvent('upshift');
      } else {
        _downshiftBlip = 1550.0;
        F1SoundEngine.playEvent('downshift');
      }
      _lastGear = curGearNow;
    }

    _updateEngineRpm(dt, onGrid: false);

    // Stream smooth engine, tire slip & track telemetry to native DSP audio engine (25Hz -> 37% less IPC heat!)
    _audioUpdateAcc += dt;
    if (_audioUpdateAcc >= 0.040) {
      _audioUpdateAcc = 0.0;
      final bool onKerbNow = carX.abs() > 0.88 && carX.abs() <= 1.04;
      final double tireSlip = ((steerAngle.abs() * (speedKmh / 205.0)) + (carHeading.abs() * 0.85) + (lateralVel.abs() * 0.24)).clamp(0.0, 1.0).toDouble();
      F1SoundEngine.update(
        rpm: _engineRpm,
        speed: speedKmh,
        throttle: gasHeld && !brakeHeld,
        brake: brakeHeld,
        ers: ersActive,
        offTrack: inGravel || onGrass,
        onKerb: onKerbNow,
        slip: tireSlip,
        active: true,
      );
    }

    // Instant Sub-Frame Exact Start/Finish Line Crossing (ZERO delay — updates lap & lap times right on the checkered line!)
    final int prevCrossings = (prevPlayerDist / circuit.lapLengthMeters).floor();
    final int currCrossings = (playerDist / circuit.lapLengthMeters).floor();
    if (currCrossings > prevCrossings) {
      final double lineDist = currCrossings * circuit.lapLengthMeters;
      final double moveDist = max(1e-5, playerDist - prevPlayerDist);
      final double frac = ((lineDist - prevPlayerDist) / moveDist).clamp(0.0, 1.0).toDouble();
      final double exactCrossTime = (totalRaceTime - dt) + (frac * dt);
      final double lapDuration = max(0.001, exactCrossTime - lapStartTime);
      lapStartTime = exactCrossTime;
      if (lapDuration < bestLapTime) bestLapTime = lapDuration;
      if (lapDuration < fastLapTime) fastLapTime = lapDuration;
      lapStateChanged = true;

      if (currCrossings >= totalLaps) {
        totalRaceTime = exactCrossTime;
        raceFinished = true;
        F1SoundEngine.stop();
        F1SoundEngine.playEvent('finish');
        notifyListeners();
        return 2;
      } else {
        F1SoundEngine.playEvent('lap');
        final int mins = lapDuration ~/ 60;
        final int secs = lapDuration.toInt() % 60;
        final int ms = ((lapDuration - lapDuration.floor()) * 1000).toInt();
        final String lapStr = '${mins.toString().padLeft(2, '0')}:${secs.toString().padLeft(2, '0')}.${ms.toString().padLeft(3, '0')}';
        showRadio('VUELTA ${currCrossings + 1}/$totalLaps  •  $lapStr', secs: 2.2);
      }
    }

    notifyListeners();
    return 0;
  }

  void _updateSmartAiAndCollisions(double dt) {
    rivalCloseLeft = false;
    rivalCloseRight = false;

    // PHASE A: GTA 3 Dual-Tier Rival Simulation!
    // - Active Streaming Bubble (-120m .. +280m around player): 100% full Pro AI radar, battles, evasion & Ultra-HD 3D!
    // - Off-Screen Persistent World (>280m ahead or >120m behind): O(1) continuous real-physics progression so EVERY rival
    //   keeps racing, overtaking & completing laps in real time at a fraction of the CPU cost!
    for (int i = 0; i < aiDrivers.length; i++) {
      final AiDriver ai = aiDrivers[i];
      ai.prevTrackDist = ai.trackDist;

      if (ai.overtakeCommitTimer > 0) ai.overtakeCommitTimer = max(0.0, ai.overtakeCommitTimer - dt);
      if (ai.evadeLockTimer > 0) ai.evadeLockTimer = max(0.0, ai.evadeLockTimer - dt);
      if (ai.defenseCooldown > 0) ai.defenseCooldown = max(0.0, ai.defenseCooldown - dt);
      if (ai.defenseHoldTimer > 0) ai.defenseHoldTimer = max(0.0, ai.defenseHoldTimer - dt);
      if (ai.collisionCooldown > 0) ai.collisionCooldown = max(0.0, ai.collisionCooldown - dt);

      // Realistic F1 standing-start reaction delay
      if (totalRaceTime < ai.launchDelay) {
        ai.currentSpeedKmh = 0.0;
        ai.smoothLatRate = 0.0;
        ai.steerTilt *= exp(-8.0 * dt);
        ai.smoothYaw *= exp(-8.0 * dt);
        ai.smoothDrsOpen *= exp(-8.0 * dt);
        continue;
      }

      // 5-Tier F1 AI Envelope (N4 Difícil & N5 Leyenda use optimal late braking, corner-exit MGU-K & true F1 racecraft!)
      final int dLvl = aiDifficultyLevel.clamp(0, 4).toInt();
      final bool eliteTier = dLvl >= 3;
      final bool legendTier = dLvl == 4;
      final double lvlFrac = dLvl / 4.0;
      final double sNorm = ((ai.skill - 0.78) / 0.21).clamp(0.0, 1.0).toDouble();
      final double aiBaseTop = _aiTopMin[dLvl] + (_aiTopMax[dLvl] - _aiTopMin[dLvl]) * sNorm;
      final double cornerCap = eliteTier ? 1.42 : 1.22;
      final double aiCornerMult = ((_aiCornerMin[dLvl] + (_aiCornerMax[dLvl] - _aiCornerMin[dLvl]) * sNorm) * circuitAiPaceScale).clamp(0.55, cornerCap).toDouble();
      final double aiAccelBase = _aiAccelMin[dLvl] + (_aiAccelMax[dLvl] - _aiAccelMin[dLvl]) * sNorm;
      final double aiErsAccelAdd = _aiErsAccelAdd[dLvl];
      final double aiBrakeBase = _aiBrakeMin[dLvl] + (_aiBrakeMax[dLvl] - _aiBrakeMin[dLvl]) * sNorm;
      final double aiMaxErsTop = min(_aiErsCap[dLvl], aiBaseTop + (eliteTier ? 36.0 : (26.0 + 13.0 * lvlFrac)));
      final double aiErsMin = _aiErsMinCharge[dLvl];
      final double aiSlipBonus = eliteTier ? (legendTier ? 20.0 : 18.0) : (7.0 + 9.0 * lvlFrac);
      final double brakeLookM = legendTier ? 3.5 : (eliteTier ? 8.0 : 18.0);
      final double ersDrainRate = legendTier ? 18.5 : 20.0;
      final double ersRegenBrake = eliteTier ? 19.5 : 16.0;
      final double ersRegenCoast = legendTier ? 8.4 : (eliteTier ? 7.8 : 7.2);
      final double accelCap = legendTier ? 205.0 : (eliteTier ? 192.0 : 182.0);
      final double slipTopCap = legendTier ? 378.0 : (eliteTier ? 372.0 : 368.0);

      final double relDistToPlayer = ai.trackDist - playerDist;
      final bool inActiveStreamBubble = relDistToPlayer >= -120.0 && relDistToPlayer <= 280.0;
      if (!inActiveStreamBubble) {
        // PERSISTENT OFF-SCREEN WORLD SIMULATION (100% matched to active 5-level bubble!)
        final double lapLenBg = circuit.lapLengthMeters;
        final double aiProgBg = (ai.trackDist % lapLenBg) / lapLenBg;
        final double aiProgBgLook = ((ai.trackDist + brakeLookM) % lapLenBg) / lapLenBg;
        final double aiProgBg45 = ((ai.trackDist + 45.0) % lapLenBg) / lapLenBg;
        final double kBg = geometry.kappaAtProgress(aiProgBg);
        final double kBg45 = geometry.kappaAtProgress(aiProgBg45).abs();
        final double vtMinBg = min(
          geometry.targetSpeedAtProgress(aiProgBg) * aiCornerMult,
          geometry.targetSpeedAtProgress(aiProgBgLook) * aiCornerMult,
        );
        double desiredBg = min(aiBaseTop, vtMinBg);

        final bool onStrBg = kBg.abs() < (eliteTier ? 0.0080 : 0.0060) && kBg45 < (eliteTier ? 0.0095 : 0.0080);
        final bool exitLaunchBg = eliteTier && kBg.abs() < 0.0088 && ai.currentSpeedKmh < 280.0 && vtMinBg > ai.currentSpeedKmh + 14.0;
        if ((onStrBg || exitLaunchBg) && ai.ersCharge > aiErsMin && vtMinBg > (eliteTier ? 125.0 : 235.0)) {
          ai.drsOpen = true;
          ai.ersCharge = max(0.0, ai.ersCharge - ersDrainRate * dt);
          desiredBg = min(aiMaxErsTop, vtMinBg);
        } else {
          ai.drsOpen = false;
          ai.ersCharge = min(100.0, ai.ersCharge + (ai.isBraking ? ersRegenBrake : ersRegenCoast) * dt);
        }

        // Difficulty-respecting pack balance: ZERO artificial leader slowdown on Difícil/Leyenda!
        final double deltaBg = playerDist - ai.trackDist;
        if (deltaBg > 260.0 && dLvl >= 2) {
          final double catchBg = ((deltaBg - 260.0) / 240.0).clamp(0.0, 1.0).toDouble();
          desiredBg = min(aiMaxErsTop, desiredBg * (1.0 + (0.014 + 0.022 * lvlFrac) * catchBg));
        } else if (deltaBg < -260.0 && dLvl <= 2) {
          final double waitBg = ((-deltaBg - 260.0) / 300.0).clamp(0.0, 1.0).toDouble();
          desiredBg *= (1.0 - (0.055 - dLvl * 0.018) * waitBg);
        }

        final double diffBg = desiredBg - ai.currentSpeedKmh;
        if (diffBg > 0.0) {
          ai.currentSpeedKmh = min(desiredBg, ai.currentSpeedKmh + min(accelCap, aiAccelBase + (ai.drsOpen ? aiErsAccelAdd : 0.0)) * dt);
          ai.isBraking = false;
        } else {
          ai.currentSpeedKmh = max(desiredBg, ai.currentSpeedKmh - aiBrakeBase * dt);
          ai.isBraking = diffBg < -10.0;
        }
        ai.trackDist += (ai.currentSpeedKmh / 3.6) * dt;
        // Keep lane & yaw seamlessly aligned to the ideal racing line so entering the streaming bubble has ZERO pop!
        final double idealBg = geometry.idealLineAtProgress(aiProgBg).clamp(-0.78, 0.78).toDouble();
        ai.targetLaneX = idealBg;
        ai.smoothTargetLaneX = idealBg;
        ai.laneX += (idealBg - ai.laneX) * (1.0 - exp(-3.5 * dt));
        ai.smoothLatRate = 0.0;
        ai.lateralVel = 0.0;
        ai.steerTilt *= exp(-6.0 * dt);
        ai.smoothYaw = (kBg * 2.15).clamp(-0.30, 0.30).toDouble();
        ai.smoothDrsOpen = ai.drsOpen ? 1.0 : 0.0;
        continue;
      }

      final double collDx = carCollisionDxLane;
      final double sideClearDx = (collDx * (eliteTier ? 1.38 : 1.48)).clamp(0.38, 0.72).toDouble();
      final double draftDx = (collDx * 0.96).clamp(0.28, 0.48).toDouble();

      // 1. Optimal late-braking lookahead on N4/N5 using exact curvature & unified per-circuit corner envelope
      final double kNowSigned = _kappaAtDist(ai.trackDist);
      final double kNearSigned = _kappaAtDist(ai.trackDist + 45.0);
      final double kNow = kNowSigned.abs();
      final double kNear = kNearSigned.abs();

      final double lapLenAi = circuit.lapLengthMeters;
      final double aiProg = (ai.trackDist % lapLenAi) / lapLenAi;
      final double aiProgLook = ((ai.trackDist + brakeLookM) % lapLenAi) / lapLenAi;
      final double vtMin = min(
        geometry.targetSpeedAtProgress(aiProg) * aiCornerMult,
        geometry.targetSpeedAtProgress(aiProgLook) * aiCornerMult,
      );
      double desiredSpeed = min(aiBaseTop, vtMin);

      // 2. Wide-range traffic & anti-wall cluster radar scaled to real track width
      double closestAheadDz = 999.0;
      double closestAheadLane = 0.0;
      double closestAheadSpeed = 999.0;
      double closestSameLaneDz = 999.0;
      double closestSameLaneSpeed = 999.0;
      bool sideBlockedLeft = false;
      bool sideBlockedRight = false;
      int abreastCount = 0;
      int aheadClusterCount = 0;

      for (int j = 0; j < aiDrivers.length; j++) {
        if (i == j) continue;
        final AiDriver other = aiDrivers[j];
        final double dz = other.trackDist - ai.trackDist;
        final double dx = other.laneX - ai.laneX;
        if (dz > 1.0 && dz < 64.0 && dx.abs() < sideClearDx && dz < closestAheadDz) {
          closestAheadDz = dz;
          closestAheadLane = other.laneX;
          closestAheadSpeed = other.currentSpeedKmh;
        }
        if (dz > 0.5 && dz < 26.0 && dx.abs() < collDx * 1.12 && dz < closestSameLaneDz) {
          closestSameLaneDz = dz;
          closestSameLaneSpeed = other.currentSpeedKmh;
        }
        if (dz.abs() < 10.5) {
          abreastCount++;
          if (dx < 0 && dx > -sideClearDx) sideBlockedLeft = true;
          if (dx > 0 && dx < sideClearDx) sideBlockedRight = true;
        }
        if (dz > 4.0 && dz < 24.0) {
          aheadClusterCount++;
        }
      }

      final double dzPlayer = playerDist - ai.trackDist;
      final double dxPlayer = carX - ai.laneX;
      if (dzPlayer > 1.5 && dzPlayer < 64.0 && dxPlayer.abs() < sideClearDx && dzPlayer < closestAheadDz) {
        closestAheadDz = dzPlayer;
        closestAheadLane = carX;
        closestAheadSpeed = speedKmh;
      }
      if (dzPlayer.abs() < 10.5) {
        if (dxPlayer < 0 && dxPlayer > -sideClearDx) sideBlockedLeft = true;
        if (dxPlayer > 0 && dxPlayer < sideClearDx) sideBlockedRight = true;
      }

      // 3. Proactive Slipstream, Corner-Exit MGU-K Launch, Standing-Start Launch ERS & Tactical DRS!
      final bool directlyBehind = closestAheadDz < (eliteTier ? 58.0 : 52.0) && closestAheadDz > 5.0 && (closestAheadLane - ai.laneX).abs() < draftDx;
      ai.isDrafting = directlyBehind && kNow < 0.0095;
      final bool onStraight = kNow < (eliteTier ? 0.0080 : 0.0065) && kNear < (eliteTier ? 0.0098 : 0.0085);
      final bool inCorner = kNow > (eliteTier ? 0.0115 : 0.0090) || kNear > (eliteTier ? 0.0150 : 0.0125);
      final bool launchBoost = eliteTier && totalRaceTime < 4.8 && ai.currentSpeedKmh < 275.0 && ai.ersCharge > 18.0;
      final bool cornerExitBoost = eliteTier
          ? (kNow < 0.0088 && ai.currentSpeedKmh < 285.0 && vtMin > ai.currentSpeedKmh + 14.0 && ai.ersCharge > aiErsMin)
          : (dLvl >= 2 && kNow < 0.0055 && ai.currentSpeedKmh < 274.0 && ai.ersCharge > aiErsMin);
      final double playerBehindDz = ai.trackDist - playerDist;
      final bool defendingPlayer = dLvl >= 1 && playerBehindDz > 4.0 && playerBehindDz < (eliteTier ? 48.0 : 38.0) && speedKmh > ai.currentSpeedKmh + 2.0 && abreastCount == 0;
      final bool attackingPlayer = eliteTier && dzPlayer > 4.0 && dzPlayer < 52.0 && ai.ersCharge > 6.0;
      final bool wantsOvertake = ai.isDrafting && (aiBaseTop > closestAheadSpeed - (eliteTier ? 14.0 : 8.0)) && abreastCount == 0 && aheadClusterCount <= (eliteTier ? 2 : 1);

      final bool canDeployErs = (launchBoost || wantsOvertake || defendingPlayer || attackingPlayer || cornerExitBoost || (ai.ersCharge > aiErsMin && onStraight && abreastCount == 0)) &&
          (onStraight || cornerExitBoost || launchBoost) &&
          vtMin > (eliteTier ? 120.0 : 235.0) &&
          ai.ersCharge > (legendTier ? 2.5 : (eliteTier ? 4.5 : 12.0));

      if (canDeployErs) {
        ai.drsOpen = true;
        ai.ersCharge = max(0.0, ai.ersCharge - ersDrainRate * dt);
        final double slipCap = min(slipTopCap, aiMaxErsTop + (ai.isDrafting ? aiSlipBonus : 0.0));
        desiredSpeed = min(slipCap, vtMin);
      } else {
        ai.drsOpen = false;
        ai.ersCharge = min(100.0, ai.ersCharge + (ai.isBraking ? ersRegenBrake : ersRegenCoast) * dt);
        if (ai.isDrafting) {
          desiredSpeed = min(min(slipTopCap, aiMaxErsTop), min(vtMin, desiredSpeed + aiSlipBonus));
        }
      }

      // Difficulty-respecting pack balance: ZERO artificial leader slowdown on Difícil/Leyenda!
      final double deltaToPlayer = playerDist - ai.trackDist;
      if (deltaToPlayer > 260.0 && dLvl >= 2) {
        final double catchFactor = ((deltaToPlayer - 260.0) / 240.0).clamp(0.0, 1.0).toDouble();
        desiredSpeed = min(aiMaxErsTop, desiredSpeed * (1.0 + (0.014 + 0.022 * lvlFrac) * catchFactor));
      } else if (deltaToPlayer < -260.0 && dLvl <= 2) {
        final double waitFactor = ((-deltaToPlayer - 260.0) / 300.0).clamp(0.0, 1.0).toDouble();
        desiredSpeed *= (1.0 - (0.055 - dLvl * 0.018) * waitFactor);
      }

      // Proactive smooth longitudinal spacing behind a car directly ahead in the same lane (tighter & braver on N4/N5!)
      final double followWindow = eliteTier ? 12.0 : 16.0;
      if (closestSameLaneDz < followWindow) {
        final double gapNorm = ((closestSameLaneDz - 5.8) / max(1.0, followWindow - 5.8)).clamp(0.0, 1.0).toDouble();
        final double safeFollowSpeed = max(0.0, closestSameLaneSpeed - (1.0 - gapNorm) * (eliteTier ? 20.0 : 26.0));
        desiredSpeed = min(desiredSpeed, safeFollowSpeed);
      }

      // 4. Precision FIA Out-In-Out Racing Line + Pro Overtaking + Persistent 1-Move F1 Defense!
      double targetX = geometry.idealLineAtProgress(aiProg).clamp(-0.78, 0.78).toDouble();

      // 4A. Slipstream Hunting on straights (N4/N5 aggressively tuck into tow from up to 62m away!)
      if (onStraight && closestAheadDz >= (eliteTier ? 18.0 : 24.0) && closestAheadDz < (eliteTier ? 62.0 : 54.0) && ai.overtakeCommitTimer <= 0 && abreastCount == 0) {
        targetX = closestAheadLane.clamp(-0.80, 0.80).toDouble();
      }

      // 4B. Clean Overtaking + Late-Braking Inside Corner Dives on N4/N5!
      final bool cornerEntryDive = eliteTier && kNear > 0.0085 && kNow < 0.014 && closestAheadDz > 4.0 && closestAheadDz < 24.0 && abreastCount == 0;
      final bool canStartOvertake = ((!inCorner) || cornerEntryDive) && abreastCount == 0 && aheadClusterCount <= (eliteTier ? 2 : 1);
      final double overtakeRange = eliteTier ? 38.0 : 32.0;
      if (closestAheadDz < overtakeRange && (ai.currentSpeedKmh > closestAheadSpeed - (eliteTier ? 10.0 : 6.0) || ai.drsOpen || cornerEntryDive)) {
        if (canStartOvertake) {
          if (ai.overtakeCommitTimer <= 0) {
            final bool cornerAhead = kNear > 0.0085;
            final double diveAggrReq = eliteTier ? 0.65 : 0.80;
            final bool diveLeft = cornerAhead && kNearSigned < 0 && ai.aggression > diveAggrReq;
            final bool diveRight = cornerAhead && kNearSigned > 0 && ai.aggression > diveAggrReq;

            if (diveLeft && !sideBlockedLeft) {
              ai.overtakeSide = -1.0;
            } else if (diveRight && !sideBlockedRight) {
              ai.overtakeSide = 1.0;
            } else if (closestAheadLane <= -0.15 && !sideBlockedRight) {
              ai.overtakeSide = 1.0;
            } else if (closestAheadLane >= 0.15 && !sideBlockedLeft) {
              ai.overtakeSide = -1.0;
            } else if (!sideBlockedLeft) {
              ai.overtakeSide = -1.0;
            } else if (!sideBlockedRight) {
              ai.overtakeSide = 1.0;
            } else {
              ai.overtakeSide = 0.0;
            }
            ai.overtakeCommitTimer = (eliteTier ? 1.55 : 1.35) + (ai.aggression * 0.45);
          }
          if (ai.overtakeSide != 0.0) {
            final double passGap = max(collDx * 1.30, 0.40);
            targetX = (closestAheadLane + ai.overtakeSide * passGap).clamp(-0.84, 0.84).toDouble();
          }
        } else {
          ai.overtakeSide = 0.0;
          ai.overtakeCommitTimer = 0.0;
          targetX = closestAheadLane.clamp(-0.80, 0.80).toDouble();
          if (closestAheadDz < 14.0) {
            desiredSpeed = min(desiredSpeed, closestAheadSpeed - (14.0 - closestAheadDz) * 1.8);
          }
        }
      } else if (ai.overtakeCommitTimer > 0 && ai.overtakeSide != 0.0 && abreastCount <= 1) {
        targetX = (ai.laneX + ai.overtakeSide * 0.14).clamp(-0.84, 0.84).toDouble();
      } else {
        ai.overtakeSide = 0.0;
      }

      // 4C. PERSISTENT FIA 1-MOVE INSIDE-LINE DEFENSE (Actually holds the inside line for 1.4..1.85s on N4/N5!)
      if (ai.defenseHoldTimer > 0.0 && playerBehindDz > 2.5 && playerBehindDz < 48.0) {
        final bool defBlocked = (ai.defenseTargetX < ai.laneX && sideBlockedLeft) || (ai.defenseTargetX > ai.laneX && sideBlockedRight);
        if (!defBlocked) {
          targetX = ai.defenseTargetX;
        }
      } else if (playerBehindDz > (eliteTier ? 9.0 : 20.0) &&
          playerBehindDz < (eliteTier ? 48.0 : 42.0) &&
          speedKmh > ai.currentSpeedKmh + (eliteTier ? 2.0 : 5.0) &&
          abreastCount == 0 &&
          ai.defenseCooldown <= 0) {
        if (rng.nextDouble() < ai.defenseSkill * _aiDefenseRate[dLvl]) {
          final double nextK = _kappaAtDist(ai.trackDist + 95.0);
          // Protect the inside apex of the next corner OR break the player's slipstream cleanly on straights!
          final double insideLine = nextK.abs() > 0.0045
              ? (nextK.sign * 0.62)
              : (carX.abs() < 0.25 ? (ai.laneX >= 0 ? 0.50 : -0.50) : (carX >= 0 ? -0.52 : 0.52));
          if ((insideLine - carX).abs() > max(collDx * 1.05, 0.34) &&
              ((insideLine < ai.laneX && !sideBlockedLeft) || (insideLine > ai.laneX && !sideBlockedRight))) {
            ai.defenseTargetX = insideLine.clamp(-0.78, 0.78).toDouble();
            ai.defenseHoldTimer = legendTier ? 1.85 : (eliteTier ? 1.45 : 0.75);
            ai.defenseCooldown = legendTier ? 2.4 : (eliteTier ? 2.9 : 3.4);
            targetX = ai.defenseTargetX;
          }
        }
      }

      // 4D. SMART WHEEL-TO-WHEEL RACING vs PLAYER:
      // - N4/N5 NEVER jump submissively out of the player's way from ahead!
      // - N4/N5 pull cleanly ALONGSIDE to overtake a slower player WITHOUT slamming brakes or killing DRS!
      // - Still prevents clumsy rear-end collisions & side-swipes with smooth hysteresis!
      bool evadingPlayer = false;
      final double absDxPlayer = dxPlayer.abs();

      if (dzPlayer > 1.5 && dzPlayer < 40.0) {
        final double closingMs = (ai.currentSpeedKmh - speedKmh) / 3.6;
        final double ttc = closingMs > 0.5 ? (dzPlayer / closingMs) : 99.0;
        final double triggerDx = eliteTier ? (collDx * 1.42).clamp(0.46, 0.64).toDouble() : 0.68;
        if (absDxPlayer < triggerDx && (closingMs > -2.0 || dzPlayer < 16.0)) {
          evadingPlayer = true;
          if (ai.evadeLockTimer <= 0.0 || ai.evadeSide == 0.0) {
            final bool cornerRight = kNearSigned > 0.008;
            final bool cornerLeft = kNearSigned < -0.008;
            if (eliteTier && cornerLeft && !sideBlockedLeft && carX > -0.35) {
              ai.evadeSide = -1.0; // Dive up the inside on left corners!
            } else if (eliteTier && cornerRight && !sideBlockedRight && carX < 0.35) {
              ai.evadeSide = 1.0;  // Dive up the inside on right corners!
            } else if (carX > 0.22 && !sideBlockedLeft) {
              ai.evadeSide = -1.0;
            } else if (carX < -0.22 && !sideBlockedRight) {
              ai.evadeSide = 1.0;
            } else if (ai.laneX >= carX && !sideBlockedRight) {
              ai.evadeSide = 1.0;
            } else if (!sideBlockedLeft) {
              ai.evadeSide = -1.0;
            } else {
              ai.evadeSide = (ai.laneX >= carX) ? 1.0 : -1.0;
            }
            ai.evadeLockTimer = 0.72;
          }
          final double passOffset = eliteTier ? max(collDx * 1.38, 0.58) : 0.72;
          targetX = (carX + ai.evadeSide * passOffset).clamp(-0.90, 0.90).toDouble();

          // On N4/N5, keep full throttle/DRS while pulling alongside; ONLY lift if trapped directly behind (<11.5m)!
          final double panicDz = eliteTier ? 11.5 : 22.0;
          final double panicTtc = eliteTier ? 0.62 : 1.45;
          final double panicDx = eliteTier ? (collDx * 1.08) : 0.58;
          if ((dzPlayer < panicDz || ttc < panicTtc) && absDxPlayer < panicDx) {
            final double safeCap = max(0.0, speedKmh - (panicDz + 1.0 - min(panicDz, dzPlayer)) * 1.85);
            desiredSpeed = min(desiredSpeed, safeCap);
            if (dzPlayer < 8.5) ai.drsOpen = false;
          }
        }
      } else if (dzPlayer.abs() <= 12.0) {
        // Firm wheel-to-wheel side clearance (respects space without backing off the throttle!)
        final double wheelGap = eliteTier ? max(collDx * 1.24, 0.50) : 0.72;
        if (absDxPlayer < wheelGap) {
          evadingPlayer = true;
          if (ai.evadeLockTimer <= 0.0 || ai.evadeSide == 0.0) {
            ai.evadeSide = (ai.laneX >= carX) ? 1.0 : -1.0;
            ai.evadeLockTimer = 0.50;
          }
          targetX = (carX + ai.evadeSide * (wheelGap + 0.04)).clamp(-0.92, 0.92).toDouble();
        }
      } else if (!eliteTier && playerBehindDz > 3.0 && playerBehindDz < 24.0 && speedKmh > ai.currentSpeedKmh + 16.0) {
        // Gentle courtesy yield ONLY on N1/N2/N3 (NEVER on Difícil or Leyenda — make the player earn the pass!)
        if (absDxPlayer < 0.54) {
          evadingPlayer = true;
          if (ai.evadeLockTimer <= 0.0 || ai.evadeSide == 0.0) {
            ai.evadeSide = (ai.laneX >= carX)
                ? (!sideBlockedRight ? 1.0 : -1.0)
                : (!sideBlockedLeft ? -1.0 : 1.0);
            ai.evadeLockTimer = 0.65;
          }
          targetX = (carX + ai.evadeSide * 0.66).clamp(-0.88, 0.88).toDouble();
        }
      } else if (ai.evadeLockTimer <= 0.0) {
        ai.evadeSide = 0.0;
      }

      if (!evadingPlayer) {
        if (sideBlockedLeft && targetX < ai.laneX) targetX = max(targetX, ai.laneX + 0.03);
        if (sideBlockedRight && targetX > ai.laneX) targetX = min(targetX, ai.laneX - 0.03);
      }
      targetX = targetX.clamp(-0.92, 0.92).toDouble();
      ai.targetLaneX = targetX;

      // 5. Realistic High-Performance F1 Acceleration & Late Carbon-Ceramic Braking
      final double speedDiff = desiredSpeed - ai.currentSpeedKmh;
      if (speedDiff > 0) {
        final double aiAccel = min(accelCap, aiAccelBase + (ai.drsOpen ? aiErsAccelAdd : 0.0) + (ai.isDrafting ? (8.0 + 10.0 * lvlFrac) : 0.0));
        ai.currentSpeedKmh = min(desiredSpeed, ai.currentSpeedKmh + aiAccel * dt);
        ai.isBraking = false;
      } else {
        final double aiBrake = evadingPlayer ? (aiBrakeBase * 1.40) : aiBrakeBase;
        ai.currentSpeedKmh = max(desiredSpeed, ai.currentSpeedKmh - aiBrake * dt);
        ai.isBraking = speedDiff < -10.0;
      }

      ai.trackDist += (ai.currentSpeedKmh / 3.6) * dt;

      // 6. 2nd-Order Critically Damped F1 Lateral Kinematics (Crisper apex precision & decisive passes on N4/N5!)
      final double targetFilterRate = evadingPlayer ? (eliteTier ? 9.5 : 7.5) : (eliteTier ? 6.8 : 4.8);
      ai.smoothTargetLaneX += (targetX - ai.smoothTargetLaneX) * (1.0 - exp(-targetFilterRate * dt));
      final double baseLatRate = eliteTier ? (legendTier ? 1.58 : 1.38) : 1.15;
      final double evadeLatRate = eliteTier ? 2.15 : 1.85;
      final double maxLatRate = (evadingPlayer ? evadeLatRate : baseLatRate) * (ai.currentSpeedKmh / 140.0).clamp(0.18, 1.0).toDouble();
      final double desiredLatRate = ((ai.smoothTargetLaneX - ai.laneX) * (evadingPlayer ? 4.8 : (eliteTier ? 4.0 : 3.2))).clamp(-maxLatRate, maxLatRate).toDouble();
      ai.smoothLatRate += (desiredLatRate - ai.smoothLatRate) * (1.0 - exp(-(eliteTier ? 10.5 : 8.5) * dt));
      ai.lateralVel *= exp(-6.5 * dt);

      final double prevLane = ai.laneX;
      ai.laneX = (ai.laneX + (ai.smoothLatRate + ai.lateralVel) * dt).clamp(-0.94, 0.94).toDouble();

      final double actualLatRate = (ai.laneX - prevLane) / max(dt, 0.004);
      final double targetTilt = (actualLatRate * 0.095).clamp(-0.14, 0.14).toDouble();
      ai.steerTilt += (targetTilt - ai.steerTilt) * (1.0 - exp(-9.0 * dt));

      final double exactCurv = _kappaAtDist(ai.trackDist);
      final double targetYaw = (ai.steerTilt * 1.10 + exactCurv * 2.15).clamp(-0.32, 0.32).toDouble();
      ai.smoothYaw += (targetYaw - ai.smoothYaw) * (1.0 - exp(-10.5 * dt));
      ai.smoothDrsOpen += ((ai.drsOpen ? 1.0 : 0.0) - ai.smoothDrsOpen) * (1.0 - exp(-11.0 * dt));
    }

    // PHASE B: Smooth Velocity-Only Anti-Wall & Spacing Enforcement (Zero-GC reused sort index buffer!)
    if (_aiOrderScratch.length != aiDrivers.length) {
      _aiOrderScratch
        ..clear()
        ..addAll(List<int>.generate(aiDrivers.length, (i) => i));
    }
    final List<int> order = _aiOrderScratch;
    order.sort((a, b) => aiDrivers[b].trackDist.compareTo(aiDrivers[a].trackDist));

    for (int rank = 1; rank < order.length; rank++) {
      final AiDriver lead = aiDrivers[order[rank - 1]];
      final AiDriver trail = aiDrivers[order[rank]];
      final double dz = lead.trackDist - trail.trackDist;
      final double dx = (lead.laneX - trail.laneX).abs();

      if (dz < 10.5) {
        // Never allow 3 cars within 15m to fan out across the track: smoothly ease trail behind lead!
        if (rank >= 2 && (aiDrivers[order[rank - 2]].trackDist - trail.trackDist) < 15.0) {
          final double targetSlow = max(45.0, lead.currentSpeedKmh - 16.0);
          trail.currentSpeedKmh = max(targetSlow, trail.currentSpeedKmh - 170.0 * dt);
          trail.isBraking = trail.currentSpeedKmh > targetSlow + 4.0;
          trail.overtakeSide = 0.0;
          trail.overtakeCommitTimer = 0.0;
          trail.smoothTargetLaneX += (lead.laneX - trail.smoothTargetLaneX) * (1.0 - exp(-4.5 * dt));
        } else if (dx >= carCollisionDxLane) {
          // Two cars temporarily side-by-side: gently differentiate pace & bias corridor smoothly
          if (trail.currentSpeedKmh <= lead.currentSpeedKmh + 6.0) {
            trail.currentSpeedKmh = max(55.0, trail.currentSpeedKmh - 18.0 * dt);
          } else {
            lead.currentSpeedKmh = max(55.0, lead.currentSpeedKmh - 10.0 * dt);
          }
          if (lead.laneX * trail.laneX < 0 && dx > 0.56) {
            final double bias = (lead.laneX + trail.laneX) <= 0 ? -1.0 : 1.0;
            lead.smoothTargetLaneX = (lead.smoothTargetLaneX + bias * 0.45 * dt).clamp(-0.84, 0.84).toDouble();
            trail.smoothTargetLaneX = (trail.smoothTargetLaneX + bias * 0.45 * dt).clamp(-0.84, 0.84).toDouble();
          }
        } else if (dz < 7.4) {
          // Same lane & close: smooth braking + tiny continuous velocity separation ONLY (ZERO teleport!)
          final double targetSlow = max(35.0, lead.currentSpeedKmh - (7.4 - dz) * 6.5);
          trail.currentSpeedKmh = max(targetSlow, trail.currentSpeedKmh - 260.0 * dt);
          trail.isBraking = true;
          if (dz < 5.0) {
            final double sep = min(5.0 - dz, 6.0 * dt);
            trail.trackDist -= sep;
          }
        }
      }
    }

    // PHASE C: Mirror Radar & Smooth Swept Player-vs-AI Collision Detection (Spatial early-out for off-screen rivals!)
    for (int i = 0; i < aiDrivers.length; i++) {
      final AiDriver ai = aiDrivers[i];
      if ((ai.trackDist - playerDist).abs() > 44.0) continue;

      final double behindDist = playerDist - ai.trackDist;
      if (behindDist > 2.4 && behindDist < 32.0) {
        if (ai.laneX <= carX) {
          rivalCloseLeft = true;
        } else {
          rivalCloseRight = true;
        }
      }

      final double prevDz = ai.prevTrackDist - prevPlayerDist;
      final double currDz = ai.trackDist - playerDist;
      final double minDz = min(prevDz, currDz);
      final double maxDz = max(prevDz, currDz);
      final bool zOverlaps = (maxDz >= kCarLengthOverlapBack) && (minDz <= kCarLengthOverlapFront);
      final double dxSigned = carX - ai.laneX;
      final double absDx = dxSigned.abs();

      final double dynCollDx = carCollisionDxLane;
      if (zOverlaps && absDx < dynCollDx && ai.collisionCooldown <= 0.0) {
        final bool isRearEndByPlayer = (currDz > 1.7) && (absDx < dynCollDx * 0.72) && (speedKmh > ai.currentSpeedKmh + 8.0);
        final bool isRearEndedByAi = (currDz < -1.4) && (absDx < dynCollDx * 0.72) && (ai.currentSpeedKmh > speedKmh + 10.0);

        if (isRearEndByPlayer) {
          final double closingKmh = (speedKmh - ai.currentSpeedKmh).clamp(10.0, 140.0).toDouble();
          final double severity = (closingKmh / 80.0).clamp(0.45, 1.5).toDouble();
          final double deflectDir = dxSigned >= 0 ? 1.0 : -1.0;

          playerDist = ai.trackDist - kCarLengthOverlapFront - 0.10;
          speedKmh = max(0.0, min(speedKmh, ai.currentSpeedKmh - closingKmh * 0.35));
          ai.currentSpeedKmh = min(345.0, ai.currentSpeedKmh + closingKmh * 0.18);

          impactLatVel += deflectDir * (1.45 * severity);
          spinYaw = deflectDir * (0.20 * severity);
          controlRecoveryTimer = 0.45 * severity;
          hitFlash = (0.55 + 0.45 * severity).clamp(0.55, 1.0).toDouble();
          ersToggledOn = false;
          ai.collisionCooldown = 0.42;

          spawnParticles(const Color(0xFFFFD54F), 14, sparks: true);
          F1SoundEngine.playEvent('crash', intensity: (0.6 + 0.4 * severity).clamp(0.6, 1.0).toDouble());
          showRadio('¡IMPACTO TRASERO CON ${ai.code}!', secs: 1.8);
        } else if (isRearEndedByAi) {
          final double closingKmh = (ai.currentSpeedKmh - speedKmh).clamp(10.0, 110.0).toDouble();
          final double overlapZ = (ai.trackDist - (playerDist + kCarLengthOverlapBack)).clamp(0.0, 0.65).toDouble();
          ai.trackDist -= overlapZ;
          ai.currentSpeedKmh = max(40.0, speedKmh - 14.0);
          ai.isBraking = true;
          speedKmh = min(355.0, speedKmh + closingKmh * 0.20);
          final double pushDir = dxSigned >= 0 ? 1.0 : -1.0;
          impactLatVel += pushDir * 0.72;
          ai.lateralVel = -pushDir * 0.85;
          hitFlash = 0.55;
          ai.collisionCooldown = 0.45;
          spawnParticles(const Color(0xFFFFAB00), 8, sparks: true);
          F1SoundEngine.playEvent('crash', intensity: 0.65);
        } else {
          final double pushDir = dxSigned >= 0 ? 1.0 : -1.0;
          final double penetration = (dynCollDx - absDx).clamp(0.02, dynCollDx).toDouble();
          carX += pushDir * (penetration * 0.65 + 0.02);
          ai.laneX = (ai.laneX - pushDir * min(0.06, penetration * 0.30)).clamp(-0.94, 0.94).toDouble();

          final double speedFactor = (speedKmh / 210.0).clamp(0.55, 1.65).toDouble();
          final double hardHit = (penetration / 0.18).clamp(0.65, 1.45).toDouble();

          impactLatVel = pushDir * (1.35 * speedFactor * hardHit);
          spinYaw = pushDir * (0.22 * hardHit);
          controlRecoveryTimer = 0.25;
          speedKmh = max(0.0, speedKmh * (1.0 - 0.18 * hardHit));
          hitFlash = (0.65 + 0.35 * hardHit).clamp(0.65, 1.0).toDouble();
          ersToggledOn = false;

          ai.lateralVel = -pushDir * (1.45 * hardHit);
          ai.currentSpeedKmh = max(60.0, ai.currentSpeedKmh * 0.90);
          ai.collisionCooldown = 0.42;

          spawnParticles(const Color(0xFFFFD54F), 14, sparks: true);
          F1SoundEngine.playEvent('crash', intensity: (0.55 + 0.45 * hardHit).clamp(0.55, 1.0).toDouble());
          showRadio('¡TOQUE RUEDA A RUEDA CON ${ai.code}!', secs: 1.9);
        }
      }
    }
  }
}

class CockpitRaceScreen extends StatefulWidget {
  final CircuitInfo circuit;
  final TeamLivery livery;

  const CockpitRaceScreen({
    super.key,
    required this.circuit,
    required this.livery,
  });

  @override
  State<CockpitRaceScreen> createState() => _CockpitRaceScreenState();
}

class _CockpitRaceScreenState extends State<CockpitRaceScreen> with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final RaceEngineState engine;
  late final Ticker _ticker;
  final ValueNotifier<int> _hudTick = ValueNotifier<int>(0);
  Duration _lastElapsed = Duration.zero;
  double _frameAcc = 0.0;
  double _avgVsyncDt = 0.0166;
  bool _skipAltFrame = false;
  double _filteredDt = 0.0166;
  double _hudAccumulator = 0.0;
  final Map<int, bool> _steerPointers = {};
  int? _analogSteerPointer;
  final Set<int> _brakePointers = {};
  final Set<int> _gasPointers = {};
  final List<int> _lbOrderScratch = [];
  final List<Map<String, Object>> _lbSliceScratch = [];

  void _syncSteerPointers() {
    engine.leftHeld = _steerPointers.values.any((isRight) => !isRight);
    engine.rightHeld = _steerPointers.values.any((isRight) => isRight);
    _hudTick.value++;
  }

  void _syncPedalPointers() {
    engine.brakeHeld = _brakePointers.isNotEmpty;
    if (!engine.brakeHeld) engine.brakePressure = 0.0;
    engine.gasHeld = _gasPointers.isNotEmpty;
    _hudTick.value++;
  }

  void _clearAllInputPointers() {
    _steerPointers.clear();
    _analogSteerPointer = null;
    _brakePointers.clear();
    _gasPointers.clear();
    engine.leftHeld = false;
    engine.rightHeld = false;
    engine.analogSteerTarget = null;
    engine.brakeHeld = false;
    engine.brakePressure = 0.0;
    engine.gasHeld = false;
  }

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    SystemChrome.setPreferredOrientations([
      DeviceOrientation.landscapeLeft,
      DeviceOrientation.landscapeRight,
    ]);
    engine = RaceEngineState(circuit: widget.circuit, livery: widget.livery);
    _ticker = createTicker(_onTick)..start();
  }

  void _onTick(Duration elapsed) {
    final double rawDt = (elapsed - _lastElapsed).inMicroseconds / 1000000.0;
    _lastElapsed = elapsed;
    if (rawDt <= 0.0) return;
    if (engine.isPaused || engine.raceFinished || engine.phase == SessionPhase.gridOverview) {
      _frameAcc = 0.0;
      return;
    }

    // Silky Vsync-Aligned Frame Pacer:
    // - On 60Hz & 90Hz phones: NEVER drops vsync frames (zero 60->30 or 90->45 micro-stutter!).
    // - On 120Hz phones in Eco mode: clean exact 2:1 cadence = rock-solid 60.0 FPS without jitter!
    if (rawDt > 0.003 && rawDt < 0.040) {
      _avgVsyncDt = (_avgVsyncDt * 0.90) + (rawDt * 0.10);
    }
    _frameAcc += rawDt;
    if (RaceEngineState.eco60FpsMode && _avgVsyncDt < 0.0096) {
      _skipAltFrame = !_skipAltFrame;
      if (_skipAltFrame && _frameAcc < 0.0145) {
        return;
      }
    }
    final double clamped = _frameAcc.clamp(0.004, 0.032).toDouble();
    _frameAcc = 0.0;

    // Silky adaptive frame-time low-pass filter: erases Choreographer micro-jitter for buttery motion!
    if ((clamped - _filteredDt).abs() > 0.012) {
      _filteredDt = clamped;
    } else {
      _filteredDt = (_filteredDt * 0.74) + (clamped * 0.26);
    }
    final double dt = _filteredDt;

    final int status = engine.step(dt);
    if (status == 1) {
      // Qualifying finished -> release all held pedals/steering & show Starting Grid overlay immediately!
      _clearAllInputPointers();
      _hudTick.value++;
      return;
    } else if (status == 2) {
      _clearAllInputPointers();
      _ticker.stop();
      _hudTick.value++;
      _showFinishDialog();
      return;
    }

    _hudAccumulator += dt;
    if (engine.offTrackStateChanged || engine.lapStateChanged || _hudAccumulator >= 0.050) {
      engine.offTrackStateChanged = false;
      engine.lapStateChanged = false;
      _hudAccumulator = 0.0;
      _hudTick.value++;
    }
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.paused || state == AppLifecycleState.inactive) {
      GamePrefsStore.saveAll();
      if (!engine.isPaused &&
          !engine.raceFinished &&
          engine.phase != SessionPhase.gridOverview) {
        _clearAllInputPointers();
        engine.togglePause();
        _hudTick.value++;
      }
    }
  }

  @override
  void dispose() {
    F1SoundEngine.stop();
    WidgetsBinding.instance.removeObserver(this);
    _ticker.dispose();
    engine.dispose();
    _hudTick.dispose();
    SystemChrome.setPreferredOrientations([
      DeviceOrientation.portraitUp,
      DeviceOrientation.landscapeLeft,
      DeviceOrientation.landscapeRight,
    ]);
    super.dispose();
  }

  String _formatTime(double seconds) {
    if (seconds >= 900) return '--:--.---';
    final int mins = seconds ~/ 60;
    final int secs = seconds.toInt() % 60;
    final int ms = ((seconds - seconds.floor()) * 1000).toInt();
    return '${mins.toString().padLeft(2, '0')}:${secs.toString().padLeft(2, '0')}.${ms.toString().padLeft(3, '0')}';
  }

  int _pointsForPos(int pos) {
    const List<int> table = [25, 18, 15, 12, 10, 8, 6, 4, 2, 1];
    return pos <= 10 ? table[pos - 1] : 0;
  }

  void _toggleErs() {
    if (engine.isPaused || engine.startLightsTimer > 0 || engine.resumeCountdownTimer > 0 || engine.phase == SessionPhase.gridOverview) return;
    if (!engine.ersToggledOn && engine.ersCharge < 5.0) {
      engine.showRadio('BATERÍA ERS BAJA — FRENA PARA RECARGAR', secs: 2.0);
      _hudTick.value++;
      return;
    }
    engine.ersToggledOn = !engine.ersToggledOn;
    if (engine.ersToggledOn) {
      F1SoundEngine.playEvent('ers');
    }
    _hudTick.value++;
  }

