  List<Map<String, Object>> _getMiniLeaderboard() {
    // Zero-Map-Churn leaderboard: sorts integer indices (-1 = Player, 0..N-1 = AI) in place!
    final int total = engine.aiDrivers.length + 1;
    if (_lbOrderScratch.length != total) {
      _lbOrderScratch
        ..clear()
        ..add(-1);
      for (int i = 0; i < engine.aiDrivers.length; i++) {
        _lbOrderScratch.add(i);
      }
    }
    double distOf(int idx) => idx < 0 ? engine.playerDist : engine.aiDrivers[idx].trackDist;
    _lbOrderScratch.sort((a, b) => distOf(b).compareTo(distOf(a)));

    final int pIdx = _lbOrderScratch.indexOf(-1);
    final int start = max(0, min(total - 3, pIdx - 1));
    final double leadDist = distOf(_lbOrderScratch[start]);
    _lbSliceScratch.clear();
    for (int i = start; i < min(total, start + 3); i++) {
      final int idx = _lbOrderScratch[i];
      final bool isMe = idx < 0;
      final double gapSec = (leadDist - distOf(idx)) / 65.0;
      _lbSliceScratch.add({
        'pos': i + 1,
        'code': isMe ? 'YOU' : engine.aiDrivers[idx].code,
        'color': isMe ? widget.livery.primary : engine.aiDrivers[idx].bodyColor,
        'isPlayer': isMe,
        'gap': i == start ? 'GAP' : '+${gapSec.toStringAsFixed(3)}',
      });
    }
    return _lbSliceScratch;
  }

  Widget _pedalWidget({
    required bool isGas,
    required bool pressed,
  }) {
    final double pedalW = isGas ? 66.0 : 74.0;
    final double pedalH = isGas ? 98.0 : 72.0;
    final double margin = isGas ? 10.0 : 4.0;
    final Set<int> activeSet = isGas ? _gasPointers : _brakePointers;

    return Listener(
      behavior: HitTestBehavior.opaque,
      onPointerDown: (e) {
        activeSet.add(e.pointer);
        _syncPedalPointers();
      },
      onPointerMove: (e) {
        final bool inside = e.localPosition.dx >= -margin &&
            e.localPosition.dx <= pedalW + margin &&
            e.localPosition.dy >= -margin &&
            e.localPosition.dy <= pedalH + margin;
        if (!inside && activeSet.remove(e.pointer)) {
          _syncPedalPointers();
        }
      },
      onPointerUp: (e) {
        if (activeSet.remove(e.pointer) || (isGas ? engine.gasHeld : engine.brakeHeld)) {
          _syncPedalPointers();
        }
      },
      onPointerCancel: (e) {
        if (activeSet.remove(e.pointer) || (isGas ? engine.gasHeld : engine.brakeHeld)) {
          _syncPedalPointers();
        }
      },
      child: Container(
        width: pedalW,
        height: pedalH,
        decoration: BoxDecoration(
          gradient: LinearGradient(
            colors: pressed
                ? (isGas
                    ? const [Color(0xEE2B6E47), Color(0xEE133020)]
                    : const [Color(0xEE8A2626), Color(0xEE381010)])
                : const [Color(0xEEC4CEDB), Color(0xEE5E6775), Color(0xEE343B45)],
            begin: Alignment.topLeft,
            end: Alignment.bottomRight,
          ),
          borderRadius: BorderRadius.circular(11),
          border: Border.all(
            color: pressed
                ? (isGas ? const Color(0xFF00E676) : const Color(0xFFFF5252))
