                borderRadius: BorderRadius.circular(18),
                border: Border.all(color: active ? const Color(0xFF00E5FF) : Colors.white38, width: 2.0),
                boxShadow: const [BoxShadow(color: Color(0x77000000), blurRadius: 8)],
              ),
              child: Stack(
                alignment: Alignment.center,
                children: [
                  // Recessed center rail groove
