                  ),
                  const Positioned(
                    right: 14,
                    child: Text('>', style: TextStyle(fontSize: 26, fontWeight: FontWeight.w900, color: Colors.white54)),
                  ),
                  Container(width: 2.5, height: 38, color: Colors.white24),
                  Positioned(
                    left: (halfW - knobW * 0.5) + curSteer * maxTravel,
                    child: Container(
                      width: knobW,
                      height: knobH,
                      decoration: BoxDecoration(
                        gradient: const LinearGradient(
                          colors: [Color(0xFF40EAFF), Color(0xFF0088CC)],
                          begin: Alignment.topCenter,
                          end: Alignment.bottomCenter,
                        ),
                        borderRadius: BorderRadius.circular(13),
                        border: Border.all(color: Colors.white, width: 2.0),
                        boxShadow: const [BoxShadow(color: Color(0x9900E5FF), blurRadius: 10)],
                      ),
                      child: Row(
                        mainAxisAlignment: MainAxisAlignment.center,
                        children: [
                          Container(width: 2.2, height: 28, decoration: BoxDecoration(color: Colors.white60, borderRadius: BorderRadius.circular(1))),
