class RealCircuitMinimapPainter extends CustomPainter {
  final TrackGeometry geometry;
  final double playerProgress;
  final List<AiDriver> aiDrivers;
  final double lapLengthMeters;
  final Color kerbColor;

  // Cached static minimap track path & paints (zero Path/Paint allocation at 20Hz!)
  static TrackGeometry? _cachedGeom;
  static Size _cachedSize = Size.zero;
  static Path? _cachedPath;
  static Offset _cachedSf = Offset.zero;
  static final Paint _trackPaint = Paint()
    ..isAntiAlias = true
    ..color = Colors.white70
    ..style = PaintingStyle.stroke
    ..strokeWidth = 2.6
    ..strokeJoin = StrokeJoin.round;
  static final Paint _sfPaint = Paint()..isAntiAlias = true;
  static final Paint _aiPaint = Paint()..isAntiAlias = true..color = const Color(0xAAFF5252);
  static final Paint _playerPaint = Paint()..isAntiAlias = true..color = const Color(0xFF00E676);

  RealCircuitMinimapPainter({
    required this.geometry,
    required this.playerProgress,
    required this.aiDrivers,
    required this.lapLengthMeters,
    required this.kerbColor,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final double cx = size.width * 0.5;
    final double cy = size.height * 0.5;
    final double r = min(size.width, size.height) * 0.46;

    if (!identical(_cachedGeom, geometry) || _cachedSize != size || _cachedPath == null) {
      _cachedGeom = geometry;
      _cachedSize = size;
      final Path p = Path();
      for (int i = 0; i < geometry.smoothPoints.length; i++) {
        final Offset pt = geometry.smoothPoints[i];
        final double x = cx + pt.dx * r;
        final double y = cy + pt.dy * r;
        if (i == 0) {
          p.moveTo(x, y);
        } else {
          p.lineTo(x, y);
        }
      }
      p.close();
      _cachedPath = p;
      final Offset sf = geometry.pointAtProgress(0.0);
      _cachedSf = Offset(cx + sf.dx * r, cy + sf.dy * r);
    }

    canvas.drawPath(_cachedPath!, _trackPaint);
    _sfPaint.color = kerbColor;
    canvas.drawCircle(_cachedSf, 3.0, _sfPaint);

    final double invLap = 1.0 / max(1.0, lapLengthMeters);
    for (int i = 0; i < aiDrivers.length; i++) {
      final double prog = (aiDrivers[i].trackDist % lapLengthMeters) * invLap;
      final Offset ap = geometry.pointAtProgress(prog);
      canvas.drawCircle(Offset(cx + ap.dx * r, cy + ap.dy * r), 1.8, _aiPaint);
    }

    final Offset pp = geometry.pointAtProgress(playerProgress);
    canvas.drawCircle(Offset(cx + pp.dx * r, cy + pp.dy * r), 3.9, _playerPaint);
  }

  @override
  bool shouldRepaint(covariant RealCircuitMinimapPainter oldDelegate) =>
      oldDelegate.playerProgress != playerProgress ||
      !identical(oldDelegate.geometry, geometry) ||
      oldDelegate.aiDrivers.length != aiDrivers.length;
}

