    // 3. Precompute Adaptive 104-Slice TRUE 1:1 FIA 3D Track Spine (Exact 226m Horizon & Zero Wasted Sub-Pixel Slices!)
    final double roadHalfW = engine.roadHalfWorldX;
    final double kerbOuterW = roadHalfW + (circuit.isStreetCircuit ? 0.40 : 0.54);
    final double astroOuterW = circuit.isStreetCircuit ? (kerbOuterW + 0.14) : (kerbOuterW + 0.52);
    const double terrainOuterW = 82.0;
    const double baseSegLen = 0.44;

    final double kerbJitter = (engine.carX.abs() > 0.88 && engine.carX.abs() < 1.05 && engine.speedKmh > 40)
