    // Exact chase camera Z distance so the player's True-3D Chase Car sits planted on the asphalt at 89.5% height on any screen!
    final double playerChaseZ = cockpit
        ? 0.0
        : ((-baseCamHeight * w * fovMult) / max(45.0, 0.895 * h - horizonY)).clamp(3.15, 5.20).toDouble();
    final double camOriginDist = cockpit ? engine.playerDist : (engine.playerDist - playerChaseZ * 2.0);
    // GTA 3 WORLD STREAMING: load upcoming 40m track sectors ahead & immediately unload passed sectors behind!
    final TrackStreamManager streamer = engine.streamer;
    streamer.streamAround(camOriginDist);
    final double camOriginHill = streamer.hillAt(camOriginDist);

    // Fractional slice phase (0..1): moves ALL quadratic slice depths smoothly from i -> i-1 with ZERO snap!
    final double slicePhase = _posMod(camOriginDist * 0.5, baseSegLen) / baseSegLen;
    _segZ[0] = 0.0;
    _segShift[0] = 0.0;
    _segElev[0] = 0.0;
    _segCurv[0] = streamer.kappaAt(camOriginDist);
    _segRunoffL[0] = streamer.runoffLeftAt(camOriginDist);
    _segRunoffR[0] = streamer.runoffRightAt(camOriginDist);
    _segIdealX[0] = streamer.idealLineAt(camOriginDist);
    _segTargetSpd[0] = streamer.targetSpeedAt(camOriginDist);
    _segHeavyBrake[0] = streamer.isHeavyBrakingAt(camOriginDist) ? 1 : 0;

    // EXACT EUCLIDEAN CURVE INTEGRATION sampled in O(1) directly from the active streamed 40m chunks!
    double thetaRoad = 0.0;
    double xRoadMeters = 0.0;
    double prevZVal = 0.0;
    final double yawSlope = (sin(engine.carHeading) * 1.22) + (engine.smoothSteerLook * 0.14);
    for (int i = 1; i <= segCount + 1; i++) {
      final double effI = i - slicePhase;
      final double zVal = (effI * baseSegLen) + (effI * effI * 0.00630);
      _segZ[i] = zVal;
      final double dsMeters = max(0.0, (zVal - prevZVal) * 2.0);
      prevZVal = zVal;
      final double wd = camOriginDist + zVal * 2.0;
      final double kappa = streamer.kappaAt(wd);
      _segCurv[i] = kappa;
      _segRunoffL[i] = streamer.runoffLeftAt(wd);
      _segRunoffR[i] = streamer.runoffRightAt(wd);
      _segIdealX[i] = streamer.idealLineAt(wd);
      _segTargetSpd[i] = streamer.targetSpeedAt(wd);
      _segHeavyBrake[i] = streamer.isHeavyBrakingAt(wd) ? 1 : 0;
      thetaRoad += kappa * dsMeters;
      final double thetaVis = thetaRoad.clamp(-1.36, 1.36).toDouble();
      xRoadMeters += sin(thetaVis) * dsMeters;
      _segShift[i] = (xRoadMeters * RaceEngineState.kMetersToWorldX) - (zVal * yawSlope);
      // Real vertical elevation minus camera tangent plane so crests rise & fall authentically!
      final double relHill = (streamer.hillAt(wd) - camOriginHill) - (hillSlope * zVal * 1.45);
      _segElev[i] = relHill * (0.35 + 0.65 * (i / segCount));
    }

