    final double gLean = engine.smoothSteerLook * 0.22;
    final double chaseSpineFollow = cockpit ? 0.0 : (_sampleSpineShift(playerChaseZ) * 0.72);
    final double camShift = chaseSpineFollow + engine.carX * engine.laneToWorldX + engine.spinYaw * 1.4 + gLean;

