    final Color kerbLitBRaw = Color.lerp(circuit.kerbB, Colors.white, sunNormX >= 0 ? 0.14 : 0.02)!;
    final Color kerbDarkARaw = Color.lerp(circuit.kerbA, Colors.black, sunNormX >= 0 ? 0.10 : 0.02)!;
    final Color kerbDarkBRaw = Color.lerp(circuit.kerbB, Colors.black, sunNormX >= 0 ? 0.10 : 0.02)!;
