    final Color aspMidOdd = Color.lerp(aspBaseOdd, Colors.black, 0.04)!;
    final Color aspCrownEven = Color.lerp(aspBaseEven, Colors.white, circuit.nightMode ? 0.04 : 0.06)!;
    final Color aspCrownOdd = Color.lerp(aspBaseOdd, Colors.white, circuit.nightMode ? 0.04 : 0.06)!;

