    final Color tecproMidRaw = Color.lerp(const Color(0xFFE61919), const Color(0xFFF9FBFF), 0.5)!;
    final Color chevMidRaw = Color.lerp(const Color(0xFFFFEA00), const Color(0xFF0E121A), 0.5)!;
    final Color kerbMidLitL = Color.lerp(kerbLitARaw, kerbLitBRaw, 0.5)!;
    final Color kerbMidLitR = Color.lerp(kerbDarkARaw, kerbDarkBRaw, 0.5)!;

    for (int i = segCount; i >= 0; i--) {
      final double z1Raw = _segZ[i];
      final double z2 = _segZ[i + 1];
      if (z2 <= 0.20) continue;

      final double tClip = z1Raw < 0.20
          ? ((0.20 - z1Raw) / max(1e-5, z2 - z1Raw)).clamp(0.0, 0.96).toDouble()
          : 0.0;
      final double z1 = z1Raw < 0.20 ? 0.20 : z1Raw;

      final double worldDist1 = camOriginDist + z1 * 2.0;
      final double worldDist2 = camOriginDist + z2 * 2.0;
      final double worldSpan = max(1e-5, worldDist2 - worldDist1);
      final double midWorldDist = 0.5 * (worldDist1 + worldDist2);
      final double lapDist1 = _posMod(worldDist1, lapLen);
      final double midLapDist = _posMod(midWorldDist, lapLen);
      // Nyquist-safe 4.2m physical block index (ALWAYS > max slice length 3.45m -> ZERO red/white/yellow strobing!)
      final int segIndex = (midWorldDist / 4.2).floor();

      final double s1Raw = _segShift[i] - camShift;
      final double s2 = _segShift[i + 1] - camShift;
      final double s1 = tClip > 0.0 ? (s1Raw + (s2 - s1Raw) * tClip) : s1Raw;

      final double y1Raw = baseCamHeight + _segElev[i];
      final double y2 = baseCamHeight + _segElev[i + 1];
      final double y1 = tClip > 0.0 ? (y1Raw + (y2 - y1Raw) * tClip) : y1Raw;
      final double kNow = _segCurv[i];

      // Smooth sub-slice continuous atmospheric fog (ZERO per-slice color stepping!)
      final double fogA = _fogTable[i];
      final double fogB = i > 0 ? _fogTable[i - 1] : 0.0;
      final double fogMix = fogA + (fogB - fogA) * slicePhase;
      final double farAntiShimmer = ((i - 52) / 36.0).clamp(0.0, 1.0).toDouble();

      // 3A. TRUE 3D PERSPECTIVE TERRAIN STRIPS & SIDE EMBANKMENTS (Rushes past in 100% genuine 3D foreshortening!)
      final int terrainBand = (worldDist1 / 9.5).floor();
      final Color rawTerrain = terrainBand % 2 == 0 ? groundLight : groundDark;
      final Color terrainCol = Color.lerp(rawTerrain, circuit.skyBottom, fogMix)!;
      final Offset t1L = _project(-terrainOuterW + s1, y1 - 0.06, z1, w, horizonY, fovMult);
      final Offset t1R = _project(terrainOuterW + s1, y1 - 0.06, z1, w, horizonY, fovMult);
      final Offset t2L = _project(-terrainOuterW + s2, y2 - 0.06, z2, w, horizonY, fovMult);
      final Offset t2R = _project(terrainOuterW + s2, y2 - 0.06, z2, w, horizonY, fovMult);
      _drawQuad(canvas, t1L, t1R, t2R, t2L, terrainCol);

      // Exact Asymmetric Left & Right Real-Meter Barrier Distances at slice z1 and z2 (interpolated cleanly at near plane!)
      final double run2L = _segRunoffL[i + 1];
      final double run2R = _segRunoffR[i + 1];
      final double run1L = tClip > 0.0 ? (_segRunoffL[i] + (run2L - _segRunoffL[i]) * tClip) : _segRunoffL[i];
      final double run1R = tClip > 0.0 ? (_segRunoffR[i] + (run2R - _segRunoffR[i]) * tClip) : _segRunoffR[i];
      final double wallCap1L = run1L + 0.50;
      final double wallCap2L = run2L + 0.50;
      final double wallCap1R = run1R + 0.50;
      final double wallCap2R = run2R + 0.50;
      final double clear1L = max(0.0, run1L - roadHalfW);
      final double clear1R = max(0.0, run1R - roadHalfW);

      // Sloped 3D Terrain Embankments flanking outside the actual asymmetric barriers
      if (i < 88 && circuit.propStyle != PropStyle.skyline) {
        final double bermH = 1.85 + circuit.hillAmp * 1.25;
        final Offset bm1LI = _project(-wallCap1L - 0.4 + s1, y1, z1, w, horizonY, fovMult);
        final Offset bm2LI = _project(-wallCap2L - 0.4 + s2, y2, z2, w, horizonY, fovMult);
        final Offset bm1LO = _project(-wallCap1L - 10.5 + s1, y1 + bermH, z1, w, horizonY, fovMult);
        final Offset bm2LO = _project(-wallCap2L - 10.5 + s2, y2 + bermH, z2, w, horizonY, fovMult);
        final Offset bm1RI = _project(wallCap1R + 0.4 + s1, y1, z1, w, horizonY, fovMult);
        final Offset bm2RI = _project(wallCap2R + 0.4 + s2, y2, z2, w, horizonY, fovMult);
        final Offset bm1RO = _project(wallCap1R + 10.5 + s1, y1 + bermH, z1, w, horizonY, fovMult);
        final Offset bm2RO = _project(wallCap2R + 10.5 + s2, y2 + bermH, z2, w, horizonY, fovMult);
        _drawQuad(canvas, bm1LO, bm1LI, bm2LI, bm2LO, Color.lerp(sunNormX >= 0 ? bermLight : bermDark, circuit.skyBottom, fogMix)!);
        _drawQuad(canvas, bm1RI, bm1RO, bm2RO, bm2RI, Color.lerp(sunNormX >= 0 ? bermDark : bermLight, circuit.skyBottom, fogMix)!);
      }

      // 3B. REAL-SPACE TRACK-TO-BARRIER RUNOFF APRON (Painted FIA Tarmac + Gravel Traps + Grass Verges + Pit Lane!)
      final bool onPitStraight = (lapDist1 < 185.0) || (lapDist1 > lapLen - 85.0);
      final Offset r1L = _project(-run1L + s1, y1, z1, w, horizonY, fovMult);
      final Offset r1R = _project(run1R + s1, y1, z1, w, horizonY, fovMult);
      final Offset r2L = _project(-run2L + s2, y2, z2, w, horizonY, fovMult);
      final Offset r2R = _project(run2R + s2, y2, z2, w, horizonY, fovMult);

      final Color tarmacRunRaw = segIndex % 2 == 0 ? circuit.runoffColor : tarmacRunDarkRaw;
      final Color tarmacRunCol = Color.lerp(tarmacRunRaw, circuit.skyBottom, fogMix)!;
      final Color pitLaneRaw = segIndex % 2 == 0 ? const Color(0xFF282E38) : const Color(0xFF232832);
      final Color pitLaneCol = Color.lerp(pitLaneRaw, circuit.skyBottom, fogMix)!;

      // Base runoff plane spanning exact real distance from left barrier to right barrier
      _drawQuad(canvas, r1L, r1R, r2R, r2L, onPitStraight ? pitLaneCol : tarmacRunCol);
      if (i < _asphaltClipMaxSlice) {
        final double minY = min(t1L.dy, min(t1R.dy, min(t2L.dy, t2R.dy)));
        if (minY < topRunoffY) topRunoffY = minY;
      }

      // Left-side & Right-side real-surface layering (Gravel Traps on wide corner runoffs, Mowed Grass Verges, or FIA Painted Tarmac Stripes!)
      if (!circuit.isStreetCircuit) {
        final Color gravelBase = circuit.nightMode
            ? (segIndex % 2 == 0 ? const Color(0xFF6B5D4A) : const Color(0xFF5F5241))
            : (segIndex % 2 == 0 ? const Color(0xFFC2AB82) : const Color(0xFFB39B72));
        final Color gravelCol = Color.lerp(gravelBase, circuit.skyBottom, fogMix)!;
        final Color grassVergeCol = Color.lerp(segIndex % 2 == 0 ? grassVergeEvenRaw : grassVergeOddRaw, circuit.skyBottom, fogMix)!;
        final Color stripeCol = Color.lerp(stripeRaw, circuit.skyBottom, fogMix)!;

        // LEFT SIDE RUNOFF DETAIL
        if (circuit.hasGravelTraps && clear1L >= 10.8) {
          // Outer ~56% of wide corner runoff is an authentic raked FIA Gravel Trap (leca de grava)!
          final double g1LI = roadHalfW + clear1L * 0.44;
          final double g2LI = roadHalfW + max(0.0, run2L - roadHalfW) * 0.44;
          final Offset gr1I = _project(-g1LI + s1, y1 + 0.005, z1, w, horizonY, fovMult);
          final Offset gr2I = _project(-g2LI + s2, y2 + 0.005, z2, w, horizonY, fovMult);
          _drawQuad(canvas, r1L, gr1I, gr2I, r2L, gravelCol);
          // Crisp sunken concrete retaining curb + 3D sunlit/shadowed corduroy raked gravel furrows!
          if (i < 56) {
            _strokePaint
              ..color = Color.lerp(const Color(0xCC9AA6B5), circuit.skyBottom, fogMix)!
              ..strokeWidth = max(1.0, 3.8 / z1);
            canvas.drawLine(gr1I, gr2I, _strokePaint);
            if (segIndex % 2 == 0) {
              _strokePaint
                ..color = Color.fromARGB((66 * (1.0 - fogMix)).toInt(), 42, 28, 12)
                ..strokeWidth = max(1.1, 3.4 / z1);
              canvas.drawLine(Offset.lerp(r1L, gr1I, 0.25)!, Offset.lerp(r2L, gr2I, 0.25)!, _strokePaint);
              canvas.drawLine(Offset.lerp(r1L, gr1I, 0.55)!, Offset.lerp(r2L, gr2I, 0.55)!, _strokePaint);
              canvas.drawLine(Offset.lerp(r1L, gr1I, 0.82)!, Offset.lerp(r2L, gr2I, 0.82)!, _strokePaint);
              if (i < 34) {
                _strokePaint
                  ..color = Color.fromARGB((44 * (1.0 - fogMix)).toInt(), 255, 242, 214)
                  ..strokeWidth = max(0.8, 2.0 / z1);
                canvas.drawLine(Offset.lerp(r1L, gr1I, 0.30)!, Offset.lerp(r2L, gr2I, 0.30)!, _strokePaint);
                canvas.drawLine(Offset.lerp(r1L, gr1I, 0.60)!, Offset.lerp(r2L, gr2I, 0.60)!, _strokePaint);
              }
            }
          }
          if (i < 68 && segIndex % 4 == 0 && g1LI > astroOuterW + 0.8) {
            _drawQuad(
              canvas,
              _project(-g1LI + 0.25 + s1, y1 + 0.008, z1, w, horizonY, fovMult),
              _project(-astroOuterW - 0.12 + s1, y1 + 0.008, z1, w, horizonY, fovMult),
              _project(-astroOuterW + 0.12 + s2, y2 + 0.008, z2, w, horizonY, fovMult),
              _project(-g2LI + 0.55 + s2, y2 + 0.008, z2, w, horizonY, fovMult),
              stripeCol,
            );
          }
        } else if (circuit.hasGravelTraps && !onPitStraight && clear1L > 2.6) {
          // Classic grass verge between trackside tarmac strip & straightaway barrier
          final double v1LI = min(run1L - 0.4, astroOuterW + 1.45);
          final double v2LI = min(run2L - 0.4, astroOuterW + 1.45);
          _drawQuad(
            canvas,
            r1L,
            _project(-v1LI + s1, y1 + 0.004, z1, w, horizonY, fovMult),
            _project(-v2LI + s2, y2 + 0.004, z2, w, horizonY, fovMult),
            r2L,
            grassVergeCol,
          );
        } else if (!onPitStraight && i < 68 && segIndex % 4 == 0 && clear1L > 2.2) {
          // Painted FIA high-grip diagonal runoff stripes (Abu Dhabi, COTA, Mexico)
          final double stOut1 = min(run1L - 0.35, astroOuterW + 7.5);
          final double stOut2 = min(run2L - 0.35, astroOuterW + 7.5);
          _drawQuad(
            canvas,
            _project(-stOut1 + s1, y1 + 0.008, z1, w, horizonY, fovMult),
            _project(-astroOuterW - 0.12 + s1, y1 + 0.008, z1, w, horizonY, fovMult),
            _project(-astroOuterW + 0.12 + s2, y2 + 0.008, z2, w, horizonY, fovMult),
            _project(-stOut2 + 0.35 + s2, y2 + 0.008, z2, w, horizonY, fovMult),
            stripeCol,
          );
        }

        // RIGHT SIDE RUNOFF DETAIL (skip gravel/grass when on Pit Lane straight!)
        if (!onPitStraight) {
          if (circuit.hasGravelTraps && clear1R >= 10.8) {
            final double g1RI = roadHalfW + clear1R * 0.44;
            final double g2RI = roadHalfW + max(0.0, run2R - roadHalfW) * 0.44;
            final Offset gr1RI = _project(g1RI + s1, y1 + 0.005, z1, w, horizonY, fovMult);
            final Offset gr2RI = _project(g2RI + s2, y2 + 0.005, z2, w, horizonY, fovMult);
            _drawQuad(canvas, gr1RI, r1R, r2R, gr2RI, gravelCol);
            if (i < 56) {
              _strokePaint
                ..color = Color.lerp(const Color(0xCC9AA6B5), circuit.skyBottom, fogMix)!
                ..strokeWidth = max(1.0, 3.8 / z1);
              canvas.drawLine(gr1RI, gr2RI, _strokePaint);
              if (segIndex % 2 == 0) {
                _strokePaint
                  ..color = Color.fromARGB((66 * (1.0 - fogMix)).toInt(), 42, 28, 12)
                  ..strokeWidth = max(1.1, 3.4 / z1);
                canvas.drawLine(Offset.lerp(gr1RI, r1R, 0.25)!, Offset.lerp(gr2RI, r2R, 0.25)!, _strokePaint);
                canvas.drawLine(Offset.lerp(gr1RI, r1R, 0.55)!, Offset.lerp(gr2RI, r2R, 0.55)!, _strokePaint);
                canvas.drawLine(Offset.lerp(gr1RI, r1R, 0.82)!, Offset.lerp(gr2RI, r2R, 0.82)!, _strokePaint);
                if (i < 34) {
                  _strokePaint
                    ..color = Color.fromARGB((44 * (1.0 - fogMix)).toInt(), 255, 242, 214)
                    ..strokeWidth = max(0.8, 2.0 / z1);
                  canvas.drawLine(Offset.lerp(gr1RI, r1R, 0.30)!, Offset.lerp(gr2RI, r2R, 0.30)!, _strokePaint);
                  canvas.drawLine(Offset.lerp(gr1RI, r1R, 0.60)!, Offset.lerp(gr2RI, r2R, 0.60)!, _strokePaint);
                }
              }
            }
            if (i < 68 && segIndex % 4 == 0 && g1RI > astroOuterW + 0.8) {
              _drawQuad(
                canvas,
                _project(astroOuterW + 0.12 + s1, y1 + 0.008, z1, w, horizonY, fovMult),
                _project(g1RI - 0.25 + s1, y1 + 0.008, z1, w, horizonY, fovMult),
                _project(g2RI - 0.55 + s2, y2 + 0.008, z2, w, horizonY, fovMult),
                _project(astroOuterW - 0.12 + s2, y2 + 0.008, z2, w, horizonY, fovMult),
                stripeCol,
              );
            }
          } else if (circuit.hasGravelTraps && clear1R > 2.6) {
            final double v1RI = min(run1R - 0.4, astroOuterW + 1.45);
            final double v2RI = min(run2R - 0.4, astroOuterW + 1.45);
            _drawQuad(
              canvas,
              _project(v1RI + s1, y1 + 0.004, z1, w, horizonY, fovMult),
              r1R,
              r2R,
              _project(v2RI + s2, y2 + 0.004, z2, w, horizonY, fovMult),
              grassVergeCol,
            );
          } else if (i < 68 && segIndex % 4 == 0 && clear1R > 2.2) {
            final double stOut1 = min(run1R - 0.35, astroOuterW + 7.5);
            final double stOut2 = min(run2R - 0.35, astroOuterW + 7.5);
            _drawQuad(
              canvas,
              _project(astroOuterW + 0.12 + s1, y1 + 0.008, z1, w, horizonY, fovMult),
              _project(stOut1 + s1, y1 + 0.008, z1, w, horizonY, fovMult),
              _project(stOut2 - 0.35 + s2, y2 + 0.008, z2, w, horizonY, fovMult),
              _project(astroOuterW - 0.12 + s2, y2 + 0.008, z2, w, horizonY, fovMult),
              stripeCol,
            );
          }
        }
      }

      // Pit Lane White Divider & Team Pit Wall on Right Side of Main Straight
      if (onPitStraight && i < 76) {
        final double pitLine1 = min(run1R - 0.4, astroOuterW + 0.45);
        final double pitLine2 = min(run2R - 0.4, astroOuterW + 0.45);
        final Offset pl1 = _project(pitLine1 + s1, y1 + 0.01, z1, w, horizonY, fovMult);
        final Offset pl2 = _project(pitLine2 + s2, y2 + 0.01, z2, w, horizonY, fovMult);
        _strokePaint
          ..color = Color.lerp(const Color(0xDDFFFFFF), circuit.skyBottom, fogMix)!
          ..strokeWidth = max(1.0, 3.6 / z1);
        canvas.drawLine(pl1, pl2, _strokePaint);

        // 3D Pit Wall + Illuminated Telemetry Timing Stands + Team Pit Garages!
        final Offset pw1B = _project(run1R + 0.15 + s1, y1, z1, w, horizonY, fovMult);
        final Offset pw2B = _project(run2R + 0.15 + s2, y2, z2, w, horizonY, fovMult);
        final Offset pw1T = _project(run1R + 0.15 + s1, y1 + 1.62, z1, w, horizonY, fovMult);
        final Offset pw2T = _project(run2R + 0.15 + s2, y2 + 1.62, z2, w, horizonY, fovMult);
        final Offset pw1R = _project(run1R + 1.85 + s1, y1 + 2.05, z1, w, horizonY, fovMult);
        final Offset pw2R = _project(run2R + 1.85 + s2, y2 + 2.05, z2, w, horizonY, fovMult);
        _drawQuad(canvas, pw1B, pw2B, pw2T, pw1T, Color.lerp(const Color(0xFF172030), circuit.skyBottom, fogMix)!);
        _drawQuad(canvas, pw1T, pw2T, pw2R, pw1R, Color.lerp(segIndex % 6 < 3 ? circuit.kerbA : const Color(0xFF0D1320), circuit.skyBottom, fogMix)!);

        // Glowing cyan/amber pit-wall monitor LED ribbon & backlit team garage bay behind pit lane
        final Offset mon1 = _project(run1R + 0.22 + s1, y1 + 1.24, z1, w, horizonY, fovMult);
        final Offset mon2 = _project(run2R + 0.22 + s2, y2 + 1.24, z2, w, horizonY, fovMult);
        _strokePaint
          ..color = Color.lerp(segIndex % 4 == 0 ? const Color(0xCC00E5FF) : const Color(0xAAFFD54F), circuit.skyBottom, fogMix)!
          ..strokeWidth = max(1.0, 4.2 / z1);
        canvas.drawLine(mon1, mon2, _strokePaint);

        if (i < 64) {
          final Offset gb1B = _project(run1R + 4.4 + s1, y1, z1, w, horizonY, fovMult);
          final Offset gb2B = _project(run2R + 4.4 + s2, y2, z2, w, horizonY, fovMult);
          final Offset gb1T = _project(run1R + 4.4 + s1, y1 + 4.35, z1, w, horizonY, fovMult);
          final Offset gb2T = _project(run2R + 4.4 + s2, y2 + 4.35, z2, w, horizonY, fovMult);
          final bool litBay = segIndex % 5 != 0;
          _drawQuad(
            canvas,
            gb1B,
            gb2B,
            gb2T,
            gb1T,
            Color.lerp(litBay ? const Color(0xFF222D40) : const Color(0xFF111622), circuit.skyBottom, fogMix)!,
          );
          if (litBay) {
            final Offset gl1 = _project(run1R + 4.32 + s1, y1 + 2.55, z1, w, horizonY, fovMult);
            final Offset gl2 = _project(run2R + 4.32 + s2, y2 + 2.55, z2, w, horizonY, fovMult);
            _strokePaint
              ..color = Color.lerp(const Color(0xCCEAF6FF), circuit.skyBottom, fogMix)!
              ..strokeWidth = max(1.2, 6.2 / z1);
            canvas.drawLine(gl1, gl2, _strokePaint);
          }
        }

        // Iconic 3D FIA Race Control Tower & Glowing Digital Timing Pylon right near the Start/Finish Line!
        if (lapDist1 > 12.0 && lapDist1 < 22.0 && i < 68) {
          final Offset rc1B = _project(run1R + 5.2 + s1, y1, z1, w, horizonY, fovMult);
          final Offset rc2B = _project(run2R + 5.2 + s2, y2, z2, w, horizonY, fovMult);
          final Offset rc1T = _project(run1R + 5.2 + s1, y1 + 8.4, z1, w, horizonY, fovMult);
          final Offset rc2T = _project(run2R + 5.2 + s2, y2 + 8.4, z2, w, horizonY, fovMult);
          _drawQuad(canvas, rc1B, rc2B, rc2T, rc1T, Color.lerp(const Color(0xFF1A2438), circuit.skyBottom, fogMix)!);
          // Illuminated panoramic race-director glass observation floor
          final Offset gl1B = _project(run1R + 5.05 + s1, y1 + 5.4, z1, w, horizonY, fovMult);
          final Offset gl2B = _project(run2R + 5.05 + s2, y2 + 5.4, z2, w, horizonY, fovMult);
          final Offset gl1T = _project(run1R + 5.05 + s1, y1 + 7.2, z1, w, horizonY, fovMult);
          final Offset gl2T = _project(run2R + 5.05 + s2, y2 + 7.2, z2, w, horizonY, fovMult);
          _drawQuad(
            canvas,
            gl1B,
            gl2B,
            gl2T,
            gl1T,
            Color.lerp(circuit.nightMode ? const Color(0xFF56D4FF) : const Color(0xFFAAD8FA), circuit.skyBottom, fogMix * 0.75)!,
          );
          // Red FIA roof band
          final Offset rf1B = _project(run1R + 5.05 + s1, y1 + 7.6, z1, w, horizonY, fovMult);
          final Offset rf2B = _project(run2R + 5.05 + s2, y2 + 7.6, z2, w, horizonY, fovMult);
          _drawQuad(canvas, rf1B, rf2B, rc2T, rc1T, Color.lerp(const Color(0xFFE10600), circuit.skyBottom, fogMix)!);
        }
      }

      // 3C. TRUE 3D MULTI-SLICE EXTRUDED GRANDSTANDS (Anchored smoothly BEHIND the real outer barriers!)
      final int gsBlock = (lapDist1 / 175.0).floor();
      final double gsLocal = lapDist1 % 175.0;
      if (gsLocal >= 14.0 && gsLocal <= 52.0 && i < 90) {
        final bool onLeftSide = (gsBlock % 2 == 0);
        if (!(onPitStraight && !onLeftSide)) {
          _draw3DExtrudedGrandstandSlice(
            canvas,
            onLeftSide ? (-wallCap1L - 0.55) : (wallCap1R + 0.55),
            onLeftSide ? (-wallCap2L - 0.55) : (wallCap2R + 0.55),
            s1,
            s2,
            y1,
            y2,
            z1,
            z2,
            onLeftSide,
            segIndex,
            w,
            horizonY,
            fovMult,
            fogMix,
            circuit,
          );
        }
      }

      // 3C-2. EXACT SUB-SLICE WORLD-ANCHORED 3D Trackside Props (Buildings, Trees, Palms, Floodlights) BEHIND outer barriers!
      // Exact world-coordinate interpolation eliminates ALL 3-6m depth jumping, popping & blinking!
      if (i >= 0 && i < segCount - 3) {
        final int propIdx = (worldDist2 / 32.0).floor();
        final double propWorldDist = propIdx * 32.0;
        if (propWorldDist >= worldDist1 && propWorldDist < worldDist2) {
          final double frac = ((propWorldDist - worldDist1) / worldSpan).clamp(0.0, 1.0).toDouble();
          final double pz = z1 + (z2 - z1) * frac;
          if (pz > 0.35) {
            final double ps = s1 + (s2 - s1) * frac;
            final double py = y1 + (y2 - y1) * frac;
            final double pCapL = wallCap1L + (wallCap2L - wallCap1L) * frac;
            final double pCapR = wallCap1R + (wallCap2R - wallCap1R) * frac;
            final double pLapD = _posMod(propWorldDist, lapLen);
            final int pGsBlock = (pLapD / 175.0).floor();
            final double pGsLocal = pLapD % 175.0;
            final bool pOnPit = (pLapD < 185.0) || (pLapD > lapLen - 85.0);
            final bool inGsLeft = (pGsLocal >= 10.0 && pGsLocal <= 56.0 && pGsBlock % 2 == 0);
            final bool inGsRight = (pGsLocal >= 10.0 && pGsLocal <= 56.0 && pGsBlock % 2 == 1);
            // Gentle horizon mist fade-in across the last 8 slices so buildings emerge smoothly, never pop!
            final double horizonFade = ((segCount - 3 - i) / 9.0).clamp(0.0, 1.0).toDouble();
            final double propFog = (fogMix + (1.0 - horizonFade) * (1.0 - fogMix) * 0.72).clamp(0.0, 0.96).toDouble();
            if (!inGsLeft) {
              _drawTracksideProp3D(canvas, -pCapL - 2.35 + ps, py, pz, w, horizonY, fovMult, propFog, circuit, true, propIdx);
            }
            if (!inGsRight && !pOnPit) {
              _drawTracksideProp3D(canvas, pCapR + 2.35 + ps, py, pz, w, horizonY, fovMult, propFog, circuit, false, propIdx + 17);
            }
          }
        }
      }

      // 3D. CRYSTAL-CLEAR SOLID 3D ASYMMETRIC BARRIERS (Outer Wall + Top Cap + High-Contrast Front Face + Armco Rails + Chevrons!)
      // Full 3D solidity + bright galvanized/TECPRO contrast + reduced fog washout -> ZERO invisible walls in Monaco or tight hairpins!
      final double wallH = circuit.isStreetCircuit ? 1.24 : 1.04;
      final double barrierFog = fogMix * 0.56;
      final Offset w1LT = _project(-run1L + s1, y1 + wallH, z1, w, horizonY, fovMult);
      final Offset w2LT = _project(-run2L + s2, y2 + wallH, z2, w, horizonY, fovMult);
      final Offset w1RT = _project(run1R + s1, y1 + wallH, z1, w, horizonY, fovMult);
      final Offset w2RT = _project(run2R + s2, y2 + wallH, z2, w, horizonY, fovMult);
      final Offset wc1LT = _project(-wallCap1L + s1, y1 + wallH, z1, w, horizonY, fovMult);
      final Offset wc2LT = _project(-wallCap2L + s2, y2 + wallH, z2, w, horizonY, fovMult);
      final Offset wc1RT = _project(wallCap1R + s1, y1 + wallH, z1, w, horizonY, fovMult);
      final Offset wc2RT = _project(wallCap2R + s2, y2 + wallH, z2, w, horizonY, fovMult);
      final Offset bo1L = _project(-wallCap1L + s1, y1, z1, w, horizonY, fovMult);
      final Offset bo2L = _project(-wallCap2L + s2, y2, z2, w, horizonY, fovMult);
      final Offset bo1R = _project(wallCap1R + s1, y1, z1, w, horizonY, fovMult);
      final Offset bo2R = _project(wallCap2R + s2, y2, z2, w, horizonY, fovMult);

      // Directional Barrier Cast Shadows onto the Runoff / Gravel
      if (i < 75) {
        final double lShadW = min(clear1L * 0.65, sunNormX >= 0 ? 0.92 : 0.48);
        final double rShadW = min(clear1R * 0.65, sunNormX >= 0 ? 0.48 : 0.92);
