      // 3D Top Cap of Concrete / Galvanized Armco / TECPRO Barrier (batched left+right!)
      final Color capCol = Color.lerp(
        circuit.isStreetCircuit ? const Color(0xFFE2ECF8) : const Color(0xFFD2DCEB),
        circuit.skyBottom,
