      )!;
      _drawQuadPair(canvas, wc1LT, w1LT, w2LT, wc2LT, w1RT, wc1RT, wc2RT, w2RT, capCol);

      // High-Contrast Barrier Front Faces:
      // - Outer corners: Bright FIA Red & White TECPRO blocks!
      // - Street circuits (Monaco, Baku, Jeddah, etc.): Bright Galvanized Steel Armco + Circuit Sponsor Panels (ZERO dark camouflage!)
      // - Permanent circuits: Crisp Light Concrete + Sponsor Panels
      final bool leftIsOutsideCorner = kNow > 0.010;
      final bool rightIsOutsideCorner = kNow < -0.010;
      final Color wallBase = circuit.isStreetCircuit
          ? ((segIndex % 6 < 3)
              ? const Color(0xFFC4D0DF)
              : (segIndex % 12 < 6 ? circuit.kerbA : const Color(0xFFF6F9FF)))
          : ((segIndex % 6 < 3)
              ? const Color(0xFFB4C0D0)
              : (segIndex % 12 < 6 ? circuit.kerbA : const Color(0xFFF4F7FC)));
      final Color tecproRaw = segIndex % 2 == 0 ? const Color(0xFFE61919) : const Color(0xFFF9FBFF);
      final Color tecproStable = farAntiShimmer > 0.0
          ? Color.lerp(tecproRaw, tecproMidRaw, farAntiShimmer * 0.72)!
          : tecproRaw;
      final Color leftWallRaw = leftIsOutsideCorner ? tecproStable : wallBase;
      final Color rightWallRaw = rightIsOutsideCorner ? tecproStable : wallBase;

      final Color wallLeftCol = Color.lerp(
