      _drawQuad(canvas, r1R, r2R, w2RT, w1RT, wallRightCol);

      // Realistic 3D Sloped New-Jersey Concrete Plinth Base + Upper Specular Rim + Tire Scuff Patina!
      if (i < 58) {
