        final Offset pl2LT = _project(-run2L + 0.03 + s2, y2 + plinthH, z2, w, horizonY, fovMult);
        final Offset pl1LB = _project(-run1L + 0.14 + s1, y1, z1, w, horizonY, fovMult);
        final Offset pl2LB = _project(-run2L + 0.14 + s2, y2, z2, w, horizonY, fovMult);
        final Offset pl1RT = _project(run1R - 0.03 + s1, y1 + plinthH, z1, w, horizonY, fovMult);
        final Offset pl2RT = _project(run2R - 0.03 + s2, y2 + plinthH, z2, w, horizonY, fovMult);
