      // Authentic Stacked 3D FIA Tire-Barrier Cushions & Conveyor Belt Straps on Heavy Outer Corners!
      if ((leftIsOutsideCorner || rightIsOutsideCorner) && i < 54) {
        final bool onLeft = leftIsOutsideCorner;
        final double txIn1 = onLeft ? (-run1L + 0.34) : (run1R - 0.34);
