        final Offset tb1B = _project(txIn1 + s1, y1, z1, w, horizonY, fovMult);
        final Offset tb2B = _project(txIn2 + s2, y2, z2, w, horizonY, fovMult);
        final Offset tb1T = _project(txIn1 + s1, y1 + tH, z1, w, horizonY, fovMult);
        final Offset tb2T = _project(txIn2 + s2, y2 + tH, z2, w, horizonY, fovMult);
        final Offset tb1BackT = _project(txOut1 + s1, y1 + tH, z1, w, horizonY, fovMult);
        final Offset tb2BackT = _project(txOut2 + s2, y2 + tH, z2, w, horizonY, fovMult);
        final Color tireWallCol = Color.lerp(segIndex % 2 == 0 ? const Color(0xFF1A1E26) : const Color(0xFF10131A), circuit.skyBottom, barrierFog)!;
        final Color tireTopCol = Color.lerp(const Color(0xFF2B323E), circuit.skyBottom, barrierFog)!;
        _drawQuad(canvas, tb1B, tb1T, tb2T, tb2B, tireWallCol);
        _drawQuad(canvas, tb1BackT, tb1T, tb2T, tb2BackT, tireTopCol);
        // Horizontal FIA rubber conveyor-belt strap & red/white impact fascia across the tire stack!
        final Offset st1A = _project(txIn1 + (onLeft ? 0.02 : -0.02) + s1, y1 + tH * 0.56, z1, w, horizonY, fovMult);
        final Offset st2A = _project(txIn2 + (onLeft ? 0.02 : -0.02) + s2, y2 + tH * 0.56, z2, w, horizonY, fovMult);
