        // Individual stacked rubber tire horizontal ribs
        if (i < 34) {
          _strokePaint
            ..color = Color.lerp(const Color(0xAA05070A), circuit.skyBottom, barrierFog)!
            ..strokeWidth = max(1.0, 2.8 / z1);
          canvas.drawLine(
            _project(txIn1 + s1, y1 + tH * 0.30, z1, w, horizonY, fovMult),
