        }
      }

      // Unmistakable High-Contrast Upper Edge & Base Curb Trim (guarantees barrier is ALWAYS legible even at grazing angles!)
      _strokePaint
        ..color = Color.lerp(const Color(0xF5FFFFFF), circuit.skyBottom, barrierFog * 0.72)!
        ..strokeWidth = max(1.2, 4.2 / z1);
      canvas.drawLine(w1LT, w2LT, _strokePaint);
      canvas.drawLine(w1RT, w2RT, _strokePaint);

      _strokePaint
        ..color = Color.lerp(const Color(0xDD1A2230), circuit.skyBottom, barrierFog * 0.75)!
        ..strokeWidth = max(1.0, 3.6 / z1);
      canvas.drawLine(r1L, r2L, _strokePaint);
      canvas.drawLine(r1R, r2R, _strokePaint);

      // Iconic Double Galvanized Armco W-Beam Guardrails (Street Circuits like Monaco!) & Crisp Structural Panel Seams!
      if (i < 74) {
        final double ribH1 = wallH * (circuit.isStreetCircuit ? 0.42 : 0.76);
        final double ribH2 = wallH * 0.74;
        final Offset lr1A = _project(-run1L + 0.02 + s1, y1 + ribH1, z1, w, horizonY, fovMult);
        final Offset lr2A = _project(-run2L + 0.02 + s2, y2 + ribH1, z2, w, horizonY, fovMult);
        final Offset rr1A = _project(run1R - 0.02 + s1, y1 + ribH1, z1, w, horizonY, fovMult);
        final Offset rr2A = _project(run2R - 0.02 + s2, y2 + ribH1, z2, w, horizonY, fovMult);
        _strokePaint
          ..color = Color.lerp(
