        if (circuit.isStreetCircuit) {
          // Dark shadow groove under upper Armco beam + second upper steel rail (classic Monaco guardrail look!)
          final double grooveH = wallH * 0.58;
          _strokePaint
            ..color = Color.lerp(const Color(0xCC243044), circuit.skyBottom, barrierFog)!
