            _strokePaint,
          );
          final Offset lr1B = _project(-run1L + 0.02 + s1, y1 + ribH2, z1, w, horizonY, fovMult);
          final Offset lr2B = _project(-run2L + 0.02 + s2, y2 + ribH2, z2, w, horizonY, fovMult);
          final Offset rr1B = _project(run1R - 0.02 + s1, y1 + ribH2, z1, w, horizonY, fovMult);
          final Offset rr2B = _project(run2R - 0.02 + s2, y2 + ribH2, z2, w, horizonY, fovMult);
          _strokePaint
