          final double seamDist = seamIdx * 4.2;
          if (seamDist >= worldDist1 && seamDist < worldDist2) {
            final double sFrac = ((seamDist - worldDist1) / worldSpan).clamp(0.0, 1.0).toDouble();
            final Offset srL = Offset.lerp(r1L, r2L, sFrac)!;
