            final Offset srR = Offset.lerp(r1R, r2R, sFrac)!;
            final Offset swR = Offset.lerp(w1RT, w2RT, sFrac)!;
            final double sz = z1 + (z2 - z1) * sFrac;
            _strokePaint
              ..color = Color.lerp(const Color(0xC4141C2A), circuit.skyBottom, barrierFog)!
