            canvas.drawLine(srL, swL, _strokePaint);
            canvas.drawLine(srR, swR, _strokePaint);
            if (i < 32) {
              _strokePaint
                ..color = Color.lerp(const Color(0x66FFFFFF), circuit.skyBottom, barrierFog)!
                ..strokeWidth = max(0.8, 1.8 / sz);
              canvas.drawLine(Offset(srL.dx + 1.5, srL.dy), Offset(swL.dx + 1.5, swL.dy), _strokePaint);
              canvas.drawLine(Offset(srR.dx - 1.5, srR.dy), Offset(swR.dx - 1.5, swR.dy), _strokePaint);
