          }
        }
        // Realistic dark rubber tire-kiss scuff streaks along street-circuit walls & braking zones!
        if (i < 42 && (circuit.isStreetCircuit || kNow.abs() > 0.008) && (segIndex % 5 == 0 || segIndex % 5 == 1)) {
          final double scH = wallH * 0.36;
          _strokePaint
            ..color = Color.fromARGB((76 * (1.0 - barrierFog)).toInt(), 8, 10, 14)
            ..strokeWidth = max(1.4, 5.2 / z1);
          canvas.drawLine(
            _project(-run1L + 0.04 + s1, y1 + scH, z1, w, horizonY, fovMult),
            _project(-run2L + 0.04 + s2, y2 + scH, z2, w, horizonY, fovMult),
