          canvas.drawLine(
            _project(run1R - 0.04 + s1, y1 + scH, z1, w, horizonY, fovMult),
            _project(run2R - 0.04 + s2, y2 + scH, z2, w, horizonY, fovMult),
            _strokePaint,
          );
        }

        // Smooth F1 Digital LED Sponsor Ribbon along main barrier segments (gentle color glide -> ZERO strobing!)
        if (!leftIsOutsideCorner && !rightIsOutsideCorner && (segIndex % 8 < 3) && i < 56) {
          final double wave = 0.5 + 0.5 * sin(engine.totalRaceTime * 2.8 + segIndex * 0.65);
          final Color ledStripCol = Color.lerp(const Color(0xEEE10600), const Color(0xF000E5FF), wave * 0.45)!;
          final double ledY = wallH * 0.56;
          _strokePaint
            ..color = Color.lerp(ledStripCol, circuit.skyBottom, barrierFog * 0.55)!
            ..strokeWidth = max(1.2, 4.8 / z1);
          canvas.drawLine(
            _project(-run1L + 0.04 + s1, y1 + ledY, z1, w, horizonY, fovMult),
