      // 3D Curved FIA Corner Chevron Boards with Crisp Directional Arrow Chevrons above Outer Barrier!
      if ((leftIsOutsideCorner || rightIsOutsideCorner) && i < 68) {
        final bool onLeft = leftIsOutsideCorner;
        final double cx1 = (onLeft ? -run1L - 0.05 : run1R + 0.05) + s1;
        final double cx2 = (onLeft ? -run2L - 0.05 : run2R + 0.05) + s2;
        final Offset ch1B = _project(cx1, y1 + wallH + 0.06, z1, w, horizonY, fovMult);
        final Offset ch2B = _project(cx2, y2 + wallH + 0.06, z2, w, horizonY, fovMult);
        final Offset ch1T = _project(cx1, y1 + wallH + 0.78, z1, w, horizonY, fovMult);
        final Offset ch2T = _project(cx2, y2 + wallH + 0.78, z2, w, horizonY, fovMult);
        final bool isYellow = segIndex % 2 != 0;
        final Color chevBase = isYellow ? const Color(0xFFFFEA00) : const Color(0xFF0E121A);
        final Color chevStable = farAntiShimmer > 0.0
            ? Color.lerp(chevBase, chevMidRaw, farAntiShimmer * 0.72)!
