        final Color chevCol = Color.lerp(chevStable, circuit.skyBottom, barrierFog)!;
        _drawQuad(canvas, ch1B, ch1T, ch2T, ch2B, chevCol);
        if (i < 44) {
          final Offset midEdge = Offset.lerp(ch1B, ch1T, 0.50)!;
          final Offset tipTop = Offset.lerp(ch1T, ch2T, 0.65)!;
          final Offset tipBot = Offset.lerp(ch1B, ch2B, 0.65)!;
          _strokePaint
            ..color = Color.lerp(isYellow ? const Color(0xFF0C1018) : const Color(0xFFFFEA00), circuit.skyBottom, barrierFog)!
            ..strokeWidth = max(1.0, 3.8 / z1);
          canvas.drawLine(tipTop, midEdge, _strokePaint);
          canvas.drawLine(midEdge, tipBot, _strokePaint);
