      // World-Anchored 3D Catch Fencing mounted directly along the Asymmetric Outer Barriers (high-visibility steel posts!)
      if (i < 78) {
        final Offset f1LT = _project(-run1L + s1, y1 + wallH + 1.38, z1, w, horizonY, fovMult);
        final Offset f2LT = _project(-run2L + s2, y2 + wallH + 1.38, z2, w, horizonY, fovMult);
        final Offset f1RT = _project(run1R + s1, y1 + wallH + 1.38, z1, w, horizonY, fovMult);
        final Offset f2RT = _project(run2R + s2, y2 + wallH + 1.38, z2, w, horizonY, fovMult);
        final Offset f1LM = _project(-run1L + s1, y1 + wallH + 0.68, z1, w, horizonY, fovMult);
        final Offset f2LM = _project(-run2L + s2, y2 + wallH + 0.68, z2, w, horizonY, fovMult);
        final Offset f1RM = _project(run1R + s1, y1 + wallH + 0.68, z1, w, horizonY, fovMult);
        final Offset f2RM = _project(run2R + s2, y2 + wallH + 0.68, z2, w, horizonY, fovMult);

        // Translucent chain-link catch-fence mesh band (batched left+right in 1 GPU draw call!)
        if (i < 42) {
