          _drawQuadPair(canvas, w1LT, f1LT, f2LT, w2LT, w1RT, w2RT, f2RT, f1RT, meshTint);
          // Crisp cross-diagonal chain-link wire reflections in foreground
          if (i < 24 && segIndex % 2 == 0) {
            _strokePaint
              ..color = Color.fromARGB((54 * (1.0 - barrierFog)).toInt(), 210, 224, 242)
              ..strokeWidth = 0.85;
            canvas.drawLine(w1LT, f2LT, _strokePaint);
            canvas.drawLine(f1LT, w2LT, _strokePaint);
            canvas.drawLine(w1RT, f2RT, _strokePaint);
            canvas.drawLine(f1RT, w2RT, _strokePaint);
