        _strokePaint
          ..color = Color.lerp(const Color(0xA6D8E6F6), circuit.skyBottom, barrierFog)!
          ..strokeWidth = max(0.9, 2.6 / z1);
        canvas.drawLine(f1LT, f2LT, _strokePaint);
        canvas.drawLine(f1RT, f2RT, _strokePaint);
        canvas.drawLine(f1LM, f2LM, _strokePaint);
        canvas.drawLine(f1RM, f2RM, _strokePaint);

