        final int postIdx = (worldDist2 / 14.0).floor();
        final double postWorldDist = postIdx * 14.0;
        if (postWorldDist >= worldDist1 && postWorldDist < worldDist2) {
          final double pFrac = ((postWorldDist - worldDist1) / worldSpan).clamp(0.0, 1.0).toDouble();
          final double pz = z1 + (z2 - z1) * pFrac;
          final double ps = s1 + (s2 - s1) * pFrac;
          final double py = y1 + (y2 - y1) * pFrac;
          final double pRunL = run1L + (run2L - run1L) * pFrac;
          final double pRunR = run1R + (run2R - run1R) * pFrac;
          final Offset pwL = Offset.lerp(w1LT, w2LT, pFrac)!;
          final Offset pfL = Offset.lerp(f1LT, f2LT, pFrac)!;
          final Offset pwR = Offset.lerp(w1RT, w2RT, pFrac)!;
          final Offset pfR = Offset.lerp(f1RT, f2RT, pFrac)!;
          _strokePaint
            ..color = Color.lerp(const Color(0xD4C2D4E8), circuit.skyBottom, barrierFog)!
            ..strokeWidth = max(1.4, 5.8 / pz);
          canvas.drawLine(pwL, pfL, _strokePaint);
          canvas.drawLine(pwR, pfR, _strokePaint);
          final Offset armL = _project(-pRunL + 0.42 + ps, py + wallH + 1.70, pz, w, horizonY, fovMult);
          final Offset armR = _project(pRunR - 0.42 + ps, py + wallH + 1.70, pz, w, horizonY, fovMult);
