            final Offset mp = panelLeft ? Offset.lerp(f1LM, f2LM, pFrac)! : Offset.lerp(f1RM, f2RM, pFrac)!;
            final double pw = (36.0 / pz).clamp(4.5, 24.0).toDouble();
            final double ph = pw * 0.68;
            final Rect pRect = Rect.fromCenter(center: mp, width: pw, height: ph);
            final Color ledCol = engine.startLightsTimer > 0
                ? const Color(0xFFFF1744)
                : (kNow.abs() > 0.018 ? const Color(0xFFFFD600) : const Color(0xFF00E676));
            if (pw > 7.0) {
              final int baseA = ((92 * (1.0 - barrierFog))).toInt().clamp(0, 255).toInt();
              _fillPaint.color = ledCol.withAlpha(baseA >> 1);
              canvas.drawCircle(mp, pw * 1.12, _fillPaint);
              _fillPaint.color = ledCol.withAlpha(baseA);
              canvas.drawCircle(mp, pw * 0.66, _fillPaint);
