      // 3E. Astroturf Verge + True 3D Raised Kerbs (Top Face + Vertical Bevel Lip + Cast Shadow on Asphalt)
      final Offset a1LO = _project(-astroOuterW + s1, y1 + 0.02, z1, w, horizonY, fovMult);
      final Offset a2LO = _project(-astroOuterW + s2, y2 + 0.02, z2, w, horizonY, fovMult);
      final Offset a1RO = _project(astroOuterW + s1, y1 + 0.02, z1, w, horizonY, fovMult);
      final Offset a2RO = _project(astroOuterW + s2, y2 + 0.02, z2, w, horizonY, fovMult);

      final Offset k1LO = _project(-kerbOuterW + s1, y1 + 0.125, z1, w, horizonY, fovMult);
      final Offset k2LO = _project(-kerbOuterW + s2, y2 + 0.125, z2, w, horizonY, fovMult);
      final Offset k1RO = _project(kerbOuterW + s1, y1 + 0.125, z1, w, horizonY, fovMult);
      final Offset k2RO = _project(kerbOuterW + s2, y2 + 0.125, z2, w, horizonY, fovMult);

      final Offset k1LI = _project(-roadHalfW - 0.04 + s1, y1 + 0.098, z1, w, horizonY, fovMult);
      final Offset k2LI = _project(-roadHalfW - 0.04 + s2, y2 + 0.098, z2, w, horizonY, fovMult);
      final Offset k1RI = _project(roadHalfW + 0.04 + s1, y1 + 0.098, z1, w, horizonY, fovMult);
      final Offset k2RI = _project(roadHalfW + 0.04 + s2, y2 + 0.098, z2, w, horizonY, fovMult);

      final Offset p1L = _project(-roadHalfW + s1, y1, z1, w, horizonY, fovMult);
      final Offset p1R = _project(roadHalfW + s1, y1, z1, w, horizonY, fovMult);
      final Offset p2L = _project(-roadHalfW + s2, y2, z2, w, horizonY, fovMult);
      final Offset p2R = _project(roadHalfW + s2, y2, z2, w, horizonY, fovMult);

      final Color astroCol = Color.lerp(segIndex % 2 == 0 ? const Color(0xFF1A6134) : const Color(0xFF15502A), circuit.skyBottom, fogMix)!;
      _drawQuadPair(canvas, a1LO, k1LO, k2LO, a2LO, k1RO, a1RO, a2RO, k2RO, astroCol);

      final bool kerbEven = segIndex % 2 == 0;
      final Color kerbRawL = farAntiShimmer > 0.0
          ? Color.lerp(kerbEven ? kerbLitARaw : kerbLitBRaw, kerbMidLitL, farAntiShimmer * 0.68)!
          : (kerbEven ? kerbLitARaw : kerbLitBRaw);
      final Color kerbRawR = farAntiShimmer > 0.0
          ? Color.lerp(kerbEven ? kerbDarkARaw : kerbDarkBRaw, kerbMidLitR, farAntiShimmer * 0.68)!
          : (kerbEven ? kerbDarkARaw : kerbDarkBRaw);
      final Color kerbLitL = Color.lerp(kerbRawL, circuit.skyBottom, fogMix)!;
      final Color kerbLitR = Color.lerp(kerbRawR, circuit.skyBottom, fogMix)!;
      final Color kerbLipCol = Color.lerp(kerbEven ? kerbLipARaw : kerbLipBRaw, circuit.skyBottom, fogMix)!;
      _drawQuad(canvas, k1LO, k1LI, k2LI, k2LO, kerbLitL);
      _drawQuad(canvas, k1RI, k1RO, k2RO, k2RI, kerbLitR);
      if (i < 64) {
        _drawQuadPair(canvas, k1LI, p1L, p2L, k2LI, p1R, k1RI, k2RI, p2R, kerbLipCol);
        // Serrated 3D Kerb Block Relief Grooves + Outer Concrete Drainage Channel + Apex Rubber Scuffs!
        if (i < 46) {
          _strokePaint
            ..color = Color.fromARGB((108 * (1.0 - fogMix)).toInt(), 255, 255, 255)
            ..strokeWidth = max(0.9, 2.3 / z1);
          canvas.drawLine(k1LI, k2LI, _strokePaint);
          canvas.drawLine(k1RI, k2RI, _strokePaint);
          // Concrete drainage gutter strip right behind the outer kerb edge
          _strokePaint
            ..color = Color.lerp(const Color(0xAA4D5868), circuit.skyBottom, fogMix)!
            ..strokeWidth = max(1.0, 3.2 / z1);
          canvas.drawLine(k1LO, k2LO, _strokePaint);
          canvas.drawLine(k1RO, k2RO, _strokePaint);
          // Transverse serrated FIA kerb block joint lines in foreground (tactile 3D concrete tiles!)
          if (i < 30) {
            _strokePaint
              ..color = Color.fromARGB((115 * (1.0 - fogMix)).toInt(), 10, 14, 20)
              ..strokeWidth = max(0.9, 2.6 / z1);
            canvas.drawLine(k1LO, k1LI, _strokePaint);
            canvas.drawLine(k1RI, k1RO, _strokePaint);
          }
          if (kNow.abs() > 0.011) {
            final bool apexRight = kNow > 0;
            final Color scuffCol = Color.fromARGB((92 * (1.0 - fogMix)).toInt(), 7, 9, 13);
            if (apexRight) {
              _drawQuad(canvas, k1RI, Offset.lerp(k1RI, k1RO, 0.62)!, Offset.lerp(k2RI, k2RO, 0.62)!, k2RI, scuffCol);
            } else {
              _drawQuad(canvas, Offset.lerp(k1LI, k1LO, 0.62)!, k1LI, k2LI, Offset.lerp(k2LI, k2LO, 0.62)!, scuffCol);
            }
          }
        }

        // Authentic Raised 3D FIA Yellow/Black Apex Sausage Kerbs on tight corner insides!
        if (kNow.abs() > 0.015 && i < 52 && segIndex % 2 == 0) {
          final bool apexRight = kNow > 0;
          final double skIn = apexRight ? (kerbOuterW + 0.06) : (-kerbOuterW - 0.34);
          final double skOut = apexRight ? (kerbOuterW + 0.34) : (-kerbOuterW - 0.06);
          final Color sausageCol = Color.lerp(
            (segIndex % 4 == 0) ? const Color(0xFFFFD600) : const Color(0xFF141820),
            circuit.skyBottom,
            fogMix,
          )!;
          _drawQuad(
            canvas,
            _project(skIn + s1, y1 + 0.22, z1, w, horizonY, fovMult),
            _project(skOut + s1, y1 + 0.22, z1, w, horizonY, fovMult),
            _project(skOut + s2, y2 + 0.22, z2, w, horizonY, fovMult),
            _project(skIn + s2, y2 + 0.22, z2, w, horizonY, fovMult),
            sausageCol,
          );
        }
      }

      // 3F. Photorealistic 3D Crowned PBR Asphalt + Sector/DRS Markings + Tire Rubber Groove + Specular Sun Glint
      final bool isStartLine = lapDist1 < 5.2;
      final double sec1Dist = lapLen * 0.333;
      final double sec2Dist = lapLen * 0.666;
      final bool isSectorLine = !isStartLine && ((lapDist1 - sec1Dist).abs() < 1.6 || (lapDist1 - sec2Dist).abs() < 1.6);
      final bool isDrsLine = !isStartLine && (lapDist1 > 158.0 && lapDist1 < 161.2);

      // Silky-Smooth Continuous Modern FIA Tarmac (pre-hoisted base colors -> zero redundant Color.lerp per slice!)
      final bool aspEven = segIndex % 2 == 0;
      final Color rawAsphalt = isStartLine ? const Color(0xFFF2F5FA) : (aspEven ? aspBaseEven : aspBaseOdd);
      final Color asphaltCol = Color.lerp(rawAsphalt, circuit.skyBottom, fogMix)!;
      if (!isStartLine && i < 64) {
        // Seamless soft cylindrical tarmac crown shading (imperceptible tonal step -> zero vertical banding!)
        final Color edgeSoft = Color.lerp(aspEven ? aspEdgeEven : aspEdgeOdd, circuit.skyBottom, fogMix)!;
        final Color midSoft = Color.lerp(aspEven ? aspMidEven : aspMidOdd, circuit.skyBottom, fogMix)!;
        final Color crownSoft = Color.lerp(aspEven ? aspCrownEven : aspCrownOdd, circuit.skyBottom, fogMix)!;
        _drawQuad(canvas, p1L, p1R, p2R, p2L, edgeSoft);
        _drawQuad(
          canvas,
          Offset.lerp(p1L, p1R, 0.07)!,
          Offset.lerp(p1L, p1R, 0.93)!,
          Offset.lerp(p2L, p2R, 0.93)!,
          Offset.lerp(p2L, p2R, 0.07)!,
          midSoft,
        );
        _drawQuad(
          canvas,
          Offset.lerp(p1L, p1R, 0.18)!,
          Offset.lerp(p1L, p1R, 0.82)!,
          Offset.lerp(p2L, p2R, 0.82)!,
          Offset.lerp(p2L, p2R, 0.18)!,
          asphaltCol,
        );
        if (i < 34) {
          _drawQuad(
            canvas,
            Offset.lerp(p1L, p1R, 0.30)!,
            Offset.lerp(p1L, p1R, 0.70)!,
            Offset.lerp(p2L, p2R, 0.70)!,
            Offset.lerp(p2L, p2R, 0.30)!,
            crownSoft,
          );
          // Steel FIA storm drainage grates recessed cleanly along street-circuit gutters
          if (circuit.isStreetCircuit && segIndex % 9 == 0 && i < 24) {
            final Color grateCol = Color.lerp(const Color(0xFF141922), circuit.skyBottom, fogMix)!;
            _drawQuad(canvas, Offset.lerp(p1L, p1R, 0.015)!, Offset.lerp(p1L, p1R, 0.050)!, Offset.lerp(p2L, p2R, 0.050)!, Offset.lerp(p2L, p2R, 0.015)!, grateCol);
            _drawQuad(canvas, Offset.lerp(p1L, p1R, 0.950)!, Offset.lerp(p1L, p1R, 0.985)!, Offset.lerp(p2L, p2R, 0.985)!, Offset.lerp(p2L, p2R, 0.950)!, grateCol);
          }
        }
      } else {
        _drawQuad(canvas, p1L, p1R, p2R, p2L, asphaltCol);
      }

      // FIA Sector Timing Lines (Red/White) & DRS Activation Line (Bright White + Cyan accent)
      if (isSectorLine && i < 56) {
        _drawQuad(canvas, p1L, p1R, p2R, p2L, Color.lerp(const Color(0xCCE10600), circuit.skyBottom, fogMix)!);
      } else if (isDrsLine && i < 56) {
        _drawQuad(canvas, p1L, p1R, p2R, p2L, Color.lerp(const Color(0xEEFFFFFF), circuit.skyBottom, fogMix)!);
      }

      // Subtle 3D kerb contact shadow onto asphalt edges (batched left+right!)
      if (i < 55) {
        final Color edgeShad = Color.fromARGB((54 * (1.0 - fogMix)).toInt(), 0, 0, 0);
        final Offset es1L = _project(-roadHalfW + 0.24 + s1, y1 + 0.004, z1, w, horizonY, fovMult);
        final Offset es2L = _project(-roadHalfW + 0.24 + s2, y2 + 0.004, z2, w, horizonY, fovMult);
        final Offset es1R = _project(roadHalfW - 0.24 + s1, y1 + 0.004, z1, w, horizonY, fovMult);
        final Offset es2R = _project(roadHalfW - 0.24 + s2, y2 + 0.004, z2, w, horizonY, fovMult);
        _drawQuadPair(canvas, p1L, es1L, es2L, p2L, es1R, p1R, p2R, es2R, edgeShad);
      }

      if (isStartLine && i < 54) {
        final bool alt = (lapDist1 / 2.6).floor() % 2 == 0;
        for (int sq = 0; sq < 8; sq++) {
          if ((sq % 2 == 0) == alt) {
            final double xA = -roadHalfW + (sq * (roadHalfW * 2 / 8));
            final double xB = xA + (roadHalfW * 2 / 8);
            _drawQuad(
              canvas,
              _project(xA + s1, y1, z1, w, horizonY, fovMult),
              _project(xB + s1, y1, z1, w, horizonY, fovMult),
              _project(xB + s2, y2, z2, w, horizonY, fovMult),
              _project(xA + s2, y2, z2, w, horizonY, fovMult),
              Color.lerp(const Color(0xFF141820), circuit.skyBottom, fogMix)!,
            );
          }
        }
      }

      if (!isStartLine && lapDist1 > 10.0 && lapDist1 < 350.0 && i < 58) {
        final double slotMod = (lapDist1 - 14.0) % RaceEngineState.kGridSpacing;
        if (slotMod >= 0.0 && slotMod < 2.2) {
          final int slotIdx = ((lapDist1 - 14.0) / RaceEngineState.kGridSpacing).floor();
          final double boxCenter = (slotIdx % 2 == 0 ? -0.44 : 0.44) * engine.laneToWorldX;
          final Color boxCol = Color.lerp(const Color(0xD8F5F8FC), circuit.skyBottom, fogMix)!;
          final Offset gb1L = _project(boxCenter - 0.72 + s1, y1 + 0.008, z1, w, horizonY, fovMult);
          final Offset gb1R = _project(boxCenter + 0.72 + s1, y1 + 0.008, z1, w, horizonY, fovMult);
          final Offset gb2L = _project(boxCenter - 0.72 + s2, y2 + 0.008, z2, w, horizonY, fovMult);
          final Offset gb2R = _project(boxCenter + 0.72 + s2, y2 + 0.008, z2, w, horizonY, fovMult);
          _strokePaint
            ..color = boxCol
            ..strokeWidth = max(1.0, 4.0 / z1);
          canvas.drawLine(gb2L, gb2R, _strokePaint);
          canvas.drawLine(gb1L, gb2L, _strokePaint);
          canvas.drawLine(gb1R, gb2R, _strokePaint);
          // Official FIA yellow front-wheel contact line + dark burnout launch rubber marks inside each grid box!
          _strokePaint
            ..color = Color.lerp(const Color(0xEEFFD600), circuit.skyBottom, fogMix)!
            ..strokeWidth = max(1.0, 3.2 / z1);
          canvas.drawLine(Offset.lerp(gb1L, gb2L, 0.78)!, Offset.lerp(gb1R, gb2R, 0.78)!, _strokePaint);
          if (i < 34) {
            final Color burnCol = Color.fromARGB((74 * (1.0 - fogMix)).toInt(), 4, 6, 10);
            _drawQuad(canvas, Offset.lerp(gb1L, gb1R, 0.16)!, Offset.lerp(gb1L, gb1R, 0.34)!, Offset.lerp(gb2L, gb2R, 0.34)!, Offset.lerp(gb2L, gb2R, 0.16)!, burnCol);
            _drawQuad(canvas, Offset.lerp(gb1L, gb1R, 0.66)!, Offset.lerp(gb1L, gb1R, 0.84)!, Offset.lerp(gb2L, gb2R, 0.84)!, Offset.lerp(gb2L, gb2R, 0.66)!, burnCol);
          }
        }
      }

      if (i <= 34) {
        _asphaltEdgeL[i] = p1L;
        _asphaltEdgeR[i] = p1R;
        if (i > asphaltClipMaxHit) asphaltClipMaxHit = i;
      }

      if (!isStartLine && i < 66) {
        final double grooveX1 = _segIdealX[i];
        final double grooveX2 = _segIdealX[i + 1];
        final bool isHeavyBrakingZone = _segHeavyBrake[i] == 1;

        // Layered Soft-Feathered Real-World F1 Rubbered-In Racing Groove + Twin Wheel Tracks!
        final int broadA = ((isHeavyBrakingZone ? 46 : 24) * (1.0 - fogMix)).toInt();
        _drawQuad(
          canvas,
          _project(grooveX1 - 1.18 + s1, y1 + 0.004, z1, w, horizonY, fovMult),
          _project(grooveX1 + 1.18 + s1, y1 + 0.004, z1, w, horizonY, fovMult),
          _project(grooveX2 + 1.18 + s2, y2 + 0.004, z2, w, horizonY, fovMult),
          _project(grooveX2 - 1.18 + s2, y2 + 0.004, z2, w, horizonY, fovMult),
          Color.fromARGB(broadA, 6, 8, 12),
        );
        final int rubberAlpha = ((isHeavyBrakingZone ? 90 : 44) * (1.0 - fogMix)).toInt();
        final Color rubberCol = Color.fromARGB(rubberAlpha, 3, 5, 9);
        _drawQuadPair(
          canvas,
          _project(grooveX1 - 0.89 + s1, y1 + 0.005, z1, w, horizonY, fovMult),
          _project(grooveX1 - 0.35 + s1, y1 + 0.005, z1, w, horizonY, fovMult),
          _project(grooveX2 - 0.35 + s2, y2 + 0.005, z2, w, horizonY, fovMult),
          _project(grooveX2 - 0.89 + s2, y2 + 0.005, z2, w, horizonY, fovMult),
          _project(grooveX1 + 0.35 + s1, y1 + 0.005, z1, w, horizonY, fovMult),
          _project(grooveX1 + 0.89 + s1, y1 + 0.005, z1, w, horizonY, fovMult),
          _project(grooveX2 + 0.89 + s2, y2 + 0.005, z2, w, horizonY, fovMult),
          _project(grooveX2 + 0.35 + s2, y2 + 0.005, z2, w, horizonY, fovMult),
          rubberCol,
        );
        if (isHeavyBrakingZone && i < 50 && segIndex % 3 != 0) {
          final Color skidCol = Color.fromARGB((92 * (1.0 - fogMix)).toInt(), 2, 3, 6);
          final double lockOff = (segIndex % 2 == 0) ? -0.58 : 0.58;
          _strokePaint
            ..color = skidCol
            ..strokeWidth = max(1.2, 6.2 / z1);
          canvas.drawLine(
            _project(grooveX1 + lockOff + s1, y1 + 0.006, z1, w, horizonY, fovMult),
            _project(grooveX2 + lockOff + s2, y2 + 0.006, z2, w, horizonY, fovMult),
            _strokePaint,
          );
        }
        // Authentic Off-Line Rubber Marbles ("Canicas de Goma") + Individual Granulated Rubber Clumps in Foreground!
        if (i < 44) {
          final Color marbleCol = Color.fromARGB((48 * (1.0 - fogMix)).toInt(), 5, 7, 11);
          final Offset m1LI = _project(-roadHalfW + 0.28 + s1, y1 + 0.004, z1, w, horizonY, fovMult);
          final Offset m1LO = _project(-roadHalfW + 1.12 + s1, y1 + 0.004, z1, w, horizonY, fovMult);
          final Offset m2LI = _project(-roadHalfW + 0.28 + s2, y2 + 0.004, z2, w, horizonY, fovMult);
          final Offset m2LO = _project(-roadHalfW + 1.12 + s2, y2 + 0.004, z2, w, horizonY, fovMult);
          final Offset m1RI = _project(roadHalfW - 1.12 + s1, y1 + 0.004, z1, w, horizonY, fovMult);
          final Offset m1RO = _project(roadHalfW - 0.28 + s1, y1 + 0.004, z1, w, horizonY, fovMult);
          final Offset m2RI = _project(roadHalfW - 1.12 + s2, y2 + 0.004, z2, w, horizonY, fovMult);
          final Offset m2RO = _project(roadHalfW - 0.28 + s2, y2 + 0.004, z2, w, horizonY, fovMult);
          _drawQuadPair(canvas, m1LI, m1LO, m2LO, m2LI, m1RI, m1RO, m2RO, m2RI, marbleCol);
          if (i < 22) {
            _fillPaint.color = Color.fromARGB((135 * (1.0 - fogMix)).toInt(), 6, 8, 12);
            final double rM = (4.2 / z1).clamp(1.0, 2.8).toDouble();
            final double fA = ((segIndex * 37) % 100) / 100.0;
            final double fB = ((segIndex * 73 + 29) % 100) / 100.0;
            canvas.drawCircle(Offset.lerp(m1LI, m1LO, fA)!, rM, _fillPaint);
            canvas.drawCircle(Offset.lerp(m1RI, m1RO, fB)!, rM, _fillPaint);
          }
        }
        // PBR+ Glossy Sky-Horizon Reflection & Fresnel Asphalt Glaze (dramatic at Sunset, Night & High-Sun!)
        if (i < 50) {
          final int reflA = ((circuit.nightMode ? 28 : (circuit.timeLabel == 'Atardecer' ? 36 : 18)) * (1.0 - fogMix)).toInt();
          final Color reflCol = circuit.skyBottom.withAlpha(reflA.clamp(0, 255).toInt());
          _drawQuad(
            canvas,
            _project(-roadHalfW * 0.72 + s1, y1 + 0.004, z1, w, horizonY, fovMult),
            _project(roadHalfW * 0.72 + s1, y1 + 0.004, z1, w, horizonY, fovMult),
            _project(roadHalfW * 0.72 + s2, y2 + 0.004, z2, w, horizonY, fovMult),
            _project(-roadHalfW * 0.72 + s2, y2 + 0.004, z2, w, horizonY, fovMult),
            reflCol,
          );
        }

        // Dual-Layer PBR+ Directional Sun Specular Corridor / Stadium Floodlight Pool on Asphalt!
        final bool lightPool = circuit.nightMode && (segIndex % 9 == 0 || segIndex % 9 == 1);
        final bool isSunset = circuit.timeLabel == 'Atardecer';
        final int sheenAlpha = ((lightPool ? 78 : (isSunset ? 42 : (circuit.nightMode ? 26 : 30))) * (1.0 - fogMix)).toInt();
        final double sheenCenter = lightPool ? 0.0 : (sunNormX * 1.15);
        final double shW = lightPool ? 2.10 : (isSunset ? 1.18 : 0.92);
        final Offset sh1L = _project(sheenCenter - shW + s1, y1 + 0.007, z1, w, horizonY, fovMult);
        final Offset sh1R = _project(sheenCenter + shW + s1, y1 + 0.007, z1, w, horizonY, fovMult);
        final Offset sh2L = _project(sheenCenter - shW + s2, y2 + 0.007, z2, w, horizonY, fovMult);
        final Offset sh2R = _project(sheenCenter + shW + s2, y2 + 0.007, z2, w, horizonY, fovMult);
        final Color outerSpecCol = lightPool
            ? Color.fromARGB(sheenAlpha, 215, 240, 255)
            : (isSunset ? Color.fromARGB(sheenAlpha, 255, 198, 128) : Color.fromARGB(sheenAlpha, 255, 250, 232));
        _drawQuad(canvas, sh1L, sh1R, sh2R, sh2L, outerSpecCol);

        // Crisp bright inner specular core right along the road crown!
        if (i < 42) {
          final double coreW = shW * 0.36;
          final int coreA = ((lightPool ? 66 : (isSunset ? 42 : 26)) * (1.0 - fogMix)).toInt();
          _drawQuad(
            canvas,
            _project(sheenCenter - coreW + s1, y1 + 0.009, z1, w, horizonY, fovMult),
            _project(sheenCenter + coreW + s1, y1 + 0.009, z1, w, horizonY, fovMult),
            _project(sheenCenter + coreW + s2, y2 + 0.009, z2, w, horizonY, fovMult),
            _project(sheenCenter - coreW + s2, y2 + 0.009, z2, w, horizonY, fovMult),
            Color.fromARGB(coreA, 255, 252, 242),
          );
          // Broadcast Night/Sunset Curb-Edge LED & Sky Color Bounce on Outer Asphalt (batched left+right!)
          if (i < 34 && (circuit.nightMode || isSunset)) {
            final Color edgeGlow = circuit.nightMode
                ? (segIndex % 8 < 3
                    ? Color.fromARGB((30 * (1.0 - fogMix)).toInt(), 0, 224, 255)
                    : Color.fromARGB((22 * (1.0 - fogMix)).toInt(), 180, 226, 255))
                : Color.fromARGB((26 * (1.0 - fogMix)).toInt(), 255, 178, 102);
            _drawQuadPair(
              canvas,
              Offset.lerp(p1L, p1R, 0.02)!,
              Offset.lerp(p1L, p1R, 0.14)!,
              Offset.lerp(p2L, p2R, 0.14)!,
              Offset.lerp(p2L, p2R, 0.02)!,
              Offset.lerp(p1L, p1R, 0.86)!,
              Offset.lerp(p1L, p1R, 0.98)!,
              Offset.lerp(p2L, p2R, 0.98)!,
              Offset.lerp(p2L, p2R, 0.86)!,
              edgeGlow,
            );
          }
        }
      }

      // Razor-Sharp FIA Track-Limit Boundary Lines (dark contrast edge + brilliant white paint!)
      if (i < 46) {
        _strokePaint
          ..color = Color.fromARGB((95 * (1.0 - fogMix)).toInt(), 5, 7, 12)
          ..strokeWidth = max(1.8, 7.2 / z1);
        canvas.drawLine(p1L, p2L, _strokePaint);
        canvas.drawLine(p1R, p2R, _strokePaint);
      }
      _strokePaint
        ..color = Color.lerp(const Color(0xFCFFFFFF), circuit.skyBottom, fogMix * 0.85)!
        ..strokeWidth = max(1.1, 4.8 / z1);
      canvas.drawLine(p1L, p2L, _strokePaint);
      canvas.drawLine(p1R, p2R, _strokePaint);

      // 3G. Optional Dynamic Racing Line painted seamlessly onto the 3D asphalt (O(1) streamed lookup!)
      if (RaceEngineState.showRacingLine && i < segCount - 6) {
        final double lineWorldX1 = _segIdealX[i];
        final double lineWorldX2 = _segIdealX[i + 1];
        final double targetSpd = _segTargetSpd[i];

        final double overKmh = engine.speedKmh - targetSpd;
        Color guideColor;
        if (overKmh <= -12.0) {
          guideColor = const Color(0xFF00E676);
        } else if (overKmh < 12.0) {
          final double t = ((overKmh + 12.0) / 24.0).clamp(0.0, 1.0).toDouble();
          guideColor = Color.lerp(const Color(0xFF00E676), const Color(0xFFFFD600), t)!;
        } else if (overKmh < 34.0) {
          final double t = ((overKmh - 12.0) / 22.0).clamp(0.0, 1.0).toDouble();
          guideColor = Color.lerp(const Color(0xFFFFD600), const Color(0xFFFF1744), t)!;
        } else {
          guideColor = const Color(0xFFFF1744);
        }

        final bool isDash = (segIndex % 2 == 0);
        final double baseAlpha = (isDash ? 0.56 : 0.22) * (1.0 - fogMix);
        final Color outerRibbonCol = Color.lerp(guideColor, circuit.skyBottom, fogMix * 0.65)!
            .withAlpha((baseAlpha * 255.0).clamp(0.0, 255.0).toInt());
        const double lineHalfW = 0.25;
        final Offset rl1L = _project(lineWorldX1 - lineHalfW + s1, y1 + 0.012, z1, w, horizonY, fovMult);
        final Offset rl1R = _project(lineWorldX1 + lineHalfW + s1, y1 + 0.012, z1, w, horizonY, fovMult);
        final Offset rl2L = _project(lineWorldX2 - lineHalfW + s2, y2 + 0.012, z2, w, horizonY, fovMult);
        final Offset rl2R = _project(lineWorldX2 + lineHalfW + s2, y2 + 0.012, z2, w, horizonY, fovMult);
        _drawQuad(canvas, rl1L, rl1R, rl2R, rl2L, outerRibbonCol);

        if (isDash && i < 60) {
          const double coreHalfW = 0.085;
          final Color coreCol = Color.lerp(guideColor, Colors.white, 0.35)!
              .withAlpha(((0.74 * (1.0 - fogMix)) * 255.0).clamp(0.0, 255.0).toInt());
          final Offset rc1L = _project(lineWorldX1 - coreHalfW + s1, y1 + 0.016, z1, w, horizonY, fovMult);
          final Offset rc1R = _project(lineWorldX1 + coreHalfW + s1, y1 + 0.016, z1, w, horizonY, fovMult);
          final Offset rc2L = _project(lineWorldX2 - coreHalfW + s2, y2 + 0.016, z2, w, horizonY, fovMult);
          final Offset rc2R = _project(lineWorldX2 + coreHalfW + s2, y2 + 0.016, z2, w, horizonY, fovMult);
          _drawQuad(canvas, rc1L, rc1R, rc2R, rc2L, coreCol);
        }
      }

      // 3H. EXACT SUB-SLICE WORLD-ANCHORED 3D Braking Marker Boards (ZERO jumping or number-flipping!)
      if (i > 2 && i < 62) {
        final int brakeIdx = (worldDist2 / 28.0).floor();
        final double brakeDist = brakeIdx * 28.0;
        if (brakeDist >= worldDist1 && brakeDist < worldDist2) {
          final double kAtBoard = streamer.kappaAt(brakeDist);
          if (kAtBoard.abs() < 0.008) {
            final double aheadK50 = streamer.kappaAt(brakeDist + 55.0);
            final double aheadK100 = streamer.kappaAt(brakeDist + 105.0);
            final double aheadK150 = streamer.kappaAt(brakeDist + 155.0);
            String? markerTxt;
            double markerK = 0.0;
            if (aheadK50.abs() > 0.016) {
              markerTxt = '50';
              markerK = aheadK50;
            } else if (aheadK100.abs() > 0.016) {
              markerTxt = '100';
              markerK = aheadK100;
            } else if (aheadK150.abs() > 0.016) {
              markerTxt = '150';
              markerK = aheadK150;
            }
            if (markerTxt != null) {
              final double bFrac = ((brakeDist - worldDist1) / worldSpan).clamp(0.0, 1.0).toDouble();
              final double bz = z1 + (z2 - z1) * bFrac;
              final double bs = s1 + (s2 - s1) * bFrac;
              final double by = y1 + (y2 - y1) * bFrac;
              final bool onLeft = markerK > 0;
              final double sideWall = onLeft ? (run1L + (run2L - run1L) * bFrac) : (run1R + (run2R - run1R) * bFrac);
              final double boardOff = min(sideWall - 0.35, roadHalfW + 2.65);
              _drawBrakingBoard(canvas, (onLeft ? -boardOff : boardOff) + bs, by, bz, w, horizonY, fovMult, markerTxt, fogMix);
            }
          }
        }
      }

      // 3J. DEPTH-INTERLEAVED TRUE-3D SURFACE-CONFORMING F1 CARS (Rivals + Player Chase Car grounded 100% flush on the 3D track!)
      final List<AiDriver> sliceRivals = _rivalsBySlice[i];
      final bool drawPlayerHere = (!cockpit && i == playerChaseSlice);
      if (sliceRivals.isNotEmpty || drawPlayerHere) {
        bool playerDrawn = !drawPlayerHere;
        for (final ai in sliceRivals) {
          // Draw player car in exact back-to-front order if wheel-to-wheel in same slice!
          if (!playerDrawn && ai.trackDist < engine.playerDist) {
            _drawPlayerTrue3DChaseCar(
              canvas,
              playerChaseZ,
              baseCamHeight,
              camShift,
              w,
              horizonY,
              fovMult,
              sunNormX,
            );
            playerDrawn = true;
          }
          final double rz = (ai.trackDist - camOriginDist) / 2.0;
          final double exactCurv = _kappaAtWorldDist(ai.trackDist);
          final double exactDepthT = (rz / max(1.0, _segZ[segCount])).clamp(0.0, 1.0).toDouble();
          final double exactFog = pow(exactDepthT, 1.95).toDouble() * 0.54;
          _drawRivalTrue3DCar(
            canvas,
            rz,
            baseCamHeight,
            camShift,
            w,
            horizonY,
            fovMult,
            exactCurv,
            exactFog,
            sunNormX,
            ai,
          );
        }
        if (!playerDrawn) {
          _drawPlayerTrue3DChaseCar(
            canvas,
            playerChaseZ,
            baseCamHeight,
            camShift,
            w,
            horizonY,
            fovMult,
            sunNormX,
          );
        }
      }

      // 3K. EXACT SUB-SLICE 3D Overhead Sponsor Bridges (Drawn AFTER rivals -> silky overpass, ZERO jumping!)
      if (i > 1 && i < 66) {
        final int archIdx = (worldDist2 / 380.0).floor();
        final double archDist = archIdx * 380.0;
        if (archDist >= worldDist1 && archDist < worldDist2) {
          final double archLapD = _posMod(archDist, lapLen);
          if (archLapD > 24.0 && archLapD < lapLen - 24.0) {
            final double aFrac = ((archDist - worldDist1) / worldSpan).clamp(0.0, 1.0).toDouble();
            final double az1 = z1 + (z2 - z1) * aFrac;
            final double as1 = s1 + (s2 - s1) * aFrac;
            final double ay1 = y1 + (y2 - y1) * aFrac;
            final double az2 = az1 + 1.10;
            final double as2 = _sampleSpineShift(az2) - camShift;
            final double ay2 = baseCamHeight + _sampleSpineElev(az2);
            _draw3DSponsorArch(
              canvas,
              as1,
              as2,
              ay1,
              ay2,
              az1,
              az2,
              roadHalfW,
              w,
              horizonY,
              fovMult,
              fogMix,
              circuit,
              archIdx,
            );
          }
        }
      }

      // 3L. EXACT SUB-SLICE 3D Start/Finish Truss Gantry at exact lap boundary (N * lapLen) -> ZERO jumping!
      if (i > 1 && i < 66) {
        final int sfLapIdx = (worldDist2 / lapLen).floor();
        final double sfDist = sfLapIdx * lapLen + 2.4;
        if (sfDist >= worldDist1 && sfDist < worldDist2) {
          final double gFrac = ((sfDist - worldDist1) / worldSpan).clamp(0.0, 1.0).toDouble();
          final double gz1 = z1 + (z2 - z1) * gFrac;
          final double gs1 = s1 + (s2 - s1) * gFrac;
          final double gy1 = y1 + (y2 - y1) * gFrac;
          final double gz2 = gz1 + 1.25;
          final double gs2 = _sampleSpineShift(gz2) - camShift;
          final double gy2 = baseCamHeight + _sampleSpineElev(gz2);
          _drawStartGantry3D(canvas, gs1, gs2, gy1, gy2, gz1, gz2, roadHalfW, w, horizonY, fovMult, fogMix, circuit);
        }
      }

      // 3M. EXACT SUB-SLICE Glowing FIA DRS Activation Zone Pylons at exact 159.5m -> ZERO blinking!
      if (i > 1 && i < 56) {
        final int drsLapIdx = (worldDist1 / lapLen).floor();
        final double drsDist = drsLapIdx * lapLen + 159.5;
        if (drsDist >= worldDist1 && drsDist < worldDist2) {
          final double dFrac = ((drsDist - worldDist1) / worldSpan).clamp(0.0, 1.0).toDouble();
          final double dz = z1 + (z2 - z1) * dFrac;
          final double ds = s1 + (s2 - s1) * dFrac;
          final double dy = y1 + (y2 - y1) * dFrac;
          for (final double sDir in const [-1.0, 1.0]) {
            final double px = sDir * (roadHalfW + 0.75) + ds;
            final Offset db = _project(px, dy, dz, w, horizonY, fovMult);
            final Offset dt = _project(px, dy + 1.95, dz, w, horizonY, fovMult);
            _strokePaint
              ..color = Color.lerp(const Color(0xFF00E676), circuit.skyBottom, fogMix * 0.5)!
              ..strokeWidth = max(1.6, 10.0 / dz);
            canvas.drawLine(db, dt, _strokePaint);
            _fillPaint.color = Color.fromARGB((92 * (1.0 - fogMix)).toInt(), 0, 230, 118);
            canvas.drawCircle(dt, max(3.5, 16.0 / dz), _fillPaint);
            _fillPaint.color = const Color(0xFFE0FFF0);
            canvas.drawCircle(dt, max(1.6, 6.5 / dz), _fillPaint);
          }
        }
      }

      // 3N. ICONIC 3D CIRCUIT MONUMENTS & ARCHITECTURAL LANDMARKS (Drawn AFTER cars -> True 3D Overpass/Tunnel Depth!)
      final double sliceProg = lapDist1 / lapLen;
      if (circuit.code == 'MON' && sliceProg >= 0.42 && sliceProg <= 0.52 && i < 68) {
        // ICONIC MONACO LOUIS II CURVED 3D ILLUMINATED TUNNEL (Ribbed Concrete Vault + Portal Beams + Warm Amber Floor Reflections!)
        final double tunH = 4.65;
        final double tunArchH = 5.45;
        final double tunL1 = -run1L - 0.15 + s1;
        final double tunL2 = -run2L - 0.15 + s2;
        final double tunR1 = run1R + 0.15 + s1;
        final double tunR2 = run2R + 0.15 + s2;
        final Offset wl1B = _project(tunL1, y1 + wallH, z1, w, horizonY, fovMult);
        final Offset wl2B = _project(tunL2, y2 + wallH, z2, w, horizonY, fovMult);
        final Offset wl1T = _project(tunL1, y1 + tunH, z1, w, horizonY, fovMult);
        final Offset wl2T = _project(tunL2, y2 + tunH, z2, w, horizonY, fovMult);
        final Offset wr1B = _project(tunR1, y1 + wallH, z1, w, horizonY, fovMult);
        final Offset wr2B = _project(tunR2, y2 + wallH, z2, w, horizonY, fovMult);
        final Offset wr1T = _project(tunR1, y1 + tunH, z1, w, horizonY, fovMult);
        final Offset wr2T = _project(tunR2, y2 + tunH, z2, w, horizonY, fovMult);
        final Offset mid1T = _project((tunL1 + tunR1) * 0.5, y1 + tunArchH, z1, w, horizonY, fovMult);
        final Offset mid2T = _project((tunL2 + tunR2) * 0.5, y2 + tunArchH, z2, w, horizonY, fovMult);

        final bool ribSlice = segIndex % 4 == 0;
        final bool isPortal = (sliceProg < 0.424) || (sliceProg > 0.516);
        final Color tunWallCol = Color.lerp(
          isPortal ? const Color(0xFF424D5E) : (ribSlice ? const Color(0xFF2C3544) : const Color(0xFF1A202B)),
          circuit.skyBottom,
          fogMix * 0.30,
        )!;
        final Color tunRoofCol = Color.lerp(
          isPortal ? const Color(0xFF333D4D) : (ribSlice ? const Color(0xFF212836) : const Color(0xFF0F131C)),
          circuit.skyBottom,
          fogMix * 0.30,
        )!;
        _drawQuad(canvas, wl1B, wl1T, wl2T, wl2B, tunWallCol);
        _drawQuad(canvas, wr1B, wr2B, wr2T, wr1T, tunWallCol);
        _drawQuad(canvas, wl1T, mid1T, mid2T, wl2T, tunRoofCol);
        _drawQuad(canvas, mid1T, wr1T, wr2T, mid2T, tunRoofCol);

        // Portal concrete clearance fascia + black/yellow chevron clearance stripe!
        if (isPortal) {
          _strokePaint
            ..color = const Color(0xEEFFD600)
            ..strokeWidth = max(1.8, 9.0 / z1);
          canvas.drawLine(wl1T, mid1T, _strokePaint);
          canvas.drawLine(mid1T, wr1T, _strokePaint);
        }

        // Sea-side white architectural concrete tunnel pillars & illuminated warm amber ceiling bays
        if (ribSlice && i < 54) {
          _strokePaint
            ..color = Color.lerp(const Color(0xAA6A7A90), circuit.skyBottom, fogMix * 0.4)!
            ..strokeWidth = max(1.4, 7.5 / z1);
          canvas.drawLine(wl1B, wl1T, _strokePaint);
          canvas.drawLine(wr1B, wr1T, _strokePaint);
        }
        if (segIndex % 3 == 0 && i < 56) {
          final Offset lt1L = Offset.lerp(wl1T, mid1T, 0.55)!;
          final Offset lt2L = Offset.lerp(wl2T, mid2T, 0.55)!;
          final Offset lt1R = Offset.lerp(mid1T, wr1T, 0.45)!;
          final Offset lt2R = Offset.lerp(mid2T, wr2T, 0.45)!;
          _strokePaint
            ..color = Color.fromARGB((105 * (1.0 - fogMix * 0.5)).toInt(), 255, 214, 130)
            ..strokeWidth = max(2.4, 18.0 / z1);
          canvas.drawLine(lt1L, lt2L, _strokePaint);
          canvas.drawLine(lt1R, lt2R, _strokePaint);
          _strokePaint
            ..color = const Color(0xFAFFF8E1)
            ..strokeWidth = max(1.1, 6.0 / z1);
          canvas.drawLine(lt1L, lt2L, _strokePaint);
          canvas.drawLine(lt1R, lt2R, _strokePaint);
          // Warm amber overhead ceiling light pool reflecting softly on tunnel asphalt!
          _drawQuad(
            canvas,
            Offset.lerp(p1L, p1R, 0.22)!,
            Offset.lerp(p1L, p1R, 0.78)!,
            Offset.lerp(p2L, p2R, 0.78)!,
            Offset.lerp(p2L, p2R, 0.22)!,
            Color.fromARGB((34 * (1.0 - fogMix)).toInt(), 255, 206, 120),
          );
        }
      } else if (circuit.code == 'ABU' && sliceProg >= 0.72 && sliceProg <= 0.77 && i < 68) {
        // ICONIC ABU DHABI W YAS HOTEL COLOR-SHIFTING 3D DIAMOND-GRID LED CANOPY!
        final double hSpanL1 = -run1L - 0.8 + s1;
        final double hSpanL2 = -run2L - 0.8 + s2;
        final double hSpanR1 = run1R + 0.8 + s1;
        final double hSpanR2 = run2R + 0.8 + s2;
        final double hTop = 5.65;
        final Offset hl1 = _project(hSpanL1, y1 + hTop, z1, w, horizonY, fovMult);
        final Offset hl2 = _project(hSpanL2, y2 + hTop, z2, w, horizonY, fovMult);
        final Offset hr1 = _project(hSpanR1, y1 + hTop, z1, w, horizonY, fovMult);
        final Offset hr2 = _project(hSpanR2, y2 + hTop, z2, w, horizonY, fovMult);
        final Offset hm1 = _project((hSpanL1 + hSpanR1) * 0.5, y1 + hTop + 1.25, z1, w, horizonY, fovMult);
        final Offset hm2 = _project((hSpanL2 + hSpanR2) * 0.5, y2 + hTop + 1.25, z2, w, horizonY, fovMult);
        final Offset hb1L = _project(hSpanL1, y1, z1, w, horizonY, fovMult);
        final Offset hb1R = _project(hSpanR1, y1, z1, w, horizonY, fovMult);

        final double huePhase = 0.5 + 0.5 * sin(engine.totalRaceTime * 1.6 + segIndex * 0.35);
        final Color yasLed = Color.lerp(const Color(0xFF00E5FF), const Color(0xFFFF2A85), huePhase)!;
        _drawQuad(canvas, hl1, hm1, hm2, hl2, Color.lerp(yasLed, const Color(0xFF0D1426), 0.52)!.withAlpha(180));
        _drawQuad(canvas, hm1, hr1, hr2, hm2, Color.lerp(yasLed, const Color(0xFF0D1426), 0.52)!.withAlpha(180));
        // Diamond architectural steel/LED grid crisscross across the glowing canopy!
        _strokePaint
          ..color = yasLed.withAlpha((225 * (1.0 - fogMix * 0.45)).toInt())
          ..strokeWidth = max(1.2, 6.2 / z1);
        canvas.drawLine(hl1, hm2, _strokePaint);
        canvas.drawLine(hm1, hl2, _strokePaint);
        canvas.drawLine(hm1, hr2, _strokePaint);
        canvas.drawLine(hr1, hm2, _strokePaint);
        if (segIndex % 2 == 0) {
          _strokePaint
            ..color = Color.lerp(yasLed, Colors.white, 0.45)!.withAlpha((235 * (1.0 - fogMix * 0.45)).toInt())
            ..strokeWidth = max(1.4, 7.8 / z1);
          canvas.drawLine(hl1, hm1, _strokePaint);
          canvas.drawLine(hm1, hr1, _strokePaint);
          canvas.drawLine(hl1, hb1L, _strokePaint);
          canvas.drawLine(hr1, hb1R, _strokePaint);
          // Colorful Yas LED reflection shimmer onto the track below!
          _drawQuad(canvas, p1L, p1R, p2R, p2L, yasLed.withAlpha((28 * (1.0 - fogMix)).toInt()));
        }
      } else if (circuit.code == 'JPN' && sliceProg >= 0.48 && sliceProg <= 0.515 && i < 64) {
        // ICONIC SUZUKA FIGURE-8 CONCRETE CROSSOVER BRIDGE PASSING DIRECTLY OVERHEAD!
        final double brL1 = -run1L - 2.6 + s1;
        final double brL2 = -run2L - 2.6 + s2;
        final double brR1 = run1R + 2.6 + s1;
        final double brR2 = run2R + 2.6 + s2;
        final Offset bu1L = _project(brL1, y1 + 4.4, z1, w, horizonY, fovMult);
        final Offset bu2L = _project(brL2, y2 + 4.4, z2, w, horizonY, fovMult);
        final Offset bu1R = _project(brR1, y1 + 4.4, z1, w, horizonY, fovMult);
        final Offset bu2R = _project(brR2, y2 + 4.4, z2, w, horizonY, fovMult);
        final Offset bt1L = _project(brL1, y1 + 5.75, z1, w, horizonY, fovMult);
        final Offset bt1R = _project(brR1, y1 + 5.75, z1, w, horizonY, fovMult);
        // Dark overpass shadow on track + concrete abutment walls + upper track deck!
        _drawQuad(canvas, p1L, p1R, p2R, p2L, Color.fromARGB((105 * (1.0 - fogMix)).toInt(), 0, 0, 0));
        _drawQuad(canvas, _project(brL1, y1, z1, w, horizonY, fovMult), bu1L, bu2L, _project(brL2, y2, z2, w, horizonY, fovMult), Color.lerp(const Color(0xFF5A6575), circuit.skyBottom, fogMix)!);
        _drawQuad(canvas, _project(brR1, y1, z1, w, horizonY, fovMult), _project(brR2, y2, z2, w, horizonY, fovMult), bu2R, bu1R, Color.lerp(const Color(0xFF475160), circuit.skyBottom, fogMix)!);
        _drawQuad(canvas, bu1L, bu1R, bu2R, bu2L, Color.lerp(const Color(0xFF1F2530), circuit.skyBottom, fogMix)!);
        _drawQuad(canvas, bu1L, bu1R, bt1R, bt1L, Color.lerp(const Color(0xFF8B98AA), circuit.skyBottom, fogMix)!);
        _strokePaint
          ..color = Color.lerp(const Color(0xFFE10600), circuit.skyBottom, fogMix)!
          ..strokeWidth = max(1.4, 8.0 / z1);
        canvas.drawLine(Offset.lerp(bu1L, bt1L, 0.55)!, Offset.lerp(bu1R, bt1R, 0.55)!, _strokePaint);
      } else if (circuit.code == 'AZE' && sliceProg >= 0.42 && sliceProg <= 0.54 && i < 64) {
        // ICONIC BAKU MEDIEVAL OLD CITY CASTLE STONE FORTRESS WALLS & BATTLEMENT MERLONS!
        final double cw1L = -run1L - 0.55 + s1;
        final double cw2L = -run2L - 0.55 + s2;
        final double cw1R = run1R + 0.55 + s1;
        final double cw2R = run2R + 0.55 + s2;
        final double castleH = (segIndex % 2 == 0) ? 4.35 : 3.75;
        final Color stoneL = Color.lerp(segIndex % 3 == 0 ? const Color(0xFFBFA37A) : const Color(0xFFA88C64), circuit.skyBottom, fogMix)!;
        final Color stoneR = Color.lerp(segIndex % 3 == 0 ? const Color(0xFF9C815C) : const Color(0xFF876E4D), circuit.skyBottom, fogMix)!;
        _drawQuad(canvas, w1LT, _project(cw1L, y1 + castleH, z1, w, horizonY, fovMult), _project(cw2L, y2 + castleH, z2, w, horizonY, fovMult), w2LT, stoneL);
        _drawQuad(canvas, w1RT, w2RT, _project(cw2R, y2 + castleH, z2, w, horizonY, fovMult), _project(cw1R, y1 + castleH, z1, w, horizonY, fovMult), stoneR);
        // Horizontal ashlar stone masonry courses
        if (i < 38) {
          _strokePaint
            ..color = Color.lerp(const Color(0x664A3924), circuit.skyBottom, fogMix)!
            ..strokeWidth = max(0.8, 2.2 / z1);
          canvas.drawLine(_project(cw1L, y1 + 2.4, z1, w, horizonY, fovMult), _project(cw2L, y2 + 2.4, z2, w, horizonY, fovMult), _strokePaint);
          canvas.drawLine(_project(cw1R, y1 + 2.4, z1, w, horizonY, fovMult), _project(cw2R, y2 + 2.4, z2, w, horizonY, fovMult), _strokePaint);
        }
      }

      // 3O. EXACT SUB-SLICE STANDALONE 3D CIRCUIT MONUMENTS (0.14 & 0.64 lap) -> ZERO strobing!
      if (i > 2 && i < 76) {
        final int lmLapIdx = (worldDist1 / lapLen).floor();
        for (int lmSide = 0; lmSide < 2; lmSide++) {
          final double lmDist = lmLapIdx * lapLen + (lmSide == 0 ? 0.14 : 0.64) * lapLen;
          if (lmDist >= worldDist1 && lmDist < worldDist2) {
            final double lFrac = ((lmDist - worldDist1) / worldSpan).clamp(0.0, 1.0).toDouble();
            final double lz = z1 + (z2 - z1) * lFrac;
            final double ls = s1 + (s2 - s1) * lFrac;
            final double ly = y1 + (y2 - y1) * lFrac;
            final bool onLeft = (lmSide == 0);
            final double lCap = onLeft
                ? (wallCap1L + (wallCap2L - wallCap1L) * lFrac)
                : (wallCap1R + (wallCap2R - wallCap1R) * lFrac);
            final double lmX = (onLeft ? (-lCap - 5.2) : (lCap + 5.2)) + ls;
            _drawCircuitMonument3D(canvas, lmX, ly, lz, w, horizonY, fovMult, fogMix, circuit, onLeft);
          }
        }
      }
    }

    // Silky Anti-Aliased Near/Mid Asphalt Sheen (Clipped strictly to road edges k=0..34 -> ZERO noise on kerbs, barriers, cars or horizon!)
    if (_asphaltTexPaint != null && asphaltClipMaxHit >= 2) {
      _asphaltClipPath
        ..reset()
        ..moveTo(_asphaltEdgeL[0].dx, _asphaltEdgeL[0].dy);
      for (int k = 1; k <= asphaltClipMaxHit; k++) {
        _asphaltClipPath.lineTo(_asphaltEdgeL[k].dx, _asphaltEdgeL[k].dy);
      }
      for (int k = asphaltClipMaxHit; k >= 0; k--) {
        _asphaltClipPath.lineTo(_asphaltEdgeR[k].dx, _asphaltEdgeR[k].dy);
      }
      _asphaltClipPath.close();

      canvas.save();
      canvas.clipPath(_asphaltClipPath);
      final double scrollY = _posMod(engine.playerDist * 32.0, 1024.0);
      canvas.translate(0, scrollY);
      canvas.drawRect(Rect.fromLTWH(0, horizonY - 1024, w, h - horizonY + 2048), _asphaltTexPaint!);
      canvas.restore();
    }

    // Soft Atmospheric Horizon Mist Ribbon (pre-cached shader -> ZERO per-frame GPU shader build!)
    if (_horizonMistPaint != null) {
      canvas.save();
      canvas.translate(0, horizonY);
      canvas.drawRect(Rect.fromLTWH(0, -22.0, w, 46.0), _horizonMistPaint!);
      canvas.restore();
    }

    // Subtle Cinematic Solar Lens Flare (100% pre-cached GPU shaders -> ZERO per-frame allocation!)
    if (!circuit.nightMode && sunX > w * 0.08 && sunX < w * 0.92) {
      final Offset sunPt = Offset(sunX, circuit.timeLabel == 'Atardecer' ? horizonY * 0.62 : horizonY * 0.27);
      final Offset screenMid = Offset(w * 0.5, h * 0.52);
      final double centerProx = (1.0 - ((sunX - w * 0.5).abs() / (w * 0.48))).clamp(0.0, 1.0).toDouble();
      if (centerProx > 0.12 && _lensFlareWarmPaint != null && _lensFlareCoolPaint != null && _lensAnaPaint != null) {
        final Offset f1 = Offset.lerp(sunPt, screenMid, 0.55)!;
        final Offset f2 = Offset.lerp(sunPt, screenMid, 1.18)!;
        final int alphaMod = (centerProx * 255.0).clamp(0.0, 255.0).toInt();
        _lensFlareWarmPaint!.color = Color.fromARGB(alphaMod, 255, 255, 255);
        canvas.save();
        canvas.translate(f1.dx, f1.dy);
        final double sc1 = (38.0 * centerProx) / 48.0;
        canvas.scale(sc1, sc1);
        canvas.drawCircle(Offset.zero, 48.0, _lensFlareWarmPaint!);
        canvas.restore();

        _lensFlareCoolPaint!.color = Color.fromARGB(alphaMod, 255, 255, 255);
        canvas.save();
        canvas.translate(f2.dx, f2.dy);
        final double sc2 = (24.0 * centerProx) / 32.0;
        canvas.scale(sc2, sc2);
        canvas.drawCircle(Offset.zero, 32.0, _lensFlareCoolPaint!);
        canvas.restore();

        _lensAnaPaint!.color = Color.fromARGB(alphaMod, 255, 255, 255);
        canvas.save();
        canvas.translate(sunPt.dx, sunPt.dy);
        canvas.scale((w * 0.58 * centerProx) / 256.0, 1.0);
        canvas.drawRect(const Rect.fromLTWH(-128.0, -5.0, 256.0, 10.0), _lensAnaPaint!);
        canvas.restore();
      }
    }

    // 4. Incandescent Sparks (Glowing Outer Trail + White-Hot Core) & Gravel/Grass Particles
    for (final p in engine.particles) {
      final Offset pt = Offset(p.x * w, p.y * h);
      if (p.isSpark) {
        final Offset tail = Offset(pt.dx - p.vx * 16, pt.dy - p.vy * 16);
        _strokePaint
          ..color = p.color.withAlpha(185)
          ..strokeWidth = p.radius * 1.7
          ..strokeCap = StrokeCap.round;
        canvas.drawLine(pt, tail, _strokePaint);
        _strokePaint
          ..color = const Color(0xF5FFFDE7)
          ..strokeWidth = max(1.0, p.radius * 0.65);
        canvas.drawLine(pt, Offset.lerp(pt, tail, 0.55)!, _strokePaint);
      } else {
        _fillPaint.color = p.color;
        canvas.drawCircle(pt, p.radius, _fillPaint);
      }
    }

    canvas.restore();

    // 5. Photorealistic 3D Cockpit Overlay (Chase Car is already rendered inside the True-3D World Spine above!)
    if (cockpit) {
      _drawCockpitUltra(canvas, w, h, sunNormX, circuit);
    }

    // 6. High-Speed Radial Perspective Motion Streaks + Curved Aerodynamic Slipstream/ERS Wind Ribbons!
    final bool ersOn = engine.ersActive;
    if (engine.speedKmh > 230 || ersOn || engine.playerInSlipstream) {
      final double alphaFrac = ((engine.speedKmh - 220) / 130.0).clamp(0.16, 0.78).toDouble();
      final Color streakCol = ersOn
          ? Color.fromARGB((alphaFrac * 145).toInt(), 0, 229, 255)
          : (engine.playerInSlipstream
              ? Color.fromARGB((alphaFrac * 124).toInt(), 105, 240, 174)
              : Color.fromARGB((alphaFrac * 90).toInt(), 255, 255, 255));
      _strokePaint
        ..color = streakCol
        ..strokeWidth = ersOn ? 2.0 : 1.6
        ..strokeCap = StrokeCap.round;
      for (int k = 0; k < 16; k++) {
        final bool isLeftEdge = k.isEven;
        final double ang = isLeftEdge ? (pi * 0.72 + (k * 0.038)) : (pi * 0.28 - (k * 0.038));
        final double distR = (w * 0.34) + ((engine.playerDist * 44.0 + k * 67.0) % (w * 0.28));
        final Offset a = Offset(w * 0.5 + cos(ang) * distR, horizonY + sin(ang) * distR * 0.65);
        final Offset b = Offset(w * 0.5 + cos(ang) * (distR + 62.0), horizonY + sin(ang) * (distR + 62.0) * 0.65);
        canvas.drawLine(a, b, _strokePaint);
      }
      // Subtle curved slipstream / ERS air-flow arcs sweeping past the peripheral visor (zero Path alloc!)
      if (ersOn || engine.playerInSlipstream) {
        _strokePaint
          ..color = streakCol.withAlpha((streakCol.alpha * 0.55).toInt())
          ..strokeWidth = 2.4;
        final double flowPhase = (engine.totalRaceTime * 10.0) % 1.0;
        for (final double sDir in const [-1.0, 1.0]) {
          _scratchPath
            ..reset()
            ..moveTo(w * (0.5 + sDir * (0.20 + flowPhase * 0.06)), horizonY + 18)
            ..quadraticBezierTo(w * (0.5 + sDir * 0.42), h * 0.56, w * (0.5 + sDir * 0.52), h * 0.86);
          canvas.drawPath(_scratchPath, _strokePaint);
        }
      }
    }

    // 7. Cached Film-Grade Atmospheric Color Grading Wash (ZERO per-frame shader allocations!)
    if (_colorGradePaint != null) {
      canvas.drawRect(Rect.fromLTWH(0, 0, w, h), _colorGradePaint!);
    }

    if (_vignettePaint != null) {
      canvas.drawRect(Rect.fromLTWH(0, 0, w, h), _vignettePaint!);
    }

    if (engine.isOffTrack && engine.startLightsTimer <= 0 && engine.hitFlash <= 0.05 && _offTrackOverlayPaint != null) {
      final double pulse = 0.58 + 0.42 * sin(engine.offTrackTime * 8.5);
      _offTrackOverlayPaint!.color = Color.fromARGB((255 * pulse).clamp(0.0, 255.0).toInt(), 255, 255, 255);
      canvas.drawRect(Rect.fromLTWH(0, 0, w, h), _offTrackOverlayPaint!);
    }

    if (engine.hitFlash > 0 && _hitFlashOverlayPaint != null) {
      _hitFlashOverlayPaint!.color = Color.fromARGB((engine.hitFlash * 255.0).clamp(0.0, 255.0).toInt(), 255, 255, 255);
      canvas.drawRect(Rect.fromLTWH(0, 0, w, h), _hitFlashOverlayPaint!);
    }
  }

  void _drawQuad(Canvas canvas, Offset a, Offset b, Offset c, Offset d, Color color) {
    // Lossless Viewport Frustum Culling: skips quads 100% off-screen before touching GPU Path rasterizer!
    if ((a.dx < -4.0 && b.dx < -4.0 && c.dx < -4.0 && d.dx < -4.0) ||
        (a.dx > _viewW + 4.0 && b.dx > _viewW + 4.0 && c.dx > _viewW + 4.0 && d.dx > _viewW + 4.0) ||
        (a.dy < -4.0 && b.dy < -4.0 && c.dy < -4.0 && d.dy < -4.0) ||
        (a.dy > _viewH + 4.0 && b.dy > _viewH + 4.0 && c.dy > _viewH + 4.0 && d.dy > _viewH + 4.0)) {
      return;
    }
    _quadPath
      ..reset()
      ..moveTo(a.dx, a.dy)
      ..lineTo(b.dx, b.dy)
      ..lineTo(c.dx, c.dy)
      ..lineTo(d.dx, d.dy)
      ..close();
    _fillPaint.color = color;
    canvas.drawPath(_quadPath, _fillPaint);
  }

  /// Batches two same-color quads (e.g. left+right barriers, kerbs, wheel tracks) into ONE single GPU drawPath!
  void _drawQuadPair(
    Canvas canvas,
    Offset a1,
    Offset b1,
    Offset c1,
    Offset d1,
    Offset a2,
    Offset b2,
    Offset c2,
    Offset d2,
    Color color,
  ) {
    final bool vis1 = !((a1.dx < -4.0 && b1.dx < -4.0 && c1.dx < -4.0 && d1.dx < -4.0) ||
        (a1.dx > _viewW + 4.0 && b1.dx > _viewW + 4.0 && c1.dx > _viewW + 4.0 && d1.dx > _viewW + 4.0) ||
        (a1.dy < -4.0 && b1.dy < -4.0 && c1.dy < -4.0 && d1.dy < -4.0) ||
        (a1.dy > _viewH + 4.0 && b1.dy > _viewH + 4.0 && c1.dy > _viewH + 4.0 && d1.dy > _viewH + 4.0));
    final bool vis2 = !((a2.dx < -4.0 && b2.dx < -4.0 && c2.dx < -4.0 && d2.dx < -4.0) ||
        (a2.dx > _viewW + 4.0 && b2.dx > _viewW + 4.0 && c2.dx > _viewW + 4.0 && d2.dx > _viewW + 4.0) ||
        (a2.dy < -4.0 && b2.dy < -4.0 && c2.dy < -4.0 && d2.dy < -4.0) ||
        (a2.dy > _viewH + 4.0 && b2.dy > _viewH + 4.0 && c2.dy > _viewH + 4.0 && d2.dy > _viewH + 4.0));
    if (!vis1 && !vis2) return;
    _quadPath.reset();
    if (vis1) {
      _quadPath
        ..moveTo(a1.dx, a1.dy)
        ..lineTo(b1.dx, b1.dy)
        ..lineTo(c1.dx, c1.dy)
        ..lineTo(d1.dx, d1.dy)
        ..close();
    }
    if (vis2) {
      _quadPath
        ..moveTo(a2.dx, a2.dy)
        ..lineTo(b2.dx, b2.dy)
        ..lineTo(c2.dx, c2.dy)
        ..lineTo(d2.dx, d2.dy)
        ..close();
    }
    _fillPaint.color = color;
    canvas.drawPath(_quadPath, _fillPaint);
  }

  void _drawTri(Canvas canvas, Offset a, Offset b, Offset c, Color color) {
    if ((a.dx < -4.0 && b.dx < -4.0 && c.dx < -4.0) ||
        (a.dx > _viewW + 4.0 && b.dx > _viewW + 4.0 && c.dx > _viewW + 4.0) ||
        (a.dy < -4.0 && b.dy < -4.0 && c.dy < -4.0) ||
        (a.dy > _viewH + 4.0 && b.dy > _viewH + 4.0 && c.dy > _viewH + 4.0)) {
      return;
    }
    _quadPath
      ..reset()
      ..moveTo(a.dx, a.dy)
      ..lineTo(b.dx, b.dy)
      ..lineTo(c.dx, c.dy)
      ..close();
    _fillPaint.color = color;
    canvas.drawPath(_quadPath, _fillPaint);
  }

  void _drawBrakingBoard(
    Canvas canvas,
    double x,
    double y1,
    double z,
    double w,
    double horizonY,
    double fovMult,
    String text,
    double fogMix,
  ) {
    final Offset base = _project(x, y1, z, w, horizonY, fovMult);
    if (base.dx < -90.0 || base.dx > w + 90.0) return;
    final Offset top = _project(x, y1 + 1.55, z, w, horizonY, fovMult);
    final double bh = max(6.0, base.dy - top.dy);
    final double bw = bh * 1.18;
    if (bw < 8.0) return;

    // Ground cast shadow & twin galvanized steel support legs
    _fillPaint.color = Color.fromARGB((82 * (1.0 - fogMix)).toInt(), 0, 0, 0);
    canvas.drawOval(Rect.fromCenter(center: Offset(base.dx + bw * 0.10, base.dy), width: bw * 1.35, height: max(2.2, bw * 0.24)), _fillPaint);

    _strokePaint
      ..color = Color.lerp(const Color(0xFF283242), engine.circuit.skyBottom, fogMix)!
      ..strokeWidth = max(1.3, bw * 0.075);
    final double legOff = bw * 0.28;
    canvas.drawLine(Offset(base.dx - legOff, base.dy), Offset(top.dx - legOff, top.dy + bh * 0.66), _strokePaint);
    canvas.drawLine(Offset(base.dx + legOff, base.dy), Offset(top.dx + legOff, top.dy + bh * 0.66), _strokePaint);

    final Rect board = Rect.fromLTWH(top.dx - bw * 0.52, top.dy, bw * 1.04, bh * 0.70);
    // 3D Polystyrene/Aluminum extruded depth side & bottom lip
    _fillPaint.color = Color.lerp(const Color(0xFF6B7B90), engine.circuit.skyBottom, fogMix)!;
    canvas.drawRect(Rect.fromLTWH(board.right, board.top + 1.0, max(2.0, bw * 0.13), board.height), _fillPaint);
    _fillPaint.color = Color.lerp(const Color(0xFF252D3B), engine.circuit.skyBottom, fogMix)!;
    canvas.drawRect(Rect.fromLTWH(board.left + 1.0, board.bottom, board.width, max(1.5, bw * 0.08)), _fillPaint);

    // High-contrast white reflective board + red FIA top header band + bold corner distance number
    _fillPaint.color = Color.lerp(const Color(0xFFF8FAFE), engine.circuit.skyBottom, fogMix)!;
    canvas.drawRect(board, _fillPaint);
    _fillPaint.color = Color.lerp(const Color(0xFFE10600), engine.circuit.skyBottom, fogMix)!;
    canvas.drawRect(Rect.fromLTWH(board.left, board.top, board.width, board.height * 0.20), _fillPaint);
    _strokePaint
      ..color = Color.lerp(const Color(0xFF141922), engine.circuit.skyBottom, fogMix)!
      ..strokeWidth = max(1.0, bw * 0.06);
    canvas.drawRect(board, _strokePaint);
    if (bw > 14.0) {
      final TextPainter tp = _getCachedBoardText(text, (bh * 0.38).clamp(7.0, 17.0).toDouble(), const Color(0xFF0E121A));
      tp.paint(canvas, Offset(board.center.dx - tp.width * 0.5, board.top + board.height * 0.58 - tp.height * 0.5));
    }
  }

  /// Next-Gen Multi-Slice Extruded 3D Grandstand (VIP Skybox Glass, Textured Crowd, LED Roof Strip & Steel Trusses!)
  void _draw3DExtrudedGrandstandSlice(
    Canvas canvas,
    double baseX1,
    double baseX2,
    double s1,
    double s2,
    double y1,
    double y2,
    double z1,
    double z2,
    bool isLeft,
    int segIndex,
    double w,
    double horizonY,
    double fovMult,
    double fogMix,
    CircuitInfo circuit,
  ) {
    final double dir = isLeft ? -1.0 : 1.0;
    const double deckDepth = 6.6;
    const double frontH = 1.50;
    const double backH = 5.45;
    const double roofH = 6.75;

    final Offset fb1 = _project(baseX1 + s1, y1, z1, w, horizonY, fovMult);
    final Offset fb2 = _project(baseX2 + s2, y2, z2, w, horizonY, fovMult);
    final Offset bt1 = _project(baseX1 + dir * deckDepth + s1, y1 + backH, z1, w, horizonY, fovMult);
    final Offset bt2 = _project(baseX2 + dir * deckDepth + s2, y2 + backH, z2, w, horizonY, fovMult);
    // GTA 3 Frustum Culling: skip grandstand slices completely outside horizontal viewport!
    final double minGx = min(min(fb1.dx, fb2.dx), min(bt1.dx, bt2.dx));
    final double maxGx = max(max(fb1.dx, fb2.dx), max(bt1.dx, bt2.dx));
    if (maxGx < -40.0 || minGx > w + 40.0) return;

    final Offset ft1 = _project(baseX1 + s1, y1 + frontH, z1, w, horizonY, fovMult);
    final Offset ft2 = _project(baseX2 + s2, y2 + frontH, z2, w, horizonY, fovMult);

    final Offset rf1 = _project(baseX1 - dir * 1.25 + s1, y1 + roofH, z1, w, horizonY, fovMult);
    final Offset rf2 = _project(baseX2 - dir * 1.25 + s2, y2 + roofH, z2, w, horizonY, fovMult);
    final Offset rb1 = _project(baseX1 + dir * (deckDepth + 0.7) + s1, y1 + roofH + 0.48, z1, w, horizonY, fovMult);
    final Offset rb2 = _project(baseX2 + dir * (deckDepth + 0.7) + s2, y2 + roofH + 0.48, z2, w, horizonY, fovMult);

    // 1. Architectural Concrete Front Facade Wall + Sponsor Banner + Glowing Upper Rail
    final Color wallCol = Color.lerp(
      circuit.nightMode ? const Color(0xFF172033) : const Color(0xFF424E61),
      circuit.skyBottom,
      fogMix,
    )!;
    _drawQuad(canvas, fb1, ft1, ft2, fb2, wallCol);

    final Offset fs1 = _project(baseX1 + s1, y1 + frontH * 0.68, z1, w, horizonY, fovMult);
    final Offset fs2 = _project(baseX2 + s2, y2 + frontH * 0.68, z2, w, horizonY, fovMult);
    _drawQuad(canvas, fs1, ft1, ft2, fs2, Color.lerp(circuit.kerbA, circuit.skyBottom, fogMix)!);

    // 2. Sloped 3D Seating Deck + High-Res Crowd Texture Overlay
    final Color deckCol = Color.lerp(
      circuit.nightMode ? const Color(0xFF0E1526) : const Color(0xFF27303E),
      circuit.skyBottom,
      fogMix,
    )!;
    _drawQuad(canvas, ft1, bt1, bt2, ft2, deckCol);

    if (UltraTextures.crowdShader != null && fogMix < 0.58) {
      _quadPath
        ..reset()
        ..moveTo(ft1.dx, ft1.dy)
        ..lineTo(bt1.dx, bt1.dy)
        ..lineTo(bt2.dx, bt2.dy)
        ..lineTo(ft2.dx, ft2.dy)
        ..close();
      _gradPaint.shader = UltraTextures.crowdShader;
      canvas.drawPath(_quadPath, _gradPaint);
    }

    // 3. Perspective Tiered Crowd & Vibrant Flag Rows along the sloped 3D deck
    const List<Color> crowdTones = [
      Color(0xFFE53935),
      Color(0xFFF5F7FA),
      Color(0xFF1E88E5),
      Color(0xFFFFCA28),
      Color(0xFF43A047),
      Color(0xFFFF6F00),
    ];
    for (int tier = 0; tier < 5; tier++) {
      final double fA = 0.08 + tier * 0.17;
      final double fB = fA + 0.09;
      final Offset p1A = Offset.lerp(ft1, bt1, fA)!;
      final Offset p2A = Offset.lerp(ft2, bt2, fA)!;
      final Offset p1B = Offset.lerp(ft1, bt1, fB)!;
      final Offset p2B = Offset.lerp(ft2, bt2, fB)!;
      final Color rowRaw = crowdTones[(segIndex + tier * 2).abs() % crowdTones.length];
      _drawQuad(canvas, p1A, p1B, p2B, p2A, Color.lerp(rowRaw, circuit.skyBottom, fogMix * 0.80 + 0.10)!);
    }

    // 3B. Concrete Grandstand Staircase Aisles with Yellow FIA Safety Handrails every 6 slices!
    if (segIndex % 6 == 0) {
      final Offset ais1A = Offset.lerp(ft1, ft2, 0.22)!;
      final Offset ais1B = Offset.lerp(ft1, ft2, 0.78)!;
      final Offset ais2A = Offset.lerp(bt1, bt2, 0.22)!;
      final Offset ais2B = Offset.lerp(bt1, bt2, 0.78)!;
      _drawQuad(canvas, ais1A, ais2A, ais2B, ais1B, Color.lerp(const Color(0xFF6B7788), circuit.skyBottom, fogMix)!);
      _strokePaint
        ..color = Color.lerp(const Color(0xEEFFD600), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(1.0, 4.2 / z1);
      canvas.drawLine(Offset.lerp(ais1A, ais1B, 0.5)!, Offset.lerp(ais2A, ais2B, 0.5)!, _strokePaint);
    }

    // 4. Illuminated VIP Paddock Club Glass Skybox with Metallic Window Mullions & Diagonal Glint!
    final Offset skyB1 = Offset.lerp(ft1, bt1, 0.84)!;
    final Offset skyB2 = Offset.lerp(ft2, bt2, 0.84)!;
    final Color vipGlass = circuit.nightMode
        ? (segIndex % 3 == 0 ? const Color(0xFF56C8FF) : const Color(0xFFFFE082))
        : const Color(0xFF8CB8D8);
    _drawQuad(canvas, skyB1, bt1, bt2, skyB2, Color.lerp(vipGlass, circuit.skyBottom, fogMix * 0.72 + 0.10)!);
    // Crisp dark architectural steel mullions separating VIP glass bays
    if (segIndex % 2 == 0) {
      _strokePaint
        ..color = Color.lerp(const Color(0xFF151C28), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(1.0, 4.5 / z1);
      canvas.drawLine(skyB1, bt1, _strokePaint);
    }
    _strokePaint
      ..color = Color.lerp(const Color(0xCCFFFFFF), circuit.skyBottom, fogMix)!
      ..strokeWidth = max(0.9, 3.2 / z1);
    canvas.drawLine(skyB1, skyB2, _strokePaint);

    // 5. Cantilevered 3D Roof Canopy (Shaded underside + glowing LED fascia + under-roof spotlights!)
    _drawQuad(
      canvas,
      rf1,
      rb1,
      rb2,
      rf2,
      Color.lerp(circuit.nightMode ? const Color(0xFF1B253B) : const Color(0xFF7B8CA3), circuit.skyBottom, fogMix)!,
    );
    // Darker structural roof underside shadow strip
    _drawQuad(
      canvas,
      rf1,
      Offset.lerp(rf1, rb1, 0.34)!,
      Offset.lerp(rf2, rb2, 0.34)!,
      rf2,
      Color.lerp(const Color(0xFF121824), circuit.skyBottom, fogMix)!,
    );
    _strokePaint
      ..color = Color.lerp(circuit.nightMode ? const Color(0xF069F0FF) : const Color(0xFFF4F8FE), circuit.skyBottom, fogMix)!
      ..strokeWidth = max(1.5, 13.0 / z1);
    canvas.drawLine(rf1, rf2, _strokePaint);

    // 6. Structural Steel Support Columns, Diagonal Roof Trusses, Under-Canopy Spotlights & Waving Rooftop Flags!
    if (segIndex % 4 == 0) {
      _strokePaint
        ..color = Color.lerp(const Color(0xFF1A2333), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(1.5, 14.5 / z1);
      canvas.drawLine(bt1, rb1, _strokePaint);
      canvas.drawLine(rb1, rf1, _strokePaint);
      _strokePaint
        ..color = Color.lerp(const Color(0xAA566B8A), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(1.0, 6.8 / z1);
      canvas.drawLine(bt1, Offset.lerp(rb1, rf1, 0.54)!, _strokePaint);
      // Glowing stadium floodlight pods mounted under the grandstand roof lip!
      final Offset podPt = Offset.lerp(rf1, rb1, 0.16)!;
      if (z1 < 34.0) {
        final double lr = max(2.0, 14.0 / z1);
        _fillPaint.color = Color.fromARGB((circuit.nightMode ? 105 : 46), 220, 242, 255);
        canvas.drawCircle(podPt, lr, _fillPaint);
        _fillPaint.color = const Color(0xF5FFFFFF);
        canvas.drawCircle(podPt, lr * 0.42, _fillPaint);
      }
      // Animated waving GP team flags along the grandstand roof crest!
      if (segIndex % 8 == 0 && z1 < 42.0) {
        final Offset poleTop = _project(baseX1 - dir * 1.15 + s1, y1 + roofH + 1.45, z1, w, horizonY, fovMult);
        _strokePaint
          ..color = Color.lerp(const Color(0xFFD0DCEB), circuit.skyBottom, fogMix)!
          ..strokeWidth = max(1.0, 4.5 / z1);
        canvas.drawLine(rf1, poleTop, _strokePaint);
        final double flW = max(4.0, 32.0 / z1);
        final double flH = flW * 0.56;
        final double flutter = sin(engine.totalRaceTime * 7.2 + segIndex) * (flH * 0.34);
        final Color flCol = (segIndex % 24 == 0)
            ? const Color(0xFFE10600)
            : (segIndex % 24 == 8 ? const Color(0xFFFFD54F) : const Color(0xFF00E5FF));
        _drawQuad(
          canvas,
          poleTop,
          Offset(poleTop.dx + dir * flW, poleTop.dy + flutter),
          Offset(poleTop.dx + dir * flW * 0.92, poleTop.dy + flH + flutter),
          Offset(poleTop.dx, poleTop.dy + flH),
          Color.lerp(flCol, circuit.skyBottom, fogMix * 0.6)!,
        );
      }
    }
  }

  void _draw3DSponsorArch(
    Canvas canvas,
    double s1,
    double s2,
    double y1,
    double y2,
    double z1,
    double z2,
    double roadHalfW,
    double w,
    double horizonY,
    double fovMult,
    double fogMix,
    CircuitInfo circuit,
    int archIndex,
  ) {
    final double spanX = roadHalfW + 1.55;
    // Crisp dark ground shadow across the entire asphalt
    final Offset sh1L = _project(-roadHalfW + s1, y1 + 0.015, z1, w, horizonY, fovMult);
    final Offset sh1R = _project(roadHalfW + s1, y1 + 0.015, z1, w, horizonY, fovMult);
    final Offset sh2L = _project(-roadHalfW + s2, y2 + 0.015, z2, w, horizonY, fovMult);
    final Offset sh2R = _project(roadHalfW + s2, y2 + 0.015, z2, w, horizonY, fovMult);
    _drawQuad(canvas, sh1L, sh1R, sh2R, sh2L, Color.fromARGB((108 * (1.0 - fogMix)).toInt(), 0, 0, 0));

    final Offset bL = _project(-spanX + s1, y1, z1, w, horizonY, fovMult);
    final Offset bR = _project(spanX + s1, y1, z1, w, horizonY, fovMult);
    final Offset bLBack = _project(-spanX + s2, y2, z2, w, horizonY, fovMult);
    final Offset bRBack = _project(spanX + s2, y2, z2, w, horizonY, fovMult);
    final Offset tL = _project(-spanX + s1, y1 + 4.35, z1, w, horizonY, fovMult);
    final Offset tR = _project(spanX + s1, y1 + 4.35, z1, w, horizonY, fovMult);
    final Offset tLBack = _project(-spanX + s2, y2 + 4.35, z2, w, horizonY, fovMult);
    final Offset tRBack = _project(spanX + s2, y2 + 4.35, z2, w, horizonY, fovMult);
    final double beamH = max(8.0, 82.0 / z1);

    // 3D Thickened Steel Towers (front + depth side + metallic highlight edge)
    _drawQuad(canvas, bL, tL, tLBack, bLBack, Color.lerp(const Color(0xFF141A24), circuit.skyBottom, fogMix)!);
    _drawQuad(canvas, bR, bRBack, tRBack, tR, Color.lerp(const Color(0xFF141A24), circuit.skyBottom, fogMix)!);
    _strokePaint
      ..color = Color.lerp(const Color(0xFF344157), circuit.skyBottom, fogMix)!
      ..strokeWidth = max(3.5, 34.0 / z1);
    canvas.drawLine(bL, tL, _strokePaint);
    canvas.drawLine(bR, tR, _strokePaint);
    // Steel cross-brace struts on towers
    if (beamH > 12.0) {
      _strokePaint
        ..color = Color.lerp(const Color(0xAA6A7E9C), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(1.0, 6.0 / z1);
      for (int tr = 0; tr < 3; tr++) {
        final double f0 = tr / 3.0;
        final double f1 = (tr + 1) / 3.0;
        canvas.drawLine(Offset.lerp(bL, tL, f0)!, Offset.lerp(bLBack, tLBack, f1)!, _strokePaint);
        canvas.drawLine(Offset.lerp(bR, tR, f0)!, Offset.lerp(bRBack, tRBack, f1)!, _strokePaint);
      }
    }

    // 3D Bridge Underside Slab
    _drawQuad(
      canvas,
      Offset(tL.dx, tL.dy + beamH * 0.52),
      Offset(tR.dx, tR.dy + beamH * 0.52),
      Offset(tRBack.dx, tRBack.dy + beamH * 0.44),
      Offset(tLBack.dx, tLBack.dy + beamH * 0.44),
      Color.lerp(const Color(0xFF090C12), circuit.skyBottom, fogMix)!,
    );

    final Rect bridge = Rect.fromLTRB(tL.dx, tL.dy - beamH * 0.52, tR.dx, tR.dy + beamH * 0.52);
    final bool altBrand = archIndex % 2 == 0;
    final Color brandBg = altBrand ? const Color(0xFF0E1422) : circuit.kerbA;
    final Color brandBgHi = Color.lerp(brandBg, Colors.white, 0.24)!;
    final Color brandBgLo = Color.lerp(brandBg, Colors.black, 0.30)!;
    final Color brandAccent = altBrand ? const Color(0xFFFFD54F) : const Color(0xFFFFFFFF);
    // Layered architectural sponsor fascia (zero shader alloc + crisp 3D depth shading!)
    _fillPaint.color = Color.lerp(brandBg, circuit.skyBottom, fogMix)!;
    canvas.drawRect(bridge, _fillPaint);
    _fillPaint.color = Color.lerp(brandBgHi, circuit.skyBottom, fogMix)!;
    canvas.drawRect(Rect.fromLTRB(bridge.left, bridge.top, bridge.right, bridge.top + beamH * 0.34), _fillPaint);
    _fillPaint.color = Color.lerp(brandBgLo, circuit.skyBottom, fogMix)!;
    canvas.drawRect(Rect.fromLTRB(bridge.left, bridge.bottom - beamH * 0.26, bridge.right, bridge.bottom), _fillPaint);
    _fillPaint.color = Color.lerp(brandAccent, circuit.skyBottom, fogMix)!;
    canvas.drawRect(Rect.fromLTRB(bridge.left, bridge.top, bridge.right, bridge.top + beamH * 0.14), _fillPaint);
    canvas.drawRect(Rect.fromLTRB(bridge.left, bridge.bottom - beamH * 0.11, bridge.right, bridge.bottom), _fillPaint);
    // Glowing under-bridge stadium LED light strip on Night circuits!
    if (circuit.nightMode && beamH > 9.0) {
      _strokePaint
        ..color = Color.lerp(const Color(0xCC69F0FF), circuit.skyBottom, fogMix * 0.6)!
        ..strokeWidth = max(1.2, 4.0 / z1);
      canvas.drawLine(Offset(bridge.left + 4, bridge.bottom + 1.5), Offset(bridge.right - 4, bridge.bottom + 1.5), _strokePaint);
    }

    if (beamH > 13.0) {
      final String label = altBrand ? 'APEX GP 24  •  PIRELLI' : 'FORMULA PRO  •  ${circuit.code}';
      final TextPainter tp = _getCachedBoardText(
        label,
        (beamH * 0.35).clamp(8.0, 22.0).toDouble(),
        Color.lerp(Colors.white, circuit.skyBottom, fogMix)!,
      );
      tp.paint(canvas, Offset(bridge.center.dx - tp.width * 0.5, bridge.center.dy - tp.height * 0.5));
    }
  }

  void _drawProEnvironment(Canvas canvas, double w, double h, double horizonY, double sunX, CircuitInfo circuit) {
    final bool isSunset = circuit.timeLabel == 'Atardecer';
    final bool isCloudy = circuit.timeLabel == 'Nublado';
    final bool isAlpine = circuit.code == 'AUT' ||
        circuit.code == 'JPN' ||
        circuit.code == 'BEL' ||
        circuit.code == 'ITA' ||
        circuit.code == 'EMI' ||
        circuit.code == 'MEX';

    // 1. Photorealistic 6-Band Rayleigh/Mie Atmospheric Sky Dome (pre-cached shader -> ZERO GPU alloc!)
    if (_skyPaint != null) {
      canvas.save();
      canvas.translate(0, horizonY);
      canvas.drawRect(Rect.fromLTWH(0, -horizonY, w, horizonY + 8.0), _skyPaint!);
      canvas.restore();
    }

    // Directional Sun/Moon Position + Volumetric Horizon Atmospheric Solar Scattering (pre-cached shaders!)
    final double sunY = isSunset ? (horizonY * 0.62) : (horizonY * 0.27);
    final Offset sunCenter = Offset(sunX, sunY);
    if (!circuit.nightMode && _horizonSolarBloomPaint != null) {
      canvas.save();
      canvas.translate(sunX, horizonY);
      canvas.scale(isSunset ? 2.15 : 1.70, isSunset ? 0.68 : 0.48);
      canvas.drawCircle(Offset.zero, 180.0, _horizonSolarBloomPaint!);
      canvas.restore();
    }
    if (_sunHaloPaint != null) {
      canvas.save();
      canvas.translate(sunCenter.dx, sunCenter.dy);
      canvas.drawCircle(Offset.zero, _cachedSunHaloR, _sunHaloPaint!);
      canvas.restore();
    }

    // Crisp Lunar Disc with subtle mare craters on Night Circuits OR Blazing Solar Core on Day/Sunset
    if (circuit.nightMode) {
      _fillPaint.color = const Color(0xF5EEF6FF);
      canvas.drawCircle(sunCenter, 12.5, _fillPaint);
      _fillPaint.color = const Color(0x448AA0BC);
      canvas.drawCircle(Offset(sunCenter.dx - 3.5, sunCenter.dy - 2.0), 3.6, _fillPaint);
      canvas.drawCircle(Offset(sunCenter.dx + 4.0, sunCenter.dy + 2.5), 2.8, _fillPaint);
      canvas.drawCircle(Offset(sunCenter.dx - 1.0, sunCenter.dy + 4.8), 2.1, _fillPaint);

      // Gently Sweeping Volumetric Stadium Sky-Beams + Dual-Tone Night Light-Pollution Horizon Glow
      for (int beam = 0; beam < 5; beam++) {
        final double bx = ((beam * (w * 0.25) + engine.horizonPan * 0.22) % (w + 150) + (w + 150)) % (w + 150) - 75;
        final double sway = sin(engine.totalRaceTime * 0.45 + beam * 1.7) * 26.0;
        final double lean = (beam.isEven ? 1.0 : -1.0) * 54.0 + sway;
        _drawQuad(
          canvas,
          Offset(bx - 7.0, horizonY),
          Offset(bx + 7.0, horizonY),
          Offset(bx + lean + 34.0, 0.0),
          Offset(bx + lean - 34.0, 0.0),
          beam % 2 == 0 ? const Color(0x1680D8FF) : const Color(0x12FFE0A0),
        );
      }
      if (_nightGlowPaint != null) {
        canvas.save();
        canvas.translate(0, horizonY);
        canvas.drawRect(Rect.fromLTWH(0, -76.0, w, 78.0), _nightGlowPaint!);
        canvas.restore();
      }

      // Multi-Magnitude Twinkling Starfield + Subtle Under-Lit Night Cloud Wisps
      for (int s = 0; s < 96; s++) {
        final double sx = ((s * 79.0 + engine.horizonPan * 0.05) % w + w) % w;
        final double sy = (s * 31.0) % (horizonY * 0.72);
        final double twinkle = 0.50 + 0.50 * sin(engine.totalRaceTime * 2.2 + s * 1.9);
        _fillPaint.color = Color.fromARGB((230 * twinkle).toInt(), s % 7 == 0 ? 185 : 255, s % 9 == 0 ? 225 : 255, 255);
        canvas.drawCircle(Offset(sx, sy), (s % 7 == 0) ? 1.85 : 0.90, _fillPaint);
      }
      for (int nc = 0; nc < 5; nc++) {
        final double ncx = ((nc * 245.0 + engine.horizonPan * 0.11) % (w + 340) + (w + 340)) % (w + 340) - 170;
        final double ncy = horizonY * (0.28 + (nc % 2) * 0.18);
        _fillPaint.color = const Color(0x281B2C4A);
        canvas.drawOval(Rect.fromCenter(center: Offset(ncx, ncy), width: 210.0, height: 24.0), _fillPaint);
        _fillPaint.color = const Color(0x1E69C8FF);
        canvas.drawOval(Rect.fromCenter(center: Offset(ncx, ncy + 7.5), width: 170.0, height: 9.0), _fillPaint);
      }
    } else {
      // Soft Volumetric God-Rays fanning from the sun
      for (int r = -3; r <= 3; r++) {
        final double ang = pi * 0.36 + r * 0.18;
        final Offset tipA = Offset(sunCenter.dx + cos(ang - 0.055) * 320.0, sunCenter.dy + sin(ang - 0.055) * 320.0);
        final Offset tipB = Offset(sunCenter.dx + cos(ang + 0.055) * 320.0, sunCenter.dy + sin(ang + 0.055) * 320.0);
        _drawTri(canvas, sunCenter, tipA, tipB, isSunset ? const Color(0x1AFFC670) : const Color(0x14FFF4CC));
      }
      // High-Altitude Wispy Cirrus Filaments (photographic perspective sky depth!)
      _strokePaint
        ..color = isSunset ? const Color(0x38FFD49E) : const Color(0x28FFFFFF)
        ..strokeWidth = 2.0
        ..strokeCap = StrokeCap.round;
      for (int ci = 0; ci < 8; ci++) {
        final double cix = ((ci * 235.0 + engine.horizonPan * 0.065) % (w + 320) + (w + 320)) % (w + 320) - 160;
        final double ciy = horizonY * (0.08 + (ci % 3) * 0.085);
        canvas.drawLine(Offset(cix - 74, ciy), Offset(cix + 74, ciy - 4.5), _strokePaint);
        canvas.drawLine(Offset(cix - 42, ciy + 3.5), Offset(cix + 54, ciy - 1.2), _strokePaint);
      }
      // Sculpted Multi-Tier Volumetric Cumulus Clouds (Sun-Directed Rim Highlight + Cool/Warm Underside!)
      final Color cloudShadowOuter = isSunset
          ? const Color(0x484E2C45)
          : Color.lerp(circuit.skyBottom, const Color(0xFF425874), isCloudy ? 0.56 : 0.40)!.withAlpha(isCloudy ? 72 : 48);
      final Color cloudShadowCore = isSunset
          ? const Color(0x663B2038)
          : Color.lerp(circuit.skyBottom, const Color(0xFF3A4E68), isCloudy ? 0.62 : 0.44)!.withAlpha(isCloudy ? 94 : 68);
      final Color cloudLitOuter = isSunset
          ? const Color(0x78FFBD70)
          : Color.lerp(Colors.white, const Color(0xFFFFF4DC), 0.22)!.withAlpha(isCloudy ? 74 : 62);
      final Color cloudLitCore = isSunset
          ? const Color(0xBAFFE6B0)
          : Color.lerp(Colors.white, const Color(0xFFFFF6E0), 0.18)!.withAlpha(isCloudy ? 112 : 110);
      final int cloudCount = isCloudy ? 11 : 9;
      for (int c = 0; c < cloudCount; c++) {
        final double cx = ((c * 196.0 + engine.horizonPan * 0.125) % (w + 400) + (w + 400)) % (w + 400) - 200;
        final double cy = horizonY * (0.13 + (c % 3) * 0.165);
        final double cwCloud = (isCloudy ? 225.0 : 185.0) + (c % 3) * 52.0;
        final double chCloud = (isCloudy ? 34.0 : 27.0) + (c % 2) * 11.0;
        final double sunBiasX = ((sunX - cx) / max(w, 1.0)).clamp(-1.0, 1.0).toDouble() * 8.0;
        _fillPaint.color = cloudShadowOuter;
        canvas.drawOval(Rect.fromCenter(center: Offset(cx - sunBiasX * 0.5, cy + chCloud * 0.26), width: cwCloud * 1.05, height: chCloud * 0.74), _fillPaint);
        _fillPaint.color = cloudShadowCore;
        canvas.drawOval(Rect.fromCenter(center: Offset(cx - sunBiasX * 0.5, cy + chCloud * 0.22), width: cwCloud * 0.72, height: chCloud * 0.48), _fillPaint);
        for (final double off in const [-0.28, -0.06, 0.14, 0.30]) {
          final double pwC = cwCloud * (off.abs() < 0.10 ? 0.58 : 0.42);
          final double phC = chCloud * (off.abs() < 0.10 ? 1.14 : 0.80);
          final Offset pc = Offset(cx + cwCloud * off + sunBiasX * 0.35, cy - (off.abs() < 0.10 ? 5.5 : 1.0));
          _fillPaint.color = cloudLitOuter;
          canvas.drawOval(Rect.fromCenter(center: pc, width: pwC, height: phC), _fillPaint);
          _fillPaint.color = cloudLitCore;
          canvas.drawOval(Rect.fromCenter(center: Offset(pc.dx + sunBiasX * 0.3, pc.dy - 1.8), width: pwC * 0.64, height: phC * 0.62), _fillPaint);
          // Sun-directed silver-lining upper crest rim highlight!
          _fillPaint.color = isSunset ? const Color(0x88FFF0C4) : const Color(0x74FFFFFF);
          canvas.drawOval(Rect.fromCenter(center: Offset(pc.dx + sunBiasX * 0.55, pc.dy - phC * 0.22), width: pwC * 0.42, height: phC * 0.26), _fillPaint);
        }
      }
    }

    // ICONIC SUZUKA MOUNT FUJI VOLCANIC CONE WITH SNOWCAP IN FAR HORIZON!
    if (circuit.code == 'JPN') {
      final double fujiX = ((w * 0.64 + engine.horizonPan * 0.11) % (w + 360) + (w + 360)) % (w + 360) - 180;
      final double fujiH = (horizonY * 0.44).clamp(48.0, 96.0).toDouble();
      final double fujiW = fujiH * 2.55;
      _drawPoly(
        canvas,
        [Offset(fujiX - fujiW * 0.55, horizonY + 2), Offset(fujiX - fujiW * 0.08, horizonY - fujiH), Offset(fujiX + fujiW * 0.08, horizonY - fujiH), Offset(fujiX + fujiW * 0.55, horizonY + 2)],
        Color.lerp(const Color(0xFF4B6488), circuit.skyBottom, 0.36)!,
      );
      // Shadow eastern volcanic slope
      _drawPoly(
        canvas,
        [Offset(fujiX + fujiW * 0.02, horizonY - fujiH), Offset(fujiX + fujiW * 0.08, horizonY - fujiH), Offset(fujiX + fujiW * 0.55, horizonY + 2), Offset(fujiX + fujiW * 0.08, horizonY + 2)],
        Color.lerp(const Color(0xFF2D4160), circuit.skyBottom, 0.42)!,
      );
      // Iconic jagged white snowcap cone
      _drawPoly(
        canvas,
        [
          Offset(fujiX - fujiW * 0.08, horizonY - fujiH),
          Offset(fujiX + fujiW * 0.08, horizonY - fujiH),
          Offset(fujiX + fujiW * 0.21, horizonY - fujiH * 0.66),
          Offset(fujiX + fujiW * 0.09, horizonY - fujiH * 0.72),
          Offset(fujiX - fujiW * 0.02, horizonY - fujiH * 0.62),
          Offset(fujiX - fujiW * 0.11, horizonY - fujiH * 0.72),
          Offset(fujiX - fujiW * 0.21, horizonY - fujiH * 0.66),
        ],
        Color.lerp(const Color(0xFFF4F8FF), circuit.skyBottom, 0.16)!,
      );
    }

    // Layer 1: High-Definition Far Atmospheric Mountain Range (pre-cached shader translated to horizonY!)
    _farRangePath
      ..reset()
      ..moveTo(0, 2);
    final double farAmp = circuit.propStyle == PropStyle.desert ? 0.55 : (isAlpine ? 1.24 : 1.0);
    for (double x = 0; x <= w + 20; x += 12) {
      final double wx = x - engine.horizonPan * 0.15;
      final double pk = (34.0 + sin(wx * 0.0068) * 30.0 + cos(wx * 0.017) * 14.0 + sin(wx * 0.031) * 5.5 + cos(wx * 0.062) * 2.5) * farAmp;
      _farRangePath.lineTo(x, -pk);
    }
    _farRangePath
      ..lineTo(w, 2)
      ..close();
    if (_farRangePaint != null) {
      canvas.save();
      canvas.translate(0, horizonY);
      canvas.drawPath(_farRangePath, _farRangePaint!);
      canvas.restore();
    }

    // 3D Faceted Mountain Ridges & Crisp Alpine Snowcaps (exact integer world index -> ZERO truncation jump!)
    if (!circuit.nightMode && circuit.propStyle != PropStyle.skyline && circuit.propStyle != PropStyle.desert) {
      final double panFar = engine.horizonPan * 0.15;
      final int firstRidgeIdx = (-panFar / 110.0).floor() - 1;
      final int lastRidgeIdx = ((w + 120.0 - panFar) / 110.0).ceil();
      final Color ridgeLit = Color.lerp(isSunset ? const Color(0x66FFCE8A) : const Color(0x52EAF4FF), circuit.skyBottom, 0.25)!;
      final Color ridgeShad = Color.lerp(const Color(0x46142238), circuit.skyBottom, 0.35)!;
      final Color snowCapCol = Color.lerp(const Color(0xCCF4F8FF), circuit.skyBottom, 0.22)!;
      for (int rIdx = firstRidgeIdx; rIdx <= lastRidgeIdx; rIdx++) {
        final double wx = rIdx * 110.0;
        final double rx = wx + panFar;
        final double pk = (34.0 + sin(wx * 0.0068) * 30.0 + cos(wx * 0.017) * 14.0 + sin(wx * 0.031) * 5.5) * farAmp;
        if (pk < 44.0) continue;
        final Offset peakPt = Offset(rx, horizonY - pk);
        _drawTri(canvas, peakPt, Offset(rx - 44.0, horizonY - pk * 0.28), Offset(rx - 4.0, horizonY - pk * 0.22), ridgeLit);
        _drawTri(canvas, peakPt, Offset(rx - 4.0, horizonY - pk * 0.22), Offset(rx + 46.0, horizonY - pk * 0.26), ridgeShad);
        if (isAlpine && pk > 58.0) {
          _drawQuad(
            canvas,
            peakPt,
            Offset(rx - 15.0, horizonY - pk * 0.72),
            Offset(rx + 2.0, horizonY - pk * 0.78),
            Offset(rx + 14.0, horizonY - pk * 0.70),
            snowCapCol,
          );
        }
      }
    }

    // Soft Aerial Perspective Valley Mist separating Far & Mid Mountain/Skyline Ranges (pre-cached shader!)
    if (_valleyMistPaint != null) {
      canvas.save();
      canvas.translate(0, horizonY);
      canvas.drawRect(Rect.fromLTWH(0, -54.0, w, 56.0), _valleyMistPaint!);
      canvas.restore();
    }

    // Layer 2: Crisp Mid-Distance Ridges / 3D Dual-Face Distant City Skyline (exact integer tower ID -> ZERO flicker!)
    if (circuit.propStyle == PropStyle.skyline) {
      final double panOff = engine.horizonPan * 0.28;
      final int firstTowerIdx = (-panOff / 26.0).floor() - 2;
      final int lastTowerIdx = ((w + 36.0 - panOff) / 26.0).ceil();
      final Color frontDay = Color.lerp(isSunset ? const Color(0xFF47374D) : const Color(0xFF334E73), circuit.skyBottom, 0.26)!;
      final Color sideDay = Color.lerp(isSunset ? const Color(0xFF281E30) : const Color(0xFF1A2B45), circuit.skyBottom, 0.34)!;
      final Color frontNight = const Color(0xFF15223E);
      final Color sideNight = const Color(0xFF0A1122);
      for (int idx = firstTowerIdx; idx <= lastTowerIdx; idx++) {
        final double tx = idx * 26.0 + panOff;
        final int tSeed = (idx * 73856093) & 0x7fffffff;
        final double tH = 26.0 + ((tSeed * 5) % 8) * 14.5;
        final double tW = 16.0 + (tSeed % 3) * 4.0;
        final double sideW = 6.5;
        final double topY = horizonY - tH;
        // Front facade + shaded 3D side wall + penthouse tier!
        _fillPaint.color = circuit.nightMode ? frontNight : frontDay;
        canvas.drawRect(Rect.fromLTWH(tx, topY, tW, tH + 2), _fillPaint);
        _fillPaint.color = circuit.nightMode ? sideNight : sideDay;
        canvas.drawRect(Rect.fromLTWH(tx + tW, topY + 3.0, sideW, tH), _fillPaint);
        if (tH > 62.0) {
          _fillPaint.color = circuit.nightMode ? const Color(0xFF1E2F52) : Color.lerp(frontDay, Colors.white, 0.12)!;
          canvas.drawRect(Rect.fromLTWH(tx + tW * 0.22, topY - 7.0, tW * 0.56, 7.5), _fillPaint);
          if (tSeed % 3 == 0) {
            _strokePaint..color = const Color(0x999EB4CC)..strokeWidth = 1.0;
            canvas.drawLine(Offset(tx + tW * 0.5, topY - 7.0), Offset(tx + tW * 0.5, topY - 21.0), _strokePaint);
            if (circuit.nightMode) {
              _fillPaint.color = const Color(0xEEFF1744);
              canvas.drawCircle(Offset(tx + tW * 0.5, topY - 21.5), 1.45, _fillPaint);
            }
          }
        }
        // Illuminated architectural glass bands
        if (tH >= 40.0) {
          final Color wCol = circuit.nightMode
              ? (tSeed % 4 == 0 ? const Color(0xCC40E5FF) : (tSeed % 4 == 2 ? const Color(0xBBFF4081) : const Color(0xCCFFE082)))
              : (isSunset ? const Color(0x88FFD599) : const Color(0x70DCEEFF));
          _fillPaint.color = wCol;
          for (double wy = topY + 5.5; wy < horizonY - 14.0; wy += 6.5) {
            canvas.drawRect(Rect.fromLTWH(tx + 2.5, wy, tW * 0.34, 2.0), _fillPaint);
            canvas.drawRect(Rect.fromLTWH(tx + tW * 0.52, wy, tW * 0.34, 2.0), _fillPaint);
          }
        }
      }
    } else {
      _midRangePath
        ..reset()
        ..moveTo(0, 2);
      for (double x = 0; x <= w + 20; x += 12) {
        final double wx = x - engine.horizonPan * 0.28;
        final double pk = circuit.propStyle == PropStyle.desert
            ? (14.0 + sin(wx * 0.009 + 0.8) * 11.0 + cos(wx * 0.021) * 4.5)
            : (23.0 + sin(wx * 0.012 + 1.1) * 20.0 + cos(wx * 0.028) * 9.5 + sin(wx * 0.055) * 3.5);
        _midRangePath.lineTo(x, -pk);
      }
      _midRangePath
        ..lineTo(w, 2)
        ..close();
      if (_midRangePaint != null) {
        canvas.save();
        canvas.translate(0, horizonY);
        canvas.drawPath(_midRangePath, _midRangePaint!);
        canvas.restore();
      }
    }

    // Layer 3: High-Definition Closer Forest / Urban Foothill Silhouette (sub-pixel smooth world-locked city roofs!)
    final Color nearBase = circuit.nightMode
        ? const Color(0xFF0A1120)
        : (circuit.propStyle == PropStyle.desert
            ? const Color(0xFF5A4832)
            : (circuit.propStyle == PropStyle.trees ? const Color(0xFF142E1B) : const Color(0xFF152736)));
    _fillPaint.color = Color.lerp(nearBase, circuit.skyBottom, 0.12)!;
    if (circuit.propStyle == PropStyle.skyline) {
      final double panNear = engine.horizonPan * 0.44;
      final int firstNear = (-panNear / 18.0).floor() - 1;
      final int lastNear = ((w + 22.0 - panNear) / 18.0).ceil();
      for (int idx = firstNear; idx <= lastNear; idx++) {
        final double bx = idx * 18.0 + panNear;
        final int nSeed = (idx * 19349663) & 0x7fffffff;
        final double bh = 14.0 + (nSeed % 5) * 11.0;
        canvas.drawRect(Rect.fromLTWH(bx, horizonY - bh, 18.6, bh + 2.0), _fillPaint);
      }
    } else {
      _nearRangePath
        ..reset()
        ..moveTo(0, horizonY + 2);
      for (double x = 0; x <= w + 18; x += 9) {
        final double wx = x - engine.horizonPan * 0.44;
        final double pk = circuit.propStyle == PropStyle.desert
            ? (7.5 + sin(wx * 0.015) * 4.5 + cos(wx * 0.036) * 2.2)
            : (12.0 + sin(wx * 0.028) * 8.5 + cos(wx * 0.064) * 5.2 + sin(wx * 0.13) * 2.6);
        _nearRangePath.lineTo(x, horizonY - pk);
      }
      _nearRangePath
        ..lineTo(w, horizonY + 2)
        ..close();
      canvas.drawPath(_nearRangePath, _fillPaint);
    }

    // Sunlit Golden Alpine Rim-Lights along Far & Mid Peaks on day/sunset circuits
    if (!circuit.nightMode && circuit.propStyle != PropStyle.skyline) {
      canvas.save();
      canvas.translate(0, horizonY);
      _strokePaint
        ..color = Color.lerp(isSunset ? const Color(0x88FFD08A) : const Color(0x66FFF2C8), circuit.skyBottom, 0.28)!
        ..strokeWidth = 1.6;
      canvas.drawPath(_farRangePath, _strokePaint);
      _strokePaint
        ..color = Color.lerp(isSunset ? const Color(0x55FFB86C) : const Color(0x44FFE9B0), circuit.skyBottom, 0.40)!
        ..strokeWidth = 1.2;
      canvas.drawPath(_midRangePath, _strokePaint);
      canvas.restore();
    }

    // Iconic Coastal Shimmering Sea & Harbor Bay on Seaside Circuits (pre-cached shader -> ZERO GPU alloc!)
    if (circuit.code == 'MON' ||
        circuit.code == 'MIA' ||
        circuit.code == 'SAU' ||
        circuit.code == 'ABU' ||
        circuit.code == 'AUS' ||
        circuit.code == 'NED' ||
        circuit.code == 'SIN' ||
        circuit.code == 'AZE') {
      if (_seaBandPaint != null) {
        canvas.save();
        canvas.translate(0, horizonY);
        canvas.drawRect(Rect.fromLTWH(0, -9.5, w, 12.0), _seaBandPaint!);
        canvas.restore();
      }
      // Crisp horizon sea waterline + shimmering directional sun/moon reflection column across ripples!
      _strokePaint
        ..color = circuit.nightMode ? const Color(0x5580D8FF) : (isSunset ? const Color(0x88FFD180) : const Color(0x66C4ECFF))
        ..strokeWidth = 1.0;
      canvas.drawLine(Offset(0, horizonY - 9.2), Offset(w, horizonY - 9.2), _strokePaint);
      _fillPaint.color = circuit.nightMode
          ? const Color(0x8890D8FF)
          : (isSunset ? const Color(0xCCFFD27D) : const Color(0xBBFFF6CC));
      for (int gl = 0; gl < 18; gl++) {
        final double gx = sunX + sin(gl * 1.9 + engine.totalRaceTime * 1.6) * (20.0 + gl * 5.2);
        final double gy = horizonY - 7.8 + (gl % 4) * 2.3;
        canvas.drawRect(Rect.fromLTWH(gx - 7.0, gy, 14.0 - (gl % 4) * 2.0, 1.35), _fillPaint);
      }
      // Iconic Luxury Harbor Superyachts moored on Monaco / Miami / Abu Dhabi / Jeddah waterfront!
      if (circuit.code == 'MON' || circuit.code == 'MIA' || circuit.code == 'ABU' || circuit.code == 'SAU') {
        for (int yt = 0; yt < 5; yt++) {
          final double yx = ((yt * 195.0 + 70.0 + engine.horizonPan * 0.32) % (w + 140) + (w + 140)) % (w + 140) - 70;
          final double yy = horizonY - 4.2;
          _fillPaint.color = circuit.nightMode ? const Color(0xCCCDD9E8) : const Color(0xEEFFFFFF);
          canvas.drawRect(Rect.fromLTWH(yx - 14.0, yy - 3.0, 28.0, 3.2), _fillPaint);
          canvas.drawRect(Rect.fromLTWH(yx - 9.0, yy - 6.2, 16.0, 3.2), _fillPaint);
          _fillPaint.color = const Color(0xCC112036);
          canvas.drawRect(Rect.fromLTWH(yx - 7.0, yy - 5.2, 12.0, 1.5), _fillPaint);
          // Yacht mast & warm evening deck lights
          _strokePaint..color = const Color(0xBBDCE8F8)..strokeWidth = 1.0;
          canvas.drawLine(Offset(yx - 1.0, yy - 6.2), Offset(yx - 1.0, yy - 13.5), _strokePaint);
          if (circuit.nightMode || circuit.timeLabel == 'Atardecer') {
            _fillPaint.color = const Color(0xEEFFE082);
            canvas.drawCircle(Offset(yx - 5.0, yy - 1.6), 1.0, _fillPaint);
            canvas.drawCircle(Offset(yx + 4.0, yy - 1.6), 1.0, _fillPaint);
          }
        }
      }
    }

    // Iconic Giant Illuminated Observation Ferris Wheel on Skyline / Night / Suzuka Circuits!
    if (circuit.code == 'SIN' ||
        circuit.code == 'JPN' ||
        circuit.code == 'LVG' ||
        circuit.code == 'ABU' ||
        circuit.code == 'SAU') {
      final double fx = ((w * 0.24 + engine.horizonPan * 0.26) % (w + 180) + (w + 180)) % (w + 180) - 90;
      final double fr = (horizonY * 0.26).clamp(24.0, 48.0).toDouble();
      final Offset fc = Offset(fx, horizonY - fr * 1.06);
      final Color wheelRimCol = circuit.nightMode ? const Color(0xCC00E5FF) : const Color(0x99CFD8E6);
      final Color wheelAccent = circuit.nightMode ? const Color(0xAAFF1744) : const Color(0x88E10600);
      // A-frame steel legs
      _strokePaint..color = const Color(0xAA253247)..strokeWidth = 2.4;
      canvas.drawLine(fc, Offset(fx - fr * 0.48, horizonY + 2), _strokePaint);
      canvas.drawLine(fc, Offset(fx + fr * 0.48, horizonY + 2), _strokePaint);
      // Slowly rotating spokes
      final double rot = engine.totalRaceTime * 0.16;
      _strokePaint..color = wheelRimCol.withAlpha(115)..strokeWidth = 1.0;
      for (int sp = 0; sp < 10; sp++) {
        final double a = rot + (sp * pi / 5.0);
        canvas.drawLine(fc, Offset(fc.dx + cos(a) * fr, fc.dy + sin(a) * fr), _strokePaint);
      }
      _strokePaint..color = wheelRimCol..strokeWidth = 2.2;
      canvas.drawCircle(fc, fr, _strokePaint);
      _strokePaint..color = wheelAccent..strokeWidth = 1.3;
      canvas.drawCircle(fc, fr * 0.72, _strokePaint);
      // Glowing gondola pods around rim
      _fillPaint.color = circuit.nightMode ? const Color(0xEEFFF59D) : const Color(0xBBFFFFFF);
      for (int pod = 0; pod < 12; pod++) {
        final double a = rot + (pod * pi / 6.0);
        canvas.drawCircle(Offset(fc.dx + cos(a) * fr, fc.dy + sin(a) * fr), 1.9, _fillPaint);
      }
    }

    // Distant Cruising Broadcast Airship / Blimp (pre-cached hull shader -> ZERO per-frame GPU alloc!)
    final double blimpX = _posMod(w * 0.80 + engine.horizonPan * 0.18 + engine.totalRaceTime * 4.5, w + 160) - 80;
    final double blimpY = horizonY * 0.24;
    if (_blimpHullPaint != null) {
      canvas.save();
      canvas.translate(blimpX, blimpY);
      canvas.drawOval(const Rect.fromLTWH(-17.0, -5.5, 34.0, 11.0), _blimpHullPaint!);
      canvas.restore();
    }
    _fillPaint.color = const Color(0xDDE10600);
    canvas.drawRect(Rect.fromCenter(center: Offset(blimpX, blimpY), width: 16.0, height: 2.6), _fillPaint);
    if ((engine.totalRaceTime * 2.5).floor() % 2 == 0) {
      _fillPaint.color = const Color(0xFFFF1744);
      canvas.drawCircle(Offset(blimpX, blimpY + 6.5), 1.6, _fillPaint);
    }

    // Live Cruising F1 TV Broadcast Helicopter tracking the race across the sky!
    final double heliX = ((w * 0.36 + engine.horizonPan * 0.24 - engine.totalRaceTime * 11.5) % (w + 220) + (w + 220)) % (w + 220) - 110;
    final double heliY = horizonY * 0.34 + sin(engine.totalRaceTime * 1.4) * 3.5;
    _fillPaint.color = circuit.nightMode ? const Color(0xCC243248) : const Color(0xDD1A2230);
    canvas.drawOval(Rect.fromCenter(center: Offset(heliX, heliY), width: 13.5, height: 5.5), _fillPaint);
    // Tail boom + rotor disc glint + red/green aviation strobes
    _strokePaint..color = const Color(0xDDE10600)..strokeWidth = 1.6;
    canvas.drawLine(Offset(heliX + 5.5, heliY), Offset(heliX + 16.0, heliY - 1.5), _strokePaint);
    final double rotorW = 11.0 + 9.0 * sin(engine.totalRaceTime * 36.0).abs();
    _strokePaint..color = const Color(0xAAECF4FF)..strokeWidth = 1.1;
    canvas.drawLine(Offset(heliX - rotorW, heliY - 4.2), Offset(heliX + rotorW, heliY - 4.2), _strokePaint);
    if ((engine.totalRaceTime * 3.8).floor() % 2 == 0) {
      _fillPaint.color = const Color(0xFFFF1744);
      canvas.drawCircle(Offset(heliX + 16.0, heliY - 2.0), 1.4, _fillPaint);
    }

    // Night distant city window glints, neon horizon accents & red rooftop aviation beacons along skyline
    if (circuit.nightMode && circuit.propStyle == PropStyle.skyline) {
      for (int b = 0; b < 42; b++) {
        final double bx = ((b * 38.0 + engine.horizonPan * 0.28) % (w + 60) + (w + 60)) % (w + 60) - 30;
        final double by = horizonY - 10.0 - (b % 6) * 12.5;
        final Color winC = (b % 4 == 0)
            ? const Color(0xBB40E5FF)
            : (b % 4 == 2 ? const Color(0xBBFF4081) : const Color(0xBBFFE082));
        _fillPaint.color = winC;
        canvas.drawRect(Rect.fromLTWH(bx, by, 3.4, 2.0), _fillPaint);
        canvas.drawRect(Rect.fromLTWH(bx + 6.0, by + 5.0, 3.0, 2.0), _fillPaint);
        if (b % 6 == 0) {
          _fillPaint.color = const Color(0xEEFF1744);
          canvas.drawCircle(Offset(bx + 3.0, by - 8.0), 1.6, _fillPaint);
        }
      }
    }
  }

  void _drawStartGantry3D(
    Canvas canvas,
    double s1,
    double s2,
    double y1,
    double y2,
    double z1,
    double z2,
    double roadHalfW,
    double w,
    double horizonY,
    double fovMult,
    double fogMix,
    CircuitInfo circuit,
  ) {
    final Offset sh1L = _project(-roadHalfW + s1, y1 + 0.015, z1, w, horizonY, fovMult);
    final Offset sh1R = _project(roadHalfW + s1, y1 + 0.015, z1, w, horizonY, fovMult);
    final Offset sh2L = _project(-roadHalfW + s2, y2 + 0.015, z2, w, horizonY, fovMult);
    final Offset sh2R = _project(roadHalfW + s2, y2 + 0.015, z2, w, horizonY, fovMult);
    _drawQuad(canvas, sh1L, sh1R, sh2R, sh2L, Color.fromARGB((115 * (1.0 - fogMix)).toInt(), 0, 0, 0));

    final Offset bL = _project(-roadHalfW - 1.05 + s1, y1, z1, w, horizonY, fovMult);
    final Offset bR = _project(roadHalfW + 1.05 + s1, y1, z1, w, horizonY, fovMult);
    final Offset tL = _project(-roadHalfW - 1.05 + s1, y1 + 4.15, z1, w, horizonY, fovMult);
    final Offset tR = _project(roadHalfW + 1.05 + s1, y1 + 4.15, z1, w, horizonY, fovMult);
    final Offset tLBack = _project(-roadHalfW - 1.05 + s2, y2 + 4.15, z2, w, horizonY, fovMult);
    final Offset tRBack = _project(roadHalfW + 1.05 + s2, y2 + 4.15, z2, w, horizonY, fovMult);
    final double beamH = max(7.0, 74.0 / z1);

    // True 3D Extruded Steel Truss Support Towers with X-Bracing!
    final Offset bLBack = _project(-roadHalfW - 1.05 + s2, y2, z2, w, horizonY, fovMult);
    final Offset bRBack = _project(roadHalfW + 1.05 + s2, y2, z2, w, horizonY, fovMult);
    _drawQuad(canvas, bL, tL, tLBack, bLBack, Color.lerp(const Color(0xFF151C28), circuit.skyBottom, fogMix)!);
    _drawQuad(canvas, bR, bRBack, tRBack, tR, Color.lerp(const Color(0xFF151C28), circuit.skyBottom, fogMix)!);
    _strokePaint
      ..color = Color.lerp(const Color(0xFF3A485E), circuit.skyBottom, fogMix)!
      ..strokeWidth = max(3.5, 34.0 / z1);
    canvas.drawLine(bL, tL, _strokePaint);
    canvas.drawLine(bR, tR, _strokePaint);
    if (beamH > 12.0) {
      _strokePaint
        ..color = Color.lerp(const Color(0xBB7A8FA8), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(1.0, 5.5 / z1);
      for (int st = 0; st < 4; st++) {
        final double f0 = st / 4.0;
        final double f1 = (st + 1) / 4.0;
        canvas.drawLine(Offset.lerp(bL, tL, f0)!, Offset.lerp(bLBack, tLBack, f1)!, _strokePaint);
        canvas.drawLine(Offset.lerp(bR, tR, f0)!, Offset.lerp(bRBack, tRBack, f1)!, _strokePaint);
      }
    }

    _drawQuad(
      canvas,
      Offset(tL.dx, tL.dy + beamH * 0.5),
      Offset(tR.dx, tR.dy + beamH * 0.5),
      Offset(tRBack.dx, tRBack.dy + beamH * 0.42),
      Offset(tLBack.dx, tLBack.dy + beamH * 0.42),
      Color.lerp(const Color(0xFF0A0D14), circuit.skyBottom, fogMix)!,
    );

    final Rect bridge = Rect.fromLTRB(tL.dx, tL.dy - beamH * 0.5, tR.dx, tR.dy + beamH * 0.5);
    _fillPaint.color = Color.lerp(const Color(0xFF101624), circuit.skyBottom, fogMix)!;
    canvas.drawRect(bridge, _fillPaint);
    _fillPaint.color = Color.lerp(const Color(0xFFE10600), circuit.skyBottom, fogMix)!;
    canvas.drawRect(Rect.fromLTRB(tL.dx, tL.dy - beamH * 0.5, tR.dx, tL.dy - beamH * 0.22), _fillPaint);
    // Overhead aluminum truss rail + broadcast camera housing on top of Start Gantry!
    _strokePaint
      ..color = Color.lerp(const Color(0xCCF0F6FF), circuit.skyBottom, fogMix)!
      ..strokeWidth = max(1.0, 4.0 / z1);
    canvas.drawLine(Offset(bridge.left, bridge.top), Offset(bridge.right, bridge.top), _strokePaint);
    if (beamH > 13.0) {
      final TextPainter tp = _getCachedBoardText(
        'START  •  FIA ${circuit.code}  •  FINISH',
        (beamH * 0.30).clamp(7.0, 18.0).toDouble(),
        Color.lerp(Colors.white, circuit.skyBottom, fogMix)!,
      );
      tp.paint(canvas, Offset(bridge.center.dx - tp.width * 0.5, bridge.center.dy + beamH * 0.08 - tp.height * 0.5));

      // 5 Authentic Dual-Lamp Hooded FIA F1 Start Light Pods hanging beneath Gantry!
      final double podW = max(4.2, (bridge.width * 0.044));
      final double podH = beamH * 0.86;
      final double totalCountdown = engine.phase == SessionPhase.qualifying ? 2.2 : 3.2;
      for (int idx = 0; idx < 5; idx++) {
        final double px = bridge.center.dx + (idx - 2) * (podW * 1.92);
        final Rect pod = Rect.fromCenter(center: Offset(px, bridge.bottom + podH * 0.46), width: podW, height: podH);
        _fillPaint.color = const Color(0xFF0A0D14);
        canvas.drawRRect(RRect.fromRectAndRadius(pod, const Radius.circular(2.5)), _fillPaint);
        _strokePaint..color = const Color(0x667D90A8)..strokeWidth = 0.9;
        canvas.drawRRect(RRect.fromRectAndRadius(pod, const Radius.circular(2.5)), _strokePaint);
        final bool lit = engine.startLightsTimer > 0 &&
            engine.startLightsTimer < (totalCountdown - 0.15 - idx * (totalCountdown * 0.15));
        final bool greenGo = engine.startLightsTimer <= 0 &&
            ((engine.phase == SessionPhase.qualifying ? engine.qualiElapsed : engine.totalRaceTime) < 2.2);
        for (final double vFrac in const [0.34, 0.72]) {
          final Offset lampC = Offset(px, pod.top + pod.height * vFrac);
          if (lit || greenGo) {
            final double lr = podW * 1.15;
            _fillPaint.color = greenGo ? const Color(0x4800E676) : const Color(0x48FF1744);
            canvas.drawCircle(lampC, lr, _fillPaint);
            _fillPaint.color = greenGo ? const Color(0xAA00E676) : const Color(0xAAFF3D57);
            canvas.drawCircle(lampC, lr * 0.56, _fillPaint);
          }
          _fillPaint.color = greenGo
              ? const Color(0xFF00E676)
              : (lit ? const Color(0xFFFF425E) : const Color(0xFF2B1216));
          canvas.drawCircle(lampC, podW * 0.28, _fillPaint);
          if (lit || greenGo) {
            _fillPaint.color = greenGo ? const Color(0xF5E0FFF0) : const Color(0xF5FFE2E6);
            canvas.drawCircle(lampC, podW * 0.12, _fillPaint);
          }
        }
      }
    }
  }

  void _drawTracksideProp3D(
    Canvas canvas,
    double x,
    double y1,
    double z,
    double w,
    double horizonY,
    double fovMult,
    double fogMix,
    CircuitInfo circuit,
    bool isLeft,
    int seed,
  ) {
    final Offset base = _project(x, y1, z, w, horizonY, fovMult);
    // GTA 3 Frustum Culling: skip trackside props completely off-screen!
    if (base.dx < -150.0 || base.dx > w + 150.0) return;
    final double heightScale = 4.6 + ((seed.abs() % 3) * 0.85);
    final Offset top = _project(x, y1 + heightScale, z, w, horizonY, fovMult);
    final double ph = max(8.0, base.dy - top.dy);
    final double pw = max(6.0, ph * 0.54);
    if (base.dx + pw * 2.2 < 0.0 || base.dx - pw * 2.2 > w) return;

    if (pw > 9.0) {
      _fillPaint.color = Color.fromARGB((82 * (1.0 - fogMix)).toInt(), 0, 0, 0);
      canvas.drawOval(Rect.fromCenter(center: base, width: pw * 1.65, height: max(2.5, pw * 0.30)), _fillPaint);
    }

    // Night circuits: tall Stadium Floodlight Towers with volumetric downward light cones!
    if (circuit.nightMode && (seed.abs() % 2 == 0)) {
      final double armDir = isLeft ? 1.0 : -1.0;
      final Offset towerTop = _project(x, y1 + 7.2, z, w, horizonY, fovMult);
      final Offset head = Offset(towerTop.dx + armDir * pw * 0.58, towerTop.dy - ph * 0.08);

      // Soft 2-Tier Volumetric Light Cone onto the track (zero per-tower GPU shader build!)
      if (pw > 10.0) {
        final Offset coneL = _project(x + armDir * 4.2, y1, z, w, horizonY, fovMult);
        final Offset coneR = _project(x + armDir * 0.4, y1, z, w, horizonY, fovMult);
        final Offset hL = Offset(head.dx - pw * 0.16, head.dy);
        final Offset hR = Offset(head.dx + pw * 0.16, head.dy);
        final Offset midL = Offset.lerp(hL, coneL, 0.52)!;
        final Offset midR = Offset.lerp(hR, coneR, 0.52)!;
        _drawQuad(canvas, hL, hR, midR, midL, Color.fromARGB((34 * (1.0 - fogMix)).toInt(), 210, 238, 255));
        _drawQuad(canvas, midL, midR, coneR, coneL, Color.fromARGB((14 * (1.0 - fogMix)).toInt(), 185, 226, 255));
      }

      _strokePaint
        ..color = Color.lerp(const Color(0xFF7D90A6), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(2.0, pw * 0.14);
      canvas.drawLine(base, towerTop, _strokePaint);
      canvas.drawLine(towerTop, head, _strokePaint);
      _fillPaint.color = Color.lerp(const Color(0xFFE6F0FA), circuit.skyBottom, fogMix)!;
      canvas.drawRect(Rect.fromCenter(center: head, width: max(5.5, pw * 0.54), height: max(3.0, pw * 0.22)), _fillPaint);

      // Photorealistic Smooth RadialGradient Bloom Halo + Anamorphic Streak (pre-cached GPU shaders -> ZERO alloc!)
      final double glowR = max(12.0, pw * 1.45);
      if (_floodBloomPaint != null) {
        canvas.save();
        canvas.translate(head.dx, head.dy);
        final double sc = glowR / 64.0;
        canvas.scale(sc, sc);
        canvas.drawCircle(Offset.zero, 64.0, _floodBloomPaint!);
        if (pw > 10.0 && _floodStreakPaint != null) {
          canvas.drawRect(Rect.fromCenter(center: Offset.zero, width: 179.2, height: 9.0), _floodStreakPaint!);
        }
        canvas.restore();
      }
      return;
    }

    // Occasional World-Anchored 3D FIA Trackside TV Broadcast Crane Camera (seed-locked -> NEVER morphs from a building!)
    if (seed.abs() % 7 == 3) {
      if (pw <= 7.0) return;
      final double armDir = isLeft ? 1.0 : -1.0;
      final Offset craneTop = _project(x, y1 + 5.8, z, w, horizonY, fovMult);
      final Offset camHead = Offset(craneTop.dx + armDir * pw * 0.95, craneTop.dy - ph * 0.05);
      _strokePaint
        ..color = Color.lerp(const Color(0xFF2B3548), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(2.0, pw * 0.14);
      canvas.drawLine(base, craneTop, _strokePaint);
      _strokePaint
        ..color = Color.lerp(const Color(0xFF536682), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(1.6, pw * 0.10);
      canvas.drawLine(craneTop, camHead, _strokePaint);
      // Broadcast TV camera box + glowing red "ON AIR" tally LED
      _fillPaint.color = Color.lerp(const Color(0xFF141922), circuit.skyBottom, fogMix)!;
      canvas.drawRRect(
        RRect.fromRectAndRadius(Rect.fromCenter(center: camHead, width: max(5.0, pw * 0.42), height: max(3.5, pw * 0.26)), const Radius.circular(2)),
        _fillPaint,
      );
      _fillPaint.color = const Color(0xFFFF1744);
      canvas.drawCircle(Offset(camHead.dx + armDir * pw * 0.14, camHead.dy - pw * 0.06), max(1.3, pw * 0.06), _fillPaint);
      return;
    } else if (seed.abs() % 9 == 4) {
      if (pw <= 7.0) return;
      // Towering 3D Trackside Giant F1 Broadcast Jumbotron Video Screen (seed-locked & zero shader alloc!)
      final Offset poleTop = _project(x, y1 + 3.6, z, w, horizonY, fovMult);
      final double scrW = max(14.0, pw * 2.15);
      final double scrH = scrW * 0.56;
      final Rect scrFrame = Rect.fromCenter(center: Offset(poleTop.dx, poleTop.dy - scrH * 0.42), width: scrW, height: scrH);
      _strokePaint..color = Color.lerp(const Color(0xFF1F2838), circuit.skyBottom, fogMix)!..strokeWidth = max(2.4, pw * 0.16);
      canvas.drawLine(base, poleTop, _strokePaint);
      _fillPaint.color = Color.lerp(const Color(0xFF0A0D14), circuit.skyBottom, fogMix * 0.6)!;
      canvas.drawRRect(RRect.fromRectAndRadius(scrFrame.inflate(2.2), const Radius.circular(3)), _fillPaint);
      _fillPaint.color = Color.lerp(circuit.skyBottom, Colors.white, 0.10)!;
      canvas.drawRect(Rect.fromLTWH(scrFrame.left, scrFrame.top, scrW, scrH * 0.52), _fillPaint);
      _fillPaint.color = const Color(0xFF1D2330);
      canvas.drawRect(Rect.fromLTWH(scrFrame.left, scrFrame.top + scrH * 0.52, scrW, scrH * 0.48), _fillPaint);
      // Red F1 broadcast telemetry lower-third ticker bar + live green status dot
      _fillPaint.color = Color.lerp(const Color(0xFFE10600), circuit.skyBottom, fogMix * 0.5)!;
      canvas.drawRect(Rect.fromLTWH(scrFrame.left, scrFrame.bottom - scrH * 0.22, scrW, scrH * 0.22), _fillPaint);
      _fillPaint.color = const Color(0xEEFFFFFF);
      canvas.drawRect(Rect.fromLTWH(scrFrame.left + scrW * 0.08, scrFrame.bottom - scrH * 0.14, scrW * 0.48, max(1.2, scrH * 0.06)), _fillPaint);
      _fillPaint.color = const Color(0xFF00E676);
      canvas.drawCircle(Offset(scrFrame.right - scrW * 0.10, scrFrame.top + scrH * 0.16), max(1.4, scrH * 0.07), _fillPaint);
      return;
    } else if (seed.abs() % 7 == 5) {
      if (pw <= 7.0) return;
      // Animated Trackside FIA Marshal Booth with Waving Green Flag!
      final Offset postTop = _project(x, y1 + 3.2, z, w, horizonY, fovMult);
      final double wave = sin(engine.totalRaceTime * 7.5 + seed) * pw * 0.16;
      _strokePaint
        ..color = Color.lerp(const Color(0xFFD0DCEB), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(1.5, pw * 0.09);
      canvas.drawLine(base, postTop, _strokePaint);
      final double fDir = isLeft ? 1.0 : -1.0;
      _drawQuad(
        canvas,
        postTop,
        Offset(postTop.dx + fDir * pw * 0.62, postTop.dy + wave),
        Offset(postTop.dx + fDir * pw * 0.58, postTop.dy + pw * 0.38 + wave),
        Offset(postTop.dx, postTop.dy + pw * 0.36),
        Color.lerp(const Color(0xFF00E676), circuit.skyBottom, fogMix * 0.5)!,
      );
      return;
    }

    if (circuit.propStyle == PropStyle.palms) {
      final double bend = isLeft ? -pw * 0.24 : pw * 0.24;
      _scratchPath
        ..reset()
        ..moveTo(base.dx, base.dy)
        ..quadraticBezierTo(base.dx + bend * 0.5, (base.dy + top.dy) * 0.5, top.dx + bend, top.dy);
      _strokePaint
        ..color = Color.lerp(const Color(0xFF6B483A), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(2.4, pw * 0.19)
        ..strokeCap = StrokeCap.round;
      canvas.drawPath(_scratchPath, _strokePaint);

      // Crisp sunlit bark edge & palm trunk segment rings
      if (pw > 12.0) {
        _strokePaint
          ..color = Color.lerp(const Color(0x88A67C64), circuit.skyBottom, fogMix)!
          ..strokeWidth = max(1.0, pw * 0.06);
        for (int rg = 1; rg <= 5; rg++) {
          final double f = rg / 6.0;
          final double rx = base.dx + bend * f * f;
          final double ry = base.dy + (top.dy - base.dy) * f;
          canvas.drawLine(Offset(rx - pw * 0.09, ry), Offset(rx + pw * 0.09, ry), _strokePaint);
        }
      }

      final Offset crown = Offset(top.dx + bend, top.dy);
      final double sway = sin(engine.totalRaceTime * 2.2 + seed) * (pw * 0.06);
      // Realistic coconut cluster tucked right under the palm crown!
      if (pw > 11.0) {
        _fillPaint.color = Color.lerp(const Color(0xFF4A2E1B), circuit.skyBottom, fogMix)!;
        canvas.drawCircle(Offset(crown.dx - pw * 0.10, crown.dy + pw * 0.10), max(1.8, pw * 0.10), _fillPaint);
        canvas.drawCircle(Offset(crown.dx + pw * 0.10, crown.dy + pw * 0.12), max(1.8, pw * 0.10), _fillPaint);
        canvas.drawCircle(Offset(crown.dx, crown.dy + pw * 0.17), max(1.8, pw * 0.095), _fillPaint);
      }
      // 11 Multi-Tone Tropical Palm Fronds with drooping feathered leaflets & gentle breeze sway!
      final Color frondDark = Color.lerp(circuit.nightMode ? const Color(0xFF123821) : const Color(0xFF185524), circuit.skyBottom, fogMix)!;
      final Color frondMid = Color.lerp(circuit.nightMode ? const Color(0xFF1F5D37) : const Color(0xFF2F8436), circuit.skyBottom, fogMix)!;
      final Color frondSun = Color.lerp(circuit.nightMode ? const Color(0xFF2F7D4E) : const Color(0xFF60B954), circuit.skyBottom, fogMix)!;
      for (int a = 0; a < 11; a++) {
        final double ang = -pi * 1.06 + (a * pi * 1.12 / 10.0);
        final Offset tip = Offset(crown.dx + cos(ang) * pw * 1.24 + sway, crown.dy + sin(ang) * pw * 0.48 + pw * 0.24);
        final Offset mid = Offset((crown.dx + tip.dx) * 0.5, crown.dy - pw * 0.28 + sin(ang) * pw * 0.10);
        final Color fCol = (a % 3 == 0) ? frondSun : ((a % 2 == 0) ? frondMid : frondDark);
        _strokePaint
          ..color = fCol
          ..strokeWidth = max(2.2, pw * 0.135)
          ..strokeCap = StrokeCap.round;
        _scratchPath
          ..reset()
          ..moveTo(crown.dx, crown.dy)
          ..quadraticBezierTo(mid.dx, mid.dy, tip.dx, tip.dy);
        canvas.drawPath(_scratchPath, _strokePaint);
        // Hanging feathered palm leaflet blades along foreground fronds!
        if (pw > 15.0 && a % 2 == 0) {
          _strokePaint..strokeWidth = max(1.0, pw * 0.048);
          for (final double tL in const [0.38, 0.62, 0.82]) {
            final Offset pt = Offset(
              (1 - tL) * (1 - tL) * crown.dx + 2 * (1 - tL) * tL * mid.dx + tL * tL * tip.dx,
              (1 - tL) * (1 - tL) * crown.dy + 2 * (1 - tL) * tL * mid.dy + tL * tL * tip.dy,
            );
            canvas.drawLine(pt, Offset(pt.dx + cos(ang) * pw * 0.12, pt.dy + pw * 0.22), _strokePaint);
          }
        }
      }
    } else if (circuit.propStyle == PropStyle.skyline) {
      final double bTop = top.dy - ph * (0.55 + (seed.abs() % 3) * 0.22);
      final double bH = base.dy - bTop;
      final double frontW = pw * 1.32;
      final double sideW = pw * 0.58;
      final double leftEdge = top.dx - frontW * 0.5;
      final Rect frontRect = Rect.fromLTWH(leftEdge, bTop, frontW, bH);
      // Warm Belle-Époque sandstone in Monaco/Baku vs modern glass towers in Singapore/Vegas/Miami/Shanghai!
      final bool historicFacade = (circuit.code == 'MON' || circuit.code == 'AZE') && (seed.abs() % 2 == 0);
      final Color baseFront = historicFacade
          ? const Color(0xFFD6BE9A)
          : (circuit.nightMode ? const Color(0xFF1A2540) : const Color(0xFF475773));
      final Color baseSide = historicFacade
          ? const Color(0xFF9C8464)
          : (circuit.nightMode ? const Color(0xFF0E1526) : const Color(0xFF263348));
      final Color frontCol = Color.lerp(baseFront, circuit.skyBottom, fogMix)!;
      final Color sideCol = Color.lerp(baseSide, circuit.skyBottom, fogMix)!;

      _fillPaint.color = frontCol;
      canvas.drawRect(frontRect, _fillPaint);
      final double sx = isLeft ? frontRect.right : frontRect.left;
      final double sxOut = isLeft ? (frontRect.right + sideW) : (frontRect.left - sideW);
      _drawQuad(
        canvas,
        Offset(sx, bTop),
        Offset(sxOut, bTop + ph * 0.10),
        Offset(sxOut, base.dy - ph * 0.04),
        Offset(sx, base.dy),
        sideCol,
      );

      // Zero-shader architectural facade lighting (sunlit upper highlight + grounded base AO -> silky smooth in Monaco/Vegas!)
      _fillPaint.color = Color.fromARGB((34 * (1.0 - fogMix)).toInt(), 255, 255, 255);
      canvas.drawRect(Rect.fromLTWH(frontRect.left, bTop, frontW * 0.42, bH * 0.55), _fillPaint);
      _fillPaint.color = Color.fromARGB((46 * (1.0 - fogMix)).toInt(), 0, 0, 0);
      canvas.drawRect(Rect.fromLTWH(frontRect.left, base.dy - bH * 0.30, frontW, bH * 0.30), _fillPaint);
      _strokePaint
        ..color = Color.lerp(const Color(0xBBFFFFFF), circuit.skyBottom, fogMix * 0.72)!
        ..strokeWidth = max(1.0, pw * 0.045);
      canvas.drawLine(Offset(frontRect.left, bTop), Offset(frontRect.right, bTop), _strokePaint);
      canvas.drawLine(Offset(sx, bTop), Offset(sx, base.dy), _strokePaint);

      if (pw > 6.5) {
        // Illuminated street-level lobby / retail storefront at ground floor!
        _fillPaint.color = Color.lerp(
          circuit.nightMode ? const Color(0xDDFFE49E) : const Color(0x99263242),
          circuit.skyBottom,
          fogMix * 0.6,
        )!;
        canvas.drawRect(Rect.fromLTWH(frontRect.left + frontW * 0.06, base.dy - bH * 0.11, frontW * 0.88, bH * 0.09), _fillPaint);

        // High-definition 3-column x 7-floor architectural window grid + balcony cornice ledges!
        for (int r = 0; r < 7; r++) {
          final Color winCol = circuit.nightMode
              ? ((r + seed) % 3 == 0 ? const Color(0xDC48E8FF) : const Color(0xDCFFE48A))
              : (historicFacade ? const Color(0xBB2C3F59) : const Color(0xB4E2F2FF));
          _fillPaint.color = Color.lerp(winCol, circuit.skyBottom, fogMix * 0.62)!;
          final double wy = bTop + bH * (0.06 + r * 0.118);
          final double wh = max(1.6, bH * 0.058);
          canvas.drawRect(Rect.fromLTWH(frontRect.left + frontW * 0.08, wy, frontW * 0.24, wh), _fillPaint);
          canvas.drawRect(Rect.fromLTWH(frontRect.left + frontW * 0.38, wy, frontW * 0.24, wh), _fillPaint);
          canvas.drawRect(Rect.fromLTWH(frontRect.left + frontW * 0.68, wy, frontW * 0.24, wh), _fillPaint);
          if (pw > 16.0) {
            // Subtle architectural balcony/slab ledge under every floor
            _strokePaint
              ..color = Color.lerp(const Color(0x66121824), circuit.skyBottom, fogMix)!
              ..strokeWidth = 1.0;
            canvas.drawLine(Offset(frontRect.left + 1, wy + wh + 1.0), Offset(frontRect.right - 1, wy + wh + 1.0), _strokePaint);
          }
        }
        // Neon LED city billboard strip on night street circuits (Las Vegas, Singapore, Jeddah!)
        if (circuit.nightMode && (seed.abs() % 3 == 1)) {
          final Color neonCol = (seed.abs() % 2 == 0) ? const Color(0xEE00E5FF) : const Color(0xEEFF2A85);
          _fillPaint.color = Color.lerp(neonCol, circuit.skyBottom, fogMix * 0.45)!;
          canvas.drawRect(Rect.fromLTWH(frontRect.left + frontW * 0.10, bTop + bH * 0.12, frontW * 0.80, max(2.2, bH * 0.05)), _fillPaint);
        }
        // Rooftop penthouse mechanical crown + AC units + steel spire & red aviation beacon
        _fillPaint.color = Color.lerp(historicFacade ? const Color(0xFF7D4B3A) : const Color(0xFF28344B), circuit.skyBottom, fogMix)!;
        canvas.drawRect(Rect.fromLTWH(frontRect.left + frontW * 0.22, bTop - ph * 0.075, frontW * 0.56, ph * 0.075), _fillPaint);
        _strokePaint
          ..color = Color.lerp(const Color(0xFFA8B9CE), circuit.skyBottom, fogMix)!
          ..strokeWidth = max(1.0, pw * 0.045);
        canvas.drawLine(Offset(frontRect.center.dx, bTop - ph * 0.075), Offset(frontRect.center.dx, bTop - ph * 0.22), _strokePaint);
        if (circuit.nightMode) {
          _fillPaint.color = const Color(0x55FF1744);
          canvas.drawCircle(Offset(frontRect.center.dx, bTop - ph * 0.23), max(2.8, pw * 0.12), _fillPaint);
          _fillPaint.color = const Color(0xF5FF526A);
          canvas.drawCircle(Offset(frontRect.center.dx, bTop - ph * 0.23), max(1.4, pw * 0.055), _fillPaint);
        }
      }
    } else if (circuit.propStyle == PropStyle.trees) {
      // REALISTIC MULTI-SPECIES 3D FOLIAGE (Alternates Alpine Conifer/Pine & Sculpted Broadleaf Oak!)
      final bool isConifer = (seed.abs() % 3 == 0);
      if (isConifer) {
        // Tapered Alpine Spruce / Pine Tree (Spa, Austria, Suzuka, Imola, Montreal!)
        _strokePaint
          ..color = Color.lerp(const Color(0xFF3F281E), circuit.skyBottom, fogMix)!
          ..strokeWidth = max(2.0, pw * 0.18)
          ..strokeCap = StrokeCap.round;
        canvas.drawLine(base, Offset(top.dx, base.dy - ph * 0.30), _strokePaint);
        final Color pineDark = Color.lerp(const Color(0xFF0B2A14), circuit.skyBottom, fogMix)!;
        final Color pineMid = Color.lerp(const Color(0xFF194E24), circuit.skyBottom, fogMix)!;
        final Color pineSun = Color.lerp(const Color(0xFF397D38), circuit.skyBottom, fogMix)!;
        for (int tier = 0; tier < 4; tier++) {
          final double fBot = 0.22 + tier * 0.19;
          final double fTop = fBot + 0.30;
          final double hw = pw * (0.76 - tier * 0.15);
          final double yBot = base.dy - ph * fBot;
          final double yTop = base.dy - ph * min(1.06, fTop);
          // Shadow right/base half + sunlit left crown half for genuine 3D conifer volume (zero list alloc!)
          _drawTri(canvas, Offset(top.dx, yTop), Offset(top.dx + hw, yBot), Offset(top.dx - hw * 0.15, yBot + ph * 0.04), pineDark);
          _drawTri(canvas, Offset(top.dx, yTop), Offset(top.dx - hw, yBot), Offset(top.dx + hw * 0.18, yBot + ph * 0.04), pineMid);
          if (pw > 13.0) {
            _drawTri(canvas, Offset(top.dx, yTop), Offset(top.dx - hw * 0.72, yBot - ph * 0.04), Offset(top.dx - hw * 0.06, yBot - ph * 0.02), pineSun);
          }
        }
      } else {
        // Organic Broadleaf Oak / European Woodland Tree (Tapered Trunk + Y-Branches + Irregular Sunlit Leaf Clusters!)
        final double trunkTopY = base.dy - ph * 0.48;
        final double baseHw = max(1.6, pw * 0.14);
        final double topHw = max(1.0, pw * 0.08);
        _drawQuad(
          canvas,
          Offset(base.dx - baseHw, base.dy),
          Offset(base.dx + baseHw, base.dy),
          Offset(top.dx + topHw, trunkTopY),
          Offset(top.dx - topHw, trunkTopY),
          Color.lerp(const Color(0xFF3E271E), circuit.skyBottom, fogMix)!,
        );
        // Sunlit bark rim + visible Y-fork limbs reaching into the canopy!
        if (pw > 12.0) {
          _strokePaint
            ..color = Color.lerp(const Color(0xFF7B5744), circuit.skyBottom, fogMix)!
            ..strokeWidth = max(1.0, pw * 0.055);
          canvas.drawLine(Offset(base.dx - baseHw * 0.55, base.dy - 1), Offset(top.dx - topHw * 0.45, trunkTopY), _strokePaint);
          _strokePaint
            ..color = Color.lerp(const Color(0xFF3E271E), circuit.skyBottom, fogMix)!
            ..strokeWidth = max(1.4, pw * 0.09);
          canvas.drawLine(Offset(top.dx, trunkTopY + ph * 0.06), Offset(top.dx - pw * 0.34, base.dy - ph * 0.64), _strokePaint);
          canvas.drawLine(Offset(top.dx, trunkTopY + ph * 0.04), Offset(top.dx + pw * 0.32, base.dy - ph * 0.62), _strokePaint);
        }
        // Multi-cluster organic foliage volume (deep cool underside -> rich woodland body -> dappled sunlit leaves!)
        final Color deepLeaf = Color.lerp(const Color(0xFF0A2411), circuit.skyBottom, fogMix)!;
        final Color midLeaf = Color.lerp(const Color(0xFF184B20), circuit.skyBottom, fogMix)!;
        final Color brightLeaf = Color.lerp(const Color(0xFF2B7532), circuit.skyBottom, fogMix)!;
        final Color sunLeaf = Color.lerp(const Color(0xFF56AD4B), circuit.skyBottom, fogMix)!;
        final Color glintLeaf = Color.lerp(const Color(0xFF8BE070), circuit.skyBottom, fogMix)!;
        final double skew = ((seed % 3) - 1) * pw * 0.08;
        _fillPaint.color = deepLeaf;
        canvas.drawOval(Rect.fromCenter(center: Offset(top.dx + pw * 0.22 + skew, base.dy - ph * 0.56), width: pw * 1.18, height: pw * 0.86), _fillPaint);
        canvas.drawOval(Rect.fromCenter(center: Offset(top.dx - pw * 0.24 + skew, base.dy - ph * 0.58), width: pw * 1.04, height: pw * 0.80), _fillPaint);
        _fillPaint.color = midLeaf;
        canvas.drawOval(Rect.fromCenter(center: Offset(top.dx + skew, base.dy - ph * 0.68), width: pw * 1.38, height: pw * 0.96), _fillPaint);
        _fillPaint.color = brightLeaf;
        canvas.drawOval(Rect.fromCenter(center: Offset(top.dx - pw * 0.14 + skew, base.dy - ph * 0.76), width: pw * 1.08, height: pw * 0.78), _fillPaint);
        canvas.drawOval(Rect.fromCenter(center: Offset(top.dx + pw * 0.26 + skew, base.dy - ph * 0.71), width: pw * 0.82, height: pw * 0.64), _fillPaint);
        _fillPaint.color = sunLeaf;
        canvas.drawOval(Rect.fromCenter(center: Offset(top.dx - pw * 0.20 + skew, base.dy - ph * 0.84), width: pw * 0.76, height: pw * 0.52), _fillPaint);
        if (pw > 13.0) {
          _fillPaint.color = glintLeaf;
          canvas.drawCircle(Offset(top.dx - pw * 0.26 + skew, base.dy - ph * 0.88), pw * 0.18, _fillPaint);
          canvas.drawCircle(Offset(top.dx + pw * 0.04 + skew, base.dy - ph * 0.84), pw * 0.16, _fillPaint);
          canvas.drawCircle(Offset(top.dx + pw * 0.28 + skew, base.dy - ph * 0.74), pw * 0.13, _fillPaint);
        }
      }
    } else {
      // REALISTIC DESERT / DUNES ARCHITECTURE (Alternates White Arabian Tensile VIP Tents, Sculpted Dunes & Lattice Floodlight Masts!)
      final int dType = seed.abs() % 3;
      if (dType == 0 && pw > 10.0) {
        // Iconic White Sail/Tensile VIP Paddock Tent (Sakhir / Lusail style!)
        final double tw = pw * 1.85;
        final double th = ph * 0.58;
        final Offset peak = Offset(top.dx, base.dy - th);
        final Offset pL = Offset(base.dx - tw * 0.56, base.dy - th * 0.28);
        final Offset pR = Offset(base.dx + tw * 0.56, base.dy - th * 0.28);
        _strokePaint
          ..color = Color.lerp(const Color(0xFF455366), circuit.skyBottom, fogMix)!
          ..strokeWidth = max(1.2, pw * 0.08);
        canvas.drawLine(Offset(pL.dx, base.dy), pL, _strokePaint);
        canvas.drawLine(Offset(pR.dx, base.dy), pR, _strokePaint);
        _drawTri(canvas, peak, pL, Offset(top.dx, base.dy - th * 0.20), Color.lerp(const Color(0xFFF5F7FA), circuit.skyBottom, fogMix)!);
        _drawTri(canvas, peak, Offset(top.dx, base.dy - th * 0.20), pR, Color.lerp(const Color(0xFFC2CCD9), circuit.skyBottom, fogMix)!);
        _strokePaint
          ..color = Color.lerp(circuit.kerbA, circuit.skyBottom, fogMix)!
          ..strokeWidth = max(1.2, pw * 0.07);
        canvas.drawLine(pL, Offset(top.dx, base.dy - th * 0.20), _strokePaint);
        canvas.drawLine(Offset(top.dx, base.dy - th * 0.20), pR, _strokePaint);
      } else if (dType == 1) {
        // Sculpted Desert Sand Dune / Coastal Zandvoort Dune Mound with Marram Grass Tufts!
        final double dw = pw * 2.2;
        final double dh = ph * 0.42;
        final Color duneLit = Color.lerp(circuit.nightMode ? const Color(0xFF4B3D2D) : const Color(0xFFC7AE82), circuit.skyBottom, fogMix)!;
        final Color duneShad = Color.lerp(circuit.nightMode ? const Color(0xFF2E251C) : const Color(0xFF917B56), circuit.skyBottom, fogMix)!;
        _drawTri(canvas, Offset(base.dx - dw * 0.55, base.dy), Offset(base.dx - dw * 0.05, base.dy - dh), Offset(base.dx + dw * 0.06, base.dy), duneLit);
        _drawTri(canvas, Offset(base.dx - dw * 0.05, base.dy - dh), Offset(base.dx + dw * 0.55, base.dy), Offset(base.dx + dw * 0.04, base.dy), duneShad);
      } else {
        // Realistic Steel Lattice Stadium Light Mast with Multi-Reflector Head
        final double armDir = isLeft ? 1.0 : -1.0;
        final Offset head = Offset(top.dx + armDir * pw * 0.48, top.dy - ph * 0.16);
        _strokePaint
          ..color = Color.lerp(const Color(0xFF7B8FA3), circuit.skyBottom, fogMix)!
          ..strokeWidth = max(2.0, pw * 0.12);
        canvas.drawLine(Offset(base.dx - pw * 0.08, base.dy), Offset(top.dx - pw * 0.03, top.dy), _strokePaint);
        canvas.drawLine(Offset(base.dx + pw * 0.08, base.dy), Offset(top.dx + pw * 0.03, top.dy), _strokePaint);
        canvas.drawLine(top, head, _strokePaint);
        _fillPaint.color = Color.lerp(const Color(0xFF1F2836), circuit.skyBottom, fogMix)!;
        canvas.drawRect(Rect.fromCenter(center: head, width: max(5.0, pw * 0.50), height: max(3.0, pw * 0.24)), _fillPaint);
        _fillPaint.color = Color.lerp(const Color(0xFFEAF4FF), circuit.skyBottom, fogMix)!;
        canvas.drawRect(Rect.fromCenter(center: head, width: max(3.5, pw * 0.36), height: max(1.8, pw * 0.13)), _fillPaint);
      }
    }
  }

  /// Iconic World-Famous 3D Trackside Circuit Monuments (COTA Tower, Sakhir Tower, Red Bull Bull,
  /// Las Vegas Sphere, Marina Bay Sands Skypark, Baku Maiden Tower, Monza Historic Tower!)
  void _drawCircuitMonument3D(
    Canvas canvas,
    double x,
    double y1,
    double z,
    double w,
    double horizonY,
    double fovMult,
    double fogMix,
    CircuitInfo circuit,
    bool isLeft,
  ) {
    final Offset base = _project(x, y1, z, w, horizonY, fovMult);
    if (base.dx < -180.0 || base.dx > w + 180.0) return;
    final Offset top = _project(x, y1 + 12.5, z, w, horizonY, fovMult);
    final double mh = max(16.0, base.dy - top.dy);
    final double mw = mh * 0.42;
    final double mFog = fogMix * 0.65;

    if (circuit.code == 'USA') {
      // COTA 77m RED OBSERVATION TOWER (Iconic Sweeping Red Canopy Rib + Glass Deck!)
      _fillPaint.color = Color.fromARGB((75 * (1.0 - mFog)).toInt(), 0, 0, 0);
      canvas.drawOval(Rect.fromCenter(center: base, width: mw * 1.4, height: max(3.0, mw * 0.25)), _fillPaint);
      _drawQuad(
        canvas,
        Offset(base.dx - mw * 0.14, base.dy),
        Offset(base.dx + mw * 0.14, base.dy),
        Offset(top.dx + mw * 0.08, top.dy + mh * 0.14),
        Offset(top.dx - mw * 0.08, top.dy + mh * 0.14),
        Color.lerp(const Color(0xFFDDE6F2), circuit.skyBottom, mFog)!,
      );
      // Iconic sweeping red steel canopy veil curving over the observation deck!
      final double arcDir = isLeft ? 1.0 : -1.0;
      _strokePaint
        ..color = Color.lerp(const Color(0xFFE10600), circuit.skyBottom, mFog)!
        ..strokeWidth = max(3.0, mw * 0.16)
        ..strokeCap = StrokeCap.round;
      _scratchPath
        ..reset()
        ..moveTo(base.dx - arcDir * mw * 0.42, base.dy)
        ..quadraticBezierTo(top.dx - arcDir * mw * 0.35, top.dy + mh * 0.18, top.dx + arcDir * mw * 0.46, top.dy);
      canvas.drawPath(_scratchPath, _strokePaint);
      // Panoramic circular observation platform
      final Offset deckC = Offset(top.dx, top.dy + mh * 0.18);
      _fillPaint.color = Color.lerp(const Color(0xFF1A2438), circuit.skyBottom, mFog)!;
      canvas.drawOval(Rect.fromCenter(center: deckC, width: mw * 0.96, height: mh * 0.11), _fillPaint);
      _fillPaint.color = Color.lerp(const Color(0xFF8ED4FF), circuit.skyBottom, mFog)!;
      canvas.drawOval(Rect.fromCenter(center: Offset(deckC.dx, deckC.dy - mh * 0.02), width: mw * 0.80, height: mh * 0.055), _fillPaint);
    } else if (circuit.code == 'LVG') {
      // ICONIC LAS VEGAS ILLUMINATED LED EXOSPHERE DOME!
      final double rad = max(14.0, mw * 1.15);
      final Offset c = Offset(base.dx, base.dy - rad * 0.78);
      final double ph = 0.5 + 0.5 * sin(engine.totalRaceTime * 1.8);
      final Color domeA = Color.lerp(const Color(0xFF00E5FF), const Color(0xFFFF6D00), ph)!;
      final Color domeB = Color.lerp(const Color(0xFF651FFF), const Color(0xFFFF1744), ph)!;
      _fillPaint.color = domeA.withAlpha((68 * (1.0 - mFog)).toInt());
      canvas.drawCircle(c, rad * 1.24, _fillPaint);
      _fillPaint.color = Color.lerp(domeB, circuit.skyBottom, mFog * 0.4)!;
      canvas.drawCircle(c, rad, _fillPaint);
      _fillPaint.color = Color.lerp(domeA, Colors.white, 0.35)!.withAlpha(195);
      canvas.drawOval(Rect.fromCenter(center: Offset(c.dx, c.dy - rad * 0.18), width: rad * 1.55, height: rad * 0.72), _fillPaint);
      _strokePaint..color = const Color(0xBBFFFFFF)..strokeWidth = max(1.0, rad * 0.05);
      canvas.drawCircle(c, rad * 0.96, _strokePaint);
    } else if (circuit.code == 'BHR' || circuit.code == 'QAT') {
      // ICONIC SAKHIR / LUSAIL ILLUMINATED GLASS VIP TOWER WITH SPIRAL LED CROWN!
      final Rect shaft = Rect.fromLTWH(top.dx - mw * 0.34, top.dy + mh * 0.08, mw * 0.68, mh * 0.92);
      _fillPaint.color = Color.lerp(const Color(0xFF182844), circuit.skyBottom, mFog)!;
      canvas.drawRRect(RRect.fromRectAndRadius(shaft, Radius.circular(mw * 0.26)), _fillPaint);
      _strokePaint
        ..color = Color.lerp(const Color(0xEE56D4FF), circuit.skyBottom, mFog * 0.4)!
        ..strokeWidth = max(1.3, mw * 0.07);
      for (int lv = 0; lv < 7; lv++) {
        final double ly = shaft.top + shaft.height * (0.12 + lv * 0.12);
        canvas.drawLine(Offset(shaft.left + 2, ly), Offset(shaft.right - 2, ly - mh * 0.025), _strokePaint);
      }
      _fillPaint.color = const Color(0xEEFFD54F);
      canvas.drawCircle(Offset(top.dx, top.dy + mh * 0.05), max(2.2, mw * 0.11), _fillPaint);
    } else if (circuit.code == 'SIN') {
      // ICONIC MARINA BAY SANDS 3-TOWER SKYPARK MONUMENT!
      final double tw = mw * 0.34;
      for (final double off in const [-0.62, 0.0, 0.62]) {
        final double tx = base.dx + off * mw;
        _drawQuad(
          canvas,
          Offset(tx - tw * 0.5, base.dy),
          Offset(tx + tw * 0.5, base.dy),
          Offset(tx + tw * 0.42, top.dy + mh * 0.14),
          Offset(tx - tw * 0.42, top.dy + mh * 0.14),
          Color.lerp(const Color(0xFF223352), circuit.skyBottom, mFog)!,
        );
        _strokePaint..color = const Color(0xBB69F0FF)..strokeWidth = max(1.0, tw * 0.12);
        canvas.drawLine(Offset(tx, base.dy - mh * 0.1), Offset(tx, top.dy + mh * 0.18), _strokePaint);
      }
      // Iconic curved boat-shaped SkyPark deck spanning all 3 towers!
      _drawQuad(
        canvas,
        Offset(base.dx - mw * 1.15, top.dy + mh * 0.14),
        Offset(base.dx + mw * 1.15, top.dy + mh * 0.14),
        Offset(base.dx + mw * 1.02, top.dy + mh * 0.04),
        Offset(base.dx - mw * 0.96, top.dy + mh * 0.04),
        Color.lerp(const Color(0xFFDDE8F8), circuit.skyBottom, mFog)!,
      );
    } else if (circuit.code == 'AUT') {
      // ICONIC RED BULL RING GIANT METALLIC BULL SCULPTURE ON STONE PEDESTAL!
      final Rect ped = Rect.fromLTWH(base.dx - mw * 0.72, base.dy - mh * 0.24, mw * 1.44, mh * 0.24);
      _fillPaint.color = Color.lerp(const Color(0xFF5A6575), circuit.skyBottom, mFog)!;
      canvas.drawRect(ped, _fillPaint);
      final Offset bC = Offset(base.dx, base.dy - mh * 0.48);
      _fillPaint.color = Color.lerp(const Color(0xFFE10600), circuit.skyBottom, mFog)!;
      canvas.drawOval(Rect.fromCenter(center: bC, width: mw * 1.25, height: mh * 0.30), _fillPaint);
      // Charging bull horns + golden sun halo behind sculpture!
      _strokePaint
        ..color = Color.lerp(const Color(0xFFFFD54F), circuit.skyBottom, mFog)!
        ..strokeWidth = max(1.8, mw * 0.09);
      canvas.drawArc(Rect.fromCenter(center: Offset(bC.dx + mw * 0.52, bC.dy - mh * 0.10), width: mw * 0.42, height: mh * 0.18), pi * 0.8, pi * 0.9, false, _strokePaint);
    } else if (circuit.code == 'AZE') {
      // ICONIC BAKU MAIDEN TOWER (QIZ QALASI) CYLINDRICAL STONE MONUMENT!
      final Rect cyl = Rect.fromLTWH(base.dx - mw * 0.46, top.dy + mh * 0.16, mw * 0.92, mh * 0.84);
      _fillPaint.color = Color.lerp(const Color(0xFFC4A77D), circuit.skyBottom, mFog)!;
      canvas.drawRect(cyl, _fillPaint);
      _fillPaint.color = Color.lerp(const Color(0xFF947A56), circuit.skyBottom, mFog)!;
      canvas.drawRect(Rect.fromLTWH(cyl.center.dx, cyl.top, cyl.width * 0.5, cyl.height), _fillPaint);
      _strokePaint..color = Color.lerp(const Color(0x774A3822), circuit.skyBottom, mFog)!..strokeWidth = max(0.9, mh * 0.018);
      for (int st = 1; st < 7; st++) {
        final double sy = cyl.top + cyl.height * (st / 7.0);
        canvas.drawLine(Offset(cyl.left, sy), Offset(cyl.right, sy), _strokePaint);
      }
    } else {
      // CLASSIC FIA CIRCUIT TIMING PYLON & GRAND PRIX SCORING TOWER (Monza, Silverstone, Spa, Australia, etc.!)
      final Rect pylon = Rect.fromLTWH(base.dx - mw * 0.32, top.dy + mh * 0.10, mw * 0.64, mh * 0.90);
      _fillPaint.color = Color.lerp(const Color(0xFF141A26), circuit.skyBottom, mFog)!;
      canvas.drawRRect(RRect.fromRectAndRadius(pylon, const Radius.circular(3)), _fillPaint);
      _fillPaint.color = Color.lerp(circuit.kerbA, circuit.skyBottom, mFog)!;
      canvas.drawRect(Rect.fromLTWH(pylon.left, pylon.top, pylon.width, pylon.height * 0.14), _fillPaint);
      // Glowing live timing leader rows (VER / NOR / LEC / YOU)
      const List<Color> rowCols = [Color(0xFFFFD54F), Color(0xFF00E676), Color(0xFF40C4FF), Color(0xFFFF7A00), Color(0xFFE53935)];
      for (int r = 0; r < 5; r++) {
        final double ry = pylon.top + pylon.height * (0.22 + r * 0.13);
        _fillPaint.color = Color.lerp(rowCols[r], circuit.skyBottom, mFog * 0.5)!;
        canvas.drawRect(Rect.fromLTWH(pylon.left + pylon.width * 0.12, ry, pylon.width * 0.76, max(1.8, pylon.height * 0.055)), _fillPaint);
      }
    }
  }

  void _drawPoly(Canvas canvas, List<Offset> pts, Color color) {
    if (pts.length < 3) return;
    _polyPath.reset();
    _polyPath.moveTo(pts[0].dx, pts[0].dy);
    for (int i = 1; i < pts.length; i++) {
      _polyPath.lineTo(pts[i].dx, pts[i].dy);
    }
    _polyPath.close();
    _fillPaint.color = color;
    canvas.drawPath(_polyPath, _fillPaint);
  }

  void _drawGradQuad(Canvas canvas, Offset a, Offset b, Offset c, Offset d, Shader shader) {
    _quadPath
      ..reset()
      ..moveTo(a.dx, a.dy)
      ..lineTo(b.dx, b.dy)
      ..lineTo(c.dx, c.dy)
      ..lineTo(d.dx, d.dy)
      ..close();
    _gradPaint.shader = shader;
    canvas.drawPath(_quadPath, _gradPaint);
  }

  /// True 3D Cylindrical Pirelli Slick Tire with:
  /// - 100% Grounded Contact Patch + Flat Bottom Rubber at ly = 0.0 (ZERO floating!)
  /// - True 3D Front-Wheel Steering Rotation around vertical kingpin axis (`wheelSteerYaw`)
  /// - Real Physical Wheel Rolling (`wheelRollAngle = dist / radius`) with spinning Pirelli red sidewall arcs, 6 rotating aero rim spokes & moving tread bands!
  /// - Glowing Carbon Brake Discs when braking
  void _draw3DTire(
    Canvas canvas,
    Offset Function(double lx, double ly, double lz) pGround,
    double sideDir,
    double zCenter,
    double halfW,
    double radius,
    bool isRear,
    bool isNearSide,
    bool isBraking,
    double wheelSteerYaw,
    double wheelRollAngle,
    double cw,
    double fogMix,
    double envShade,
    Color skyBottom,
    Color tyreCompoundColor,
  ) {
    final double xCenter = sideDir * (isRear ? 0.75 : 0.73);
    final double cosW = cos(wheelSteerYaw);
    final double sinW = sin(wheelSteerYaw);

    // Local wheel-frame -> car-frame projector (rotates front tires cleanly around their steering kingpin!)
    Offset pw(double wx, double wy, double wz) {
      final double lx = xCenter + wx * cosW + wz * sinW;
      final double lz = zCenter + wz * cosW - wx * sinW;
      return pGround(lx, wy, lz);
    }

    final double xIn = -sideDir * halfW;
    final double xOut = sideDir * halfW;
    final double xL = min(xIn, xOut);
    final double xR = max(xIn, xOut);

    // 1. Pitch-Black Grounded Tire Contact Patch Shadow directly under rubber at ly = 0.002!
    _drawQuad(
      canvas,
      pw(xL - 0.06, 0.002, -radius * 1.12),
      pw(xR + 0.06, 0.002, -radius * 1.12),
      pw(xR + 0.06, 0.002, radius * 1.12),
      pw(xL - 0.06, 0.002, radius * 1.12),
      Color.fromARGB((225 * (1.0 - fogMix)).toInt(), 0, 0, 0),
    );
    // Soft outer tire shadow skirt
    _drawQuad(
      canvas,
      pw(xL - 0.13, 0.001, -radius * 1.24),
      pw(xR + 0.13, 0.001, -radius * 1.24),
      pw(xR + 0.13, 0.001, radius * 1.24),
      pw(xL - 0.13, 0.001, radius * 1.24),
      Color.fromARGB((95 * (1.0 - fogMix)).toInt(), 0, 0, 0),
    );

    // 2. Inner Carbon Brake Duct, Glowing Brake Disc & Warm Orange Asphalt Underglow (Zero-Shader Fast Bloom!)
    if (isBraking && cw > 20.0) {
      final Offset discC = pw(xIn - sideDir * 0.035, radius * 0.96, 0.0);
      final double dr = max(3.2, cw * (isRear ? 0.105 : 0.090));
      _fillPaint.color = const Color(0x55FF3D00);
      canvas.drawCircle(discC, dr, _fillPaint);
      _fillPaint.color = const Color(0xCCFF6D00);
      canvas.drawCircle(discC, dr * 0.62, _fillPaint);
      _fillPaint.color = const Color(0xF5FFF59D);
      canvas.drawCircle(discC, dr * 0.30, _fillPaint);
      final Offset groundGlow = pw(xIn, 0.008, 0.0);
      _fillPaint.color = const Color(0x48FF5722);
      canvas.drawOval(Rect.fromCenter(center: groundGlow, width: dr * 2.2, height: dr * 0.66), _fillPaint);
    }

    // 3. Zero-Alloc High-Res Inner Sidewall & Carbon Brake Drum Barrel (reuses scratch list!)
    final bool innerVisible = !isNearSide || (wheelSteerYaw * sideDir > 0.08);
    if (innerVisible && cw > 14.0) {
      _wheelInnerScratch.clear();
      final int nIn = cw > 38.0 ? 14 : 10;
      for (int k = 0; k < nIn; k++) {
        final double a = (k / nIn) * pi * 2.0;
        _wheelInnerScratch.add(pw(xIn, radius * (1.0 + sin(a) * 0.96), radius * cos(a) * 0.96));
      }
      _drawPoly(canvas, _wheelInnerScratch, Color.lerp(const Color(0xFF0A0D13), skyBottom, fogMix * 0.55)!);
    }

    // 4. High-Resolution 8-Band Cylindrical Pirelli Slick Tire Tread (Silky round curvature, ZERO faceting!)
    final Color rubberBaseDark = Color.lerp(const Color(0xFF080B10), Colors.black, envShade * 0.4)!;
    final Color rubberBaseMid = Color.lerp(const Color(0xFF212834), Colors.black, envShade * 0.45)!;
    final Color rubberBaseHi = Color.lerp(const Color(0xFF56647D), Colors.black, envShade * 0.45)!;
    final Color rubberBaseTop = Color.lerp(const Color(0xFF394457), Colors.black, envShade * 0.45)!;

    final Color rubberDark = Color.lerp(rubberBaseDark, skyBottom, fogMix * 0.58)!;
    final Color rubberMid = Color.lerp(rubberBaseMid, skyBottom, fogMix * 0.58)!;
    final Color rubberHi = Color.lerp(rubberBaseHi, skyBottom, fogMix * 0.58)!;
    final Color rubberTop = Color.lerp(rubberBaseTop, skyBottom, fogMix * 0.58)!;

    final Offset cFL = pw(xL, 0.0, radius * 0.36);
    final Offset cFR = pw(xR, 0.0, radius * 0.36);
    final Offset cRL = pw(xL, 0.0, -radius * 0.46);
    final Offset cRR = pw(xR, 0.0, -radius * 0.46);
    final Offset lL = pw(xL, radius * 0.34, -radius * 0.90);
    final Offset lR = pw(xR, radius * 0.34, -radius * 0.90);
    final Offset m1L = pw(xL, radius * 0.84, -radius * 1.00);
    final Offset m1R = pw(xR, radius * 0.84, -radius * 1.00);
    final Offset m2L = pw(xL, radius * 1.36, -radius * 0.94);
    final Offset m2R = pw(xR, radius * 1.36, -radius * 0.94);
    final Offset uL = pw(xL, radius * 1.78, -radius * 0.66);
    final Offset uR = pw(xR, radius * 1.78, -radius * 0.66);
    final Offset tL = pw(xL, radius * 2.00, -radius * 0.06);
    final Offset tR = pw(xR, radius * 2.00, -radius * 0.06);
    final Offset fL = pw(xL, radius * 1.80, radius * 0.68);
    final Offset fR = pw(xR, radius * 1.80, radius * 0.68);

    _drawQuad(canvas, cRL, cRR, cFR, cFL, const Color(0xFF040609));
    _drawQuad(canvas, tL, tR, fR, fL, rubberTop);
    _drawQuad(canvas, uL, uR, tR, tL, rubberHi);
    _drawQuad(canvas, m2L, m2R, uR, uL, Color.lerp(rubberHi, rubberMid, 0.48)!);
    _drawQuad(canvas, m1L, m1R, m2R, m2L, rubberMid);
    _drawQuad(canvas, lL, lR, m1R, m1L, Color.lerp(rubberMid, rubberDark, 0.50)!);
    _drawQuad(canvas, cRL, cRR, lR, lL, rubberDark);

    // 5. Crisp Rolling Tread Scrub Bands & Crown Specular Sheen!
    if (cw > 18.0) {
      final double treadFrac = _posMod(wheelRollAngle / (pi * 2.0), 1.0);
      final Color treadDarkCol = Color.fromARGB((104 * (1.0 - fogMix)).toInt(), 0, 0, 0);
      final Color treadSheenCol = Color.fromARGB((82 * (1.0 - fogMix)).toInt(), 210, 224, 245);
      for (int b = 0; b < 4; b++) {
        final double ph = (treadFrac + b * 0.25) % 1.0;
        final double ang = -0.42 + ph * 2.42;
        final double ty = radius * (1.0 + sin(ang));
        final double tz = -radius * cos(ang);
        _strokePaint
          ..color = (b % 2 == 0) ? treadDarkCol : treadSheenCol
          ..strokeWidth = max(1.0, cw * (b % 2 == 0 ? 0.021 : 0.014));
        canvas.drawLine(pw(xL + 0.02, ty, tz), pw(xR - 0.02, ty, tz), _strokePaint);
      }

      _strokePaint
        ..color = Color.fromARGB((108 * (1.0 - fogMix)).toInt(), 228, 238, 255)
        ..strokeWidth = max(1.0, cw * 0.015);
      canvas.drawLine(pw(xL + 0.04, radius * 1.96, -radius * 0.20), pw(xR - 0.04, radius * 1.96, -radius * 0.20), _strokePaint);
    }

    // 6. ZERO-ALLOC ADAPTIVE-LOD 3D OUTER SIDEWALL + SPINNING PIRELLI ARCS + CARBON AERO WHEEL COVER & SPOKES!
    final bool outerVisible = isNearSide || (wheelSteerYaw * sideDir < -0.06);
    if (outerVisible && cw > 13.0) {
      _wheelOuterScratch.clear();
      _wheelBevelScratch.clear();
      _wheelCoverScratch.clear();
      final int nSeg = cw > 48.0 ? 20 : (cw > 24.0 ? 14 : 10);
      for (int k = 0; k < nSeg; k++) {
        final double a = (k / nSeg) * pi * 2.0;
        final double ca = cos(a);
        final double sa = sin(a);
        _wheelOuterScratch.add(pw(xOut, radius * (1.0 + sa * 0.98), radius * ca * 0.98));
        if (cw > 18.0) {
          _wheelBevelScratch.add(pw(xOut + sideDir * 0.006, radius * (1.0 + sa * 0.63), radius * ca * 0.63));
          _wheelCoverScratch.add(pw(xOut + sideDir * 0.010, radius * (1.0 + sa * 0.56), radius * ca * 0.56));
        }
      }
      _drawPoly(canvas, _wheelOuterScratch, Color.lerp(const Color(0xFF12161F), skyBottom, fogMix * 0.55)!);

      if (cw > 18.0) {
        // Subtle rubber sidewall specular shoulder rim
        _strokePaint
          ..color = Color.fromARGB((56 * (1.0 - fogMix)).toInt(), 210, 224, 244)
          ..strokeWidth = max(1.0, cw * 0.012);
        canvas.drawLine(
          pw(xOut, radius * 1.88, -radius * 0.35),
          pw(xOut, radius * 1.88, radius * 0.35),
          _strokePaint,
        );
        // Vivid Pirelli Compound Sidewall Arcs (Soft Red / Medium Yellow / Hard White!)
        _strokePaint
          ..color = Color.lerp(tyreCompoundColor, skyBottom, fogMix * 0.36)!
          ..strokeWidth = max(1.5, cw * 0.022)
          ..strokeCap = StrokeCap.round;
        for (int arcIdx = 0; arcIdx < 2; arcIdx++) {
          final double baseA = wheelRollAngle + arcIdx * pi;
          const int arcSteps = 7;
          Offset? prevPt;
          for (int st = 0; st <= arcSteps; st++) {
            final double a = baseA + (st / arcSteps) * 1.42;
            final Offset pt = pw(xOut + sideDir * 0.004, radius * (1.0 + sin(a) * 0.81), radius * cos(a) * 0.81);
            if (prevPt != null) {
              canvas.drawLine(prevPt, pt, _strokePaint);
            }
            prevPt = pt;
          }
        }

        _strokePaint
          ..color = Color.lerp(const Color(0xE8F5F8FC), skyBottom, fogMix * 0.42)!
          ..strokeWidth = max(1.0, cw * 0.012);
        for (int wIdx = 0; wIdx < 2; wIdx++) {
          final double a0 = wheelRollAngle + 1.92 + wIdx * pi;
          final double a1 = a0 + 0.58;
          canvas.drawLine(
            pw(xOut + sideDir * 0.005, radius * (1.0 + sin(a0) * 0.81), radius * cos(a0) * 0.81),
            pw(xOut + sideDir * 0.005, radius * (1.0 + sin(a1) * 0.81), radius * cos(a1) * 0.81),
            _strokePaint,
          );
        }

        // Crisp CNC Metallic Rim Lip + Dark Matte Carbon Aero Wheel Cover + Specular Inner Bevel
        _drawPoly(canvas, _wheelBevelScratch, Color.lerp(const Color(0xFF6B7D96), skyBottom, fogMix * 0.50)!);
        _drawPoly(canvas, _wheelCoverScratch, Color.lerp(const Color(0xFF131822), skyBottom, fogMix * 0.55)!);
        final Offset hubC = pw(xOut + sideDir * 0.014, radius, 0.0);
        if (cw > 26.0) {
          _strokePaint
            ..color = Color.lerp(const Color(0xBB7D8FA8), skyBottom, fogMix * 0.45)!
            ..strokeWidth = max(1.0, cw * 0.011);
          for (int sp = 0; sp < 6; sp++) {
            final double sa = wheelRollAngle + (sp * pi / 3.0);
            final Offset spTip = pw(xOut + sideDir * 0.012, radius * (1.0 + sin(sa) * 0.52), radius * cos(sa) * 0.52);
            canvas.drawLine(hubC, spTip, _strokePaint);
          }
        }
        _fillPaint.color = Color.lerp(sideDir < 0 ? const Color(0xFFE50914) : const Color(0xFF00B0FF), skyBottom, fogMix * 0.45)!;
        canvas.drawCircle(hubC, max(1.6, cw * 0.024), _fillPaint);
        _fillPaint.color = Color.lerp(const Color(0xFFD8E4F2), skyBottom, fogMix * 0.45)!;
        canvas.drawCircle(hubC, max(1.0, cw * 0.012), _fillPaint);
      }
    } else if (cw > 20.0) {
      final double edgePulse = 0.55 + 0.45 * sin(wheelRollAngle * 2.0);
      _strokePaint
        ..color = Color.lerp(tyreCompoundColor, skyBottom, fogMix * 0.40)!.withAlpha((edgePulse * 240).toInt())
        ..strokeWidth = max(1.3, cw * 0.019);
      canvas.drawLine(
        pw(xOut, radius * 0.34, -radius * 0.84),
        pw(xOut, radius * 1.62, -radius * 0.78),
        _strokePaint,
      );
    }
  }

  /// Ultra-HD True 3D Sculpted Sidepod Assembly (Undercut Flank, Metallic Clearcoat Shoulder, Bargeboard Winglet, Louvers & Intake)
  void _draw3DSidepod(
    Canvas canvas,
    Offset Function(double lx, double ly, double lz) p3,
    double sideDir,
    bool isLitSide,
    double cw,
    double fogMix,
    Color bodyCol,
    Color hiCol,
    Color darkCol,
    Color wingCol,
    Color skyBottom,
  ) {
    final Color sideFaceCol = isLitSide
        ? Color.lerp(bodyCol, hiCol, 0.28)!
        : Color.lerp(bodyCol, Colors.black, 0.26)!;
    final Color undercutCol = Color.lerp(bodyCol, Colors.black, isLitSide ? 0.46 : 0.64)!;
    final Color topShoulderCol = isLitSide
        ? Color.lerp(hiCol, Colors.white, 0.18)!
        : Color.lerp(bodyCol, hiCol, 0.38)!;

    final Offset fBot = p3(sideDir * 0.52, 0.14, 1.66);
    final Offset fMid = p3(sideDir * 0.66, 0.35, 1.66);
    final Offset fTop = p3(sideDir * 0.59, 0.53, 1.66);
    final Offset fInT = p3(sideDir * 0.28, 0.56, 1.66);

    final Offset mBot = p3(sideDir * 0.50, 0.12, 0.92);
    final Offset mMid = p3(sideDir * 0.67, 0.37, 0.92);
    final Offset mTop = p3(sideDir * 0.57, 0.55, 0.92);
    final Offset mInT = p3(sideDir * 0.24, 0.61, 0.92);

    final Offset rBot = p3(sideDir * 0.30, 0.15, 0.08);
    final Offset rMid = p3(sideDir * 0.43, 0.36, 0.08);
    final Offset rTop = p3(sideDir * 0.33, 0.49, 0.08);
    final Offset rInT = p3(sideDir * 0.14, 0.55, 0.08);

    _drawQuad(canvas, fBot, fMid, mMid, mBot, undercutCol);
    _drawQuad(canvas, mBot, mMid, rMid, rBot, Color.lerp(undercutCol, Colors.black, 0.20)!);

    if (cw >= 44.0) {
      _drawGradQuad(
        canvas,
        fMid,
        fTop,
        mTop,
        mMid,
        LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [Color.lerp(sideFaceCol, Colors.white, isLitSide ? 0.20 : 0.05)!, sideFaceCol, darkCol],
        ).createShader(Rect.fromPoints(fTop, mMid)),
      );
      _drawQuad(canvas, mMid, mTop, rTop, rMid, Color.lerp(sideFaceCol, darkCol, 0.22)!);

      // True PBR Metallic Clearcoat Sky-to-Body Reflection on Sidepod Upper Shoulder!
      _drawGradQuad(
        canvas,
        fTop,
        fInT,
        mInT,
        mTop,
        LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          stops: const [0.0, 0.34, 0.72, 1.0],
          colors: [
            Color.lerp(Color.lerp(topShoulderCol, skyBottom, 0.28)!, Colors.white, isLitSide ? 0.52 : 0.22)!,
            Color.lerp(topShoulderCol, Colors.white, isLitSide ? 0.24 : 0.08)!,
            topShoulderCol,
            bodyCol,
          ],
        ).createShader(Rect.fromPoints(fInT, mTop)),
      );
      _drawGradQuad(
        canvas,
        mTop,
        mInT,
        rInT,
        rTop,
        LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [topShoulderCol, bodyCol],
        ).createShader(Rect.fromPoints(mInT, rTop)),
      );
    } else {
      _drawQuad(canvas, fMid, fTop, mTop, mMid, sideFaceCol);
      _drawQuad(canvas, mMid, mTop, rTop, rMid, Color.lerp(sideFaceCol, darkCol, 0.22)!);
      _drawQuad(canvas, fTop, fInT, mInT, mTop, topShoulderCol);
      _drawQuad(canvas, mTop, mInT, rInT, rTop, Color.lerp(topShoulderCol, bodyCol, 0.50)!);
    }

    _drawQuad(
      canvas,
      p3(sideDir * 0.18, 0.22, 0.07),
      p3(sideDir * 0.37, 0.22, 0.07),
      p3(sideDir * 0.33, 0.46, 0.07),
      p3(sideDir * 0.16, 0.46, 0.07),
      Color.lerp(const Color(0xFF0A0D13), skyBottom, fogMix * 0.55)!,
    );

    if (cw > 22.0) {
      _strokePaint
        ..color = wingCol.withAlpha((242 * (1.0 - fogMix * 0.35)).toInt())
        ..strokeWidth = max(1.2, cw * 0.019);
      canvas.drawLine(fMid, mMid, _strokePaint);
      canvas.drawLine(mMid, rMid, _strokePaint);

      _strokePaint
        ..color = Color.fromARGB((168 * (1.0 - fogMix)).toInt(), 255, 255, 255)
        ..strokeWidth = max(1.0, cw * 0.012);
      canvas.drawLine(fTop, mTop, _strokePaint);
      canvas.drawLine(mTop, rTop, _strokePaint);

      _strokePaint
        ..color = Color.fromARGB((128 * (1.0 - fogMix)).toInt(), 5, 7, 11)
        ..strokeWidth = max(0.8, cw * 0.008);
      canvas.drawLine(fBot, mBot, _strokePaint);
      canvas.drawLine(mBot, rBot, _strokePaint);

      _strokePaint
        ..color = Color.fromARGB((165 * (1.0 - fogMix)).toInt(), 8, 11, 17)
        ..strokeWidth = max(0.9, cw * 0.010);
      for (int g = 0; g < 5; g++) {
        final double gz = 0.42 + g * 0.21;
        canvas.drawLine(
          p3(sideDir * 0.33, 0.55, gz),
          p3(sideDir * 0.51, 0.52, gz - 0.04),
          _strokePaint,
        );
      }

      _drawQuad(
        canvas,
        p3(sideDir * 0.34, 0.34, 1.67),
        p3(sideDir * 0.60, 0.34, 1.67),
        p3(sideDir * 0.57, 0.49, 1.67),
        p3(sideDir * 0.34, 0.49, 1.67),
        const Color(0xFF06080D),
      );
      if (cw > 36.0) {
        _strokePaint
          ..color = Color.lerp(hiCol, Colors.white, 0.35)!
          ..strokeWidth = max(1.0, cw * 0.011);
        canvas.drawLine(p3(sideDir * 0.34, 0.49, 1.67), p3(sideDir * 0.58, 0.49, 1.67), _strokePaint);
      }

      if (cw > 30.0) {
        _drawQuad(
          canvas,
          p3(sideDir * 0.72, 0.08, 1.48),
          p3(sideDir * 0.72, 0.22, 1.48),
          p3(sideDir * 0.74, 0.16, 1.72),
          p3(sideDir * 0.74, 0.08, 1.72),
          Color.lerp(const Color(0xFF151B26), skyBottom, fogMix * 0.55)!,
        );
      }
    }
  }

  /// Ultra-HD True 3D Rear Wing Endplate with Inner/Outer Side Faces, Carbon Weave Trim, Team Livery & Vertical FIA LED Strip!
  void _draw3DRearWingEndplate(
    Canvas canvas,
    Offset Function(double lx, double ly, double lz) p3,
    double sideDir,
    bool isLitSide,
    bool ledFlash,
    bool isBraking,
    double cw,
    double fogMix,
    Color bodyCol,
    Color wingCol,
    Color skyBottom,
  ) {
    final double xOut = sideDir * 0.635;
    final double xIn = sideDir * 0.595;

    final Offset eRearB = p3(xOut, 0.34, -0.32);
    final Offset eRearT = p3(xOut, 0.89, -0.35);
    final Offset eFrontT = p3(xOut, 0.87, 0.05);
    final Offset eFrontB = p3(xOut, 0.44, 0.05);

    final Color plateBase = Color.lerp(
      isLitSide ? const Color(0xFF202734) : const Color(0xFF10141C),
      skyBottom,
      fogMix * 0.60,
    )!;
    _drawQuad(canvas, eRearB, eRearT, eFrontT, eFrontB, plateBase);

    if (cw > 20.0) {
      _drawQuad(
        canvas,
        p3(xOut + sideDir * 0.004, 0.58, -0.33),
        p3(xOut + sideDir * 0.004, 0.86, -0.34),
        p3(xOut + sideDir * 0.004, 0.84, 0.02),
        p3(xOut + sideDir * 0.004, 0.58, 0.02),
        isLitSide ? bodyCol : Color.lerp(bodyCol, Colors.black, 0.25)!,
      );
      _strokePaint
        ..color = wingCol.withAlpha(235)
        ..strokeWidth = max(1.0, cw * 0.013);
      canvas.drawLine(eRearT, eFrontT, _strokePaint);
      if (cw > 40.0) {
        _strokePaint
          ..color = const Color(0xBB05070B)
          ..strokeWidth = max(0.9, cw * 0.009);
        canvas.drawLine(p3(xOut + sideDir * 0.005, 0.50, -0.22), p3(xOut + sideDir * 0.005, 0.54, -0.05), _strokePaint);
        canvas.drawLine(p3(xOut + sideDir * 0.005, 0.44, -0.22), p3(xOut + sideDir * 0.005, 0.48, -0.05), _strokePaint);
        // Subtle white sponsor decal accent bar along upper outer endplate (just like real F1 endplates!)
        _strokePaint
          ..color = Color.fromARGB((185 * (1.0 - fogMix)).toInt(), 245, 248, 255)
          ..strokeWidth = max(1.0, cw * 0.012);
        canvas.drawLine(p3(xOut + sideDir * 0.006, 0.72, -0.26), p3(xOut + sideDir * 0.006, 0.72, -0.04), _strokePaint);
      }
    }

    final Offset edgeInB = p3(xIn, 0.34, -0.32);
    final Offset edgeInT = p3(xIn, 0.89, -0.35);
    _drawQuad(
      canvas,
      edgeInB,
      eRearB,
      eRearT,
      edgeInT,
      Color.lerp(const Color(0xFF1A212E), skyBottom, fogMix * 0.58)!,
    );

    if (ledFlash && cw > 22.0) {
      final Offset ledB = p3(sideDir * 0.614, 0.42, -0.33);
      final Offset ledT = p3(sideDir * 0.614, 0.64, -0.34);
      _strokePaint
        ..color = isBraking ? const Color(0x66FF1744) : const Color(0x44FF1744)
        ..strokeWidth = max(3.0, cw * 0.036)
        ..strokeCap = StrokeCap.round;
      canvas.drawLine(ledB, ledT, _strokePaint);
      _strokePaint
        ..color = isBraking ? const Color(0xFFFF8A9B) : const Color(0xEEFF1744)
        ..strokeWidth = max(1.4, cw * 0.016);
      canvas.drawLine(ledB, ledT, _strokePaint);
    }
  }

