  /// UNIFIED ULTRA-HIGH-RESOLUTION TRUE-3D SURFACE-CONFORMING F1 CAR ENGINE
  /// - Razor-sharp PBR Clearcoat Bodywork, Crisp Panel Seams, Smooth Animated DRS, 20-Segment Rolling Pirelli Tires
  /// - Conforms EVERY vertex (lx, ly, lz) smoothly to the exact continuous 3D curved & sloped road spine!
  void _drawTrue3DF1Car({
    required Canvas canvas,
    required double rz,
    required double laneX,
    required double trackDist,
    required double speedKmh,
    required double carYaw,
    required double frontWheelSteer,
    required double baseCamHeight,
    required double camShift,
    required double w,
    required double horizonY,
    required double fovMult,
    required double trackCurv,
    required double fogMix,
    required double sunNormX,
    required Color rawBodyColor,
    required Color rawHiColor,
    required Color rawWingColor,
    required Color rawHelmetColor,
    required double drsOpenAmount,
    required bool isBraking,
    required bool isAccelerating,
    required bool yellowTCam,
    required String? driverCode,
  }) {
    if (rz <= 0.42) return;

    final bool drsOpen = drsOpenAmount > 0.35;
    final double cosY = cos(carYaw);
    final double sinY = sin(carYaw);
    final double carLaneWorldX = laneX * engine.laneToWorldX;
    final double lapLen = engine.circuit.lapLengthMeters;
    final double lapDist = _posMod(trackDist, lapLen);

    final bool underStartGantry = lapDist < 8.5 || lapDist > lapLen - 4.0;
    final double archMod = lapDist % 380.0;
    final double cProg = lapDist / lapLen;
    final bool inMonTunnel = engine.circuit.code == 'MON' && cProg >= 0.42 && cProg <= 0.52;
    final bool underYas = engine.circuit.code == 'ABU' && cProg >= 0.72 && cProg <= 0.77;
    final bool underBridge = inMonTunnel || underYas || (!underStartGantry && (archMod < 11.0 || archMod > 374.0));
    final double envShade = inMonTunnel ? 0.50 : ((underStartGantry || underBridge) ? 0.42 : 0.0);
    final int lightBand = (trackDist / 1.75).floor() % 9;
    final double floodlightBoost = (engine.circuit.nightMode && envShade == 0.0 && (lightBand == 0 || lightBand == 1)) ? 0.24 : 0.0;

    final bool onKerb = laneX.abs() > 0.84 && laneX.abs() <= 1.06;
    final double carProg = lapDist / lapLen;
    final bool onGravel = engine.isInGravelAt(laneX, carProg) || engine.isOnGrassAt(laneX, carProg);
    final double speedNorm = (speedKmh / 260.0).clamp(0.0, 1.0).toDouble();
    final double kerbBounce = (onKerb && speedKmh > 35.0)
        ? (sin(trackDist * 4.8).abs() * 0.032 * speedNorm)
        : (onGravel && speedKmh > 25.0 ? sin(trackDist * 3.6) * 0.026 * speedNorm : 0.0);
    final double suspPitch = isBraking
        ? (-0.024 * speedNorm)
        : (drsOpen ? (0.016 * speedNorm) : (isAccelerating ? (0.008 * speedNorm) : 0.0));
    final double suspRoll = (-frontWheelSteer * 0.050 * speedNorm) + (onKerb ? (-laneX.sign * 0.028) : 0.0);

    Offset pGround(double lx, double ly, double lz) {
      final double wz = max(0.24, rz + lz * cosY - lx * sinY);
      final double spineX = _sampleSpineShift(wz) - camShift;
      final double spineY = baseCamHeight + _sampleSpineElev(wz);
      final double wx = spineX + carLaneWorldX + lx * cosY + lz * sinY;
      final double wy = spineY + ly;
      return _project(wx, wy, wz, w, horizonY, fovMult);
    }

    Offset p3(double lx, double ly, double lz) {
      final double suspDy = kerbBounce + (lz - 0.80) * suspPitch + lx * suspRoll;
      return pGround(lx, max(0.015, ly + suspDy), lz);
    }

    final Offset rearL = pGround(-0.94, 0.0, 0.0);
    final Offset rearR = pGround(0.94, 0.0, 0.0);
    final double cw = (rearR.dx - rearL.dx).abs().clamp(4.0, 480.0).toDouble();
    final Color skyBottom = engine.circuit.skyBottom;

    Color shadeEnv(Color c) {
      Color out = c;
      if (envShade > 0.0) out = Color.lerp(out, Colors.black, envShade)!;
      if (floodlightBoost > 0.0) out = Color.lerp(out, const Color(0xFFE6F4FF), floodlightBoost)!;
      return Color.lerp(out, skyBottom, fogMix * 0.56)!;
    }

    final Color bodyCol = shadeEnv(rawBodyColor);
    final Color hiCol = shadeEnv(rawHiColor);
    final Color darkCol = shadeEnv(Color.lerp(rawBodyColor, Colors.black, 0.46)!);
    final Color wingCol = shadeEnv(rawWingColor);

    final double centerWorldX = (_sampleSpineShift(rz) - camShift) + carLaneWorldX;
    final double camRelX = -centerWorldX * cosY + rz * sinY;
    final double farDir = camRelX > 0.0 ? -1.0 : 1.0;
    final double nearDir = -farDir;
    final bool leftLit = sunNormX <= 0.0;
    final bool flashOn = isBraking || ((engine.totalRaceTime * 6.0).floor() % 2 == 0);

    final double rearWheelRoll = trackDist / 0.305;
    final double frontWheelRoll = trackDist / 0.270;

    // Sharp Crisp Far-Distance LOD (only below 10px width; keeps tires, body, airbox, rear wing & rain light sharp!)
    if (cw < 10.0) {
      _drawQuad(
        canvas,
        pGround(-0.96, 0.004, -0.25),
        pGround(0.96, 0.004, -0.25),
        pGround(0.86, 0.004, 2.60),
        pGround(-0.86, 0.004, 2.60),
        const Color(0xBB000000),
      );
      _drawQuad(canvas, pGround(-0.92, 0.0, 0.0), pGround(-0.56, 0.0, 0.0), pGround(-0.56, 0.56, 0.0), pGround(-0.92, 0.56, 0.0), const Color(0xFF141820));
      _drawQuad(canvas, pGround(0.56, 0.0, 0.0), pGround(0.92, 0.0, 0.0), pGround(0.92, 0.56, 0.0), pGround(0.56, 0.56, 0.0), const Color(0xFF141820));
      _drawQuad(canvas, p3(-0.58, 0.14, 0.0), p3(0.58, 0.14, 0.0), p3(0.42, 0.64, 1.15), p3(-0.42, 0.64, 1.15), bodyCol);
      _drawQuad(canvas, p3(-0.14, 0.58, 0.2), p3(0.14, 0.58, 0.2), p3(0.11, 0.88, 1.4), p3(-0.11, 0.88, 1.4), hiCol);
      _drawQuad(canvas, p3(-0.62, 0.68, -0.26), p3(0.62, 0.68, -0.26), p3(0.62, 0.86, -0.26), p3(-0.62, 0.86, -0.26), wingCol);
      if (flashOn) {
        _fillPaint.color = const Color(0xFFFF1744);
        canvas.drawCircle(p3(0.0, 0.25, -0.22), max(1.4, cw * 0.14), _fillPaint);
      }
      return;
    }

    // Authentic Pirelli tire compound per car (Soft Red / Medium Yellow / Hard White!)
    final Color tyreCompoundCol;
    if (driverCode == null) {
      tyreCompoundCol = const Color(0xFFE50914);
    } else {
      final int compHash = driverCode.codeUnitAt(0) + driverCode.codeUnitAt(driverCode.length - 1);
      tyreCompoundCol = (compHash % 3 == 0)
          ? const Color(0xFFFFD600)
          : ((compHash % 3 == 1) ? const Color(0xFFE50914) : const Color(0xFFF2F6FC));
    }

    // 1. MULTI-LAYER 3D SURFACE-CONFORMING UNDERBODY SHADOW & DIRECTIONAL SUN CAST SHADOW
    final double shOffX = -sunNormX * 0.42;
    _drawQuad(
      canvas,
      pGround(-1.18 + shOffX, 0.002, -0.52),
      pGround(1.18 + shOffX, 0.002, -0.52),
      pGround(1.04 + shOffX * 0.80, 0.002, 3.28),
      pGround(-1.04 + shOffX * 0.80, 0.002, 3.28),
      Color.fromARGB(((engine.circuit.nightMode ? 76 : 112) * (1.0 - fogMix)).toInt(), 0, 0, 0),
    );
    _drawQuad(
      canvas,
      pGround(-0.88, 0.003, -0.26),
      pGround(0.88, 0.003, -0.26),
      pGround(0.78, 0.003, 2.86),
      pGround(-0.78, 0.003, 2.86),
      Color.fromARGB((216 * (1.0 - fogMix)).toInt(), 0, 0, 0),
    );
    if (cw > 34.0) {
      final Offset bounceC = pGround(0.0, 0.006, 0.70);
      final double br = cw * 0.52;
      _fillPaint.color = rawBodyColor.withAlpha(((engine.circuit.nightMode ? 48 : 28) * (1.0 - fogMix)).toInt().clamp(0, 255).toInt());
      canvas.drawOval(Rect.fromCenter(center: bounceC, width: br * 1.35, height: br * 0.28), _fillPaint);
    }
    if (cw > 32.0 && speedKmh > 75.0 && (isBraking || trackCurv.abs() > 0.019)) {
      _strokePaint
        ..color = Color.fromARGB(((isBraking ? 124 : 78) * (1.0 - fogMix)).toInt(), 5, 6, 10)
        ..strokeWidth = max(2.0, cw * 0.055)
        ..strokeCap = StrokeCap.round;
      for (final double sDir in const [-1.0, 1.0]) {
        canvas.drawLine(pGround(sDir * 0.75, 0.006, -0.05), pGround(sDir * 0.76, 0.006, -1.65), _strokePaint);
      }
    }
    if (flashOn && cw > 28.0 && _rearLightGroundPaint != null) {
      final Offset glowGround = pGround(0.0, 0.008, -0.50);
      final double gr = cw * (isBraking ? 0.28 : 0.16);
      _rearLightGroundPaint!.color = Color.fromARGB(isBraking ? 255 : 145, 255, 255, 255);
      canvas.save();
      canvas.translate(glowGround.dx, glowGround.dy);
      canvas.scale((gr * 0.98) / 48.0, (gr * 0.28) / 48.0);
      canvas.drawCircle(Offset.zero, 48.0, _rearLightGroundPaint!);
      canvas.restore();
    }

    // 2. ULTRA-HD 3-ELEMENT FRONT WING, CURVED ENDPLATES & NOSE PYLONS
    _drawQuad(
      canvas,
      p3(-0.96, 0.09, 2.72),
      p3(0.96, 0.09, 2.72),
      p3(0.92, 0.07, 3.16),
      p3(-0.92, 0.07, 3.16),
      Color.lerp(const Color(0xFF131720), skyBottom, fogMix * 0.58)!,
    );
    _drawQuad(
      canvas,
      p3(-0.94, 0.16, 2.68),
      p3(0.94, 0.16, 2.68),
      p3(0.90, 0.11, 2.98),
      p3(-0.90, 0.11, 2.98),
      wingCol,
    );
    if (cw > 18.0) {
      _drawQuad(
        canvas,
        p3(-0.88, 0.22, 2.62),
        p3(0.88, 0.22, 2.62),
        p3(0.84, 0.16, 2.86),
        p3(-0.84, 0.16, 2.86),
        Color.lerp(bodyCol, hiCol, 0.38)!,
      );
      _strokePaint
        ..color = Color.fromARGB((130 * (1.0 - fogMix)).toInt(), 255, 255, 255)
        ..strokeWidth = max(0.8, cw * 0.008);
      canvas.drawLine(p3(-0.88, 0.22, 2.62), p3(0.88, 0.22, 2.62), _strokePaint);
      for (final double sDir in [farDir, nearDir]) {
        _drawQuad(
          canvas,
          p3(sDir * 0.96, 0.07, 2.66),
          p3(sDir * 0.96, 0.29, 2.66),
          p3(sDir * 0.94, 0.23, 3.16),
          p3(sDir * 0.94, 0.07, 3.16),
          bodyCol,
        );
        _strokePaint
          ..color = const Color(0xFF141820)
          ..strokeWidth = max(1.0, cw * 0.013);
        canvas.drawLine(p3(sDir * 0.08, 0.16, 2.98), p3(sDir * 0.08, 0.09, 3.02), _strokePaint);
      }
    }

    // 3. FRONT DOUBLE-WISHBONE CARBON SUSPENSION + HIGH-RES STEERING 3D FRONT TIRES
    if (cw > 20.0) {
      _strokePaint
        ..color = Color.lerp(const Color(0xFF1C222D), skyBottom, fogMix * 0.58)!
        ..strokeWidth = max(1.1, cw * 0.016);
      canvas.drawLine(p3(farDir * 0.22, 0.34, 2.34), pGround(farDir * 0.64, 0.34, 2.38), _strokePaint);
      canvas.drawLine(p3(farDir * 0.20, 0.18, 2.30), pGround(farDir * 0.64, 0.18, 2.38), _strokePaint);
    }
    _draw3DTire(canvas, pGround, farDir, 2.38, 0.155, 0.27, false, false, isBraking, frontWheelSteer, frontWheelRoll, cw, fogMix, envShade, skyBottom, tyreCompoundCol);

    // 4. 3D TAPERED SCULPTED NOSECONE WITH PBR CLEARCOAT SPECULAR RIBBON
    final Offset nRearL = p3(-0.26, 0.48, 1.92);
    final Offset nRearR = p3(0.26, 0.48, 1.92);
    final Offset nTipL = p3(-0.10, 0.18, 3.12);
    final Offset nTipR = p3(0.10, 0.18, 3.12);
