          final Offset sp0 = pGround(sx, sy, sz);
          final Offset sp1 = pGround(sx * 1.18, sy + 0.045, sz - 0.38);
          final int spA = (((1.0 - frac) * 245) * (1.0 - fogMix)).toInt().clamp(0, 255).toInt();
          _strokePaint
            ..color = Color.fromARGB(spA, 255, 196, 64)
            ..strokeWidth = max(1.2, cw * 0.015)
            ..strokeCap = StrokeCap.round;
          canvas.drawLine(sp0, sp1, _strokePaint);
          _strokePaint
            ..color = Color.fromARGB(spA, 255, 252, 230)
            ..strokeWidth = max(0.75, cw * 0.0065);
          canvas.drawLine(sp0, Offset.lerp(sp0, sp1, 0.55)!, _strokePaint);
        }
      }

      final bool highSlipSmoke = (isBraking && speedKmh > 125.0) || (trackCurv.abs() > 0.018 && speedKmh > 145.0);
      if (onGravel || highSlipSmoke) {
        final Color puffBase = onGravel ? const Color(0xFFC5AB80) : const Color(0xFFE5EDF5);
        final double puffPhase = (trackDist * 0.45) % 1.0;
        for (final double sDir in const [-1.0, 1.0]) {
          for (int k = 0; k < 2; k++) {
            final double pFrac = (puffPhase + k * 0.5) % 1.0;
            final Offset puffC = pGround(sDir * (0.75 + pFrac * 0.08), 0.10 + pFrac * 0.24, -0.26 - pFrac * 0.72);
            final double pr = max(3.0, cw * (0.048 + pFrac * 0.055));
            final int a = (((1.0 - pFrac) * (onGravel ? 95 : 68)) * (1.0 - fogMix)).toInt().clamp(0, 255).toInt();
            _fillPaint.color = puffBase.withAlpha(a >> 1);
            canvas.drawCircle(puffC, pr, _fillPaint);
            _fillPaint.color = puffBase.withAlpha(a);
            canvas.drawCircle(puffC, pr * 0.55, _fillPaint);
          }
        }
      }
    }

    // 12. TRUE 3D MULTI-PLANE REAR WING WITH SMOOTH ANIMATED DRS FLAP
    _draw3DRearWingEndplate(canvas, p3, farDir, farDir < 0 ? leftLit : !leftLit, flashOn, isBraking, cw, fogMix, bodyCol, wingCol, skyBottom);

    _strokePaint
      ..color = Color.lerp(const Color(0xFF161B24), skyBottom, fogMix * 0.58)!
      ..strokeWidth = max(1.4, cw * 0.020);
    canvas.drawLine(p3(-0.07, 0.38, -0.14), p3(-0.07, 0.72, -0.22), _strokePaint);
    canvas.drawLine(p3(0.07, 0.38, -0.14), p3(0.07, 0.72, -0.22), _strokePaint);

    final Offset mpL = p3(-0.60, 0.66, -0.26);
    final Offset mpMid = p3(0.0, 0.63, -0.28);
    final Offset mpR = p3(0.60, 0.66, -0.26);
    final Offset mpLT = p3(-0.60, 0.74, -0.28);
    final Offset mpMidT = p3(0.0, 0.72, -0.30);
    final Offset mpRT = p3(0.60, 0.74, -0.28);
    _drawQuad(
      canvas,
      mpL,
      mpR,
      p3(0.60, 0.64, -0.04),
      p3(-0.60, 0.64, -0.04),
      Color.lerp(const Color(0xFF0A0D14), skyBottom, fogMix * 0.58)!,
    );
    _drawQuad(canvas, mpL, mpMid, mpMidT, mpLT, Color.lerp(wingCol, Colors.black, 0.14)!);
    _drawQuad(canvas, mpMid, mpR, mpRT, mpMidT, Color.lerp(wingCol, Colors.black, 0.24)!);

    final double dOpen = drsOpenAmount.clamp(0.0, 1.0).toDouble();
    final double flapLowY = 0.75 + 0.08 * dOpen;
    final double flapHighY = 0.86 + 0.02 * dOpen;
    final double flapLowZ = -0.29 + 0.15 * dOpen;
    final Offset flL = p3(-0.60, flapLowY, flapLowZ);
    final Offset flR = p3(0.60, flapLowY, flapLowZ);
    final Offset flTR = p3(0.60, flapHighY, -0.34);
    final Offset flTL = p3(-0.60, flapHighY, -0.34);
    if (cw >= 44.0) {
      final Rect flapBounds = Rect.fromPoints(flTL, flR);
      _drawGradQuad(
        canvas,
        flL,
        flR,
        flTR,
        flTL,
        LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [
            Color.lerp(Color.lerp(wingCol, Colors.white, 0.34)!, const Color(0xFFA6F8FF), dOpen)!,
            wingCol,
          ],
        ).createShader(flapBounds),
      );
    } else {
      _drawQuad(canvas, flL, flR, flTR, flTL, Color.lerp(wingCol, const Color(0xFFA6F8FF), dOpen * 0.45)!);
    }
    if (cw > 24.0) {
      // Crisp white specular top lip + sponsor micro-stripe on DRS flap + hydraulic actuator pod!
      _strokePaint
        ..color = Color.fromARGB((180 * (1.0 - fogMix)).toInt(), 255, 255, 255)
        ..strokeWidth = max(0.9, cw * 0.010);
      canvas.drawLine(flTL, flTR, _strokePaint);
      if (cw > 38.0) {
        final Offset spL = Offset.lerp(flL, flTL, 0.50)!;
        final Offset spR = Offset.lerp(flR, flTR, 0.50)!;
        final Offset wingMid = Offset.lerp(spL, spR, 0.50)!;
        final double wingSpanPx = (spR - spL).distance;
        final double wingTiltAng = atan2(spR.dy - spL.dy, spR.dx - spL.dx);
        final String wingBrand = _rearWingBrandFor(driverCode);
        final bool lightWing = rawWingColor.computeLuminance() > 0.52;
        final Color brandInk = Color.lerp(
          lightWing ? const Color(0xFF0A0D14) : const Color(0xFFF6FAFF),
          skyBottom,
          fogMix * 0.45,
        )!;
        final double brandFont = (wingSpanPx * 0.19).clamp(7.0, 22.0).toDouble();
        final TextPainter btp = _getCachedBoardText(wingBrand, brandFont, brandInk);
        canvas.save();
        canvas.translate(wingMid.dx, wingMid.dy);
        canvas.rotate(wingTiltAng);
        final double fitScale = btp.width > wingSpanPx * 0.82 ? (wingSpanPx * 0.82 / max(1.0, btp.width)) : 1.0;
        final double vScale = (1.0 - dOpen * 0.48).clamp(0.42, 1.0).toDouble();
        canvas.scale(fitScale, fitScale * vScale);
        btp.paint(canvas, Offset(-btp.width * 0.5, -btp.height * 0.5));
        canvas.restore();
      }
      _drawQuad(
        canvas,
        p3(-0.045, 0.71, -0.30),
        p3(0.045, 0.71, -0.30),
        p3(0.04, 0.85, -0.34),
        p3(-0.04, 0.85, -0.34),
        drsOpen ? const Color(0xFF00E5FF) : const Color(0xFF141820),
      );
    }

    _draw3DRearWingEndplate(canvas, p3, nearDir, nearDir < 0 ? leftLit : !leftLit, flashOn, isBraking, cw, fogMix, bodyCol, wingCol, skyBottom);

    if ((speedKmh > 230.0 || drsOpen) && cw > 34.0) {
      final double vAlpha = (((speedKmh - 215.0) / 145.0).clamp(0.18, 0.85).toDouble() * (1.0 - fogMix));
      final Color vortCol = drsOpen
          ? Color.fromARGB((vAlpha * 115).toInt(), 110, 240, 255)
          : Color.fromARGB((vAlpha * 72).toInt(), 235, 245, 255);
      final double wave = sin(trackDist * 0.85) * 0.04;
      _strokePaint
        ..color = vortCol
        ..strokeWidth = max(1.1, cw * 0.012)
        ..strokeCap = StrokeCap.round;
      for (final double sDir in const [-1.0, 1.0]) {
        final Offset vt0 = p3(sDir * 0.62, 0.86, -0.35);
        final Offset vt1 = p3(sDir * 0.67 + wave, 0.80, -0.82);
        final Offset vt2 = p3(sDir * 0.72 - wave, 0.72, -1.35);
        canvas.drawLine(vt0, vt1, _strokePaint);
        _strokePaint.color = vortCol.withAlpha((vortCol.alpha * 0.45).toInt());
        canvas.drawLine(vt1, vt2, _strokePaint);
        _strokePaint.color = vortCol;
      }
    }

    // 13. CENTRAL VERTICAL FIA LED RAIN / BRAKE LIGHT WITH ZERO-SHADER SOFT BLOOM
    if (flashOn) {
      final Offset lightC = p3(0.0, 0.24, -0.23);
      final double lr = max(3.5, cw * (isBraking ? 0.145 : 0.090));
      _fillPaint.color = const Color(0x40FF1744);
      canvas.drawCircle(lightC, lr, _fillPaint);
      _fillPaint.color = const Color(0x88FF3D57);
      canvas.drawCircle(lightC, lr * 0.56, _fillPaint);
      _fillPaint.color = isBraking ? const Color(0xFFFFC2CC) : const Color(0xFFFF4562);
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          Rect.fromCenter(center: lightC, width: max(2.0, cw * 0.036), height: max(4.0, cw * 0.088)),
          const Radius.circular(1.5),
        ),
        _fillPaint,
      );
    }

    // 14. CRISP BROADCAST DRIVER TELEMETRY TAG (Only on Rivals!)
    if (driverCode != null && cw > 20.0) {
      final Offset tagAnchor = p3(0.0, 1.18, 0.90);
      final TextPainter tp = _getCachedTag(driverCode);
      final double pillW = tp.width + (drsOpen ? 18.0 : 11.0);
      final double bx = tagAnchor.dx - pillW * 0.5;
      final double by = tagAnchor.dy - tp.height - 2.0;
      final RRect pill = RRect.fromRectAndRadius(Rect.fromLTWH(bx, by - 1, pillW, tp.height + 2.5), const Radius.circular(4));
      _fillPaint.color = const Color(0xDC070B12);
      canvas.drawRRect(pill, _fillPaint);
      _strokePaint
        ..color = drsOpen ? const Color(0xAA00E5FF) : const Color(0x44FFFFFF)
        ..strokeWidth = 0.9;
      canvas.drawRRect(pill, _strokePaint);
      _fillPaint.color = drsOpen ? const Color(0xFF00E5FF) : rawBodyColor;
      canvas.drawRect(Rect.fromLTWH(bx + 0.5, by - 0.5, 3.2, tp.height + 1.5), _fillPaint);
      tp.paint(canvas, Offset(bx + 5.8, by));
      if (drsOpen) {
        _fillPaint.color = const Color(0xFF00E5FF);
        canvas.drawCircle(Offset(bx + pillW - 5.0, by + tp.height * 0.5), 2.5, _fillPaint);
      }
    }
  }

  /// AAA True-3D Depth F1 Broadcast Cockpit:
  /// - 6-Layer True Perspective Parallax (Wing -> Tires/Nose -> Cowling/Mirrors -> Deep Recessed Tub -> Extruded 3D Wheel/Arms -> Tubular 3D Halo)
  /// - Tapered 3D Airfoil Double-Wishbone Suspension, Cast Shadows, Inner Bulkhead Hardware, 3D Harness Straps & Sculpted Helmet Optics!
  void _drawCockpitUltra(Canvas canvas, double w, double h, double sunNormX, CircuitInfo circuit) {
    final TeamLivery livery = engine.livery;
    final double cx = w * 0.5;
    final double vib = engine.smoothCockpitHeave;
    // Real-life helmet lateral G-force sway & longitudinal braking/ERS head zoom!
    final double gShiftX = (-engine.steerAngle * 7.2) - (engine.smoothLatG * 8.5);
    final double headZoom = (1.0 - engine.smoothLongG * 0.020).clamp(0.972, 1.032).toDouble();

    // Multi-layer depth parallax offsets (near objects shift more than far objects -> unmistakable 3D depth!)
    final double pxFar = gShiftX * 0.24;
    final double pxNose = gShiftX * 0.34;
    final double pxMid = gShiftX * 0.50;
    final double pxTub = gShiftX * 0.66;
    final double pxWheel = gShiftX * 0.84;
    final double pxHalo = gShiftX * 1.10;
    final double wheelShift = engine.steerAngle * 24.0;

    canvas.save();
    if ((headZoom - 1.0).abs() > 0.0005) {
      canvas.translate(cx, h * 0.72);
      canvas.scale(headZoom, headZoom);
      canvas.translate(-cx, -h * 0.72);
    }

    final Paint carbonPaint = _carbonPaint ?? (_fillPaint..color = const Color(0xFF14171E));

    // =========================================================================
    // LAYER 0 (FARTHEST): 3D MULTI-ELEMENT FRONT WING, DIVEPLANES & ENDPLATES
    // =========================================================================
    // Dark lower carbon mainplane shadow lip
    _fillPaint.color = const Color(0xCC070A10);
    for (final double sDir in const [-1.0, 1.0]) {
      final double outX = sDir < 0 ? w * 0.042 : w * 0.958;
      final double inX = sDir < 0 ? w * 0.228 : w * 0.772;
      _scratchPath
        ..reset()
        ..moveTo(outX + pxFar + wheelShift * 0.62, h * 0.606 + vib)
        ..lineTo(inX + pxFar + wheelShift * 0.52, h * 0.627 + vib)
        ..lineTo(inX + pxFar + wheelShift * 0.52, h * 0.640 + vib)
        ..lineTo(outX + pxFar + wheelShift * 0.62, h * 0.620 + vib)
        ..close();
      canvas.drawPath(_scratchPath, _fillPaint);
    }

    // Primary painted front wing flap (pre-cached shader -> ZERO per-frame GPU shader alloc!)
    final Paint wingPaint = _cockpitWingFlapPaint ?? _fillPaint;
    _scratchPath
      ..reset()
      ..moveTo(w * 0.050 + pxFar + wheelShift * 0.65, h * 0.584 + vib)
      ..lineTo(w * 0.222 + pxFar + wheelShift * 0.55, h * 0.606 + vib)
      ..lineTo(w * 0.210 + pxFar + wheelShift * 0.55, h * 0.630 + vib)
      ..lineTo(w * 0.044 + pxFar + wheelShift * 0.65, h * 0.609 + vib)
      ..close();
    canvas.drawPath(_scratchPath, wingPaint);
    _scratchPath
      ..reset()
      ..moveTo(w * 0.950 + pxFar + wheelShift * 0.65, h * 0.584 + vib)
      ..lineTo(w * 0.778 + pxFar + wheelShift * 0.55, h * 0.606 + vib)
      ..lineTo(w * 0.790 + pxFar + wheelShift * 0.55, h * 0.630 + vib)
      ..lineTo(w * 0.956 + pxFar + wheelShift * 0.65, h * 0.609 + vib)
      ..close();
    canvas.drawPath(_scratchPath, wingPaint);

    // Secondary carbon upper cascade flap + crisp specular leading edge + CNC flap adjusters
    _scratchPath
      ..reset()
      ..moveTo(w * 0.058 + pxFar + wheelShift * 0.65, h * 0.575 + vib)
      ..lineTo(w * 0.200 + pxFar + wheelShift * 0.55, h * 0.594 + vib)
      ..lineTo(w * 0.195 + pxFar + wheelShift * 0.55, h * 0.607 + vib)
      ..lineTo(w * 0.054 + pxFar + wheelShift * 0.65, h * 0.590 + vib)
      ..close();
    canvas.drawPath(_scratchPath, carbonPaint);
    _scratchPath
      ..reset()
      ..moveTo(w * 0.942 + pxFar + wheelShift * 0.65, h * 0.575 + vib)
      ..lineTo(w * 0.800 + pxFar + wheelShift * 0.55, h * 0.594 + vib)
      ..lineTo(w * 0.805 + pxFar + wheelShift * 0.55, h * 0.607 + vib)
      ..lineTo(w * 0.946 + pxFar + wheelShift * 0.65, h * 0.590 + vib)
      ..close();
    canvas.drawPath(_scratchPath, carbonPaint);
    _strokePaint..color = const Color(0xCCFFFFFF)..strokeWidth = 1.4;
    canvas.drawLine(Offset(w * 0.058 + pxFar + wheelShift * 0.65, h * 0.575 + vib), Offset(w * 0.200 + pxFar + wheelShift * 0.55, h * 0.594 + vib), _strokePaint);
    canvas.drawLine(Offset(w * 0.942 + pxFar + wheelShift * 0.65, h * 0.575 + vib), Offset(w * 0.800 + pxFar + wheelShift * 0.55, h * 0.594 + vib), _strokePaint);
    // Metallic flap adjuster turnbuckles (twin per side)
    _strokePaint..color = const Color(0xFFDDE8F6)..strokeWidth = 2.0;
    for (final double fx in const [0.112, 0.158, 0.842, 0.888]) {
      canvas.drawLine(Offset(w * fx + pxFar + wheelShift * 0.60, h * 0.584 + vib), Offset(w * fx + pxFar + wheelShift * 0.60, h * 0.606 + vib), _strokePaint);
    }

    // 3D Sculpted Vertical Wing Endplates with inner carbon thickness wall + livery outer blade
    _fillPaint.color = const Color(0xFF0E121A);
    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(w * 0.048 + pxFar + wheelShift * 0.65, h * 0.567 + vib, 6.0, 32), const Radius.circular(2.0)), _fillPaint);
    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(w * 0.946 + pxFar + wheelShift * 0.65, h * 0.567 + vib, 6.0, 32), const Radius.circular(2.0)), _fillPaint);
    _fillPaint.color = livery.secondary;
    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(w * 0.042 + pxFar + wheelShift * 0.65, h * 0.565 + vib, 7.5, 34), const Radius.circular(2.5)), _fillPaint);
    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(w * 0.950 + pxFar + wheelShift * 0.65, h * 0.565 + vib, 7.5, 34), const Radius.circular(2.5)), _fillPaint);
    _fillPaint.color = const Color(0xAAFFFFFF);
    canvas.drawRect(Rect.fromLTWH(w * 0.044 + pxFar + wheelShift * 0.65, h * 0.567 + vib, 2.0, 30), _fillPaint);
    canvas.drawRect(Rect.fromLTWH(w * 0.952 + pxFar + wheelShift * 0.65, h * 0.567 + vib, 2.0, 30), _fillPaint);

    // =========================================================================
    // LAYER 1 (2.0m AHEAD): 3D FRONT PIRELLI SLICKS, TAPERED 3D AIRFOIL WISHBONES & 3D NOSECONE
    // =========================================================================
    _drawFrontTireUltra(canvas, Offset(w * 0.162 + pxNose + wheelShift, h * 0.720 + vib), w * 0.178, h * 0.344, true, sunNormX);
    _drawFrontTireUltra(canvas, Offset(w * 0.838 + pxNose + wheelShift, h * 0.720 + vib), w * 0.178, h * 0.344, false, sunNormX);

    // True 3D Tapered Perspective Carbon Double-Wishbone Suspension (wide inboard chord -> narrow upright!)
    for (final double sDir in const [-1.0, 1.0]) {
      final double outU = cx + sDir * w * 0.285 + pxNose + wheelShift * 0.55;
      final double inU = cx + sDir * w * 0.105 + pxMid;
      // Lower carbon wishbone (dark airfoil polygon + ground shadow)
      _scratchPath
        ..reset()
        ..moveTo(outU, h * 0.758 + vib)
        ..lineTo(inU, h * 0.785 + vib)
        ..lineTo(inU, h * 0.806 + vib)
        ..lineTo(outU, h * 0.772 + vib)
        ..close();
      _fillPaint.color = const Color(0xFF090C12);
      canvas.drawPath(_scratchPath, _fillPaint);

      // Moving Steering Track-Rod (linked directly to wheel steering movement!)
      final double rodOut = cx + sDir * w * 0.280 + pxNose + wheelShift * 0.70;
      final double rodIn = cx + sDir * w * 0.100 + pxMid + wheelShift * 0.16;
      _strokePaint..color = const Color(0xFF39475E)..strokeWidth = 4.6..strokeCap = StrokeCap.round;
      canvas.drawLine(Offset(rodOut, h * 0.712 + vib), Offset(rodIn, h * 0.744 + vib), _strokePaint);
      _strokePaint..color = const Color(0x66C6D8EE)..strokeWidth = 1.3;
      canvas.drawLine(Offset(rodOut, h * 0.710 + vib), Offset(rodIn, h * 0.742 + vib), _strokePaint);

      // Upper 3D Tapered Carbon Airfoil Wishbone (front + rear leg forming real V-triangle!)
      _scratchPath
        ..reset()
        ..moveTo(outU, h * 0.662 + vib)
        ..lineTo(inU, h * 0.715 + vib)
        ..lineTo(inU, h * 0.736 + vib)
        ..lineTo(outU, h * 0.674 + vib)
        ..close();
      canvas.drawPath(_scratchPath, carbonPaint);
      if (_cockpitWishboneShadePaint != null) {
        canvas.drawPath(_scratchPath, _cockpitWishboneShadePaint!);
      }
      // Sunlit upper airfoil leading-edge specular line
      _strokePaint..color = const Color(0x88DCE8F8)..strokeWidth = 1.6;
      canvas.drawLine(Offset(outU, h * 0.663 + vib), Offset(inU, h * 0.716 + vib), _strokePaint);

      // Rear-swept wishbone leg for true 3D double-wishbone triangle depth!
      _strokePaint..color = const Color(0xFF131822)..strokeWidth = 6.2;
      canvas.drawLine(Offset(outU, h * 0.670 + vib), Offset(cx + sDir * w * 0.135 + pxMid, h * 0.694 + vib), _strokePaint);

      // Diagonal CNC Machined Titanium Pushrod + Inboard Spherical Rose-Joint Clevis
      final double prOut = cx + sDir * w * 0.268 + pxNose + wheelShift * 0.56;
      final double prIn = cx + sDir * w * 0.102 + pxMid;
      _strokePaint..color = const Color(0xFF9EB4CE)..strokeWidth = 4.0;
      canvas.drawLine(Offset(prOut, h * 0.740 + vib), Offset(prIn, h * 0.684 + vib), _strokePaint);
      _strokePaint..color = const Color(0x99FFFFFF)..strokeWidth = 1.2;
      canvas.drawLine(Offset(prOut, h * 0.738 + vib), Offset(prIn, h * 0.682 + vib), _strokePaint);
      // Machined titanium clevis housing & bolt
      _fillPaint.color = const Color(0xFF1F2735);
      canvas.drawCircle(Offset(prIn, h * 0.684 + vib), 5.6, _fillPaint);
      _fillPaint.color = const Color(0xFFE6F0FA);
      canvas.drawCircle(Offset(prIn, h * 0.684 + vib), 2.8, _fillPaint);
    }

    // 4. Sculpted 3D F1 Nosecone (True 3-Face Volume: Left Flank + Right Flank + Crowned Top Spine + Clearcoat!)
    final double nTipY = h * 0.594 + vib;
    final double nMidY = h * 0.668 + vib;
    final double nBaseY = h * 0.754 + vib;
    final double nTipHalf = w * 0.044;
    final double nBaseHalf = w * 0.168;

    // 3D Left & Right Curved Nosecone Side Flanks (darker shadow side vs sunlit side -> huge 3D solidity!)
    for (final double sDir in const [-1.0, 1.0]) {
      final bool isLit = (sDir < 0) ? (sunNormX < 0.0) : (sunNormX >= 0.0);
      _scratchPath
        ..reset()
        ..moveTo(cx + sDir * nTipHalf + pxFar, nTipY)
        ..quadraticBezierTo(cx + sDir * w * 0.132 + pxNose, nMidY, cx + sDir * nBaseHalf + pxMid, nBaseY)
        ..lineTo(cx + sDir * (nBaseHalf - w * 0.024) + pxMid, nBaseY)
        ..quadraticBezierTo(cx + sDir * w * 0.104 + pxNose, nMidY, cx + sDir * (nTipHalf - w * 0.010) + pxFar, nTipY)
        ..close();
      _fillPaint.color = isLit
          ? Color.lerp(livery.primary, livery.primaryDark, 0.28)!
          : Color.lerp(livery.primaryDark, Colors.black, 0.45)!;
      canvas.drawPath(_scratchPath, _fillPaint);
    }

    // Crowned 3D Nosecone Top Surface
    _scratchPath
      ..reset()
      ..moveTo(cx - (nTipHalf - w * 0.009) + pxFar, nTipY)
      ..lineTo(cx + (nTipHalf - w * 0.009) + pxFar, nTipY)
      ..quadraticBezierTo(cx + w * 0.106 + pxNose, nMidY, cx + (nBaseHalf - w * 0.022) + pxMid, nBaseY)
      ..lineTo(cx - (nBaseHalf - w * 0.022) + pxMid, nBaseY)
      ..quadraticBezierTo(cx - w * 0.106 + pxNose, nMidY, cx - (nTipHalf - w * 0.009) + pxFar, nTipY)
      ..close();
    if (_cockpitNoseBasePaint != null) {
      canvas.drawPath(_scratchPath, _cockpitNoseBasePaint!);
    }
    if (_cockpitNoseReflectPaint != null) {
      canvas.drawPath(_scratchPath, _cockpitNoseReflectPaint!);
    }

    // Crisp sun-tracking clearcoat specular streak + livery twin stripes + recessed vanity panel seam
    _strokePaint..color = Color.lerp(Colors.white, circuit.skyBottom, 0.24)!.withAlpha(190)..strokeWidth = 4.8;
    canvas.drawLine(Offset(cx + sunNormX * 9.0 + pxFar, nTipY + 5), Offset(cx + sunNormX * 16.0 + pxMid, nBaseY - 14), _strokePaint);
    _strokePaint..color = livery.secondary.withAlpha(242)..strokeWidth = 3.2;
