    _strokePaint..color = Color.lerp(Colors.white, circuit.skyBottom, 0.25)!.withAlpha(175)..strokeWidth = 2.1;
    _scratchPath
      ..reset()
      ..moveTo(-8, h * 0.126)
      ..quadraticBezierTo(cx + pxHalo * 0.30, h * 0.002, w + 8, h * 0.126);
    canvas.drawPath(_scratchPath, _strokePaint);
    _strokePaint..color = livery.secondary.withAlpha(205)..strokeWidth = 2.4;
    _scratchPath
      ..reset()
      ..moveTo(w * 0.10, h * 0.088)
      ..quadraticBezierTo(cx + pxHalo * 0.30, h * 0.000, w * 0.90, h * 0.088);
    canvas.drawPath(_scratchPath, _strokePaint);

    // 3D Sculpted FIA Onboard Halo Camera Housing Pod with Reflective Glass Lens!
    final Offset camPodC = Offset(pilTopX, h * 0.142);
    final RRect camPod = RRect.fromRectAndRadius(Rect.fromCenter(center: camPodC, width: 24, height: 30), const Radius.circular(6));
    canvas.drawRRect(camPod, carbonPaint);
    _strokePaint..color = const Color(0x889EB4CE)..strokeWidth = 1.4;
    canvas.drawRRect(camPod, _strokePaint);
    // Recessed optical lens + cyan glass anti-reflective glint
    _fillPaint.color = const Color(0xFF05070C);
    canvas.drawCircle(Offset(camPodC.dx, camPodC.dy + 2), 6.2, _fillPaint);
    _fillPaint.color = const Color(0xAA29B6F6);
    canvas.drawCircle(Offset(camPodC.dx - 1.6, camPodC.dy + 0.4), 2.1, _fillPaint);

    // Real-Time Monaco Tunnel, Yas Hotel, Overhead Bridge Shadow & Night Stadium Floodlight Sweep across 3D Cockpit!
    if (engine.smoothBridgeShade > 0.02) {
      final int shadeA = (engine.smoothBridgeShade * 82).clamp(0.0, 128.0).toInt();
      _fillPaint.color = Color.fromARGB(shadeA, 4, 7, 14);
      canvas.drawRect(Rect.fromLTWH(0, 0, w, h), _fillPaint);
    }
    if (engine.smoothFloodGlow > 0.02) {
      final bool warmTunnel = circuit.code == 'MON';
      final int glowA = (engine.smoothFloodGlow * (warmTunnel ? 44 : 50)).clamp(0.0, 80.0).toInt();
      _fillPaint.color = warmTunnel
          ? Color.fromARGB(glowA, 255, 214, 140)
          : Color.fromARGB(glowA, 200, 236, 255);
      canvas.drawRect(Rect.fromLTWH(0, h * 0.56, w, h * 0.44), _fillPaint);
      // Moving overhead lamp specular ribbon gliding over the nosecone & monocoque lacquer!
      final double sweepFrac = _posMod(engine.playerDist * 0.09, 1.0);
      final double sweepY = h * (0.58 + sweepFrac * 0.19) + vib;
      _strokePaint
        ..color = warmTunnel
            ? Color.fromARGB((glowA * 1.25).clamp(0.0, 120.0).toInt(), 255, 230, 165)
            : Color.fromARGB((glowA * 1.25).clamp(0.0, 120.0).toInt(), 220, 246, 255)
        ..strokeWidth = 6.5;
      canvas.drawLine(Offset(w * 0.24, sweepY), Offset(w * 0.76, sweepY), _strokePaint);
    }
    // Delicate cyan MGU-K / ERS cockpit rim bounce when deploying ERS Boost!
    if (engine.ersActive) {
      _strokePaint
        ..color = const Color(0x4A00E5FF)
        ..strokeWidth = 4.0;
      canvas.drawLine(Offset(w * 0.30, h * 0.735 + vib), Offset(w * 0.70, h * 0.735 + vib), _strokePaint);
    }

    canvas.restore();

    // =========================================================================
    // LAYER 6 (PILOT EYEPORT): HELMET VISOR SUN-STRIP, CURVED VISOR OPTICS & TEAR-OFF TAB
    // =========================================================================
    if (_visorStripPaint != null) {
      canvas.drawRect(Rect.fromLTWH(0, 0, w, h * 0.045), _visorStripPaint!);
    }
    _strokePaint
      ..color = Color.lerp(Colors.white, circuit.skyBottom, 0.42)!.withAlpha(circuit.nightMode ? 32 : 46)
      ..strokeWidth = 2.6;
    _scratchPath
      ..reset()
      ..moveTo(w * 0.02, h * 0.17)
      ..quadraticBezierTo(w * 0.06, h * 0.055, w * 0.19, h * 0.032);
    canvas.drawPath(_scratchPath, _strokePaint);
    _scratchPath
      ..reset()
      ..moveTo(w * 0.98, h * 0.17)
      ..quadraticBezierTo(w * 0.94, h * 0.055, w * 0.81, h * 0.032);
    canvas.drawPath(_scratchPath, _strokePaint);
    // Delicate Optical Visor Rim Sun-Glint (pre-cached shader -> ZERO per-frame GPU alloc!)
    if (!circuit.nightMode && _visorGlarePaint != null) {
      final double sunAlign = (1.0 - sunNormX.abs()).clamp(0.0, 1.0).toDouble();
      if (sunAlign > 0.25) {
        final double gx = w * (0.5 + sunNormX * 0.32);
        _visorGlarePaint!.color = Color.fromARGB((255 * sunAlign).clamp(0.0, 255.0).toInt(), 255, 255, 255);
        canvas.save();
        canvas.translate(gx, h * 0.042);
        canvas.scale((w * 0.36 * sunAlign) / 240.0, (h * 0.065) / 48.0);
        canvas.drawOval(const Rect.fromLTWH(-120.0, -24.0, 240.0, 48.0), _visorGlarePaint!);
        canvas.restore();
      }
    }

    // Translucent polycarbonate Visor Tear-Off Pull-Tab on far upper-left helmet edge
    _fillPaint.color = const Color(0x34E0F4FF);
    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(w * 0.012, h * 0.195, 16, 11), const Radius.circular(3)), _fillPaint);
    _strokePaint..color = const Color(0x5EFFFFFF)..strokeWidth = 1.0;
    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(w * 0.012, h * 0.195, 16, 11), const Radius.circular(3)), _strokePaint);
  }

  void _drawSideMirrorUltra(Canvas canvas, Offset pos, bool isLeft, bool rivalBehind, CircuitInfo circuit, double sunNormX) {
    final TeamLivery livery = engine.livery;
    final double dir = isLeft ? -1.0 : 1.0;

    // Soft cast shadow of mirror pod onto the cowling shoulder below!
    _fillPaint.color = const Color(0x5C000000);
    canvas.drawOval(Rect.fromCenter(center: Offset(pos.dx - sunNormX * 6.0, pos.dy + 22), width: 54, height: 11), _fillPaint);

    // Sculpted 3D twin carbon aerodynamic mirror stalks + horizontal stay winglet
    _strokePaint..color = const Color(0xFF0E121A)..strokeWidth = 5.6..strokeCap = StrokeCap.round;
    canvas.drawLine(Offset(pos.dx - dir * 13, pos.dy + 22), Offset(pos.dx, pos.dy + 5), _strokePaint);
    _strokePaint..color = const Color(0xFF2B3548)..strokeWidth = 2.8;
    canvas.drawLine(Offset(pos.dx + dir * 10, pos.dy + 19), Offset(pos.dx + dir * 14, pos.dy + 3), _strokePaint);
    _strokePaint..color = const Color(0x55C8D8EE)..strokeWidth = 1.1;
    canvas.drawLine(Offset(pos.dx - dir * 12, pos.dy + 20), Offset(pos.dx + dir * 1, pos.dy + 5), _strokePaint);

    // 3D Extruded Mirror Shell (dark outer depth rim + painted aero casing + top sky specular highlight)
    final RRect shellDepth = RRect.fromRectAndRadius(Rect.fromCenter(center: Offset(pos.dx - dir * 2.2, pos.dy - 1.5), width: 62, height: 26), const Radius.circular(10));
    _fillPaint.color = const Color(0xFF0B0E15);
    canvas.drawRRect(shellDepth, _fillPaint);

    final RRect shell = RRect.fromRectAndRadius(Rect.fromCenter(center: pos, width: 60, height: 25), const Radius.circular(9.5));
    if (_cockpitMirrorShellPaint != null) {
      canvas.save();
      canvas.translate(pos.dx, pos.dy);
      canvas.drawRRect(RRect.fromRectAndRadius(const Rect.fromLTWH(-30.0, -12.5, 60.0, 25.0), const Radius.circular(9.5)), _cockpitMirrorShellPaint!);
      canvas.restore();
    }
    _strokePaint..color = const Color(0x66FFFFFF)..strokeWidth = 1.2;
    canvas.drawRRect(shell, _strokePaint);

    final RRect glassRRect = RRect.fromRectAndRadius(
      Rect.fromCenter(center: Offset(pos.dx, pos.dy + 1.2), width: 49, height: 15.5),
      const Radius.circular(5),
    );
    final Rect glass = glassRRect.outerRect;
    canvas.save();
    canvas.clipRRect(glassRRect);
    canvas.translate(pos.dx, pos.dy + 1.2);
    canvas.rotate(-engine.smoothCamBank * 1.45);
    if (_cockpitMirrorGlassPaint != null) {
      canvas.drawRect(const Rect.fromLTWH(-28.5, -11.75, 57.0, 23.5), _cockpitMirrorGlassPaint!);
    }
    canvas.translate(-pos.dx, -(pos.dy + 1.2));
    // Live moving kerb & white track line reflection inside the mirror!
    final double reflShift = (-engine.carX * 8.0) - (engine.steerAngle * 5.0);
    final bool kerbAlt = ((engine.playerDist / 3.5).floor() % 2 == 0);
    _strokePaint
      ..color = kerbAlt ? circuit.kerbA : Colors.white
      ..strokeWidth = 2.2;
    canvas.drawLine(
      Offset(pos.dx + dir * 8 + reflShift * 0.4, pos.dy + 1.8),
      Offset(pos.dx + dir * 18 + reflShift, glass.bottom + 2),
      _strokePaint,
    );
    // Diagonal anti-glare glass specular streak
    _strokePaint..color = const Color(0x4EFFFFFF)..strokeWidth = 2.6;
    canvas.drawLine(Offset(glass.left + 6, glass.top), Offset(glass.left + 16, glass.bottom), _strokePaint);
    if (rivalBehind) {
      // Reflected rival F1 nose/wing silhouette + pre-cached red proximity warning halo!
      _fillPaint.color = const Color(0xDD10141C);
      canvas.drawRect(Rect.fromCenter(center: Offset(pos.dx, pos.dy + 4.2), width: 13.0, height: 3.4), _fillPaint);
      if (_mirrorWarnGlowPaint != null) {
        canvas.save();
        canvas.translate(pos.dx, pos.dy + 2.8);
        canvas.drawCircle(Offset.zero, 9.5, _mirrorWarnGlowPaint!);
        canvas.restore();
      }
      _fillPaint.color = const Color(0xFFFFE5E8);
      canvas.drawCircle(Offset(pos.dx, pos.dy + 2.8), 2.8, _fillPaint);
    }
    canvas.restore();
    // Crisp recessed metallic mirror bezel + upper carbon aero vane lip
    _strokePaint..color = const Color(0xBB05070B)..strokeWidth = 2.2;
    canvas.drawRRect(glassRRect.inflate(0.8), _strokePaint);
    _strokePaint..color = rivalBehind ? const Color(0xFFFF1744) : const Color(0xCCE2ECF8)..strokeWidth = 1.3;
    canvas.drawRRect(glassRRect, _strokePaint);
  }

  void _drawFrontTireUltra(Canvas canvas, Offset center, double tw, double th, bool isLeft, double sunNormX) {
    final double steer = engine.steerAngle;
    final double dir = isLeft ? 1.0 : -1.0;
    final bool onKerb = engine.carX.abs() > 0.85 && engine.carX.abs() <= 1.05;
    final double kerbJoltY = (onKerb && engine.speedKmh > 35.0) ? (sin(engine.playerDist * 4.8) * 3.4) : 0.0;

    canvas.save();
    canvas.translate(center.dx, center.dy + kerbJoltY);

    // 1. Grounded Asphalt Contact Shadow directly beneath the 3D Front Tire!
    _fillPaint.color = const Color(0x74000000);
    canvas.drawOval(Rect.fromCenter(center: Offset(-sunNormX * 8.0, th * 0.44), width: tw * 1.38, height: th * 0.24), _fillPaint);

    canvas.rotate(steer * 0.24);
    canvas.skew(steer * 0.12, 0.0);

    final RRect tireRect = RRect.fromRectAndRadius(Rect.fromCenter(center: Offset.zero, width: tw, height: th), const Radius.circular(26));

    // 2. Sculpted 3D Inner Carbon Brake Duct Scoop + Metallic Intake Mesh tucked behind inner wheel shoulder!
    final Rect brakeDrum = Rect.fromCenter(center: Offset(dir * tw * 0.45, 0), width: tw * 0.28, height: th * 0.64);
    _fillPaint.color = const Color(0xFF0E121A);
    canvas.drawRRect(RRect.fromRectAndRadius(brakeDrum, const Radius.circular(9)), _fillPaint);
    _strokePaint..color = const Color(0x668AA0BD)..strokeWidth = 1.5;
    canvas.drawRRect(RRect.fromRectAndRadius(brakeDrum, const Radius.circular(9)), _strokePaint);
    // Recessed brake cooling scoop slot on inner face
    _fillPaint.color = const Color(0xFF04060A);
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromCenter(center: Offset(dir * tw * 0.50, -th * 0.08), width: tw * 0.11, height: th * 0.28), const Radius.circular(4)),
      _fillPaint,
    );

    // 3. Exposed Outer/Inner 3D Tire Sidewall Crescent + Wheel Rim Barrel + Metallic Center Lock-Nut when turning!
    final double sideExpose = (steer * dir * 20.0).clamp(-16.0, 18.0).toDouble();
    if (sideExpose.abs() > 1.2) {
      final double sideX = sideExpose > 0 ? (-tw * 0.48) : (tw * 0.48);
      final Rect sideOval = Rect.fromCenter(center: Offset(sideX, 0), width: sideExpose.abs() * 1.45 + 11.0, height: th * 0.89);
      _fillPaint.color = const Color(0xFF0C1018);
      canvas.drawOval(sideOval, _fillPaint);
      // Inner aero carbon wheel cover disc
      _fillPaint.color = const Color(0xFF1B2230);
      canvas.drawOval(sideOval.deflate(6.0), _fillPaint);
      final double rollPhase = engine.playerDist / 0.30;
      _strokePaint
        ..color = const Color(0xFFE50914)
        ..strokeWidth = 3.8
        ..strokeCap = StrokeCap.round;
      canvas.drawArc(sideOval.deflate(3.8), rollPhase, 1.35, false, _strokePaint);
      canvas.drawArc(sideOval.deflate(3.8), rollPhase + pi, 1.35, false, _strokePaint);
      // Machined metallic wheel center-lock nut
      _fillPaint.color = const Color(0xFFBBD0E8);
      canvas.drawCircle(Offset(sideX, 0), 3.8, _fillPaint);
    }

    // 4. Real-Life Thermal Carbon Brake Disc Glow (pre-cached radial shaders -> ZERO braking-zone stutters!)
    if (engine.smoothBrakeHeat > 0.08) {
      final double heat = engine.smoothBrakeHeat.clamp(0.0, 1.0).toDouble();
      final Offset discCenter = Offset(isLeft ? tw * 0.47 : -tw * 0.47, 0);
      final double dr = tw * (0.28 + 0.24 * heat);
      if (_brakeGlowPaint != null) {
        _brakeGlowPaint!.color = Color.fromARGB((255 * heat).clamp(0.0, 255.0).toInt(), 255, 255, 255);
        canvas.save();
        canvas.translate(discCenter.dx, discCenter.dy);
        final double sc = dr / 48.0;
        canvas.scale(sc, sc);
        canvas.drawCircle(Offset.zero, 48.0, _brakeGlowPaint!);
        canvas.restore();
      }
      final double rotorSpin = engine.playerDist / 0.18;
      _strokePaint
        ..color = Color.fromARGB((195 * heat).toInt(), 255, 224, 130)
        ..strokeWidth = 2.0;
      canvas.drawCircle(discCenter, dr * 0.56, _strokePaint);
      for (int sl = 0; sl < 6; sl++) {
        final double a = rotorSpin + sl * (pi / 3.0);
        canvas.drawLine(
          Offset(discCenter.dx + cos(a) * dr * 0.28, discCenter.dy + sin(a) * dr * 0.28),
          Offset(discCenter.dx + cos(a) * dr * 0.62, discCenter.dy + sin(a) * dr * 0.62),
          _strokePaint,
        );
      }
      if (engine.brakeHeld && heat > 0.52 && engine.speedKmh > 125 && _brakeSmokePaint != null) {
        final Offset smokeC = Offset(0, -th * 0.42);
        canvas.save();
        canvas.translate(smokeC.dx, smokeC.dy);
        final double scS = (tw * 0.46) / 48.0;
        canvas.scale(scS, scS);
        canvas.drawCircle(Offset.zero, 48.0, _brakeSmokePaint!);
        canvas.restore();
      }
    }

    // 5. True 3D Crowned Cylindrical Pirelli Slick Rubber Tread (pre-cached horizontal + vertical shaders!)
    if (_cockpitTireHorizPaint != null) {
      canvas.drawRRect(tireRect, _cockpitTireHorizPaint!);
    }

    // Vertical cylindrical curvature shading (pre-cached shader -> zero GPU alloc!)
    if (_cockpitTireVertPaint != null) {
      canvas.drawRRect(tireRect, _cockpitTireVertPaint!);
    }

    if (_tireTexPaint != null) {
      canvas.save();
      canvas.clipRRect(tireRect);
      final double rubScrollY = _posMod(engine.playerDist * 48.0, 245.76);
      canvas.translate(0, rubScrollY);
      canvas.drawRect(Rect.fromLTWH(-tw * 0.6, -th * 0.6 - 260.0, tw * 1.2, th * 1.2 + 520.0), _tireTexPaint!);
      canvas.restore();
    }
    // Photorealistic Sun-Tracking Satin Vulcanized Rubber Specular Highlight across Crowned Tire Shoulder!
    final double tireSpecX = (sunNormX * tw * 0.16).clamp(-tw * 0.22, tw * 0.22).toDouble();
    _fillPaint.color = Color.lerp(Colors.white, engine.circuit.skyBottom, 0.35)!.withAlpha(engine.circuit.nightMode ? 32 : 54);
    canvas.drawOval(Rect.fromCenter(center: Offset(tireSpecX, -th * 0.16), width: tw * 0.34, height: th * 0.52), _fillPaint);
    _fillPaint.color = Colors.white.withAlpha(engine.circuit.nightMode ? 22 : 38);
    canvas.drawOval(Rect.fromCenter(center: Offset(tireSpecX, -th * 0.22), width: tw * 0.16, height: th * 0.28), _fillPaint);

    // Crisp central vulcanized Pirelli slick mold parting rib + twin contact-patch sheen edges
    _strokePaint..color = const Color(0x5205070B)..strokeWidth = 1.8;
    canvas.drawLine(Offset(0, -th * 0.44), Offset(0, th * 0.44), _strokePaint);
    _strokePaint..color = const Color(0x36E6F0FF)..strokeWidth = 1.1;
    canvas.drawLine(Offset(1.5, -th * 0.43), Offset(1.5, th * 0.43), _strokePaint);

    // Velocity-locked rolling tread bands
    if (engine.speedKmh > 2.0) {
      final double phase = _posMod(engine.playerDist / (pi * 0.62), 1.0);
      for (int b = 0; b < 6; b++) {
        final double yFrac = ((b / 6.0 + phase) % 1.0) - 0.5;
        final double yy = yFrac * th * 0.88;
        final double edgeFade = (1.0 - (yFrac.abs() * 1.9)).clamp(0.0, 1.0).toDouble();
        _strokePaint
          ..color = (b % 2 == 0)
              ? Color.fromARGB((98 * edgeFade).toInt(), 0, 0, 0)
              : Color.fromARGB((58 * edgeFade).toInt(), 215, 228, 248)
          ..strokeWidth = (b % 2 == 0) ? 5.0 : 3.2;
        canvas.drawLine(Offset(-tw * 0.39, yy), Offset(tw * 0.39, yy), _strokePaint);
      }
    }

    // Inner Tire Shoulder Molding
    _strokePaint..color = const Color(0xFF141822)..strokeWidth = 7.4..strokeCap = StrokeCap.round;
    canvas.drawArc(
      Rect.fromCenter(center: Offset(dir * tw * 0.18, -th * 0.04), width: tw * 0.86, height: th * 0.96),
      isLeft ? -pi * 0.34 : pi * 0.66,
      pi * 0.68,
      false,
      _strokePaint,
    );

    // Cast shadow of Over-Wheel Aero Brow onto the rubber shoulder + 3D Carbon Brow Winglet!
    _scratchPath2
      ..reset()
      ..moveTo(dir * tw * 0.44, -th * 0.34)
      ..quadraticBezierTo(dir * tw * 0.58, -th * 0.16, dir * tw * 0.53, th * 0.09)
      ..lineTo(dir * tw * 0.36, th * 0.06)
      ..quadraticBezierTo(dir * tw * 0.42, -th * 0.14, dir * tw * 0.30, -th * 0.30)
      ..close();
    _fillPaint.color = const Color(0x66000000);
    canvas.drawPath(_scratchPath2, _fillPaint);

    _scratchPath2
      ..reset()
      ..moveTo(dir * tw * 0.48, -th * 0.36)
      ..quadraticBezierTo(dir * tw * 0.65, -th * 0.18, dir * tw * 0.60, th * 0.06)
      ..lineTo(dir * tw * 0.44, th * 0.04)
      ..quadraticBezierTo(dir * tw * 0.49, -th * 0.16, dir * tw * 0.36, -th * 0.32)
      ..close();
    _fillPaint.color = const Color(0xFF141923);
    canvas.drawPath(_scratchPath2, _fillPaint);
    _strokePaint..color = const Color(0xA8C0D4EE)..strokeWidth = 1.7;
    canvas.drawPath(_scratchPath2, _strokePaint);

    // Spinning Pirelli Soft Red Sidewall Marking + White Counter-Tick
    final double pPhase = engine.playerDist / 0.31;
    _strokePaint..color = const Color(0xFFE50914)..strokeWidth = 4.6;
    canvas.drawArc(
      Rect.fromCenter(center: Offset(dir * tw * 0.24, 0), width: tw * 0.48, height: th * 0.72),
      -pi * 0.38 + sin(pPhase) * 0.16,
      pi * 0.52,
      false,
      _strokePaint,
    );
    _strokePaint..color = const Color(0xCCF5F7FA)..strokeWidth = 2.4;
    canvas.drawArc(
      Rect.fromCenter(center: Offset(dir * tw * 0.24, 0), width: tw * 0.48, height: th * 0.72),
      pi * 0.30 + sin(pPhase) * 0.16,
      pi * 0.20,
      false,
      _strokePaint,
    );

    canvas.restore();
  }

  void _drawButterflyWheelUltra(
    Canvas canvas,
    double cx,
    double cy,
    double w,
    double h,
    Paint carbonPaint,
    double sunNormX,
  ) {
    final bool ersOn = engine.ersActive;
    final int rpm = engine.rpm;
    final int gear = engine.gear;
    final double kNow = _kappaAtWorldDist(engine.playerDist).abs();
    final double wheelRot = engine.steerAngle * 0.46 + engine.spinYaw * 0.5;
    final double swW = (w * 0.405).clamp(232.0, 368.0).toDouble();
    final double swH = (h * 0.330).clamp(128.0, 196.0).toDouble();

    // 1. Sculpted 3D Fireproof Nomex Driver Forearms extending organically from lower cockpit corners into wrists!
    final TeamLivery livery = engine.livery;
    final double cosR = cos(wheelRot);
    final double sinR = sin(wheelRot);
    for (final double sDir in const [-1.0, 1.0]) {
      final double localWristX = sDir * swW * 0.46;
      final double localWristY = swH * 0.40;
      final Offset wristWorld = Offset(
        cx + localWristX * cosR - localWristY * sinR,
        cy + localWristX * sinR + localWristY * cosR,
      );
      final Offset elbowWorld = Offset(cx + sDir * w * 0.31, h + 28.0);
      final double armHalfW = (swW * 0.088).clamp(18.0, 32.0).toDouble();
      _scratchPath3
        ..reset()
        ..moveTo(wristWorld.dx - armHalfW * 0.75, wristWorld.dy - 6)
        ..lineTo(wristWorld.dx + armHalfW * 0.75, wristWorld.dy - 6)
        ..lineTo(elbowWorld.dx + armHalfW * 1.15, elbowWorld.dy)
        ..lineTo(elbowWorld.dx - armHalfW * 1.15, elbowWorld.dy)
        ..close();
      final Paint? armP = sDir < 0 ? _cockpitArmLeftPaint : _cockpitArmRightPaint;
      if (armP != null) {
        canvas.drawPath(_scratchPath3, armP);
      }
      // Fireproof race-suit contrast piping stripe along forearm sleeve
      _strokePaint..color = livery.secondary.withAlpha(205)..strokeWidth = 2.8;
      canvas.drawLine(Offset(wristWorld.dx, wristWorld.dy), Offset(elbowWorld.dx, elbowWorld.dy), _strokePaint);
      _strokePaint..color = const Color(0x55000000)..strokeWidth = 2.0;
      canvas.drawPath(_scratchPath3, _strokePaint);
    }

    canvas.save();
    canvas.translate(cx, cy);
    canvas.rotate(wheelRot);

    // 2. Animated 3D Machined Carbon/Titanium Gear Shift Paddles + Lower Clutch Paddles!
    final double pullL = (engine.shiftKickTimer > 0 && !engine.shiftWasUp) ? 5.0 : 0.0;
    final double pullR = (engine.shiftKickTimer > 0 && engine.shiftWasUp) ? -5.0 : 0.0;
    final RRect padL = RRect.fromRectAndRadius(Rect.fromLTWH(-swW * 0.55 + pullL, -swH * 0.28, swW * 0.16, swH * 0.16), const Radius.circular(6));
    final RRect padR = RRect.fromRectAndRadius(Rect.fromLTWH(swW * 0.39 + pullR, -swH * 0.28, swW * 0.16, swH * 0.16), const Radius.circular(6));
    _fillPaint.color = const Color(0xFF1D2432);
    canvas.drawRRect(padL, _fillPaint);
    canvas.drawRRect(padR, _fillPaint);
    _strokePaint..color = const Color(0xCCB4C8E2)..strokeWidth = 1.5;
    canvas.drawRRect(padL, _strokePaint);
    canvas.drawRRect(padR, _strokePaint);

    // 3. Lossless Vector GPU Picture Cache for Static Wheel Chassis, Grips, Knobs & Function Buttons!
    // (100% vector sharpness, replaces ~115 draw calls + 9 TextPainter paints every frame with 1 drawPicture!)
    final bool hasTexNow = _carbonPaint != null && _alcantaraPaint != null && UltraTextures.brushedMetalShader != null;
    if (_staticWheelPicture == null ||
        _staticWheelW != swW ||
        _staticWheelH != swH ||
        (!_staticWheelHadTextures && hasTexNow)) {
      _staticWheelPicture?.dispose();
      _staticWheelW = swW;
      _staticWheelH = swH;
      _staticWheelHadTextures = hasTexNow;
      _staticWheelPicture = _recordStaticWheelPicture(swW, swH, carbonPaint);
    }
    canvas.drawPicture(_staticWheelPicture!);

    // Live RPM LED color spill onto carbon shift-light brow!
    final double spillRatio = ((rpm - 6500) / 7500.0).clamp(0.0, 1.0).toDouble();
    if (spillRatio > 0.08) {
      final Color spillCol = spillRatio < 0.45
          ? const Color(0xFF00E676)
          : (spillRatio < 0.78 ? const Color(0xFFFF1744) : const Color(0xFF2979FF));
      _fillPaint.color = spillCol.withAlpha((44 * spillRatio).toInt());
      canvas.drawOval(Rect.fromCenter(center: Offset(0, -swH * 0.32), width: swW * (0.20 + 0.30 * spillRatio), height: swH * 0.075), _fillPaint);
    }

    final double rpmRatio = ((rpm - 5800) / 8400.0).clamp(0.0, 1.0).toDouble();
    const int ledCount = 15;
    for (int i = 0; i < ledCount; i++) {
      final bool lit = (i / ledCount) < rpmRatio;
      final Color ledColor = i < 5
          ? const Color(0xFF00E676)
          : (i < 10 ? const Color(0xFFFF1744) : const Color(0xFF2979FF));
      final double lx = -swW * 0.22 + (i * (swW * 0.44 / (ledCount - 1)));
      final Offset lc = Offset(lx, -swH * 0.29);
      if (lit) {
        _fillPaint.color = ledColor.withAlpha(64);
        canvas.drawCircle(lc, 7.4, _fillPaint);
        _fillPaint.color = ledColor.withAlpha(132);
        canvas.drawCircle(lc, 4.7, _fillPaint);
      }
      _fillPaint.color = lit ? ledColor : const Color(0xFF1D232E);
      canvas.drawCircle(lc, 2.9, _fillPaint);
    }

    // Left & Right 3-LED FIA Marshal Flag Strips flanking the OLED Display!
    final Color flagLedCol = engine.startLightsTimer > 0
        ? const Color(0xFFFF1744)
        : (ersOn
            ? const Color(0xFF00E5FF)
            : (kNow > 0.018 ? const Color(0xFFFFD600) : const Color(0xFF00E676)));
    for (final double sDir in const [-1.0, 1.0]) {
      for (int m = 0; m < 3; m++) {
        final Offset mc = Offset(sDir * swW * 0.248, -swH * 0.13 + m * (swH * 0.105));
        _fillPaint.color = flagLedCol.withAlpha(58);
        canvas.drawCircle(mc, 5.8, _fillPaint);
        _fillPaint.color = flagLedCol;
        canvas.drawCircle(mc, 2.3, _fillPaint);
      }
    }

    // Live Authentic FIA F1 MFD OLED Display (Speed, Live Lap Time, Giant Gear, 4-Tyre Temps °C, Position & OVERTAKE Bar!)
    final Rect lcdRect = Rect.fromCenter(center: Offset(0, -swH * 0.01), width: swW * 0.448, height: swH * 0.448);
    final bool shiftAlert = rpm > 12400 && ((engine.totalRaceTime * 16.0).floor() % 2 == 0);
    if (shiftAlert) {
      _fillPaint.color = const Color(0x4C2979FF);
      canvas.drawRect(Rect.fromLTWH(lcdRect.left + 2, lcdRect.top + 2, lcdRect.width - 4, lcdRect.height * 0.24), _fillPaint);
    }
    final bool offTrackAlert = engine.isOffTrack && engine.startLightsTimer <= 0;
    _strokePaint
      ..color = offTrackAlert
          ? const Color(0xFFFFAB00)
          : (ersOn ? const Color(0xFF00E5FF) : (shiftAlert ? const Color(0xFF448AFF) : const Color(0xFF5D7291)))
      ..strokeWidth = offTrackAlert ? 2.2 : 1.8;
    canvas.drawRRect(RRect.fromRectAndRadius(lcdRect, const Radius.circular(5.5)), _strokePaint);

    // Subtle MFD interior horizontal & vertical divider hairlines (exact real F1 steering wheel grid!)
    _strokePaint..color = const Color(0x3894A3B8)..strokeWidth = 0.8;
    final double mfdRow1Y = lcdRect.top + lcdRect.height * 0.30;
    final double mfdBarTopY = lcdRect.bottom - lcdRect.height * 0.26;
    canvas.drawLine(Offset(lcdRect.left + 4, mfdRow1Y), Offset(lcdRect.right - 4, mfdRow1Y), _strokePaint);
    canvas.drawLine(Offset(lcdRect.left + lcdRect.width * 0.28, lcdRect.top + 3), Offset(lcdRect.left + lcdRect.width * 0.28, mfdBarTopY - 2), _strokePaint);
    canvas.drawLine(Offset(lcdRect.right - lcdRect.width * 0.28, lcdRect.top + 3), Offset(lcdRect.right - lcdRect.width * 0.28, mfdBarTopY - 2), _strokePaint);

    // Top Row: KPH (Left) | Live Lap Time (Center) | Position P1..P22 (Right)
    final double curLapSec = engine.phase == SessionPhase.qualifying
        ? engine.qualiElapsed
        : max(0.0, engine.totalRaceTime - engine.lapStartTime);
    final String lapShort = curLapSec < 60.0
        ? curLapSec.toStringAsFixed(3)
        : '${curLapSec ~/ 60}:${(curLapSec % 60).toStringAsFixed(2).padLeft(5, '0')}';
    _drawCenteredText(canvas, '${engine.speedKmh.toInt()}', Offset(lcdRect.left + lcdRect.width * 0.14, lcdRect.top + lcdRect.height * 0.13), swH * 0.088, Colors.white, FontWeight.w900);
    _drawCenteredText(canvas, 'KPH', Offset(lcdRect.left + lcdRect.width * 0.14, lcdRect.top + lcdRect.height * 0.24), swH * 0.044, const Color(0xFF94A3B8), FontWeight.w800);
    _drawCenteredText(canvas, lapShort, Offset(0, lcdRect.top + lcdRect.height * 0.15), swH * 0.082, Colors.white, FontWeight.w900);
    _drawCenteredText(
      canvas,
      engine.phase == SessionPhase.qualifying ? 'Q1' : 'P${engine.currentPosition}',
      Offset(lcdRect.right - lcdRect.width * 0.14, lcdRect.top + lcdRect.height * 0.15),
      swH * 0.088,
      const Color(0xFF40E5FF),
      FontWeight.w900,
    );

    // Center Row: Front/Rear Tyre Temps °C (Left & Right) + Giant Crisp Gear Digit (Center)
    final double tHeat = engine.smoothTireHeat.clamp(0.0, 1.0).toDouble();
    final int frontTemp = (82 + tHeat * 24).round();
    final int rearTemp = (86 + tHeat * 22).round();
    final Color tempCol = tHeat < 0.72 ? const Color(0xFFE2F5EA) : const Color(0xFFFFCC80);
    _drawCenteredText(canvas, '$frontTemp°C', Offset(lcdRect.left + lcdRect.width * 0.14, lcdRect.top + lcdRect.height * 0.44), swH * 0.056, tempCol, FontWeight.w800);
    _drawCenteredText(canvas, '$rearTemp°C', Offset(lcdRect.left + lcdRect.width * 0.14, lcdRect.top + lcdRect.height * 0.60), swH * 0.056, tempCol, FontWeight.w800);
    _drawCenteredText(canvas, '$frontTemp°C', Offset(lcdRect.right - lcdRect.width * 0.14, lcdRect.top + lcdRect.height * 0.44), swH * 0.056, tempCol, FontWeight.w800);
    _drawCenteredText(canvas, '$rearTemp°C', Offset(lcdRect.right - lcdRect.width * 0.14, lcdRect.top + lcdRect.height * 0.60), swH * 0.056, tempCol, FontWeight.w800);

    _drawCenteredText(
      canvas,
      '$gear',
      Offset(0, lcdRect.top + lcdRect.height * 0.51),
      swH * 0.215,
      shiftAlert ? const Color(0xFF80D8FF) : Colors.white,
      FontWeight.w900,
    );

    // Bottom Iconic F1 OVERTAKE / ERS Status Banner (Red-Amber-Yellow-Green segmented bar like F1 24!)
    final Rect ovtBar = Rect.fromLTWH(lcdRect.left + 4, mfdBarTopY, lcdRect.width - 8, lcdRect.bottom - mfdBarTopY - 3.5);
    _fillPaint.color = const Color(0xFF141A26);
    canvas.drawRRect(RRect.fromRectAndRadius(ovtBar, const Radius.circular(2.5)), _fillPaint);

    final double ersFrac = (engine.ersCharge / 100.0).clamp(0.0, 1.0).toDouble();
    final double fillW = ovtBar.width * ersFrac;
    if (fillW > 1.0) {
      if (ersOn) {
        _fillPaint.color = const Color(0xFF00E5FF);
        canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(ovtBar.left, ovtBar.top, fillW, ovtBar.height), const Radius.circular(2.0)), _fillPaint);
      } else {
        // Authentic 3-zone F1 OVERTAKE bar (Red left reserve -> Yellow/Amber mid -> Bright Green top charge)
        final double z1 = min(fillW, ovtBar.width * 0.20);
        final double z2 = max(0.0, min(fillW, ovtBar.width * 0.78) - ovtBar.width * 0.20);
        final double z3 = max(0.0, fillW - ovtBar.width * 0.78);
        if (z1 > 0) {
          _fillPaint.color = const Color(0xFFD52B1E);
          canvas.drawRect(Rect.fromLTWH(ovtBar.left, ovtBar.top, z1, ovtBar.height), _fillPaint);
        }
        if (z2 > 0) {
          _fillPaint.color = const Color(0xFFF6C627);
          canvas.drawRect(Rect.fromLTWH(ovtBar.left + ovtBar.width * 0.20, ovtBar.top, z2, ovtBar.height), _fillPaint);
        }
        if (z3 > 0) {
          _fillPaint.color = const Color(0xFF16C75E);
          canvas.drawRect(Rect.fromLTWH(ovtBar.left + ovtBar.width * 0.78, ovtBar.top, z3, ovtBar.height), _fillPaint);
        }
      }
    }
    _drawCenteredText(
      canvas,
      offTrackAlert
          ? 'TRACK LIMITS'
          : (ersOn ? 'OVERTAKE ON • ${engine.ersCharge.toInt()}%' : 'OVERTAKE ${engine.ersCharge.toInt()}%'),
      ovtBar.center,
      swH * 0.058,
      ersFrac > 0.25 ? const Color(0xFF070B12) : Colors.white,
      FontWeight.w900,
    );

    // Static rotary encoders & backlit function buttons are pre-baked in _staticWheelPicture!
    _drawRacingGloveUltra(canvas, swW, swH, true);
    _drawRacingGloveUltra(canvas, swW, swH, false);

    canvas.restore();
  }

  /// Records all static vector geometry of the F1 Butterfly Steering Wheel into a lossless GPU ui.Picture!
  ui.Picture _recordStaticWheelPicture(double swW, double swH, Paint carbonPaint) {
    final ui.PictureRecorder rec = ui.PictureRecorder();
    final Canvas c = Canvas(rec);

    _scratchPath2
      ..reset()
      ..moveTo(-swW * 0.42, -swH * 0.47)
      ..lineTo(-swW * 0.24, -swH * 0.47)
      ..lineTo(-swW * 0.18, -swH * 0.37)
      ..lineTo(swW * 0.18, -swH * 0.37)
      ..lineTo(swW * 0.24, -swH * 0.47)
      ..lineTo(swW * 0.42, -swH * 0.47)
      ..quadraticBezierTo(swW * 0.52, -swH * 0.45, swW * 0.50, -swH * 0.12)
      ..lineTo(swW * 0.47, swH * 0.37)
      ..quadraticBezierTo(swW * 0.44, swH * 0.49, swW * 0.24, swH * 0.47)
      ..lineTo(-swW * 0.24, swH * 0.47)
      ..quadraticBezierTo(-swW * 0.44, swH * 0.49, -swW * 0.47, swH * 0.37)
      ..lineTo(-swW * 0.50, -swH * 0.12)
      ..quadraticBezierTo(-swW * 0.52, -swH * 0.45, -swW * 0.42, -swH * 0.47)
      ..close();

    // Soft ambient occlusion shadow cast into cockpit tub behind steering wheel
    c.save();
    c.translate(0, 11.0);
    _fillPaint.color = const Color(0x6E000000);
    c.drawPath(_scratchPath2, _fillPaint);
    c.restore();

    // True 3D Extruded Carbon Side-Wall Thickness Slab
    c.save();
    c.translate(0, 6.2);
    _fillPaint.color = const Color(0xFF0A0D13);
    c.drawPath(_scratchPath2, _fillPaint);
    _strokePaint..color = const Color(0xFF3A475E)..strokeWidth = 2.0;
    c.drawPath(_scratchPath2, _strokePaint);
    c.restore();

    // Front Faceplate (2x2 Gloss Twill Carbon + Specular Sweep + Chamfered Edge)
    c.drawPath(_scratchPath2, carbonPaint);
    if (_cockpitWheelFaceSpecPaint != null) {
      c.drawPath(_scratchPath2, _cockpitWheelFaceSpecPaint!);
    }
    _strokePaint..color = const Color(0xFF8396B5)..strokeWidth = 2.6;
    c.drawPath(_scratchPath2, _strokePaint);

    // Sculpted Perforated Alcantara Side Steering Grips + CNC Machined Metallic Thumb-Wheel Rotaries
    if (_alcantaraPaint != null) {
      for (final double sDir in const [-1.0, 1.0]) {
        final RRect gripR = RRect.fromRectAndRadius(
          Rect.fromCenter(center: Offset(sDir * swW * 0.43, swH * 0.04), width: swW * 0.13, height: swH * 0.66),
          const Radius.circular(12),
        );
        c.drawRRect(gripR, _alcantaraPaint!);
      }
    }
    for (final double sDir in const [-1.0, 1.0]) {
      final RRect pocket = RRect.fromRectAndRadius(
        Rect.fromCenter(center: Offset(sDir * swW * 0.33, -swH * 0.41), width: swW * 0.105, height: swH * 0.095),
        const Radius.circular(4.0),
      );
      _fillPaint.color = const Color(0xCC04060A);
      c.drawRRect(pocket, _fillPaint);
      final RRect thumbWheel = RRect.fromRectAndRadius(
        Rect.fromCenter(center: Offset(sDir * swW * 0.33, -swH * 0.42), width: swW * 0.094, height: swH * 0.084),
        const Radius.circular(3.5),
      );
      if (UltraTextures.brushedMetalShader != null) {
        _gradPaint.shader = UltraTextures.brushedMetalShader;
        c.drawRRect(thumbWheel, _gradPaint);
      } else {
        _fillPaint.color = const Color(0xFF94A3B8);
        c.drawRRect(thumbWheel, _fillPaint);
      }
      _strokePaint..color = const Color(0xAA0D1118)..strokeWidth = 1.2;
      for (int kn = -2; kn <= 2; kn++) {
        final double kx = sDir * swW * 0.33 + kn * 4.2;
        c.drawLine(Offset(kx, -swH * 0.46), Offset(kx, -swH * 0.38), _strokePaint);
      }
    }

    // Vertical DIFF (Left) & TORQ (Right) Side Thumbwheel Housing Pods with 1-2-3-4 Scale Markings!
    for (final double sDir in const [-1.0, 1.0]) {
      final Rect podR = Rect.fromCenter(center: Offset(sDir * swW * 0.435, -swH * 0.25), width: swW * 0.072, height: swH * 0.26);
      _fillPaint.color = const Color(0xEE080B10);
      c.drawRRect(RRect.fromRectAndRadius(podR, const Radius.circular(4.0)), _fillPaint);
      _strokePaint..color = const Color(0x887C8FA8)..strokeWidth = 1.0;
      c.drawRRect(RRect.fromRectAndRadius(podR, const Radius.circular(4.0)), _strokePaint);
      final TextPainter lbl = _getCachedBoardText(sDir < 0 ? 'DIFF' : 'TORQ', 5.2, const Color(0xDDE8F0FA));
      lbl.paint(c, Offset(podR.center.dx - lbl.width * 0.5, podR.top + 2.0));
      for (int st = 0; st < 4; st++) {
        final double ty = podR.top + podR.height * (0.34 + st * 0.16);
        _strokePaint..color = st == 1 ? const Color(0xFFFF5252) : const Color(0x99B4C6DE)..strokeWidth = 1.3;
        c.drawLine(Offset(podR.left + 3.0, ty), Offset(podR.right - 3.0, ty), _strokePaint);
      }
    }

    // 8 CNC Machined Titanium Allen Hex Bolts around MFD Carbon Faceplate
    for (final Offset bPos in [
      Offset(-swW * 0.23, -swH * 0.35),
      Offset(swW * 0.23, -swH * 0.35),
      Offset(-swW * 0.255, -swH * 0.12),
      Offset(swW * 0.255, -swH * 0.12),
      Offset(-swW * 0.255, swH * 0.14),
      Offset(swW * 0.255, swH * 0.14),
      Offset(-swW * 0.21, swH * 0.39),
      Offset(swW * 0.21, swH * 0.39),
    ]) {
      _fillPaint.color = const Color(0xFF0A0D14);
      c.drawCircle(bPos, 3.4, _fillPaint);
      _fillPaint.color = const Color(0xFFB8C9E0);
      c.drawCircle(bPos, 2.2, _fillPaint);
      _fillPaint.color = const Color(0xFF151A24);
      c.drawCircle(bPos, 1.0, _fillPaint);
    }

    // 3D Hooded Carbon Shift-Light Brow Housing
    final RRect ledBezel = RRect.fromRectAndRadius(
      Rect.fromCenter(center: Offset(0, -swH * 0.29), width: swW * 0.50, height: swH * 0.092),
      const Radius.circular(5.0),
    );
    _fillPaint.color = const Color(0xEE05070B);
    c.drawRRect(ledBezel, _fillPaint);
    _strokePaint..color = const Color(0xAA9DB2CE)..strokeWidth = 2.0;
    c.drawLine(Offset(-swW * 0.24, -swH * 0.335), Offset(swW * 0.24, -swH * 0.335), _strokePaint);
    _strokePaint..color = const Color(0x777E92AE)..strokeWidth = 1.1;
    c.drawRRect(ledBezel, _strokePaint);

    // 3D Recessed High-Contrast Anti-Glare OLED Housing + Curved Glass Glare
    final Rect lcdOuter = Rect.fromCenter(center: Offset(0, -swH * 0.01), width: swW * 0.47, height: swH * 0.475);
    _fillPaint.color = const Color(0xFF0A0E16);
    c.drawRRect(RRect.fromRectAndRadius(lcdOuter, const Radius.circular(7.5)), _fillPaint);
    final Rect lcdRect = Rect.fromCenter(center: Offset(0, -swH * 0.01), width: swW * 0.448, height: swH * 0.448);
    _fillPaint.color = const Color(0xFF030509);
    c.drawRRect(RRect.fromRectAndRadius(lcdRect, const Radius.circular(5.5)), _fillPaint);
    if (_cockpitWheelLcdGlarePaint != null) {
      c.drawRRect(RRect.fromRectAndRadius(lcdRect, const Radius.circular(5.5)), _cockpitWheelLcdGlarePaint!);
    }

    // Iconic F1 Multi-Color Segmented TYRE Rotary Dial + Flanking FUEL / MFB / STRAT Encoders!
    final Offset tyreC = Offset(-swW * 0.065, swH * 0.315);
    final double tyreR = swH * 0.105;
    _fillPaint.color = const Color(0xBB000000);
    c.drawCircle(Offset(tyreC.dx, tyreC.dy + 3.0), tyreR + 2.0, _fillPaint);
    const List<Color> tyreSegs = [
      Color(0xFF00B0FF),
      Color(0xFF00E676),
      Color(0xFFFFD600),
      Color(0xFFFF1744),
      Color(0xFFE2ECF8),
      Color(0xFF2979FF),
    ];
    final Rect tyreArcR = Rect.fromCircle(center: tyreC, radius: tyreR);
    _strokePaint..strokeWidth = swH * 0.040..strokeCap = StrokeCap.butt;
    for (int s = 0; s < tyreSegs.length; s++) {
      _strokePaint.color = tyreSegs[s];
      c.drawArc(tyreArcR, -pi + s * (pi * 2.0 / tyreSegs.length), (pi * 2.0 / tyreSegs.length) - 0.08, false, _strokePaint);
    }
    _fillPaint.color = const Color(0xFF151C28);
    c.drawCircle(tyreC, tyreR * 0.68, _fillPaint);
    _strokePaint..color = const Color(0xCC9EB4CE)..strokeWidth = 1.2;
    c.drawCircle(tyreC, tyreR * 0.68, _strokePaint);
    final TextPainter tyreTp = _getCachedBoardText('TYRE', 5.4, Colors.white);
    tyreTp.paint(c, Offset(tyreC.dx - tyreTp.width * 0.5, tyreC.dy - tyreTp.height * 0.5));

    // Secondary F1 Rotary Encoders (STRAT, FUEL, MFB)
    const List<Color> knobColors = [Color(0xFFD91E18), Color(0xFF2B3548), Color(0xFF2E7D32)];
    const List<String> knobLabels = ['STRAT', 'FUEL', 'MFB'];
    final List<Offset> knobCenters = [
      Offset(swW * 0.095, swH * 0.315),
      Offset(-swW * 0.205, swH * 0.355),
      Offset(swW * 0.205, swH * 0.355),
    ];
    for (int k = 0; k < 3; k++) {
      final Offset kc = knobCenters[k];
      final double kr = k == 0 ? swH * 0.082 : swH * 0.068;
      _fillPaint.color = const Color(0xAA000000);
      c.drawCircle(Offset(kc.dx, kc.dy + 2.5), kr + 1.0, _fillPaint);
      _fillPaint.color = const Color(0xFF8A9BB2);
      c.drawCircle(kc, kr, _fillPaint);
      _fillPaint.color = knobColors[k];
      c.drawCircle(kc, kr * 0.80, _fillPaint);
      _strokePaint..color = const Color(0x88DCE8F8)..strokeWidth = 0.9;
      for (int tk = 0; tk < 8; tk++) {
        final double ta = (tk * pi * 0.25);
        c.drawLine(
          Offset(kc.dx + cos(ta) * kr * 0.78, kc.dy + sin(ta) * kr * 0.78),
          Offset(kc.dx + cos(ta) * kr * 0.98, kc.dy + sin(ta) * kr * 0.98),
          _strokePaint,
        );
      }
      _fillPaint.color = const Color(0xFF0E121A);
      c.drawCircle(kc, kr * 0.42, _fillPaint);
      _strokePaint..color = const Color(0xF5FFFFFF)..strokeWidth = 1.6;
      final double tickAng = -pi * 0.70 + k * 0.65;
      c.drawLine(kc, Offset(kc.dx + cos(tickAng) * kr * 0.78, kc.dy + sin(tickAng) * kr * 0.78), _strokePaint);
      final TextPainter ktp = _getCachedBoardText(knobLabels[k], 5.2, const Color(0xCCF0F6FF));
      ktp.paint(c, Offset(kc.dx - ktp.width * 0.5, kc.dy + kr + 1.2));
    }

    // 8 Pro-Spec Color-Coded Backlit F1 Steering Wheel Function Buttons (exact reference layout!)
    _drawWheelButton(c, Offset(-swW * 0.34, -swH * 0.32), const Color(0xFF00E676), 'N');
    _drawWheelButton(c, Offset(swW * 0.34, -swH * 0.32), const Color(0xFFFF1744), 'PIT');
    _drawWheelButton(c, Offset(-swW * 0.31, -swH * 0.14), const Color(0xFFE8F0FA), '+10');
    _drawWheelButton(c, Offset(swW * 0.31, -swH * 0.14), const Color(0xFFE8F0FA), '+1');
    _drawWheelButton(c, Offset(-swW * 0.30, swH * 0.04), const Color(0xFFFF5252), 'OVT');
    _drawWheelButton(c, Offset(swW * 0.30, swH * 0.04), const Color(0xFFFFD600), 'DRS');
    _drawWheelButton(c, Offset(-swW * 0.29, swH * 0.21), const Color(0xFF00E5FF), 'RAD');
    _drawWheelButton(c, Offset(swW * 0.29, swH * 0.21), const Color(0xFF26C6DA), 'BB');

    return rec.endRecording();
  }

  void _drawWheelButton(Canvas canvas, Offset center, Color color, String label) {
    // 3D raised collar drop shadow
    _fillPaint.color = const Color(0x99000000);
    canvas.drawCircle(Offset(center.dx, center.dy + 2.2), 7.6, _fillPaint);
    _fillPaint.color = color.withAlpha(56);
    canvas.drawCircle(center, 9.8, _fillPaint);
    // Crisp CNC machined metallic button shroud ring + specular bevel
    _fillPaint.color = const Color(0xFF7488A6);
    canvas.drawCircle(center, 7.3, _fillPaint);
    _strokePaint..color = const Color(0x88FFFFFF)..strokeWidth = 0.9;
    canvas.drawCircle(center, 7.1, _strokePaint);
    _fillPaint.color = const Color(0xFF0B0E14);
    canvas.drawCircle(center, 6.1, _fillPaint);
    _fillPaint.color = color;
