  }

  void _drawRacingGloveUltra(Canvas canvas, double swW, double swH, bool isLeft) {
    final TeamLivery livery = engine.livery;
    final double s = isLeft ? -1.0 : 1.0;
    final bool shiftingThisHand = engine.shiftKickTimer > 0.0 && (isLeft != engine.shiftWasUp);
    final double gripOffset = shiftingThisHand ? (-s * 2.8) : 0.0;

    final Rect palmRect = Rect.fromCenter(center: Offset(s * swW * 0.455 + gripOffset, swH * 0.16), width: swW * 0.235, height: swH * 0.65);

    // Soft cast shadow of gloved hand onto the carbon steering wheel rim!
    _fillPaint.color = const Color(0x66000000);
    canvas.drawRRect(RRect.fromRectAndRadius(palmRect.shift(Offset(-s * 3.5, 4.0)), const Radius.circular(20)), _fillPaint);

    // Sculpted 3D Nomex glove palm & cuff (pre-cached shader -> ZERO per-frame GPU shader alloc!)
    final Paint glovePaint = (isLeft ? _cockpitGloveLeftPaint : _cockpitGloveRightPaint) ?? (_fillPaint..color = livery.gloveColor);
    canvas.drawRRect(RRect.fromRectAndRadius(palmRect, const Radius.circular(20)), glovePaint);
    _strokePaint..color = const Color(0x66000000)..strokeWidth = 2.0;
    canvas.drawRRect(RRect.fromRectAndRadius(palmRect, const Radius.circular(20)), _strokePaint);

    // Sculpted 3D wrapped index & middle finger pads curling over the top-outer grip!
    for (int f = 0; f < 3; f++) {
      final Rect fingerR = Rect.fromCenter(
        center: Offset(s * swW * 0.405 + gripOffset, -swH * 0.13 + f * (swH * 0.11)),
        width: swW * 0.115,
        height: swH * 0.095,
      );
      canvas.drawRRect(RRect.fromRectAndRadius(fingerR, const Radius.circular(8)), glovePaint);
      _strokePaint..color = const Color(0x5A000000)..strokeWidth = 1.4;
      canvas.drawRRect(RRect.fromRectAndRadius(fingerR, const Radius.circular(8)), _strokePaint);
    }

    // Sculpted 3D Thumb wrapping naturally inward toward DRS/OVT controls with cast shadow!
    final RRect thumb = RRect.fromRectAndRadius(
      Rect.fromCenter(center: Offset(s * swW * 0.355 + gripOffset, -swH * 0.02), width: swW * 0.145, height: swH * 0.195),
      const Radius.circular(10),
    );
    _fillPaint.color = const Color(0x66000000);
    canvas.drawRRect(thumb.shift(const Offset(0, 3.0)), _fillPaint);
    canvas.drawRRect(thumb, glovePaint);
    _strokePaint..color = const Color(0x6A000000)..strokeWidth = 1.6;
    canvas.drawRRect(thumb, _strokePaint);

    // Molded 3D Carbon Knuckle Armor Guard + Contrast Stitched Wrist Strap!
    final RRect knucklePad = RRect.fromRectAndRadius(
      Rect.fromCenter(center: Offset(s * swW * 0.455 + gripOffset, swH * 0.07), width: swW * 0.17, height: swH * 0.12),
      const Radius.circular(6),
    );
    _fillPaint.color = const Color(0xE0111622);
    canvas.drawRRect(knucklePad, _fillPaint);
    _strokePaint..color = const Color(0x88FFFFFF)..strokeWidth = 1.3;
    canvas.drawRRect(knucklePad, _strokePaint);

    // Authentic F1 Pro-Glove Exterior White Racing Seams + White Nomex Wrist Cuff with Zig-Zag Stitching!
    _strokePaint..color = const Color(0xAAFFFFFF)..strokeWidth = 1.8..strokeCap = StrokeCap.round;
    canvas.drawLine(Offset(s * swW * 0.405 + gripOffset, swH * 0.14), Offset(s * swW * 0.485 + gripOffset, swH * 0.30), _strokePaint);
    canvas.drawLine(Offset(s * swW * 0.455 + gripOffset, swH * 0.15), Offset(s * swW * 0.520 + gripOffset, swH * 0.29), _strokePaint);

    // Crisp White Nomex Elastic Wrist Cuff Band (exact detail from F1 cockpit gloves!)
    final Rect cuffR = Rect.fromCenter(center: Offset(s * swW * 0.455 + gripOffset, swH * 0.375), width: swW * 0.205, height: swH * 0.088);
    _fillPaint.color = const Color(0xE8EEF4FC);
    canvas.drawRRect(RRect.fromRectAndRadius(cuffR, const Radius.circular(4.5)), _fillPaint);
    // Zig-zag exterior seam across the white cuff
    _strokePaint..color = const Color(0x88334155)..strokeWidth = 1.1;
    _scratchPath.reset();
    for (int z = 0; z <= 6; z++) {
      final double zx = cuffR.left + 4.0 + (cuffR.width - 8.0) * (z / 6.0);
      final double zy = cuffR.center.dy + (z.isEven ? -3.2 : 3.2);
      if (z == 0) {
        _scratchPath.moveTo(zx, zy);
      } else {
        _scratchPath.lineTo(zx, zy);
      }
    }
    canvas.drawPath(_scratchPath, _strokePaint);
    _strokePaint..color = livery.secondary.withAlpha(240)..strokeWidth = 2.4;
    canvas.drawLine(Offset(cuffR.left + 3, cuffR.top + 1.2), Offset(cuffR.right - 3, cuffR.top + 1.2), _strokePaint);
  }

  void _drawCenteredText(Canvas canvas, String text, Offset center, double fontSize, Color color, FontWeight weight) {
    final int fsBucket = fontSize.round().clamp(6, 48).toInt();
    final String key = '${text}_${fsBucket}_${color.hashCode}_${weight.index}';
    if (_wheelTextCache.length > 280) {
      _wheelTextCache.clear();
    }
    final TextPainter tp = _wheelTextCache.putIfAbsent(key, () {
      return TextPainter(
        text: TextSpan(text: text, style: TextStyle(color: color, fontSize: fsBucket.toDouble(), fontWeight: weight)),
        textDirection: TextDirection.ltr,
      )..layout();
    });
    tp.paint(canvas, Offset(center.dx - tp.width * 0.5, center.dy - tp.height * 0.5));
  }

  @override
  bool shouldRepaint(covariant F1UltraSmoothPainter oldDelegate) => false;
}

