package com.apexlife.apex_life_f1

import android.content.Context
import android.media.AudioAttributes
import android.os.Build
import android.os.Bundle
import android.view.WindowManager
import android.media.AudioFormat
import android.media.AudioManager
import android.media.AudioTrack
import android.os.Process
import io.flutter.embedding.android.FlutterActivity
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.MethodChannel
import kotlin.math.PI
import kotlin.math.max
import kotlin.math.min
import kotlin.math.sin

class MainActivity : FlutterActivity() {
    private val channelName = "f1_audio"
    private val prefsChannelName = "f1_prefs"
    private var synth: F1RealWaveguideV6Engine? = null

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        try {
            window.addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
                val lp = window.attributes
                lp.layoutInDisplayCutoutMode =
                    WindowManager.LayoutParams.LAYOUT_IN_DISPLAY_CUTOUT_MODE_SHORT_EDGES
                window.attributes = lp
            }
        } catch (_: Throwable) {
        }
    }

    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
        super.configureFlutterEngine(flutterEngine)
        val audioEngine = F1RealWaveguideV6Engine()
        synth = audioEngine

        MethodChannel(flutterEngine.dartExecutor.binaryMessenger, channelName)
            .setMethodCallHandler { call, result ->
                when (call.method) {
                    "update" -> {
                        val rpm = (call.argument<Number>("rpm")?.toDouble()) ?: 4200.0
                        val speed = (call.argument<Number>("speed")?.toDouble()) ?: 0.0
                        val throttle = call.argument<Boolean>("throttle") ?: false
                        val brake = call.argument<Boolean>("brake") ?: false
                        val ers = call.argument<Boolean>("ers") ?: false
                        val offTrack = call.argument<Boolean>("offTrack") ?: false
                        val onKerb = call.argument<Boolean>("onKerb") ?: false
                        val slip = (call.argument<Number>("slip")?.toDouble()) ?: 0.0
                        val active = call.argument<Boolean>("active") ?: false
                        val muted = call.argument<Boolean>("muted") ?: false
                        audioEngine.updateState(
                            rpm = rpm,
                            speed = speed,
                            throttle = throttle,
                            brake = brake,
                            ers = ers,
                            offTrack = offTrack,
                            onKerb = onKerb,
                            slip = slip,
                            active = active,
                            muted = muted
                        )
                        result.success(null)
                    }
                    "event" -> {
                        val type = call.argument<String>("type") ?: ""
                        val intensity = (call.argument<Number>("intensity")?.toDouble()) ?: 1.0
                        audioEngine.triggerEvent(type, intensity)
                        result.success(null)
                    }
                    "stop" -> {
                        audioEngine.silence()
                        result.success(null)
                    }
                    else -> result.notImplemented()
                }
            }

        val prefs = getSharedPreferences("apex_gp_24_prefs", Context.MODE_PRIVATE)
        MethodChannel(flutterEngine.dartExecutor.binaryMessenger, prefsChannelName)
            .setMethodCallHandler { call, result ->
                when (call.method) {
                    "load" -> {
                        val data = hashMapOf<String, Any>(
                            "steerSensitivity" to prefs.getFloat("steerSensitivity", 1.20f).toDouble(),
                            "analogSteeringMode" to prefs.getBoolean("analogSteeringMode", false),
                            "showRacingLine" to prefs.getBoolean("showRacingLine", true),
                            "soundEnabled" to prefs.getBoolean("soundEnabled", true),
                            "eco60FpsMode" to prefs.getBoolean("eco60FpsMode", true),
                            "aiDifficultyLevel" to prefs.getInt("aiDifficultyLevel", 2),
                            "cockpitCamera" to prefs.getBoolean("cockpitCamera", true),
                            "selectedLiveryIndex" to prefs.getInt("selectedLiveryIndex", 0),
                            "bestPositions" to (prefs.getString("bestPositions", "") ?: ""),
                            "pointsByRound" to (prefs.getString("pointsByRound", "") ?: "")
                        )
                        result.success(data)
                    }
                    "save" -> {
                        val editor = prefs.edit()
                        call.argument<Number>("steerSensitivity")?.let {
                            editor.putFloat("steerSensitivity", it.toFloat())
                        }
                        call.argument<Boolean>("analogSteeringMode")?.let {
                            editor.putBoolean("analogSteeringMode", it)
                        }
                        call.argument<Boolean>("showRacingLine")?.let {
                            editor.putBoolean("showRacingLine", it)
                        }
                        call.argument<Boolean>("soundEnabled")?.let {
                            editor.putBoolean("soundEnabled", it)
                        }
                        call.argument<Boolean>("eco60FpsMode")?.let {
                            editor.putBoolean("eco60FpsMode", it)
                        }
                        call.argument<Number>("aiDifficultyLevel")?.let {
                            editor.putInt("aiDifficultyLevel", it.toInt())
                        }
                        call.argument<Boolean>("cockpitCamera")?.let {
                            editor.putBoolean("cockpitCamera", it)
                        }
                        call.argument<Number>("selectedLiveryIndex")?.let {
                            editor.putInt("selectedLiveryIndex", it.toInt())
                        }
                        call.argument<String>("bestPositions")?.let {
                            editor.putString("bestPositions", it)
                        }
                        call.argument<String>("pointsByRound")?.let {
                            editor.putString("pointsByRound", it)
                        }
                        val syncFlush = call.argument<Boolean>("sync") ?: true
                        if (syncFlush) {
                            editor.commit()
                        } else {
                            editor.apply()
                        }
                        result.success(true)
                    }
                    else -> result.notImplemented()
                }
            }
    }

    override fun onPause() {
        synth?.setLifecyclePaused(true)
        super.onPause()
    }

    override fun onResume() {
        super.onResume()
        synth?.setLifecyclePaused(false)
    }

    override fun onDestroy() {
        synth?.release()
        synth = null
        super.onDestroy()
    }
}

private class F1RealWaveguideV6Engine {
    // 32 kHz studio audio rate (16 kHz Nyquist): crystal-clear F1 harmonics with 28% less CPU & heat!
    private val sampleRate = 32000
    private val twoPi = 2.0 * PI
    private val invTwoPiLut = 2048.0 / (2.0 * PI)
    private val sinLut = DoubleArray(2048) { idx -> sin((idx.toDouble() / 2048.0) * 2.0 * PI) }

    private fun fastSin(rad: Double): Double {
        val idx = (rad * invTwoPiLut).toInt() and 2047
        return sinLut[idx]
    }

    private fun fastCos(rad: Double): Double {
        val idx = ((rad * invTwoPiLut).toInt() + 512) and 2047
        return sinLut[idx]
    }

    private fun fastTanh(x: Double): Double {
        val c = x.coerceIn(-3.0, 3.0)
        val c2 = c * c
        return c * (27.0 + c2) / (27.0 + 9.0 * c2)
    }

    private fun fastExpNeg(posX: Double): Double {
        if (posX >= 10.0) return 0.0
        val t = 1.0 + posX * 0.125
        val t2 = t * t
        val t4 = t2 * t2
        return 1.0 / (t4 * t4)
    }

    @Volatile private var running = false
    @Volatile private var lifecyclePaused = false
    @Volatile private var muted = false
    @Volatile private var engineActive = false

    @Volatile private var targetRpm = 4200.0
    @Volatile private var targetSpeed = 0.0
    @Volatile private var targetThrottle = 0.0
    @Volatile private var targetBrake = 0.0
    @Volatile private var targetErs = 0.0
    @Volatile private var targetOffTrack = 0.0
    @Volatile private var targetOnKerb = 0.0
    @Volatile private var targetSlip = 0.0

    @Volatile private var crashEnv = 0.0
    @Volatile private var crashLowPitch = 92.0
    @Volatile private var upshiftEnv = 0.0
    @Volatile private var downshiftEnv = 0.0
    @Volatile private var wastegateLiftEnv = 0.0
    @Volatile private var ersBoostEnv = 0.0
    @Volatile private var cueEnv = 0.0
    @Volatile private var cueFreq = 220.0
    @Volatile private var cueIsDouble = false

    private var audioThread: Thread? = null

    fun setLifecyclePaused(paused: Boolean) {
        lifecyclePaused = paused
    }

    fun silence() {
        engineActive = false
        targetThrottle = 0.0
        targetBrake = 0.0
        targetErs = 0.0
        targetOffTrack = 0.0
        targetOnKerb = 0.0
        targetSlip = 0.0
    }

    fun updateState(
        rpm: Double,
        speed: Double,
        throttle: Boolean,
        brake: Boolean,
        ers: Boolean,
        offTrack: Boolean,
        onKerb: Boolean,
        slip: Double,
        active: Boolean,
        muted: Boolean
    ) {
        this.muted = muted
        this.engineActive = active
        this.targetRpm = rpm.coerceIn(3800.0, 14500.0)
        this.targetSpeed = speed.coerceIn(0.0, 380.0)
        this.targetThrottle = if (throttle) 1.0 else 0.0
        this.targetBrake = if (brake && speed > 45.0) 1.0 else 0.0
        this.targetErs = if (ers) 1.0 else 0.0
        this.targetOffTrack = if (offTrack && speed > 18.0) 1.0 else 0.0
        this.targetOnKerb = if (onKerb && speed > 35.0) 1.0 else 0.0
        this.targetSlip = if (!offTrack && speed > 55.0) slip.coerceIn(0.0, 1.0) else 0.0

        if (active && !muted) {
            ensureStarted()
        }
    }

    fun triggerEvent(type: String, intensity: Double) {
        if (muted || lifecyclePaused) return
        ensureStarted()
        when (type) {
            "upshift" -> {
                upshiftEnv = 1.0
            }
            "downshift" -> {
                downshiftEnv = 1.0
            }
            "shift" -> {
                upshiftEnv = 0.85
            }
            "wastegate" -> {
                wastegateLiftEnv = 1.0
            }
            "ers" -> {
                ersBoostEnv = 0.90
            }
            "crash" -> {
                crashLowPitch = 92.0
                crashEnv = max(crashEnv, intensity.coerceIn(0.50, 1.0))
            }
            "light" -> {
                cueFreq = 220.0
                cueIsDouble = false
                cueEnv = 0.45
            }
            "go" -> {
                cueFreq = 440.0
                cueIsDouble = true
                cueEnv = 0.62
            }
            "lap" -> {
                cueFreq = 392.0
                cueIsDouble = true
                cueEnv = 0.40
            }
            "finish" -> {
                cueFreq = 523.25
                cueIsDouble = true
                cueEnv = 0.56
            }
        }
    }

    @Synchronized
    private fun ensureStarted() {
        if (running) return
        running = true
        val t = Thread({
            try {
                Process.setThreadPriority(Process.THREAD_PRIORITY_AUDIO)
            } catch (_: Throwable) {
            }
            runAudioLoop()
        }, "F1RealWaveguideV6Thread")
        t.start()
        audioThread = t
    }

    @Synchronized
    fun release() {
        running = false
        try {
            audioThread?.join(250)
        } catch (_: Throwable) {
        }
        audioThread = null
    }

    private fun runAudioLoop() {
        var track: AudioTrack? = null
        try {
            val minBuf = AudioTrack.getMinBufferSize(
                sampleRate,
                AudioFormat.CHANNEL_OUT_MONO,
                AudioFormat.ENCODING_PCM_16BIT
            )
            val bufBytes = max(minBuf * 2, 4096)
            val attrs = AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_GAME)
                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                .build()
            val format = AudioFormat.Builder()
                .setEncoding(AudioFormat.ENCODING_PCM_16BIT)
                .setSampleRate(sampleRate)
                .setChannelMask(AudioFormat.CHANNEL_OUT_MONO)
                .build()
            track = AudioTrack(
                attrs,
                format,
                bufBytes,
                AudioTrack.MODE_STREAM,
                AudioManager.AUDIO_SESSION_ID_GENERATE
            )
            if (track.state != AudioTrack.STATE_INITIALIZED) {
                running = false
                return
            }
            track.play()

            val chunkSize = 1024
            val buffer = ShortArray(chunkSize)
            var rngState = 20261913
            fun nextNoise(): Double {
                rngState = rngState xor (rngState shl 13)
                rngState = rngState xor (rngState ushr 17)
                rngState = rngState xor (rngState shl 5)
                return (rngState.toDouble() * 4.656612873077393e-10)
            }
            fun nextUnit(): Double = nextNoise() * 0.5 + 0.5
            var trackPaused = false

            // 6-Cylinder 90 deg Split-Pin F1 V6 Firing Offsets across 2-rev 4-stroke cycle
            val cylOffsets = doubleArrayOf(0.000, 0.333, 0.667, 1.003, 1.331, 1.668)
            val cylGain = doubleArrayOf(1.00, 0.94, 1.05, 0.96, 1.04, 0.93)
            val cylPrevFire = IntArray(6) { -1 }
            val cylAmp = DoubleArray(6) { 1.0 }

            // Physical Exhaust Waveguides: Left Header (55 samps), Right Header (67 samps),
            // Single Central F1 Turbo Tailpipe (118 samps)
            val bufL = DoubleArray(128)
            val bufR = DoubleArray(128)
            val bufT = DoubleArray(256)
            var idxL = 0
            var idxR = 0
            var idxT = 0

            // Extrica 3-Band Envelope-Modulated Broadband Exhaust Combustion Turbulence
            val nbC = doubleArrayOf(
                2.0 * sin(PI * 460.0 / sampleRate),
                2.0 * sin(PI * 1250.0 / sampleRate),
                2.0 * sin(PI * 2650.0 / sampleRate)
            )
            val nbQ = doubleArrayOf(0.65, 0.55, 0.55)
            val nbLp = DoubleArray(3)
            val nbBp = DoubleArray(3)

            // 3 Fixed Physical Exhaust Collector and Carbon-Cockpit Formants (230, 620, 1380 Hz)
            val fmC = doubleArrayOf(
                2.0 * sin(PI * 230.0 / sampleRate),
                2.0 * sin(PI * 620.0 / sampleRate),
                2.0 * sin(PI * 1380.0 / sampleRate)
            )
            val fmQ = doubleArrayOf(0.70, 0.52, 0.55)
            val fmLp = DoubleArray(3)
            val fmBp = DoubleArray(3)

            var curRpm = 4200.0
            var curSpeed = 0.0
            var curThrottle = 0.0
            var curBrake = 0.0
            var curErs = 0.0
            var curOffTrack = 0.0
            var curKerb = 0.0
            var curSlip = 0.0
            var masterGain = 0.0

            var crankRev = 0.0
            var exLp1 = 0.0
            var exLp2 = 0.0
            var wgLp = 0.0
            var wgBp = 0.0
            var wgFlutterPhase = 0.0
            var gbPhase = 0.0
            var dcX = 0.0
            var dcY = 0.0

            // Road, wind, tire scrub, kerb, gravel, brakes
            var roadLp1 = 0.0
            var roadLp2 = 0.0
            var windLp = 0.0
            var slipLp = 0.0
            var slipBp = 0.0
            var brakeLp = 0.0
            var brakeBp = 0.0
            var gravelLp = 0.0
            var kerbPhase = 0.0
            var kerbThudLp = 0.0

            // Crash and race cues
            var crashPhase = 0.0
            var crashLp = 0.0
            var cuePhase = 0.0

            val dt = 1.0 / sampleRate.toDouble()

            while (running) {
                val activeNow = !muted && !lifecyclePaused && (engineActive || cueEnv > 0.004 || crashEnv > 0.004)
                val targetGain = if (activeNow) 0.86 else 0.0

                if (!activeNow && masterGain < 0.002) {
                    if (!trackPaused) {
                        try {
                            track.pause()
                            track.flush()
                        } catch (_: Throwable) {
                        }
                        trackPaused = true
                    }
                    try {
                        Thread.sleep(35)
                    } catch (_: Throwable) {
                    }
                    continue
                }
                if (trackPaused) {
                    try {
                        track.play()
                    } catch (_: Throwable) {
                    }
                    trackPaused = false
                }

                // Hoisted control-rate filter coefficients (refreshed every 32 samples -> 32x less trig CPU!)
                var cWg = 0.30
                var fS = 0.14
                var fB = 0.18
                var aLp = 0.25

                for (i in 0 until chunkSize) {
                    curRpm += (targetRpm - curRpm) * 0.0062
                    curSpeed += (targetSpeed - curSpeed) * 0.0044
                    curThrottle += (targetThrottle - curThrottle) * 0.0076
                    curBrake += (targetBrake - curBrake) * 0.0089
                    curErs += (targetErs - curErs) * 0.0076
                    curOffTrack += (targetOffTrack - curOffTrack) * 0.0089
                    curKerb += (targetOnKerb - curKerb) * 0.015
                    curSlip += (targetSlip - curSlip) * 0.0089
                    masterGain += (targetGain - masterGain) * 0.0035

                    var sample = 0.0

                    if (engineActive) {
                        val rpmNorm = ((curRpm - 3800.0) / 10000.0).coerceIn(0.0, 1.0)
                        val spdNorm = min(1.0, curSpeed / 340.0)
                        val load = (curThrottle + curErs * 0.22 + downshiftEnv * 0.72 + ersBoostEnv * 0.25).coerceIn(0.0, 1.25)

                        // Advance 4-stroke crankshaft counter across 0.0 to 2.0 revolutions
                        val effRpm = curRpm * (1.0 + downshiftEnv * 0.065)
                        crankRev += (effRpm / 60.0) * dt
                        if (crankRev >= 2.0) crankRev -= 2.0

                        // Authentic Honda/Red Bull F1 off-throttle cylinder-cut overrun growl
                        val overrunCut = curThrottle < 0.12 && curRpm > 5600.0 && downshiftEnv < 0.15

                        // =====================================================
                        // 1. SIX INDEPENDENT CYLINDER EXHAUST BLOWDOWN PULSES
                        // =====================================================
                        var bankL = 0.0
                        var bankR = 0.0
                        var peakEnv = 0.0
                        val decayK = 13.5 + load * 11.5 + rpmNorm * 4.5

                        for (c in 0..5) {
                            var p = crankRev - cylOffsets[c]
                            if (p < 0.0) p += 2.0
                            val cid = if (p < 1.0) 0 else 1
                            if (cid == 0 && cylPrevFire[c] != 0) {
                                if (overrunCut && (c == 1 || c == 4 || (c == 2 && nextUnit() < 0.45))) {
                                    cylAmp[c] = 0.18 + 0.15 * nextUnit()
                                } else {
                                    cylAmp[c] = cylGain[c] * (0.91 + 0.18 * nextUnit())
                                }
                            }
                            cylPrevFire[c] = cid

                            if (p < 0.38) {
                                val pulse = if (p < 0.024) {
                                    0.5 - 0.5 * fastCos(PI * (p / 0.024))
                                } else {
                                    fastExpNeg((p - 0.024) * decayK)
                                }
                                val v = pulse * cylAmp[c]
                                if (v > peakEnv) peakEnv = v
                                if ((c and 1) == 0) {
                                    bankL += v
                                } else {
                                    bankR += v
                                }
                            }
                        }

                        bankL -= 0.11
                        bankR -= 0.11

                        // =====================================================
                        // 2. UNEQUAL LEFT/RIGHT PRIMARY HEADER WAVEGUIDES
                        // =====================================================
                        if ((i and 31) == 0) {
                            cWg = 2.0 * fastSin(PI * (1450.0 + 750.0 * rpmNorm) / sampleRate)
                            val slipHz = 560.0 + curSlip * 320.0 + spdNorm * 140.0
                            fS = min(0.28, 2.0 * fastSin(PI * slipHz / sampleRate))
                            fB = min(0.26, 2.0 * fastSin(PI * (920.0 + spdNorm * 350.0) / sampleRate))
                            val cutHz = 780.0 + rpmNorm * 1750.0 + load * 1250.0
                            aLp = min(0.58, (twoPi * cutHz) / (twoPi * cutHz + sampleRate))
                        }

                        val delL = bufL[(idxL - 40) and 127]
                        val delR = bufR[(idxR - 49) and 127]
                        val outL = bankL + 0.32 * delL
                        val outR = bankR + 0.32 * delR
                        bufL[idxL] = (bankL - 0.26 * delL).coerceIn(-1.5, 1.5)
                        bufR[idxR] = (bankR - 0.26 * delR).coerceIn(-1.5, 1.5)
                        idxL = (idxL + 1) and 127
                        idxR = (idxR + 1) and 127

                        val ang = crankRev * PI
                        val orderCore = fastSin(ang * 3.0) * (0.24 + 0.10 * (1.0 - curThrottle)) +
                            fastSin(ang * 6.0) * (0.36 + 0.20 * load) +
                            fastSin(ang * 9.0 + 0.4) * (0.08 + 0.20 * load * (0.4 + 0.6 * rpmNorm)) +
                            fastSin(ang * 12.0 + 0.2) * (0.06 + 0.22 * load * rpmNorm)

                        var shiftCut = 1.0
                        var shiftPop = 0.0
                        if (upshiftEnv > 0.005) {
                            shiftCut = if (upshiftEnv > 0.54) 0.24 else 1.0
                            if (upshiftEnv in 0.24..0.56) {
                                shiftPop = nextNoise() * upshiftEnv * 0.52
                            }
                            upshiftEnv *= 0.99835
                            if (upshiftEnv < 0.005) upshiftEnv = 0.0
                        }
                        if (downshiftEnv > 0.005) {
                            downshiftEnv *= 0.99876
                            if (downshiftEnv < 0.005) downshiftEnv = 0.0
                        }
                        if (ersBoostEnv > 0.005) {
                            ersBoostEnv *= 0.99904
                            if (ersBoostEnv < 0.005) ersBoostEnv = 0.0
                        }

                        val merged = ((outL + outR * 0.90) * (0.72 + 0.65 * load) + orderCore) * shiftCut + shiftPop

                        // =====================================================
                        // 3. EXTRICA ENVELOPE-MODULATED COMBUSTION TURBULENCE
                        // =====================================================
                        val wn = nextNoise()
                        for (b in 0..2) {
                            val hp = wn - nbLp[b] - nbQ[b] * nbBp[b]
                            nbBp[b] += nbC[b] * hp
                            nbLp[b] += nbC[b] * nbBp[b]
                        }
                        val modEnv = 0.20 + 0.80 * min(1.2, peakEnv)
                        val broadband = (
                            nbBp[0] * (0.30 + 0.25 * load) +
                            nbBp[1] * (0.20 + 0.50 * load * (0.35 + 0.65 * rpmNorm)) +
                            nbBp[2] * (0.06 + 0.30 * load * rpmNorm)
                        ) * modEnv

                        // =====================================================
                        // 4. EXTERNAL F1 WASTEGATE SCREAMER + LIFT-OFF FLUTTER
                        // =====================================================
                        val wgOpen = max(0.0, (curRpm - 8800.0) / 4400.0) * curThrottle
                        var wgSig = 0.0
                        if (wgOpen > 0.02 || wastegateLiftEnv > 0.005) {
                            val rawWg = (merged * 0.80 + wn * 0.36) * modEnv
                            wgBp += cWg * (rawWg - wgLp - 0.52 * wgBp)
                            wgLp += cWg * wgBp
                            if (wgOpen > 0.02) {
                                wgSig += fastTanh(wgBp * 1.45) * wgOpen * 0.26
                            }
                            if (wastegateLiftEnv > 0.005) {
                                wgFlutterPhase += twoPi * 24.0 * dt
                                if (wgFlutterPhase > twoPi) wgFlutterPhase -= twoPi
                                val fl = 0.55 + 0.45 * fastSin(wgFlutterPhase)
                                wgSig += nbBp[2] * wastegateLiftEnv * fl * 0.20
                                wastegateLiftEnv *= 0.99945
                                if (wastegateLiftEnv < 0.005) wastegateLiftEnv = 0.0
                            }
                        }

                        // =====================================================
                        // 5. COLLECTOR SATURATION + SINGLE TAILPIPE WAVEGUIDE + FORMANTS
                        // =====================================================
                        val collectorRaw = merged + broadband * 0.26
                        val drive = 1.25 + 1.15 * load + 0.40 * rpmNorm
                        val bias = 0.12 * load
                        val collectorSat = fastTanh((collectorRaw + bias) * drive) - fastTanh(bias * drive)

                        val delT = bufT[(idxT - 86) and 255]
                        val tailpipe = collectorSat - 0.22 * delT
                        bufT[idxT] = (collectorSat - 0.24 * delT).coerceIn(-1.4, 1.4)
                        idxT = (idxT + 1) and 255

                        for (k in 0..2) {
                            fmBp[k] += fmC[k] * (tailpipe - fmLp[k] - fmQ[k] * fmBp[k])
                            fmLp[k] += fmC[k] * fmBp[k]
                        }
                        val formantMix = tailpipe * 0.36 +
                            fmBp[0] * (0.42 + 0.14 * (1.0 - curThrottle)) +
                            fmBp[1] * (0.44 + 0.26 * load) +
                            fmBp[2] * (0.12 + 0.42 * load * (0.3 + 0.7 * rpmNorm))

                        exLp1 += (formantMix - exLp1) * aLp
                        exLp2 += (exLp1 - exLp2) * min(0.62, aLp * 1.25)

                        gbPhase += twoPi * (250.0 + curSpeed * 2.3) * dt
                        if (gbPhase > twoPi) gbPhase -= twoPi
                        val gearbox = fastSin(gbPhase) * (0.024 * spdNorm * (0.35 + 0.65 * curThrottle))

                        val engOut = (exLp2 * 0.78 + wgSig) * (0.42 + 0.30 * load) + gearbox
                        val dcEng = engOut - dcX + 0.995 * dcY
                        dcX = engOut
                        dcY = dcEng
                        sample += dcEng

                        // =====================================================
                        // 6. ASPHALT TIRE ROLL + WIND RUSH + CORNERING RUBBER SCRUB
                        // =====================================================
                        val nRoad = nextNoise()
                        roadLp1 += (nRoad - roadLp1) * (0.032 + 0.040 * spdNorm)
                        roadLp2 += (roadLp1 - roadLp2) * 0.10
                        sample += roadLp2 * (0.32 * spdNorm)

                        val nWind = nextNoise()
                        windLp += (nWind - windLp) * (0.040 + 0.10 * spdNorm)
                        sample += (windLp - roadLp2) * (0.22 * spdNorm * spdNorm)

                        if (curSlip > 0.04) {
                            val nSlip = nextNoise()
                            val sHp = nSlip - slipLp - 0.38 * slipBp
                            slipBp += fS * sHp
                            slipLp += fS * slipBp
                            sample += fastTanh(slipBp * 1.5) * curSlip * 0.25
                        }

                        // =====================================================
                        // 7. KERBS (PIANOS), GRAVEL & CARBON BRAKE FRICTION
                        // =====================================================
                        if (curKerb > 0.01) {
                            val kerbHz = 34.0 + curSpeed * 0.16
                            kerbPhase += kerbHz * dt
                            if (kerbPhase >= 1.0) kerbPhase -= 1.0
                            val rawThud = if (kerbPhase < 0.28) 1.0 else -0.35
                            kerbThudLp += (rawThud - kerbThudLp) * 0.062
                            sample += kerbThudLp * curKerb * 0.28
                        }

                        if (curOffTrack > 0.01) {
                            val rawG = nextNoise()
                            gravelLp += (rawG - gravelLp) * 0.135
                            val stoneHit = if (nextUnit() < 0.035) nextNoise() * 0.45 else 0.0
                            sample += (gravelLp * 0.55 + stoneHit) * curOffTrack * 0.44
                        }

                        if (curBrake > 0.01) {
                            val nBrk = nextNoise()
                            val bHp = nBrk - brakeLp - 0.55 * brakeBp
                            brakeBp += fB * bHp
                            brakeLp += fB * brakeBp
                            sample += brakeBp * curBrake * 0.14
                        }
                    }

                    // =========================================================
                    // 8. DEEP COLLISION THUD + CARBON CRUNCH
                    // =========================================================
                    if (crashEnv > 0.004) {
                        crashPhase += twoPi * crashLowPitch * dt
                        if (crashPhase > twoPi) crashPhase -= twoPi
                        crashLowPitch = max(34.0, crashLowPitch * 0.9996)
                        val nCr = nextNoise()
                        crashLp += (nCr - crashLp) * 0.21
                        sample += (fastSin(crashPhase) * 0.62 + crashLp * 0.55) * crashEnv * 0.72
                        crashEnv *= 0.99948
                        if (crashEnv < 0.004) crashEnv = 0.0
                    }

                    // =========================================================
                    // 9. SHORT WARM START-LIGHT / LAP TELEMETRY CUE
                    // =========================================================
                    if (cueEnv > 0.004) {
                        cuePhase += twoPi * cueFreq * dt
                        if (cuePhase > twoPi) cuePhase -= twoPi
                        val tone = if (cueIsDouble) {
                            fastSin(cuePhase) * 0.65 + fastSin(cuePhase * 1.5) * 0.35
                        } else {
                            fastSin(cuePhase)
                        }
                        sample += tone * cueEnv * 0.15
                        cueEnv *= 0.99876
                        if (cueEnv < 0.004) cueEnv = 0.0
                    }

                    val outVal = fastTanh(sample * masterGain * 1.08).coerceIn(-0.96, 0.96)
                    buffer[i] = (outVal * 32767.0).toInt().toShort()
                }

                track.write(buffer, 0, chunkSize)
            }
        } catch (_: Throwable) {
        } finally {
            running = false
            try {
                track?.stop()
                track?.release()
            } catch (_: Throwable) {
            }
        }
    }
}
